# 18d) DC IPs not declared in AD Sites and Services subnets (S-DC-SubnetMissing)
function Test-IPInSubnet {
    param([string]$IP, [string]$CIDR)
    try {
        $parts = $CIDR -split '/'
        if ($parts.Count -ne 2) { return $false }
        $networkIP = [System.Net.IPAddress]::Parse($parts[0])
        $prefixLen  = [int]$parts[1]
        $testIP     = [System.Net.IPAddress]::Parse($IP)
        $maskVal    = if ($prefixLen -eq 0) { 0 } else { ([uint32]0xFFFFFFFF) -shl (32 - $prefixLen) }
        $netBytes   = $networkIP.GetAddressBytes(); [System.Array]::Reverse($netBytes)
        $testBytes  = $testIP.GetAddressBytes();    [System.Array]::Reverse($testBytes)
        $networkInt = [System.BitConverter]::ToUInt32($netBytes, 0) -band $maskVal
        $testInt    = [System.BitConverter]::ToUInt32($testBytes, 0) -band $maskVal
        return $networkInt -eq $testInt
    } catch { return $false }
}

$AdSubnetCidrs = @()
try {
    $AdSubnetCidrs = @(Get-ADReplicationSubnet -Filter * -ErrorAction Stop |
        Select-Object -ExpandProperty Name |
        Where-Object { $_ -match '^\d+\.\d+\.\d+\.\d+/' })
} catch {}

$DcSubnetMissingList = @()
foreach ($dc in $DCs) {
    $dcIP = $dc.IPv4Address
    if (-not $dcIP) { continue }
    $inSubnet = $false
    foreach ($cidr in $AdSubnetCidrs) {
        if (Test-IPInSubnet -IP $dcIP -CIDR $cidr) { $inSubnet = $true; break }
    }
    if (-not $inSubnet) { $DcSubnetMissingList += "$($dc.Name) ($dcIP)" }
}

$DcSubnetMissingCount = $DcSubnetMissingList.Count
$DcSubnetMissingSample = if ($DcSubnetMissingCount -gt 0) {
