Add-PingFinding -Category "Stale Objects" -Rule "DC subnet registration" -Severity $DcSubnetMissingSeverity -Count $DcSubnetMissingCount -Sample $DcSubnetMissingSample -Recommendation "Declare subnets in AD Sites and Services for all DC network ranges to improve site routing."
foreach ($entry in $DcSubnetMissingList | Select-Object -First 10) {
