# 24b) Hardened UNC paths (SYSVOL/NETLOGON) — check for a domain GPO, not just DC-local registry
$HardenedPathsIssues = @()
$hardenedGPOFound = $false
try {
    $allGPOs = @(Get-GPO -All -ErrorAction Stop)
    foreach ($gpo in $allGPOs) {
        try {
            $sysvolVal = Get-GPRegistryValue -Guid $gpo.Id -Key 'HKLM\SOFTWARE\Policies\Microsoft\Windows\NetworkProvider\HardenedPaths' -ValueName '\\*\SYSVOL' -ErrorAction Stop
            if ($sysvolVal -and $sysvolVal.Value -match 'RequireIntegrity=1' -and $sysvolVal.Value -match 'RequireMutualAuthentication=1') {
                $hardenedGPOFound = $true
                break
            }
        } catch {}
    }
} catch {
    # GroupPolicy module unavailable; fall back to DC registry check
    foreach ($dc in $DCs) {
        try {
            $hpResult = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
                $key = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\NetworkProvider\HardenedPaths' -ErrorAction SilentlyContinue
                if ($null -eq $key) { return @{ Issue = $true; DC = $env:COMPUTERNAME; Reason = 'No GPO configuring Hardened Paths for SYSVOL/NETLOGON' } }
                $sv = $key.'\\*\SYSVOL'; $nl = $key.'\\*\NETLOGON'
                $svOk = ($sv -and $sv -match 'RequireIntegrity=1' -and $sv -match 'RequireMutualAuthentication=1')
                $nlOk = ($nl -and $nl -match 'RequireIntegrity=1' -and $nl -match 'RequireMutualAuthentication=1')
                if (-not $svOk -or -not $nlOk) { return @{ Issue = $true; DC = $env:COMPUTERNAME; Reason = if (-not $svOk) { 'SYSVOL hardening missing/weak' } else { 'NETLOGON hardening missing/weak' } } }
                return @{ Issue = $false; DC = $env:COMPUTERNAME; Reason = '' }
            } -ErrorAction SilentlyContinue
            if ($hpResult -and $hpResult.Issue) { $HardenedPathsIssues += "$($hpResult.DC): $($hpResult.Reason)" }
        } catch { Add-SkippedDCRecord -DC $dc.Name -Section "Hardened UNC Paths" -Reason $_.Exception.Message }
    }
}
if (-not $hardenedGPOFound -and $HardenedPathsIssues.Count -eq 0) {
    $HardenedPathsIssues += "Domain: No domain GPO enforcing RequireIntegrity and RequireMutualAuthentication for \\*\SYSVOL and \\*\NETLOGON"
}
$HardenedPathsCount  = $HardenedPathsIssues.Count
$HardenedPathsSample = ($HardenedPathsIssues | Select-Object -First 4) -join "; "
Add-PingFinding -Category "Anomalies" -Rule "Hardened UNC paths not enforced" `
    -Severity $(if ($HardenedPathsCount -gt 0) { "Low" } else { "Low" }) `
    -Count $HardenedPathsCount -Sample $HardenedPathsSample `
    -Recommendation "Configure GPO to enforce RequireIntegrity and RequireMutualAuthentication for \\*\SYSVOL and \\*\NETLOGON under Computer Configuration > Network > Network Provider > Hardened UNC Paths."
foreach ($msg in $HardenedPathsIssues | Select-Object -First 20) {
    Add-PingDetail -Category "Anomalies" -Rule "Hardened UNC paths not enforced" -Target ($msg -split ":")[0].Trim() -Detail ($msg -split ":",2)[-1].Trim() -Severity "Low"
}

# 24c) LLMNR not disabled via GPO
$LLMNREnabledDcs = @()
foreach ($dc in $DCs) {
    try {
        $llResult = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            $k = Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient" -Name "EnableMulticast" -ErrorAction SilentlyContinue
            return @{ Disabled = ($k -and $k.EnableMulticast -eq 0); DC = $env:COMPUTERNAME }
        } -ErrorAction SilentlyContinue
        if ($llResult -and -not $llResult.Disabled) { $LLMNREnabledDcs += $llResult.DC }
    } catch { Add-SkippedDCRecord -DC $dc.Name -Section "LLMNR GPO" -Reason $_.Exception.Message }
}
$LLMNRCount  = $LLMNREnabledDcs.Count
$LLMNRSample = ($LLMNREnabledDcs | Select-Object -First 4) -join "; "
Add-PingFinding -Category "Anomalies" -Rule "LLMNR not disabled via GPO" `
    -Severity $(if ($LLMNRCount -gt 0) { "Low" } else { "Low" }) `
    -Count $LLMNRCount -Sample $LLMNRSample `
    -Recommendation "Disable LLMNR via GPO: Computer Configuration > Administrative Templates > Network > DNS Client > Turn off Multicast Name Resolution."

# 24d) PowerShell script block logging not enforced
$PSLoggingMissingDcs = @()
foreach ($dc in $DCs) {
    try {
        $psResult = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            $sb  = Get-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging" -Name EnableScriptBlockLogging -ErrorAction SilentlyContinue
            $mod = Get-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ModuleLogging"     -Name EnableModuleLogging       -ErrorAction SilentlyContinue
            return @{ FullLogging = ($sb -and $sb.EnableScriptBlockLogging -eq 1 -and $mod -and $mod.EnableModuleLogging -eq 1); DC = $env:COMPUTERNAME }
        } -ErrorAction SilentlyContinue
        if ($psResult -and -not $psResult.FullLogging) { $PSLoggingMissingDcs += $psResult.DC }
    } catch { Add-SkippedDCRecord -DC $dc.Name -Section "PS Logging" -Reason $_.Exception.Message }
}
$PSLoggingCount  = $PSLoggingMissingDcs.Count
$PSLoggingSample = ($PSLoggingMissingDcs | Select-Object -First 4) -join "; "
Add-PingFinding -Category "Anomalies" -Rule "PowerShell script block logging not enabled" `
    -Severity $(if ($PSLoggingCount -gt 0) { "Low" } else { "Low" }) `
    -Count $PSLoggingCount -Sample $PSLoggingSample `
    -Recommendation "Enable PowerShell Script Block Logging and Module Logging via GPO: Computer Configuration > Windows Components > Windows PowerShell."

# 24e) CVE-2021-42291 dsHeuristics mitigation not applied
$DsHeuristicsOk     = $false
$DsHeuristicsDetail = "LDAPAddAuthZVerifications and LDAPOwnerModify not set to 1"
try {
    $dsSvc = Get-ADObject -Identity "CN=Directory Service,CN=Windows NT,CN=Services,$((Get-ADRootDSE).configurationNamingContext)" -Properties dsHeuristics -ErrorAction SilentlyContinue
    $dsH   = if ($dsSvc -and $dsSvc.dsHeuristics) { [string]$dsSvc.dsHeuristics } else { "" }
    $pos28 = if ($dsH.Length -ge 28) { $dsH[27] } else { "0" }
    $pos29 = if ($dsH.Length -ge 29) { $dsH[28] } else { "0" }
    if ($pos28 -eq "1" -and $pos29 -eq "1") { $DsHeuristicsOk = $true; $DsHeuristicsDetail = "" }
    else { $DsHeuristicsDetail = "LDAPAddAuthZVerifications=$pos28, LDAPOwnerModify=$pos29 (both should be 1)" }
} catch {}
$DsHeuristicsCount = if (-not $DsHeuristicsOk) { 1 } else { 0 }
Add-PingFinding -Category "Anomalies" -Rule "CVE-2021-42291 dsHeuristics mitigation not applied" `
    -Severity $(if ($DsHeuristicsCount -gt 0) { "Low" } else { "Low" }) `
    -Count $DsHeuristicsCount -Sample $DsHeuristicsDetail `
    -Recommendation "Set positions 28-29 of dsHeuristics to '1' (LDAPAddAuthZVerifications=1, LDAPOwnerModify=1) per KB5008383 to enforce enhanced AD security."

# 24f) No Fine-Grained Password Policy (PSO) with 20+ char minimum
$ServicePSOFound = $false
try { $ServicePSOFound = (@(Get-ADFineGrainedPasswordPolicy -Filter * -ErrorAction SilentlyContinue | Where-Object { [int]$_.MinPasswordLength -ge 20 }).Count -gt 0) } catch {}
$ServicePSOCount  = if (-not $ServicePSOFound) { 1 } else { 0 }
$ServicePSOSample = if ($ServicePSOCount -gt 0) { "No PSO with MinPasswordLength >= 20 found" } else { "" }
Add-PingFinding -Category "Anomalies" -Rule "No service account password policy (PSO 20+ chars)" `
    -Severity $(if ($ServicePSOCount -gt 0) { "Low" } else { "Low" }) `
    -Count $ServicePSOCount -Sample $ServicePSOSample `
    -Recommendation "Create a Fine-Grained Password Policy (PSO) with MinPasswordLength >= 20 and apply it to service accounts to reduce Kerberoasting exposure."

# 24g) Anonymous LDAP binding (rootDse) enabled
$AnonBindingEnabled = $true
try {
    $dsSvc2       = Get-ADObject -Identity "CN=Directory Service,CN=Windows NT,CN=Services,$((Get-ADRootDSE).configurationNamingContext)" -Properties "msDS-Other-Settings" -ErrorAction SilentlyContinue
    $otherSettings = @($dsSvc2."msDS-Other-Settings")
    $AnonBindingEnabled = -not ($otherSettings -contains "DenyUnauthenticatedBind=1")
} catch {}
$AnonBindingCount  = if ($AnonBindingEnabled) { 1 } else { 0 }
$AnonBindingSample = if ($AnonBindingCount -gt 0) { "DenyUnauthenticatedBind not set on Directory Service object" } else { "" }
Add-PingFinding -Category "Anomalies" -Rule "Anonymous LDAP binding (rootDse) enabled" `
    -Severity $(if ($AnonBindingCount -gt 0) { "Low" } else { "Low" }) `
    -Count $AnonBindingCount -Sample $AnonBindingSample `
    -Recommendation "Add 'DenyUnauthenticatedBind=1' to msDS-Other-Settings of CN=Directory Service to block anonymous LDAP enumeration (Windows Server 2019+ required)."

# 25) Old NTLM posture (LmCompatibilityLevel)
$OldNtlmDcs = @()
foreach ($dc in $DCs) {
    try {
        $lmValue = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            try {
                (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name LmCompatibilityLevel -ErrorAction Stop).LmCompatibilityLevel
            } catch {
                $null
            }
        } -ErrorAction Stop

        if ($null -eq $lmValue -or [int]$lmValue -lt 5) {
            $OldNtlmDcs += [PSCustomObject]@{ DC = $dc.Name; LmCompatibilityLevel = $lmValue }
        }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "Old NTLM Posture" -Reason $_.Exception.Message
        $OldNtlmDcs += [PSCustomObject]@{ DC = $dc.Name; LmCompatibilityLevel = $null }
    }
}

$OldNtlmCount = $OldNtlmDcs.Count
$OldNtlmSample = if ($OldNtlmCount -gt 0) {
    ($OldNtlmDcs | Select-Object -First 4 | ForEach-Object { "$($_.DC): LmCompatibilityLevel=$($_.LmCompatibilityLevel)" }) -join "; "
} else {
    "No DC with old NTLM compatibility detected"
}
$OldNtlmSeverity = if ($OldNtlmCount -gt 0) { "High" } else { "Low" }
Add-PingFinding -Category "Stale Objects" -Rule "Old NTLM posture" -Severity $OldNtlmSeverity -Count $OldNtlmCount -Sample $OldNtlmSample -Recommendation "Set LmCompatibilityLevel to 5 on DCs and disable legacy NTLM protocols."
foreach ($item in $OldNtlmDcs | Select-Object -First 20) {
    Add-PingDetail -Category "Stale Objects" -Rule "Old NTLM posture" -Target $item.DC -Detail "LmCompatibilityLevel: $($item.LmCompatibilityLevel)" -Severity "High"
}

# S-KerberosArmoring: check if KDC claims/armoring (FAST) is enabled on DCs via GPO registry
$KerberosArmoringIssues = @()
foreach ($dc in $DCs) {
    try {
        $armorResult = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            $kdcPath = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System\KDC\Parameters'
            try {
                $val = (Get-ItemProperty -Path $kdcPath -Name EnableCbacAndArmor -ErrorAction Stop).EnableCbacAndArmor
                [PSCustomObject]@{ Enabled = ($val -eq 1); Value = $val }
            } catch {
                [PSCustomObject]@{ Enabled = $false; Value = $null }
            }
        } -ErrorAction Stop
        if (-not $armorResult.Enabled) {
            $KerberosArmoringIssues += [PSCustomObject]@{ DC = $dc.Name; Value = $armorResult.Value }
        }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "Kerberos Armoring" -Reason $_.Exception.Message
    }
}
$KerberosArmoringCount  = $KerberosArmoringIssues.Count
$KerberosArmoringSev    = if ($KerberosArmoringCount -gt 0) { "Low" } else { "Low" }
$KerberosArmoringSample = if ($KerberosArmoringCount -gt 0) { ($KerberosArmoringIssues | Select-Object -First 4 -ExpandProperty DC) -join ", " } else { "Kerberos armoring (FAST) configured on all reachable DCs" }
Add-PingFinding -Category "Stale Objects" -Rule "Kerberos armoring not configured" -Severity $KerberosArmoringSev -Count $KerberosArmoringCount -Sample $KerberosArmoringSample -Recommendation "Enable 'KDC support for claims, compound authentication and Kerberos armoring' via GPO on all DCs (Computer Config > Admin Templates > System/KDC > set to Supported)."
foreach ($item in $KerberosArmoringIssues | Select-Object -First 20) {
    Add-PingDetail -Category "Stale Objects" -Rule "Kerberos armoring not configured" -Target $item.DC -Detail "EnableCbacAndArmor registry value: $(if ($null -eq $item.Value) { 'not set' } else { $item.Value })" -Severity "Low"
}

# 26) LDAP signing and channel binding posture
$LdapSigningIssues = @()
$LdapChannelBindingIssues = @()
foreach ($dc in $DCs) {
    try {
        $ldapPosture = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            $ntdsPath = 'HKLM:\SYSTEM\CurrentControlSet\Services\NTDS\Parameters'

            $signing = $null
            $channelBinding = $null

            try {
                $signing = (Get-ItemProperty -Path $ntdsPath -Name LDAPServerIntegrity -ErrorAction Stop).LDAPServerIntegrity
            } catch {}

            try {
                $channelBinding = (Get-ItemProperty -Path $ntdsPath -Name LdapEnforceChannelBinding -ErrorAction Stop).LdapEnforceChannelBinding
            } catch {}

            [PSCustomObject]@{
                LDAPServerIntegrity = $signing
                LdapEnforceChannelBinding = $channelBinding
            }
        } -ErrorAction Stop

        if ($null -eq $ldapPosture.LDAPServerIntegrity -or [int]$ldapPosture.LDAPServerIntegrity -lt 2) {
            $issueSeverity = if ($null -eq $ldapPosture.LDAPServerIntegrity -or [int]$ldapPosture.LDAPServerIntegrity -lt 1) { "High" } else { "Medium" }
            $LdapSigningIssues += [PSCustomObject]@{ DC = $dc.Name; Value = $ldapPosture.LDAPServerIntegrity; Severity = $issueSeverity }
        }

        if ($null -eq $ldapPosture.LdapEnforceChannelBinding -or [int]$ldapPosture.LdapEnforceChannelBinding -lt 1) {
            $LdapChannelBindingIssues += [PSCustomObject]@{ DC = $dc.Name; Value = $ldapPosture.LdapEnforceChannelBinding; Severity = "High" }
        }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "LDAP Signing Posture" -Reason $_.Exception.Message
        $LdapSigningIssues += [PSCustomObject]@{ DC = $dc.Name; Value = $null; Severity = "Medium" }
        $LdapChannelBindingIssues += [PSCustomObject]@{ DC = $dc.Name; Value = $null; Severity = "Medium" }
    }
}

$LdapSigningCount = @($LdapSigningIssues).Count
$LdapSigningSeverity = if ($LdapSigningCount -gt 0) {
    if (@($LdapSigningIssues | Where-Object { $_.Severity -eq "High" }).Count -gt 0) { "High" } else { "Medium" }
} else {
    "Low"
}
$LdapSigningSample = if ($LdapSigningCount -gt 0) {
    (@($LdapSigningIssues | Select-Object -First 4 | ForEach-Object { "$($_.DC): LDAPServerIntegrity=$($_.Value)" })) -join "; "
} else {
    "LDAP signing appears enforced on reachable DCs"
}
Add-PingFinding -Category "Anomalies" -Rule "LDAP signing posture" -Severity $LdapSigningSeverity -Count $LdapSigningCount -Sample $LdapSigningSample -Recommendation "Set LDAPServerIntegrity to enforce LDAP signing on domain controllers."
foreach ($issue in $LdapSigningIssues | Select-Object -First 20) {
    Add-PingDetail -Category "Anomalies" -Rule "LDAP signing posture" -Target $issue.DC -Detail "LDAPServerIntegrity: $($issue.Value)" -Severity $issue.Severity
}

$LdapChannelBindingCount = @($LdapChannelBindingIssues).Count
$LdapChannelBindingSeverity = if ($LdapChannelBindingCount -gt 0) {
    if (@($LdapChannelBindingIssues | Where-Object { $_.Severity -eq "High" }).Count -gt 0) { "High" } else { "Medium" }
} else {
    "Low"
}
$LdapChannelBindingSample = if ($LdapChannelBindingCount -gt 0) {
    (@($LdapChannelBindingIssues | Select-Object -First 4 | ForEach-Object { "$($_.DC): LdapEnforceChannelBinding=$($_.Value)" })) -join "; "
} else {
    "LDAP channel binding appears enforced on reachable DCs"
}
Add-PingFinding -Category "Privileged Infrastructure" -Rule "LDAP channel binding posture" -Severity $LdapChannelBindingSeverity -Count $LdapChannelBindingCount -Sample $LdapChannelBindingSample -Recommendation "Set LdapEnforceChannelBinding to a protected mode and validate client compatibility."
foreach ($issue in $LdapChannelBindingIssues | Select-Object -First 20) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "LDAP channel binding posture" -Target $issue.DC -Detail "LdapEnforceChannelBinding: $($issue.Value)" -Severity $issue.Severity
}

# 27) Shadow admin exposure (delegated operator paths)
$ShadowAdminGroupNames = @(
    "Account Operators",
    "Backup Operators",
    "Server Operators",
    "Print Operators",
    "DnsAdmins",
    "Group Policy Creator Owners",
    "Enterprise Key Admins",
    "Key Admins",
    "Certificate Operators",
    "Certificate Publishers"
)

$ShadowAdminExposures = @()
foreach ($row in $PrivilegedGroupReviewRows | Where-Object { $ShadowAdminGroupNames -contains $_.ObjectName }) {
    $usersCount = Get-IntOrZero $row.UsersMember
    $computerCount = Get-IntOrZero $row.ComputersMember
    $indirectCount = Get-IntOrZero $row.IndirectControl
    $unresolvedCount = Get-IntOrZero $row.UnresolvedMembers
    $exposureCount = $usersCount + $computerCount + $indirectCount + $unresolvedCount

    if ($exposureCount -gt 0) {
        $ShadowAdminExposures += [PSCustomObject]@{
            GroupName = $row.ObjectName
            Exposure = $exposureCount
            Users = $usersCount
            Computers = $computerCount
            Indirect = $indirectCount
            Unresolved = $unresolvedCount
        }
    }
}

$ShadowAdminCount = @($ShadowAdminExposures | Measure-Object -Property Exposure -Sum).Sum
if ($null -eq $ShadowAdminCount) { $ShadowAdminCount = 0 }
$ShadowAdminSeverity = if ($ShadowAdminCount -gt 0) { "High" } else { "Low" }
$ShadowAdminSample = if ($ShadowAdminCount -gt 0) {
    (@($ShadowAdminExposures | Sort-Object Exposure -Descending | Select-Object -First 4 | ForEach-Object { "$($_.GroupName): exposure=$($_.Exposure)" })) -join "; "
} else {
    "No delegated operator group exposure detected"
}
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Shadow admin exposure" -Severity $ShadowAdminSeverity -Count $ShadowAdminCount -Sample $ShadowAdminSample -Recommendation "Review delegated operator groups and remove non-essential members and nested control paths."
foreach ($item in $ShadowAdminExposures | Sort-Object Exposure -Descending | Select-Object -First 20) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Shadow admin exposure" -Target $item.GroupName -Detail "Users=$($item.Users), Computers=$($item.Computers), Indirect=$($item.Indirect), Unresolved=$($item.Unresolved)" -Severity "High"
}

# 28) Tiering violations (privileged logon from non-DC endpoints)
$PrivilegedSamLookup = @{}
foreach ($sam in $PrivilegedSamAccounts) {
    if (-not [string]::IsNullOrWhiteSpace($sam)) {
        $PrivilegedSamLookup[$sam.ToLowerInvariant()] = $true
    }
}

$DcHostLookup = @{}
$DcIpLookup = @{}
foreach ($dc in $DCs) {
    if (-not [string]::IsNullOrWhiteSpace($dc.Name)) {
        $dcNameLower = $dc.Name.ToLowerInvariant()
        $DcHostLookup[$dcNameLower] = $true
        $DcHostLookup[($dcNameLower -split '\.')[0]] = $true
    }
    if (-not [string]::IsNullOrWhiteSpace($dc.IPv4Address)) {
        $DcIpLookup[$dc.IPv4Address] = $true
    }
}

$TieringViolationsRaw = @()
foreach ($ev in $UserRiskUserDeviceEvents) {
    $targetUser = "$($ev.TargetUser)".Trim()
    if ([string]::IsNullOrWhiteSpace($targetUser)) { continue }

    if ($targetUser -match '\\') {
        $targetUser = ($targetUser -split '\\')[-1]
    }
    if ($targetUser -match '@') {
        $targetUser = ($targetUser -split '@')[0]
    }
    $targetUser = $targetUser.ToLowerInvariant()

    if (-not $PrivilegedSamLookup.ContainsKey($targetUser)) { continue }

    $sourceParts = Split-UserRiskEndpoint $ev.Source
    $sourceHost = "$($sourceParts.Host)".Trim()
    $sourceIp = "$($sourceParts.IP)".Trim()

    $isDcSource = $false
    if (-not [string]::IsNullOrWhiteSpace($sourceHost) -and $sourceHost -ne "-") {
        $hostLower = $sourceHost.ToLowerInvariant()
        $hostShort = ($hostLower -split '\.')[0]
        if ($DcHostLookup.ContainsKey($hostLower) -or $DcHostLookup.ContainsKey($hostShort)) {
            $isDcSource = $true
        }
    } elseif (-not [string]::IsNullOrWhiteSpace($sourceIp) -and $sourceIp -ne "-") {
        if ($DcIpLookup.ContainsKey($sourceIp)) {
            $isDcSource = $true
        }
    }

    if (-not $isDcSource) {
        $TieringViolationsRaw += [PSCustomObject]@{
            User = $targetUser
            Source = if ([string]::IsNullOrWhiteSpace($ev.Source)) { "-" } else { $ev.Source }
            LogonType = if ([string]::IsNullOrWhiteSpace($ev.LogonType)) { "-" } else { $ev.LogonType }
            LastSeen = $ev.TimeCreated
        }
    }
}

$TieringViolationRows = @(
    $TieringViolationsRaw |
        Group-Object { "$($_.User)|$($_.Source)|$($_.LogonType)" } |
        ForEach-Object {
            $parts = $_.Name -split '\|', 3
            $latest = $_.Group | Sort-Object LastSeen -Descending | Select-Object -First 1
            [PSCustomObject]@{
                User = if ($parts.Count -gt 0) { $parts[0] } else { "-" }
                Source = if ($parts.Count -gt 1) { $parts[1] } else { "-" }
                LogonType = if ($parts.Count -gt 2) { $parts[2] } else { "-" }
                Count = $_.Count
                LastSeen = if ($latest) { $latest.LastSeen } else { $null }
            }
        } |
        Sort-Object Count, LastSeen -Descending |
        Select-Object -First 100
)

$TieringViolationCount = @($TieringViolationRows).Count
$TieringViolationSeverity = if ($TieringViolationCount -gt 0) { "High" } else { "Low" }
$TieringViolationSample = if ($TieringViolationCount -gt 0) {
    (@($TieringViolationRows | Select-Object -First 4 | ForEach-Object { "$($_.User) from $($_.Source) (type $($_.LogonType))" })) -join "; "
} else {
    "No privileged logon detected from non-DC endpoints in lookback window"
}
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tiering violations" -Severity $TieringViolationSeverity -Count $TieringViolationCount -Sample $TieringViolationSample -Recommendation "Restrict privileged account logons to tiered admin workstations and domain controllers only."
foreach ($row in $TieringViolationRows | Select-Object -First 20) {
    $lastSeenText = if ($row.LastSeen) { $row.LastSeen.ToString("yyyy-MM-dd HH:mm") } else { "N/A" }
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tiering violations" -Target $row.User -Detail "Source=$($row.Source), LogonType=$($row.LogonType), Seen=$($row.Count), LastSeen=$lastSeenText" -Severity "High"
}

# 29) Tier 0 - DCSync rights exposure
$DcsyncRightGuids = @(
    "1131f6aa-9c07-11d1-f79f-00c04fc2dcd2", # DS-Replication-Get-Changes
    "1131f6ad-9c07-11d1-f79f-00c04fc2dcd2", # DS-Replication-Get-Changes-All
    "89e95b76-444d-4c62-991a-0facbeda640c"  # DS-Replication-Get-Changes-In-Filtered-Set
)
$DcsyncAllowList = @("NT AUTHORITY\\SYSTEM", "BUILTIN\\Administrators")
$DcsyncExposures = @()
try {
    $rootDse = Get-ADRootDSE
    $namingContexts = @($rootDse.defaultNamingContext, $rootDse.configurationNamingContext, $rootDse.schemaNamingContext) | Where-Object { $_ } | Select-Object -Unique
    foreach ($nc in $namingContexts) {
        try {
            $acl = Get-Acl -Path ("AD:" + $nc)
            foreach ($ace in $acl.Access) {
                if ($ace.AccessControlType -ne "Allow") { continue }
                if (-not ($ace.ActiveDirectoryRights.ToString() -match "ExtendedRight")) { continue }
                $objType = "$($ace.ObjectType)".ToLowerInvariant()
                if ($DcsyncRightGuids -notcontains $objType) { continue }

                $principal = "$($ace.IdentityReference)"
                if ($DcsyncAllowList -contains $principal) { continue }

                $DcsyncExposures += [PSCustomObject]@{ NamingContext = $nc; Principal = $principal; RightGuid = $objType }
            }
        } catch {}
    }
} catch {}

$DcsyncUnique = @($DcsyncExposures | Select-Object -ExpandProperty Principal -Unique)
$DcsyncCount = @($DcsyncUnique).Count
$DcsyncSample = if ($DcsyncCount -gt 0) { ($DcsyncUnique | Select-Object -First 5) -join "; " } else { "No unexpected DCSync ACL principal detected" }
$DcsyncSeverity = if ($DcsyncCount -gt 0) { "Critical" } else { "Low" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: DCSync rights exposure" -Severity $DcsyncSeverity -Count $DcsyncCount -Sample $DcsyncSample -Recommendation "Restrict DS replication rights to built-in replication principals and remove delegated DCSync paths."
foreach ($item in $DcsyncExposures | Select-Object -First 30) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: DCSync rights exposure" -Target $item.Principal -Detail "NC=$($item.NamingContext), Right=$($item.RightGuid)" -Severity "Critical"
}

# 30) Tier 0 - Kerberoastable normal users
$AllSpnUsers = @()
try {
    $AllSpnUsers = Get-ADUser -LDAPFilter "(&(objectCategory=person)(objectClass=user)(servicePrincipalName=*)(!(samAccountName=krbtgt)))" -Properties Enabled,PasswordLastSet,SamAccountName,servicePrincipalName,LastLogonTimestamp,DisplayName
} catch {
    $AllSpnUsers = @()
}
$NormalSpnUsers = @($AllSpnUsers | Where-Object { $_.Enabled -eq $true -and -not $PrivilegedSamAccounts.Contains($_.SamAccountName) })
$KerberoastRiskRows = @()
foreach ($u in $NormalSpnUsers) {
    $pwdAge = if ($u.PasswordLastSet) { [int](New-TimeSpan -Start $u.PasswordLastSet -End $Today).TotalDays } else { 9999 }
    $sev = if ($pwdAge -ge 365) { "Critical" } elseif ($pwdAge -ge 180) { "High" } else { "Medium" }
    $KerberoastRiskRows += [PSCustomObject]@{ Sam = $u.SamAccountName; PwdAge = $pwdAge; Severity = $sev }
}
$KerberoastCount = @($KerberoastRiskRows).Count
$KerberoastSev = if (@($KerberoastRiskRows | Where-Object { $_.Severity -eq "Critical" }).Count -gt 0) { "Critical" } elseif ($KerberoastCount -gt 0) { "High" } else { "Low" }
$KerberoastSample = if ($KerberoastCount -gt 0) { (@($KerberoastRiskRows | Sort-Object PwdAge -Descending | Select-Object -First 5 | ForEach-Object { "$($_.Sam): pwdAge=$($_.PwdAge)d" })) -join "; " } else { "No non-privileged SPN user found" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: Kerberoastable normal users" -Severity $KerberoastSev -Count $KerberoastCount -Sample $KerberoastSample -Recommendation "Migrate service identities to gMSA, rotate stale passwords, and remove unnecessary SPNs."
foreach ($k in $KerberoastRiskRows | Sort-Object PwdAge -Descending | Select-Object -First 30) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: Kerberoastable normal users" -Target $k.Sam -Detail "Password age days=$($k.PwdAge)" -Severity $k.Severity
}

# 31) Tier 0 - Dangerous ACE on critical objects
$DangerousAceRows = @()
$DangerousRightNames = @("GenericAll", "GenericWrite", "WriteDacl", "WriteOwner")
$CriticalObjectDns = @(
    $DomainInfo.DistinguishedName,
    "CN=AdminSDHolder,CN=System,$($DomainInfo.DistinguishedName)",
    "CN=Policies,CN=System,$($DomainInfo.DistinguishedName)"
) | Where-Object { $_ } | Select-Object -Unique
foreach ($dc in $DCs) {
    if ($dc.ComputerObjectDN) { $CriticalObjectDns += $dc.ComputerObjectDN }
}
$DangerousAllowList = @("NT AUTHORITY\\SYSTEM", "BUILTIN\\Administrators")
foreach ($dn in $CriticalObjectDns | Select-Object -Unique) {
    try {
        $acl = Get-Acl -Path ("AD:" + $dn)
        foreach ($ace in $acl.Access) {
            if ($ace.AccessControlType -ne "Allow") { continue }
            $principal = "$($ace.IdentityReference)"
            if ($DangerousAllowList -contains $principal) { continue }

            $rightsText = $ace.ActiveDirectoryRights.ToString()
            $matchedRights = @($DangerousRightNames | Where-Object { $rightsText -match $_ })
            if (@($matchedRights).Count -eq 0) { continue }

            $DangerousAceRows += [PSCustomObject]@{ DN = $dn; Principal = $principal; Rights = ($matchedRights -join ",") }
        }
    } catch {}
}
$DangerousAceCount = @($DangerousAceRows).Count
$DangerousAceSeverity = if ($DangerousAceCount -gt 0) { "Critical" } else { "Low" }
$DangerousAceSample = if ($DangerousAceCount -gt 0) { (@($DangerousAceRows | Select-Object -First 5 | ForEach-Object { "$($_.Principal) on $($_.DN) [$($_.Rights)]" })) -join "; " } else { "No dangerous ACE detected on monitored critical objects" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: Dangerous ACE on critical objects" -Severity $DangerousAceSeverity -Count $DangerousAceCount -Sample $DangerousAceSample -Recommendation "Remove non-essential GenericAll/GenericWrite/WriteDacl/WriteOwner ACEs from Tier-0 objects."
foreach ($rowAce in $DangerousAceRows | Select-Object -First 30) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: Dangerous ACE on critical objects" -Target $rowAce.Principal -Detail "Object=$($rowAce.DN), Rights=$($rowAce.Rights)" -Severity "Critical"
}

# =====================================================
# ATTACK PATHS — privilege escalation graph
# Builds a directed graph (member->group, principal->object via dangerous ACE,
# manager->group via ManagedBy) then keeps only nodes/edges that can reach a
# Tier-0 target. All data reused from earlier collection — no new AD queries.
# =====================================================
$AttackPathNodesJson   = "[]"
$AttackPathEdgesJson    = "[]"
$AttackPathSpotlightJson = "[]"
$AttackPathExposedJson  = "[]"
$AttackPathReachCount  = 0
$AttackPathShortestHops = 0
$AttackPathTargetCount = 0
try {
    $apCn = { param($dn) if ($dn) { ($dn -replace '^CN=([^,]+?),.*$', '$1') } else { $dn } }

    # --- DN / sam resolution maps (lowercased keys) ---
    $apGroupByDn = @{}; $apSamToDn = @{}
    foreach ($g in $script:AllGroups) {
        if (-not $g.DistinguishedName) { continue }
        $dl = $g.DistinguishedName.ToLower()
        $apGroupByDn[$dl] = $g
        if ($g.SamAccountName) { $apSamToDn[$g.SamAccountName.ToLower()] = $dl }
    }
    $apUserByDn = @{}
    foreach ($u in $AllUsersRaw) {
        if (-not $u.DistinguishedName) { continue }
        $dl = $u.DistinguishedName.ToLower()
        $apUserByDn[$dl] = $u
        if ($u.SamAccountName) { $apSamToDn[$u.SamAccountName.ToLower()] = $dl }
    }
    $apCompByDn = @{}
    foreach ($c in $AllComputers) {
        if (-not $c.DistinguishedName) { continue }
        $apCompByDn[$c.DistinguishedName.ToLower()] = $c
    }

    # --- node registry ---
    $apNodes = @{}   # id(lower dn or synth) -> hashtable
    function Add-ApNode($id, $label, $type) {
        if (-not $id) { return $null }
        $k = $id.ToString().ToLower()
        if (-not $apNodes.ContainsKey($k)) {
            $apNodes[$k] = @{ id = $k; label = $label; type = $type; tier = 2; target = $false; flags = @() }
        } elseif ($label -and -not $apNodes[$k].label) {
            $apNodes[$k].label = $label
        }
        return $k
    }
    function Resolve-ApNodeByDn($dn) {
        if (-not $dn) { return $null }
        $k = $dn.ToLower()
        if ($apGroupByDn.ContainsKey($k)) { return (Add-ApNode $k $apGroupByDn[$k].Name 'group') }
        if ($apUserByDn.ContainsKey($k))  { return (Add-ApNode $k $apUserByDn[$k].Name  'user') }
        if ($apCompByDn.ContainsKey($k))  { return (Add-ApNode $k (& $apCn $dn) 'computer') }
        # unresolved DN — infer type from string, keep as generic node
        $t = if ($k -match ',cn=computers,' -or $k -match 'objectclass=computer') { 'computer' } else { 'unknown' }
        return (Add-ApNode $k (& $apCn $dn) $t)
    }

    $apEdges = [System.Collections.Generic.List[object]]::new()
    function Add-ApEdge($s, $d, $kind, $lbl) {
        if ($s -and $d -and ($s -ne $d)) { $apEdges.Add(@{ s = $s; d = $d; k = $kind; lbl = $lbl }) }
    }

    # --- targets (Tier-0 sinks) ---
    $apTargetIds = @{}
    foreach ($pgName in $AllPrivGroupDefs.Keys) {
        $pg = $script:AllGroups | Where-Object { $_.Name -eq $pgName } | Select-Object -First 1
        if ($pg -and $pg.DistinguishedName) {
            $tid = Add-ApNode $pg.DistinguishedName.ToLower() $pg.Name 'group'
            $apNodes[$tid].target = $true; $apNodes[$tid].tier = 0
            $apTargetIds[$tid] = $true
        }
    }
    # domain root + AdminSDHolder synthetic targets
    if ($DomainInfo -and $DomainInfo.DistinguishedName) {
        $rootId = Add-ApNode $DomainInfo.DistinguishedName.ToLower() "Domain Root ($($DomainInfo.NetBIOSName))" 'domain'
        $apNodes[$rootId].target = $true; $apNodes[$rootId].tier = 0; $apTargetIds[$rootId] = $true
        $asdh = "CN=AdminSDHolder,CN=System,$($DomainInfo.DistinguishedName)".ToLower()
        $asdhId = Add-ApNode $asdh "AdminSDHolder" 'domain'
        $apNodes[$asdhId].target = $true; $apNodes[$asdhId].tier = 0; $apTargetIds[$asdhId] = $true
    }

    # --- edges: MemberOf (member -> group) ---
    foreach ($g in $script:AllGroups) {
        if (-not $g.DistinguishedName) { continue }
        $gid = Add-ApNode $g.DistinguishedName.ToLower() $g.Name 'group'
        foreach ($mdn in @($g.MemberDNs)) {
            if (-not $mdn) { continue }
            $mid = Resolve-ApNodeByDn $mdn
            Add-ApEdge $mid $gid 'mem' $null
        }
    }

    # --- edges: dangerous ACE (principal -> object) ---
    foreach ($ace in $DangerousAceRows) {
        $objId = Resolve-ApNodeByDn $ace.DN
        if ($apTargetIds.ContainsKey($objId) -eq $false) {
            # treat any dangerous-ACE object as a Tier-0 target too
            $apNodes[$objId].target = $true; $apNodes[$objId].tier = 0; $apTargetIds[$objId] = $true
        }
        $sam = ($ace.Principal -replace '^.*\\', '').ToLower()
        $prinId = if ($apSamToDn.ContainsKey($sam)) { Resolve-ApNodeByDn $apSamToDn[$sam] } else { Add-ApNode "synth:$($ace.Principal)" $ace.Principal 'unknown' }
        Add-ApEdge $prinId $objId 'ace' $ace.Rights
    }

    # --- edges: ManagedBy (manager -> group, potential control) ---
    foreach ($g in $script:AllGroups) {
        if (-not $g.ManagedBy -or -not $g.DistinguishedName) { continue }
        $mgrSam = $g.ManagedBy.ToLower()
        # ManagedBy stored as CN only (line ~448); match by node label
        $mgrId = $null
        foreach ($n in $apNodes.Values) { if ($n.label -and $n.label.ToLower() -eq $mgrSam) { $mgrId = $n.id; break } }
        if ($mgrId) { Add-ApEdge $mgrId ($g.DistinguishedName.ToLower()) 'mgr' $null }
    }

    # --- flags: shadow admins & weak entry points ---
    foreach ($drift in @($AdminCountDriftUsers)) {
        $sam = $drift.SamAccountName.ToLower()
        if ($apSamToDn.ContainsKey($sam)) {
            $id = $apSamToDn[$sam]
            if ($apNodes.ContainsKey($id)) { $apNodes[$id].flags += 'shadow' }
        }
    }

    # --- reverse-reachability prune + distance-to-target (BFS on reversed edges) ---
    $apRev = @{}   # dest -> list of sources
    foreach ($e in $apEdges) {
        if (-not $apRev.ContainsKey($e.d)) { $apRev[$e.d] = [System.Collections.Generic.List[string]]::new() }
        $apRev[$e.d].Add($e.s)
    }
    $apDist = @{}; $apParent = @{}; $apTargetOf = @{}
    $apQueue = [System.Collections.Generic.Queue[string]]::new()
    foreach ($t in $apTargetIds.Keys) { $apDist[$t] = 0; $apTargetOf[$t] = $t; $apQueue.Enqueue($t) }
    while ($apQueue.Count -gt 0) {
        $cur = $apQueue.Dequeue()
        if ($apRev.ContainsKey($cur)) {
            foreach ($src in $apRev[$cur]) {
                if (-not $apDist.ContainsKey($src)) {
                    $apDist[$src] = $apDist[$cur] + 1
                    $apParent[$src] = $cur
                    $apTargetOf[$src] = $apTargetOf[$cur]
                    $apQueue.Enqueue($src)
                }
            }
        }
    }

    # keep only nodes that can reach a target (distance defined)
    $apKeep = @{}
    foreach ($id in $apDist.Keys) { $apKeep[$id] = $true }
    # cap graph size: prefer closest-to-target nodes
    $apMaxNodes = 320
    if ($apKeep.Count -gt $apMaxNodes) {
        $apKeepSorted = $apDist.GetEnumerator() | Sort-Object Value | Select-Object -First $apMaxNodes -ExpandProperty Key
        $apKeep = @{}; foreach ($id in $apKeepSorted) { $apKeep[$id] = $true }
        foreach ($t in $apTargetIds.Keys) { $apKeep[$t] = $true }
    }

    # exposed principals = non-target users/computers with a path to Tier-0
    $apReachUsers = @($apDist.Keys | Where-Object { $apDist[$_] -gt 0 -and $apNodes.ContainsKey($_) -and ($apNodes[$_].type -eq 'user' -or $apNodes[$_].type -eq 'computer') })
    $AttackPathReachCount = $apReachUsers.Count
    $AttackPathTargetCount = $apTargetIds.Count

    # exposed principal rows for the ranked table (sorted worst-first: fewest hops, shadow first)
    $apExposedOut = foreach ($id in ($apReachUsers | Sort-Object @{Expression={$apDist[$_]}}, @{Expression={if($apNodes[$_].flags -contains 'shadow'){0}else{1}}}, @{Expression={$apNodes[$_].label}})) {
        $tid = $apTargetOf[$id]
        [PSCustomObject]@{
            id   = $id
            l    = $apNodes[$id].label
            t    = $apNodes[$id].type
            hops = $apDist[$id]
            tl   = if ($tid -and $apNodes.ContainsKey($tid)) { $apNodes[$tid].label } else { '-' }
            f    = (@($apNodes[$id].flags) -join ',')
        }
    }
    $AttackPathExposedJson = @($apExposedOut) | ConvertTo-Json -Depth 3 -Compress
    if ($AttackPathExposedJson -notmatch '^\[') { $AttackPathExposedJson = "[$AttackPathExposedJson]" }

    # spotlight: most-exposed principal = smallest positive distance (prefer flagged)
    $apSpot = $apReachUsers | Sort-Object @{ Expression = { if ($apNodes[$_].flags -contains 'shadow') { 0 } else { 1 } } }, @{ Expression = { $apDist[$_] } } | Select-Object -First 1
    $apSpotPath = @()
    if ($apSpot) {
        $node = $apSpot; $guard = 0
        while ($node -and $guard -lt 64) {
            $apSpotPath += $node
            if ($apDist[$node] -eq 0) { break }
            $node = $apParent[$node]; $guard++
        }
        $AttackPathShortestHops = $apDist[$apSpot]
    }

    # --- emit JSON ---
    $apNodeOut = foreach ($id in $apKeep.Keys) {
        $n = $apNodes[$id]
        [PSCustomObject]@{
            id  = $n.id
            l   = $n.label
            t   = $n.type
            g   = $n.tier
            tgt = [int][bool]$n.target
            d   = if ($apDist.ContainsKey($id)) { $apDist[$id] } else { -1 }
            f   = (@($n.flags) -join ',')
        }
    }
    $apEdgeOut = foreach ($e in $apEdges) {
        if ($apKeep.ContainsKey($e.s) -and $apKeep.ContainsKey($e.d)) {
            [PSCustomObject]@{ s = $e.s; d = $e.d; k = $e.k; lbl = $e.lbl }
        }
    }
    $AttackPathNodesJson    = @($apNodeOut) | ConvertTo-Json -Depth 4 -Compress
    $AttackPathEdgesJson    = @($apEdgeOut) | ConvertTo-Json -Depth 4 -Compress
    $AttackPathSpotlightJson = @($apSpotPath) | ConvertTo-Json -Depth 2 -Compress
    if ($AttackPathNodesJson -notmatch '^\[') { $AttackPathNodesJson = "[$AttackPathNodesJson]" }
    if ($AttackPathEdgesJson -notmatch '^\[') { $AttackPathEdgesJson = "[$AttackPathEdgesJson]" }
    if ($AttackPathSpotlightJson -notmatch '^\[') { $AttackPathSpotlightJson = "[$AttackPathSpotlightJson]" }
} catch {
    Write-Warning "Attack Path graph build failed: $($_.Exception.Message)"
}

# 32) Tier 0 - NTLMv1 active usage from Security events
$NtlmV1Rows = @()
foreach ($dc in $DCs) {
    try {
        $events = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            param($StartTime)
            Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4624; StartTime=$StartTime} -ErrorAction Stop | Select-Object -First 1500 | ForEach-Object {
                $xml = [xml]$_.ToXml()
                $eventData = @{}
                foreach ($node in $xml.Event.EventData.Data) { $eventData[$node.Name] = [string]$node.'#text' }
                [PSCustomObject]@{
                    TimeCreated = $_.TimeCreated
                    LogonType = $eventData['LogonType']
                    AuthPackage = $eventData['AuthenticationPackageName']
                    LmPackage = $eventData['LmPackageName']
                    TargetUser = $eventData['TargetUserName']
                    Workstation = $eventData['WorkstationName']
                    IpAddress = $eventData['IpAddress']
                }
            }
        } -ArgumentList (Get-Date).AddDays(-30) -ErrorAction Stop

        $hits = @($events | Where-Object {
            $_.LogonType -eq '3' -and
            $_.AuthPackage -match 'NTLM' -and
            ($_.LmPackage -match 'NTLM V1' -or $_.LmPackage -match '^LM$')
        })

        foreach ($h in $hits) {
            $src = if (-not [string]::IsNullOrWhiteSpace($h.Workstation)) { $h.Workstation } elseif (-not [string]::IsNullOrWhiteSpace($h.IpAddress)) { $h.IpAddress } else { '-' }
            $NtlmV1Rows += [PSCustomObject]@{ DC = $dc.Name; User = $h.TargetUser; Source = $src; Time = $h.TimeCreated; LmPackage = $h.LmPackage }
        }
    } catch {}
}
$NtlmV1Count = @($NtlmV1Rows).Count
$NtlmV1Severity = if ($NtlmV1Count -gt 0) { "Critical" } else { "Low" }
$NtlmV1Sample = if ($NtlmV1Count -gt 0) { (@($NtlmV1Rows | Select-Object -First 5 | ForEach-Object { "$($_.User) from $($_.Source) on $($_.DC)" })) -join "; " } else { "No NTLMv1 logon evidence in sampled 4624 events" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: NTLMv1 active usage" -Severity $NtlmV1Severity -Count $NtlmV1Count -Sample $NtlmV1Sample -Recommendation "Identify NTLMv1 clients, enforce NTLM hardening and eliminate legacy authentication paths."
foreach ($n in $NtlmV1Rows | Select-Object -First 30) {
    $tm = if ($n.Time) { $n.Time.ToString("yyyy-MM-dd HH:mm") } else { "N/A" }
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: NTLMv1 active usage" -Target $n.User -Detail "Source=$($n.Source), DC=$($n.DC), LmPackage=$($n.LmPackage), Time=$tm" -Severity "Critical"
}

# 33) Tier 0 - Explicit tier model finding (same data source)
$TierModelSeverity = if ($TieringViolationCount -gt 0) { "Critical" } else { "Low" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: Tier model violations" -Severity $TierModelSeverity -Count $TieringViolationCount -Sample $TieringViolationSample -Recommendation "Separate Tier-0 and Tier-1 administration paths and enforce PAW usage for privileged identities."

# 34) Tier 1 - Shadow Credentials (msDS-KeyCredentialLink)
$ShadowCredentialRows = @()
try {
    $scUsers = Get-ADUser -LDAPFilter "(&(objectCategory=person)(objectClass=user)(msDS-KeyCredentialLink=*))" -Properties SamAccountName,msDS-KeyCredentialLink
    foreach ($u in $scUsers) {
        $ShadowCredentialRows += [PSCustomObject]@{ Obj = $u.SamAccountName; Type = "User"; Count = @($u.'msDS-KeyCredentialLink').Count }
    }
} catch {}
try {
    $scComputers = Get-ADComputer -LDAPFilter "(&(objectClass=computer)(msDS-KeyCredentialLink=*))" -Properties Name,msDS-KeyCredentialLink
    foreach ($c in $scComputers) {
        $ShadowCredentialRows += [PSCustomObject]@{ Obj = $c.Name; Type = "Computer"; Count = @($c.'msDS-KeyCredentialLink').Count }
    }
} catch {}
$ShadowCredentialCount = @($ShadowCredentialRows).Count
$ShadowCredentialSeverity = if ($ShadowCredentialCount -gt 0) { "High" } else { "Low" }
$ShadowCredentialSample = if ($ShadowCredentialCount -gt 0) { (@($ShadowCredentialRows | Select-Object -First 5 | ForEach-Object { "$($_.Obj) ($($_.Type))" })) -join "; " } else { "No object with msDS-KeyCredentialLink found" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: Shadow credentials exposure" -Severity $ShadowCredentialSeverity -Count $ShadowCredentialCount -Sample $ShadowCredentialSample -Recommendation "Review WHfB key credentials and restrict write permissions to msDS-KeyCredentialLink."
foreach ($sc in $ShadowCredentialRows | Select-Object -First 30) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier1: Shadow credentials exposure" -Target $sc.Obj -Detail "ObjectType=$($sc.Type), KeyCredentialCount=$($sc.Count)" -Severity "High"
}

# 35) Tier 1 - Pre-Windows 2000 compatible access
$PreWinFindings = @()
try {
    $preMembers = Get-ADGroupMember -Identity "Pre-Windows 2000 Compatible Access" -ErrorAction Stop
    foreach ($m in $preMembers) {
        $name = if ($m.SamAccountName) { $m.SamAccountName } else { $m.Name }
        if ($name -match 'Authenticated Users|Anonymous Logon|Everyone') {
            $PreWinFindings += "$name"
        }
    }
} catch {}
$PreWinCount = @($PreWinFindings).Count
$PreWinSeverity = if ($PreWinCount -gt 0) { "High" } else { "Low" }
$PreWinSample = if ($PreWinCount -gt 0) { ($PreWinFindings | Select-Object -First 4) -join ", " } else { "No risky principal found in Pre-Windows 2000 Compatible Access" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: Pre-Windows 2000 compatible access" -Severity $PreWinSeverity -Count $PreWinCount -Sample $PreWinSample -Recommendation "Remove broad identities from Pre-Windows 2000 Compatible Access group."

# 36) Tier 1 - DNS Admin and zone transfer posture
$DnsServerName = if (@($DCs).Count -gt 0) { $DCs[0].Name } else { $env:COMPUTERNAME }
$DnsAdmins = @()
try { $DnsAdmins = Get-ADGroupMember -Identity "DnsAdmins" -ErrorAction Stop } catch { $DnsAdmins = @() }
$DnsAdminCount = @($DnsAdmins).Count
$DnsZoneTransferRisk = 0
$DnsZoneTransferSample = "DNS zone transfer posture unavailable"
$dnsChecks = @()
$DnsZoneData = @()
$DnsForwarderIPs = @()
$DnsForwarderStatus = @()
$DnsScavenging = $null
$DnsHealthScore = 0
$DnsHealthGrade = 'F'
$DnsHealthColor = '#dc2626'
$DnsHealthBg    = '#fff1f2'

function Format-DnsTTL($ts) {
    if (-not $ts) { return '-' }
    try {
        $s = [timespan]$ts
        if ($s.TotalSeconds -eq 0) { return '0' }
        if ($s.TotalDays -ge 1)    { return "$([int]$s.TotalDays)d" }
        if ($s.TotalHours -ge 1)   { return "$([int]$s.TotalHours)h" }
        return "$([int]$s.TotalMinutes)m"
    } catch { return [string]$ts }
}

try {
    if (Get-Command Get-DnsServerZone -ErrorAction SilentlyContinue) {
        $rawZones = @(Get-DnsServerZone -ErrorAction Stop)
        $dnsChecks = @($rawZones | Where-Object { $_.ZoneName -ne '.' } |
            Select-Object ZoneName, ZoneType, IsAutoCreated, IsDsIntegrated, SecureSecondaries, ReplicationScope, ZoneFile)

        try {
            $fwdCfg = Get-DnsServerForwarder -ErrorAction Stop
            $DnsForwarderIPs = @($fwdCfg.IPAddress | ForEach-Object { [string]$_ })
            foreach ($fip in $DnsForwarderIPs) {
                $fReach = $false
                try { $fReach = [bool](Test-Connection -ComputerName $fip -Count 1 -Quiet -ErrorAction SilentlyContinue) } catch {}
                $DnsForwarderStatus += [PSCustomObject]@{ IP = $fip; Reachable = $fReach }
            }
        } catch { }

        try { $DnsScavenging = Get-DnsServerScavenging -ErrorAction Stop } catch { }

        foreach ($zone in $rawZones | Where-Object { $_.ZoneName -ne '.' -and [string]$_.ZoneType -in @('Primary','Secondary') }) {
            $zoneRecs = @()
            try {
                $rawRecs = @(Get-DnsServerResourceRecord -ZoneName $zone.ZoneName -ErrorAction Stop | Select-Object -First 1000)
                foreach ($rec in $rawRecs) {
                    $recData = ''
                    try {
                        $d = $rec.RecordData
                        $recData = switch ([string]$rec.RecordType) {
                            'A'     { [string]$d.IPv4Address }
                            'AAAA'  { [string]$d.IPv6Address }
                            'CNAME' { [string]$d.HostNameAlias }
                            'MX'    { "$($d.MailExchange) (pref $($d.Preference))" }
                            'NS'    { [string]$d.NameServer }
                            'PTR'   { [string]$d.PtrDomainName }
                            'SRV'   { "$($d.DomainName):$($d.Port) [pri=$($d.Priority) w=$($d.Weight)]" }
                            'TXT'   { [string]($d.DescriptiveText -join ' ') }
                            'SOA'   { "$($d.PrimaryServer) serial=$($d.SerialNumber)" }
                            default { [string]$d }
                        }
                    } catch { $recData = '' }
                    $zoneRecs += [PSCustomObject]@{
                        HostName   = [string]$rec.HostName
                        RecordType = [string]$rec.RecordType
                        TTL        = Format-DnsTTL $rec.TimeToLive
                        RecordData = $recData
                    }
                }
            } catch { }

            $isReverse = [string]$zone.ZoneName -match '\.in-addr\.arpa$|\.ip6\.arpa$'
            $ztStr  = [string]$zone.SecureSecondaries
            $ztSafe = $ztStr -in @('TransferToSecureServers','NoTransfer') -or [bool]$zone.IsDsIntegrated
            if (-not $ztSafe) { $DnsZoneTransferRisk++ }

            # Zone health checks
            $zoneIssues = @()
            $zoneHealth = 'OK'
            $_hasSoa = (@($zoneRecs | Where-Object { $_.RecordType -eq 'SOA' })).Count -gt 0
            $_hasNs  = (@($zoneRecs | Where-Object { $_.RecordType -eq 'NS'  })).Count -gt 0
            if (-not $_hasSoa) { $zoneIssues += 'Missing SOA record'; $zoneHealth = 'Error' }
            if (-not $_hasNs)  { $zoneIssues += 'Missing NS record';  if ($zoneHealth -ne 'Error') { $zoneHealth = 'Warn' } }
            if (-not [bool]$zone.IsDsIntegrated -and -not $ztSafe) {
                if ($zoneIssues -notcontains 'File-based zone with open transfer') { $zoneIssues += 'File-based zone with open transfer' }
                $zoneHealth = 'Error'
            }
            try {
                $lowTTL = @($rawRecs | Where-Object {
                    [string]$_.RecordType -notin @('SOA','NS') -and $_.TimeToLive -and
                    [int]$_.TimeToLive.TotalSeconds -gt 0 -and [int]$_.TimeToLive.TotalSeconds -lt 300
                })
                if ($lowTTL.Count -gt 0) {
                    $zoneIssues += "$($lowTTL.Count) record(s) with TTL < 5 min"
                    if ($zoneHealth -eq 'OK') { $zoneHealth = 'Warn' }
                }
            } catch {}

            $DnsZoneData += [PSCustomObject]@{
                ZoneName          = [string]$zone.ZoneName
                ZoneType          = [string]$zone.ZoneType
                IsReverse         = $isReverse
                IsDsIntegrated    = [bool]$zone.IsDsIntegrated
                ReplicationScope  = [string]$zone.ReplicationScope
                SecureSecondaries = $ztStr
                ZoneTransferSafe  = $ztSafe
                RecordCount       = $zoneRecs.Count
                Records           = $zoneRecs
                ZoneHealth        = $zoneHealth
                ZoneIssues        = $zoneIssues
            }
        }

        $DnsZoneTransferSample = if ($DnsZoneTransferRisk -gt 0) {
            (@($DnsZoneData | Where-Object { -not $_.ZoneTransferSafe } | Select-Object -First 4 -ExpandProperty ZoneName)) -join ', '
        } else { "No risky zone transfer setting detected" }
    }
} catch {
    $dnsProbeDc = if (@($DCs).Count -gt 0) { [string]$DCs[0].Name } else { "Unknown" }
    Add-SkippedDCRecord -DC $dnsProbeDc -Section "DNS Admin and Zone Transfer" -Reason $_.Exception.Message
}
$DnsRiskTotal = $DnsAdminCount + $DnsZoneTransferRisk
$DnsSeverity  = if ($DnsRiskTotal -gt 0) { "High" } else { "Low" }
$DnsSample    = "DnsAdmins=$DnsAdminCount; ZoneTransferRisk=$DnsZoneTransferRisk; $DnsZoneTransferSample"
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: DNS admin and zone transfer" -Severity $DnsSeverity -Count $DnsRiskTotal -Sample $DnsSample -Recommendation "Minimize DnsAdmins membership and enforce secure zone transfer configuration."

# DNS Health Score (0-100)
$_scavEnabled = $DnsScavenging -and $DnsScavenging.ScavengingState -eq $true
$DnsHealthScore = 100
if (-not $_scavEnabled)                { $DnsHealthScore -= 25 }
$DnsHealthScore -= [math]::Min($DnsZoneTransferRisk * 10, 30)
if ($DnsAdminCount -gt 3)              { $DnsHealthScore -= 15 }
elseif ($DnsAdminCount -gt 0)          { $DnsHealthScore -= 5  }
if (@($DnsForwarderStatus | Where-Object { -not $_.Reachable }).Count -gt 0) { $DnsHealthScore -= 10 }
if ($DnsForwarderIPs.Count -eq 0)      { $DnsHealthScore -= 5  }
foreach ($_z in $DnsZoneData) {
    if ($_z.ZoneHealth -eq 'Error')    { $DnsHealthScore -= 10 }
    elseif ($_z.ZoneHealth -eq 'Warn') { $DnsHealthScore -= 3  }
}
$DnsHealthScore = [math]::Max(0, [math]::Min(100, $DnsHealthScore))
$DnsHealthGrade = if ($DnsHealthScore -ge 90){'A'} elseif($DnsHealthScore -ge 75){'B'} elseif($DnsHealthScore -ge 60){'C'} elseif($DnsHealthScore -ge 40){'D'} else{'F'}
$DnsHealthColor = if ($DnsHealthScore -ge 90){'#16a34a'} elseif($DnsHealthScore -ge 75){'#65a30d'} elseif($DnsHealthScore -ge 60){'#d97706'} elseif($DnsHealthScore -ge 40){'#ea580c'} else{'#dc2626'}
$DnsHealthBg    = if ($DnsHealthScore -ge 90){'#f0fdf4'} elseif($DnsHealthScore -ge 75){'#f7fee7'} elseif($DnsHealthScore -ge 60){'#fffbeb'} elseif($DnsHealthScore -ge 40){'#fff7ed'} else{'#fff1f2'}
$DnsHealthBorder = if ($DnsHealthScore -ge 90){'#86efac'} elseif($DnsHealthScore -ge 75){'#bef264'} elseif($DnsHealthScore -ge 60){'#fde68a'} elseif($DnsHealthScore -ge 40){'#fdba74'} else{'#fca5a5'}

# 37) Tier 1 - Inactive or orphan service accounts
$OrphanServiceRows = @()
foreach ($u in $AllSpnUsers) {
    $lastLogonDate = if ($u.LastLogonTimestamp) { [DateTime]::FromFileTime([int64]$u.LastLogonTimestamp) } else { [datetime]::MinValue }
    $stale = ($lastLogonDate -eq [datetime]::MinValue -or $lastLogonDate -lt (Get-Date).AddDays(-90))
    $disabled = ($u.Enabled -eq $false)
    if (-not ($stale -or $disabled)) { continue }
    $OrphanServiceRows += [PSCustomObject]@{ Sam = $u.SamAccountName; Disabled = $disabled; LastLogon = $lastLogonDate }
}
$OrphanServiceCount = @($OrphanServiceRows).Count
$OrphanServiceSeverity = if ($OrphanServiceCount -gt 0) { "High" } else { "Low" }
$OrphanServiceSample = if ($OrphanServiceCount -gt 0) { (@($OrphanServiceRows | Select-Object -First 5 | ForEach-Object { "$($_.Sam)" })) -join ", " } else { "No stale/disabled SPN service account detected" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: Inactive or orphan service accounts" -Severity $OrphanServiceSeverity -Count $OrphanServiceCount -Sample $OrphanServiceSample -Recommendation "Disable or clean stale SPN accounts and migrate service identities to managed models."

# 38) Tier 1 - gMSA adoption ratio
$gmsaCount = 0
$gmsaAccounts = @()
try {
    if (Get-Command Get-ADServiceAccount -ErrorAction SilentlyContinue) {
        $gmsaAccounts = @(Get-ADServiceAccount -Filter * -Properties Name,SamAccountName,Enabled,Created,Description,PrincipalsAllowedToRetrieveManagedPassword -ErrorAction Stop)
        $gmsaCount = $gmsaAccounts.Count
    }
} catch {}
$spnServiceCount = @($AllSpnUsers).Count
$legacyServiceCount = [math]::Max($spnServiceCount - $gmsaCount, 0)
$gmsaSeverity = if ($legacyServiceCount -gt 0) { "High" } elseif ($spnServiceCount -gt 0) { "Medium" } else { "Low" }
$gmsaSample = "gMSA=$gmsaCount, SPN users=$spnServiceCount, legacy service identities=$legacyServiceCount"
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: gMSA adoption" -Severity $gmsaSeverity -Count $legacyServiceCount -Sample $gmsaSample -Recommendation "Increase gMSA usage and reduce password-managed service accounts."

# Pattern-based service accounts (no SPN but naming convention suggests service identity)
$PatternSvcAccounts = @()
try {
    $PatternSvcAccounts = @(Get-ADUser -Filter {Enabled -eq $true} -Properties SamAccountName,DisplayName,Enabled,PasswordLastSet,LastLogonTimestamp,Description,servicePrincipalName -ErrorAction SilentlyContinue |
        Where-Object {
            $sn = $_.SamAccountName.ToLower()
            ($sn -match '^svc[_\-]|[_\-]svc$|[_\-]svc[_\-]|^srv[_\-]|[_\-]srv$|^sa[_\-]|[_\-]sa$|service' ) -and
            $_.SamAccountName -ne 'administrator' -and
            -not ($AllSpnUsers | Where-Object { $_.SamAccountName -eq $_.SamAccountName })
        })
    # Remove duplicates already in AllSpnUsers
    $spnSams = $AllSpnUsers | ForEach-Object { $_.SamAccountName }
    $PatternSvcAccounts = @($PatternSvcAccounts | Where-Object { $spnSams -notcontains $_.SamAccountName })
} catch {
    $PatternSvcAccounts = @()
}

# 39) Tier 1 - SYSVOL/NETLOGON posture — per-DC detailed checks
$frsRiskCount = 0
$frsRiskDcs   = @()
$SysvolDcDetails = @()

foreach ($dc in $DCs) {
    $dcName       = $dc.Name
    $isFrs        = $false
    $sysvolReach  = $false
    $netlogonReach= $false
    $gpoCount     = 0
    $scriptCount  = 0
    $dfsrState    = 'Unknown'
    $dfsrStateNum = -1
    $sysvolSize   = 0

    # FRS check
    try {
        $frs = Get-CimInstance -ClassName Win32_Service -ComputerName $dcName -Filter "Name='NtFrs'" -ErrorAction Stop
        if ($frs -and $frs.State -eq 'Running') { $isFrs = $true; $frsRiskCount++; $frsRiskDcs += $dcName }
    } catch {}

    # Share accessibility
    try { $sysvolReach   = [bool](Test-Path "\\$dcName\SYSVOL"   -ErrorAction Stop) } catch {}
    try { $netlogonReach = [bool](Test-Path "\\$dcName\NETLOGON" -ErrorAction Stop) } catch {}

    # GPO folder count in SYSVOL (folders named {GUID})
    if ($sysvolReach) {
        try {
            $gpoPath = "\\$dcName\SYSVOL\$Domain\Policies"
            $gpoCount = @(Get-ChildItem $gpoPath -Directory -ErrorAction Stop |
                Where-Object { $_.Name -match '^\{[0-9A-Fa-f\-]{36}\}$' }).Count
        } catch {}
        try {
            $sysvolSize = [math]::Round((Get-ChildItem "\\$dcName\SYSVOL" -Recurse -File -ErrorAction Stop |
                Measure-Object -Property Length -Sum -ErrorAction Stop).Sum / 1MB, 1)
        } catch {}
    }

    # Script count in NETLOGON
    if ($netlogonReach) {
        try {
            $scriptCount = @(Get-ChildItem "\\$dcName\NETLOGON" -Recurse -File -ErrorAction Stop |
                Where-Object { $_.Extension -in @('.bat','.cmd','.ps1','.vbs','.js','.wsf') }).Count
        } catch {}
    }

    # DFSR replication state via CIM
    if (-not $isFrs) {
        try {
            $dfsrInfo = @(Get-CimInstance -Namespace 'root\microsoftdfs' -ClassName 'DfsrReplicatedFolderInfo' `
                -ComputerName $dcName -ErrorAction Stop |
                Where-Object { $_.ReplicatedFolderName -like '*SYSVOL*' -or $_.ReplicationGroupName -like '*System Volume*' } |
                Select-Object -First 1)
            if ($dfsrInfo) {
                $dfsrStateNum = [int]$dfsrInfo.State
                $dfsrState = switch ($dfsrStateNum) {
                    0  { 'Uninitialized' } 1 { 'Initialized' } 2 { 'Initial Sync' }
                    3  { 'Auto Recovery' } 4 { 'Normal'       } 5 { 'In Error'     }
                    6  { 'Disabled'      } default { "State $dfsrStateNum" }
                }
            }
        } catch {}
    }

    $dcHealthy = $sysvolReach -and $netlogonReach -and -not $isFrs -and ($dfsrStateNum -in @(-1,4))
    $SysvolDcDetails += [PSCustomObject]@{
        DCName         = $dcName
        IsFrs          = $isFrs
        SysvolReach    = $sysvolReach
        NetlogonReach  = $netlogonReach
        GpoCount       = $gpoCount
        ScriptCount    = $scriptCount
        DfsrState      = $dfsrState
        DfsrStateNum   = $dfsrStateNum
        SysvolSizeMB   = $sysvolSize
        IsHealthy      = $dcHealthy
    }
}

$netlogonSensitiveCount = 0
try {
    $netlogonPath = "\\$Domain\\NETLOGON"
    if (Test-Path $netlogonPath) {
        $netlogonSensitiveCount = @(
            Get-ChildItem -Path $netlogonPath -Recurse -File -ErrorAction SilentlyContinue |
                Select-String -Pattern "password|passwd|secret|credential" -SimpleMatch -ErrorAction SilentlyContinue
        ).Count
    }
} catch {}

$_sysvolUnreach  = @($SysvolDcDetails | Where-Object { -not $_.SysvolReach   }).Count
$_netlogUnreach  = @($SysvolDcDetails | Where-Object { -not $_.NetlogonReach }).Count
$_dfsrError      = @($SysvolDcDetails | Where-Object { $_.DfsrStateNum -notin @(-1,4) -and -not $_.IsFrs }).Count
$sysvolRiskCount = $frsRiskCount + $GppCount + $netlogonSensitiveCount + $_sysvolUnreach + $_netlogUnreach + $_dfsrError
$sysvolSeverity  = if ($sysvolRiskCount -gt 0) { "High" } else { "Low" }
$sysvolSample    = "FRS=$frsRiskCount; SYSVOL unreachable=$_sysvolUnreach; NETLOGON unreachable=$_netlogUnreach; DFSR errors=$_dfsrError; GPP=$GppCount; NETLOGON hits=$netlogonSensitiveCount"
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: SYSVOL and NETLOGON posture" -Severity $sysvolSeverity -Count $sysvolRiskCount -Sample $sysvolSample -Recommendation "Use DFS-R only, remove credential residues from SYSVOL/NETLOGON, and monitor script shares."

# 39b) ADCS / PKI Health
$AdcsInstalled   = $false
$AdcsCAs         = @()
$AdcsTemplates   = @()
$AdcsEscCount    = 0
$AdcsHealthScore = 100
$AdcsConfigNC    = ""
try { $AdcsConfigNC = (Get-ADRootDSE -ErrorAction Stop).configurationNamingContext } catch {}

# Detect ADCS by checking AD Configuration NC — works even if CA is on a different server
if ($AdcsConfigNC) {
    try {
        $_adcsCaProbe = @(Get-ADObject -SearchBase "CN=Enrollment Services,CN=Public Key Services,CN=Services,$AdcsConfigNC" `
            -Filter * -ErrorAction Stop | Where-Object { $_.objectClass -eq 'pKIEnrollmentService' })
        $AdcsInstalled = ($_adcsCaProbe.Count -gt 0)
    } catch {}
}

if ($AdcsInstalled -and $AdcsConfigNC) {
    # Enumerate CAs from AD Enrollment Services
    try {
        $caObjects = @(Get-ADObject -SearchBase "CN=Enrollment Services,CN=Public Key Services,CN=Services,$AdcsConfigNC" `
            -Filter * -Properties dNSHostName,displayName,flags -ErrorAction Stop |
            Where-Object { $_.objectClass -eq 'pKIEnrollmentService' })
        $localHost = $env:COMPUTERNAME
        foreach ($ca in $caObjects) {
            $caHost        = [string]$ca.dNSHostName
            $caReachable   = $false
            $caSvcRunning  = $false
            $caSvcStatus   = 'Unknown'
            $esc6Risk      = $false
            $esc6Checked   = $false
            $webEnroll     = $false
            $isLocalHost   = ($caHost -eq $localHost -or $caHost -split '\.' | Select-Object -First 1 | ForEach-Object { $_ -eq $localHost })

            # Reachability via ping
            try { $caReachable = [bool](Test-Connection -ComputerName $caHost -Count 1 -Quiet -ErrorAction SilentlyContinue) } catch {}

            # CertSvc service status — local or remote CIM
            if ($caReachable) {
                try {
                    if ($isLocalHost) {
                        $svc = Get-CimInstance -ClassName Win32_Service -Filter "Name='CertSvc'" -ErrorAction Stop
                    } else {
                        $svc = Get-CimInstance -ClassName Win32_Service -ComputerName $caHost -Filter "Name='CertSvc'" -ErrorAction Stop
                    }
                    if ($svc) { $caSvcStatus = $svc.State; $caSvcRunning = ($svc.State -eq 'Running') }
                } catch { $caSvcStatus = 'Check failed' }
            }

            # ESC6: EDITF_ATTRIBUTESUBJECTALTNAME2
            try {
                if ($isLocalHost) {
                    $ef = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\CertSvc\Configuration\$($ca.Name)" -Name EditFlags -ErrorAction Stop).EditFlags
                } else {
                    $ef = Invoke-Command -ComputerName $caHost -ScriptBlock {
                        param($n) (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\CertSvc\Configuration\$n" -Name EditFlags -ErrorAction Stop).EditFlags
                    } -ArgumentList $ca.Name -ErrorAction Stop
                }
                $esc6Risk    = ($ef -band 0x40) -ne 0
                $esc6Checked = $true
            } catch {}

            # ESC8: Web enrollment endpoint (port 80)
            try {
                $webEnroll = [bool](Test-NetConnection -ComputerName $caHost -Port 80 -InformationLevel Quiet `
                    -ErrorAction SilentlyContinue -WarningAction SilentlyContinue)
            } catch {}

            $AdcsCAs += [PSCustomObject]@{
                Name         = [string]$ca.Name
                DisplayName  = [string]$ca.displayName
                DNSHost      = $caHost
                IsLocal      = [bool]$isLocalHost
                SvcStatus    = $caSvcStatus
                SvcRunning   = $caSvcRunning
                Reachable    = $caReachable
                Esc6Risk     = $esc6Risk
                Esc6Checked  = $esc6Checked
                WebEnroll    = $webEnroll
                IsHealthy    = ($caReachable -and $caSvcRunning -and -not $esc6Risk)
            }
        }
    } catch {}

    # Enumerate Certificate Templates
    try {
        $tmplObjects = @(Get-ADObject -SearchBase "CN=Certificate Templates,CN=Public Key Services,CN=Services,$AdcsConfigNC" `
            -Filter * -Properties 'msPKI-Certificate-Name-Flag','msPKI-Enrollment-Flag','pKIExtendedKeyUsage','nTSecurityDescriptor','displayName' `
            -ErrorAction Stop | Where-Object { $_.objectClass -eq 'pKICertificateTemplate' })
        $_enrollRight = [guid]'0e10c968-78fb-11d2-90d4-00c04f79dc55'
        foreach ($tmpl in $tmplObjects) {
            $nameFlag   = try { [int64]($tmpl.'msPKI-Certificate-Name-Flag') } catch { 0 }
            $enrollFlag = try { [int64]($tmpl.'msPKI-Enrollment-Flag')       } catch { 0 }
            $ekus       = @($tmpl.'pKIExtendedKeyUsage')
            $enrolleeSuppliesSAN = ($nameFlag   -band 0x1) -ne 0
            $requiresApproval    = ($enrollFlag -band 0x2) -ne 0
            $hasClientAuth       = '1.3.6.1.5.5.7.3.2'       -in $ekus
            $hasAnyPurpose       = '2.5.29.37.0'              -in $ekus
            $hasCertReqAgent     = '1.3.6.1.4.1.311.20.2.1'  -in $ekus
            $lowPrivCanEnroll    = $false
            try {
                $sd = $tmpl.nTSecurityDescriptor
                if ($sd -and $sd.Access) {
                    foreach ($ace in $sd.Access) {
                        $id  = [string]$ace.IdentityReference
                        $isLP = $id -match 'Domain Users|Authenticated Users|Everyone|S-1-1-0|S-1-5-11'
                        $hasEx = ($ace.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight) -ne 0
                        $okObj = ($ace.ObjectType -eq $_enrollRight -or $ace.ObjectType -eq [guid]::Empty)
                        if ($isLP -and $hasEx -and $okObj -and $ace.AccessControlType -eq 'Allow') {
                            $lowPrivCanEnroll = $true; break
                        }
                    }
                }
            } catch {}
            $escs = @()
            if ($enrolleeSuppliesSAN -and $hasClientAuth -and $lowPrivCanEnroll -and -not $requiresApproval) { $escs += 'ESC1' }
            if ($hasAnyPurpose       -and $lowPrivCanEnroll -and -not $requiresApproval)                     { $escs += 'ESC2' }
            if ($hasCertReqAgent     -and $lowPrivCanEnroll -and -not $requiresApproval)                     { $escs += 'ESC3' }
            $AdcsTemplates += [PSCustomObject]@{
                Name                = [string]$tmpl.Name
                DisplayName         = [string]$tmpl.displayName
                EnrolleeSuppliesSAN = $enrolleeSuppliesSAN
                RequiresApproval    = $requiresApproval
                HasClientAuth       = $hasClientAuth
                HasAnyPurpose       = $hasAnyPurpose
                HasCertReqAgent     = $hasCertReqAgent
                LowPrivCanEnroll    = $lowPrivCanEnroll
                EscFindings         = $escs
                IsRisky             = ($escs.Count -gt 0)
            }
        }
    } catch {}

    $AdcsEscCount  = @($AdcsTemplates | Where-Object { $_.EscFindings.Count -gt 0 }).Count
    $AdcsEscCount += @($AdcsCAs | Where-Object { $_.Esc6Risk   }).Count
    $AdcsEscCount += @($AdcsCAs | Where-Object { $_.WebEnroll  }).Count

    $AdcsHealthScore = 100
    if (@($AdcsCAs | Where-Object { -not $_.Reachable }).Count -gt 0) { $AdcsHealthScore -= 30 }
    foreach ($_t in $AdcsTemplates | Where-Object { $_.IsRisky }) {
        if ('ESC1' -in $_t.EscFindings) { $AdcsHealthScore -= 20 }
        elseif ('ESC2' -in $_t.EscFindings) { $AdcsHealthScore -= 15 }
        elseif ('ESC3' -in $_t.EscFindings) { $AdcsHealthScore -= 10 }
    }
    if (@($AdcsCAs | Where-Object { $_.Esc6Risk   }).Count -gt 0) { $AdcsHealthScore -= 25 }
    if (@($AdcsCAs | Where-Object { $_.WebEnroll  }).Count -gt 0) { $AdcsHealthScore -= 10 }
    $AdcsHealthScore = [math]::Max(0,[math]::Min(100,$AdcsHealthScore))
}
$_adcsSeverity = if (-not $AdcsInstalled) { "Info" } elseif ($AdcsEscCount -gt 0) { "Critical" } else { "Low" }
Add-PingFinding -Category "Certificate Services" -Rule "ADCS PKI posture" -Severity $_adcsSeverity -Count $AdcsEscCount `
    -Sample "CA count=$($AdcsCAs.Count); ESC findings=$AdcsEscCount; Health=$AdcsHealthScore/100" `
    -Recommendation "Harden certificate templates (ESC1-8) and restrict enrollment permissions to prevent privilege escalation via ADCS."

# 40) Tier 1 - Privileged account 24h anomalies
$Priv24Rows = @()
$last24 = (Get-Date).AddHours(-24)
foreach ($ev in $UserRiskUserDeviceEvents | Where-Object { $_.TimeCreated -ge $last24 }) {
    $u = "$($ev.TargetUser)"
    if ($u -match '\\') { $u = ($u -split '\\')[-1] }
    if ($u -match '@') { $u = ($u -split '@')[0] }
    if (-not $PrivilegedSamLookup.ContainsKey($u.ToLowerInvariant())) { continue }

    $hour = if ($ev.TimeCreated) { [int]$ev.TimeCreated.Hour } else { 12 }
    $offHours = ($hour -lt 6 -or $hour -gt 20)
    if ($offHours) {
        $Priv24Rows += [PSCustomObject]@{ User = $u; Source = $ev.Source; Time = $ev.TimeCreated; Kind = "OffHours" }
    }
}
$Priv24Count = @($Priv24Rows).Count
$Priv24Severity = if ($Priv24Count -gt 0) { "High" } else { "Low" }
$Priv24Sample = if ($Priv24Count -gt 0) { (@($Priv24Rows | Select-Object -First 5 | ForEach-Object { "$($_.User) from $($_.Source)" })) -join "; " } else { "No off-hours privileged logon anomaly in last 24h" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: Privileged 24h behavior anomalies" -Severity $Priv24Severity -Count $Priv24Count -Sample $Priv24Sample -Recommendation "Investigate off-hours privileged activity and enforce just-in-time administrative sessions."

# 41) Tier 2 - Fine-grained password policy coverage
$FgppMissing = @()
try {
    $fgppPolicies = @(Get-ADFineGrainedPasswordPolicy -Filter * -ErrorAction Stop)
    if ($fgppPolicies.Count -gt 0) {
        foreach ($sam in $PrivilegedSamAccounts) {
            try {
                $rp = Get-ADUserResultantPasswordPolicy -Identity $sam -ErrorAction Stop
                if (-not $rp) { $FgppMissing += $sam }
            } catch {
                $FgppMissing += $sam
            }
        }
    }
} catch {}
$FgppCount = @($FgppMissing | Select-Object -Unique).Count
$FgppSeverity = if ($FgppCount -gt 0) { "Medium" } else { "Low" }
$FgppSample = if ($FgppCount -gt 0) { (@($FgppMissing | Select-Object -Unique | Select-Object -First 5)) -join ", " } else { "FGPP coverage appears acceptable or no FGPP configured" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier2: FGPP coverage for privileged accounts" -Severity $FgppSeverity -Count $FgppCount -Sample $FgppSample -Recommendation "Apply stricter fine-grained password policies to privileged identities."

# 42) Tier 2 - SMB/LDAP signing baseline on DCs
$SmbSigningIssues = @()
foreach ($dc in $DCs) {
    try {
        $smbReq = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            try {
                (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters' -Name RequireSecuritySignature -ErrorAction Stop).RequireSecuritySignature
            } catch { $null }
        } -ErrorAction Stop
        if ($null -eq $smbReq -or [int]$smbReq -ne 1) {
            $SmbSigningIssues += [PSCustomObject]@{ DC = $dc.Name; Value = $smbReq }
        }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "SMB Signing Baseline" -Reason $_.Exception.Message
        $SmbSigningIssues += [PSCustomObject]@{ DC = $dc.Name; Value = $null }
    }
}
$SmbLdapCount = @($SmbSigningIssues).Count + $LdapSigningCount + $LdapChannelBindingCount
$SmbLdapSeverity = if ($SmbLdapCount -gt 0) { "Medium" } else { "Low" }
$SmbLdapSample = "SMB signing issues=$(@($SmbSigningIssues).Count); LDAP signing issues=$LdapSigningCount; LDAP channel binding issues=$LdapChannelBindingCount"
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier2: SMB and LDAP signing baseline" -Severity $SmbLdapSeverity -Count $SmbLdapCount -Sample $SmbLdapSample -Recommendation "Enforce SMB signing, LDAP signing and channel binding across all domain controllers."

# 43) Tier 2 - Orphan and unlinked GPOs
$OrphanGpoCount = 0
$DisabledGpoCount = 0
$NeverLinkedGpoNames = @()
$GpoOwnerAnomalyRows = @()
$GpoWriteAbuseRows = @()
try {
    if (Get-Command Get-GPO -ErrorAction SilentlyContinue) {
        $allGpos = @(Get-GPO -All -ErrorAction Stop)
        foreach ($g in $allGpos) {
            try {
                $xml = [xml](Get-GPOReport -Guid $g.Id -ReportType Xml -ErrorAction Stop)
                $links = @($xml.GPO.LinksTo)
                if (@($links).Count -eq 0) {
                    $OrphanGpoCount++
                    $NeverLinkedGpoNames += [string]$g.DisplayName
                }
                if ($g.GpoStatus -ne "AllSettingsEnabled") { $DisabledGpoCount++ }

                try {
                    $owner = (Get-Acl ("AD:" + $g.Path)).Owner
                    if ($owner -match "Domain Users|Authenticated Users|Everyone") {
                        $GpoOwnerAnomalyRows += [PSCustomObject]@{ GPO = $g.DisplayName; Owner = $owner }
                    }
                } catch {}

                try {
                    $perms = @(Get-GPPermission -Guid $g.Id -All -ErrorAction Stop)
                    foreach ($perm in $perms) {
                        $permName = [string]$perm.Permission
                        $trusteeName = [string]$perm.Trustee.Name
                        if ([string]::IsNullOrWhiteSpace($trusteeName)) { continue }

                        $isWriteAbuse = ($permName -match "GpoEditDeleteModifySecurity|GpoEdit")
                        if (-not $isWriteAbuse) { continue }

                        $isBroadPrincipal = $trusteeName -match "Domain Users|Authenticated Users|Everyone"
                        $isTier0Admin = $trusteeName -match "Domain Admins|Enterprise Admins|Administrators|SYSTEM"

                        if ($isBroadPrincipal -or -not $isTier0Admin) {
                            $GpoWriteAbuseRows += [PSCustomObject]@{ GPO = $g.DisplayName; Trustee = $trusteeName; Permission = $permName }
                        }
                    }
                } catch {}
            } catch {}
        }
    }
} catch {}

$GpoOwnerAnomalyCount = @($GpoOwnerAnomalyRows).Count
$GpoOwnerAnomalySample = if ($GpoOwnerAnomalyCount -gt 0) {
    (@($GpoOwnerAnomalyRows | Select-Object -First 5 | ForEach-Object { "$($_.GPO):$($_.Owner)" })) -join "; "
} else {
    "No Domain Users/Authenticated Users/Everyone GPO owner anomaly"
}
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: GPO owner anomalies" -Severity $(if ($GpoOwnerAnomalyCount -gt 0) { "High" } else { "Low" }) -Count $GpoOwnerAnomalyCount -Sample $GpoOwnerAnomalySample -Recommendation "Set secure GPO ownership and remove broad principals from GPO owner chain."
foreach ($gpoOwner in $GpoOwnerAnomalyRows | Select-Object -First 40) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier1: GPO owner anomalies" -Target $gpoOwner.GPO -Detail "Owner=$($gpoOwner.Owner)" -Severity "High"
}

$GpoWriteAbuseCount = @($GpoWriteAbuseRows).Count
$GpoWriteAbuseSample = if ($GpoWriteAbuseCount -gt 0) {
    (@($GpoWriteAbuseRows | Select-Object -First 5 | ForEach-Object { "$($_.Trustee) on $($_.GPO) ($($_.Permission))" })) -join "; "
} else {
    "No risky GPO write delegation detected"
}
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: GPO write permission abuse" -Severity $(if ($GpoWriteAbuseCount -gt 0) { "High" } else { "Low" }) -Count $GpoWriteAbuseCount -Sample $GpoWriteAbuseSample -Recommendation "Remove unsafe GPO edit and modify-security rights from non-admin principals."
foreach ($gpoPerm in $GpoWriteAbuseRows | Select-Object -First 40) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier1: GPO write permission abuse" -Target $gpoPerm.GPO -Detail "Trustee=$($gpoPerm.Trustee), Permission=$($gpoPerm.Permission)" -Severity "High"
}

$GpoNoiseCount = $OrphanGpoCount + $DisabledGpoCount
$GpoNoiseSeverity = if ($GpoNoiseCount -gt 0) { "Medium" } else { "Low" }
$NeverLinkedSample = if (@($NeverLinkedGpoNames).Count -gt 0) { (@($NeverLinkedGpoNames | Select-Object -First 5)) -join ", " } else { "None" }
$GpoNoiseSample = "Unlinked (never linked) GPO=$OrphanGpoCount; Disabled/partial GPO=$DisabledGpoCount; Sample=$NeverLinkedSample"
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier2: Orphan and disabled GPO posture" -Severity $GpoNoiseSeverity -Count $GpoNoiseCount -Sample $GpoNoiseSample -Recommendation "Clean unlinked/disabled GPOs and reduce policy management noise."
foreach ($gpoName in $NeverLinkedGpoNames | Select-Object -First 40) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier2: Orphan and disabled GPO posture" -Target $gpoName -Detail "GPO has no links (never linked)" -Severity "Medium"
}

# 44) Tier 2 - Computer object owner anomalies (DC objects)
$OwnerAnomalyRows = @()
foreach ($dc in $DCs) {
    if (-not $dc.ComputerObjectDN) { continue }
    try {
        $owner = (Get-Acl -Path ("AD:" + $dc.ComputerObjectDN)).Owner
        if ($owner -notmatch "Domain Admins|Administrators|SYSTEM") {
            $OwnerAnomalyRows += [PSCustomObject]@{ DC = $dc.Name; Owner = $owner }
        }
    } catch {}
}
$OwnerAnomalyCount = @($OwnerAnomalyRows).Count
$OwnerAnomalySeverity = if ($OwnerAnomalyCount -gt 0) { "Medium" } else { "Low" }
$OwnerAnomalySample = if ($OwnerAnomalyCount -gt 0) { (@($OwnerAnomalyRows | Select-Object -First 4 | ForEach-Object { "$($_.DC):$($_.Owner)" })) -join "; " } else { "No DC computer object owner anomaly detected" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier2: Computer object owner anomalies" -Severity $OwnerAnomalySeverity -Count $OwnerAnomalyCount -Sample $OwnerAnomalySample -Recommendation "Set expected owner principals for Tier-0 computer objects and review delegated ACL changes."

# 45) Tier 2 - WinRM/RDP authorization scope on DCs
$RemoteAccessRows = @()
foreach ($dc in $DCs) {
    try {
        $groups = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            $rm = @()
            $rdp = @()
            try { $rm = net localgroup "Remote Management Users" | Out-String } catch {}
            try { $rdp = net localgroup "Remote Desktop Users" | Out-String } catch {}
            [PSCustomObject]@{ RM = $rm; RDP = $rdp }
        } -ErrorAction Stop
        $rmHits = if ($groups.RM -and $groups.RM -notmatch "There are no members") { 1 } else { 0 }
        $rdpHits = if ($groups.RDP -and $groups.RDP -notmatch "There are no members") { 1 } else { 0 }
        if (($rmHits + $rdpHits) -gt 0) {
            $RemoteAccessRows += [PSCustomObject]@{ DC = $dc.Name; RM = $rmHits; RDP = $rdpHits }
        }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "WinRM and RDP Authorization" -Reason $_.Exception.Message
    }
}
$RemoteAccessCount = @($RemoteAccessRows).Count
$RemoteAccessSeverity = if ($RemoteAccessCount -gt 0) { "Medium" } else { "Low" }
$RemoteAccessSample = if ($RemoteAccessCount -gt 0) { (@($RemoteAccessRows | Select-Object -First 4 | ForEach-Object { "$($_.DC): RM=$($_.RM),RDP=$($_.RDP)" })) -join "; " } else { "No non-empty Remote Management/Remote Desktop local groups detected on sampled DCs" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier2: WinRM and RDP authorization scope" -Severity $RemoteAccessSeverity -Count $RemoteAccessCount -Sample $RemoteAccessSample -Recommendation "Limit WinRM/RDP local group membership on domain controllers to approved admins only."

# 46) Tier 2 - CredSSP usage exposure
$CredSspRows = @()
foreach ($dc in $DCs) {
    try {
        $credSspEnabled = Invoke-Command -ComputerName $dc.Name -ScriptBlock {
            try {
                $v = (Get-Item -Path WSMan:\localhost\Service\Auth\CredSSP -ErrorAction Stop).Value
                if ("$v" -eq "true") { return $true }
            } catch {}
            return $false
        } -ErrorAction Stop
        if ($credSspEnabled) { $CredSspRows += $dc.Name }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "CredSSP Exposure" -Reason $_.Exception.Message
    }
}
$CredSspCount = @($CredSspRows).Count
$CredSspSeverity = if ($CredSspCount -gt 0) { "Medium" } else { "Low" }
$CredSspSample = if ($CredSspCount -gt 0) { ($CredSspRows | Select-Object -First 5) -join ", " } else { "No CredSSP enabled DC detected" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier2: CredSSP exposure" -Severity $CredSspSeverity -Count $CredSspCount -Sample $CredSspSample -Recommendation "Disable CredSSP where not required and prefer Kerberos constrained delegation patterns."

# 47b) Tier0: SMBv1 enabled on DC
$Smb1DCs = @()
$_localHost = $env:COMPUTERNAME
foreach ($dc in $DCs) {
    $dcShort = ($dc.Name -split '\.')[0]
    try {
        $smb1Val = $null
        if ($dcShort -ieq $_localHost) {
            try { $smb1Val = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters' -Name SMB1 -EA Stop).SMB1 } catch {}
        } else {
            try {
                $wmireg = [wmiclass]"\\$($dc.Name)\root\default:StdRegProv"
                $r = $wmireg.GetDWORDValue(2147483650, "SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters", "SMB1")
                if ($r.ReturnValue -eq 0) { $smb1Val = $r.uValue }
            } catch {}
        }
        if ($null -ne $smb1Val -and [int]$smb1Val -eq 1) {
            $Smb1DCs += $dc.Name
        }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "SMBv1 Check" -Reason $_.Exception.Message
    }
}
$Smb1Count = @($Smb1DCs).Count
$Smb1Severity = if ($Smb1Count -gt 0) { "Critical" } else { "Low" }
$Smb1Sample = if ($Smb1Count -gt 0) { ($Smb1DCs | Select-Object -First 5) -join ", " } else { "No DC with SMBv1 enabled detected" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: SMBv1 enabled on DC" -Severity $Smb1Severity -Count $Smb1Count -Sample $Smb1Sample -Recommendation "Disable SMBv1 on all domain controllers immediately — set SMB1=0 in LanmanServer Parameters and disable the Windows feature."
foreach ($item in $Smb1DCs | Select-Object -First 20) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: SMBv1 enabled on DC" -Target $item -Detail "SMBv1 registry key = 1 (enabled)" -Severity "Critical"
}

# 47c) Tier0: WDigest + Tier0: LSA Protection + Tier1: Credential Guard
# Uses direct registry for local DC and WMI StdRegProv for remote DCs to avoid double-hop auth failure.
$WDigestRows = @()
$LsaProtectionRows = @()
$CredGuardRows = @()

foreach ($dc in $DCs) {
    $dcShort = ($dc.Name -split '\.')[0]
    $isLocal = ($dcShort -ieq $_localHost)
    try {
        $wdigest   = $null
        $lsaPPL    = $null
        $credGuard = $false

        if ($isLocal) {
            try { $wdigest  = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest' -Name UseLogonCredential -EA Stop).UseLogonCredential } catch {}
            try { $lsaPPL   = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name RunAsPPL -EA Stop).RunAsPPL } catch {}
            try {
                $dg = Get-CimInstance Win32_DeviceGuard -Namespace root\Microsoft\Windows\DeviceGuard -EA Stop
                if ($dg -and @($dg.SecurityServicesRunning) -contains 1) { $credGuard = $true }
            } catch {}
        } else {
            try {
                $HKLM = 2147483650
                $wmireg = [wmiclass]"\\$($dc.Name)\root\default:StdRegProv"
                $r = $wmireg.GetDWORDValue($HKLM, "SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest", "UseLogonCredential")
                if ($r.ReturnValue -eq 0) { $wdigest = $r.uValue }
                $r = $wmireg.GetDWORDValue($HKLM, "SYSTEM\CurrentControlSet\Control\Lsa", "RunAsPPL")
                if ($r.ReturnValue -eq 0) { $lsaPPL = $r.uValue }
            } catch {}
            try {
                $dg = Get-CimInstance Win32_DeviceGuard -Namespace root\Microsoft\Windows\DeviceGuard -ComputerName $dc.Name -EA Stop
                if ($dg -and @($dg.SecurityServicesRunning) -contains 1) { $credGuard = $true }
            } catch {}
        }

        if ($null -ne $wdigest -and [int]$wdigest -eq 1) {
            $WDigestRows += [PSCustomObject]@{ DC = $dc.Name; Value = $wdigest }
        }
        if ($null -eq $lsaPPL -or [int]$lsaPPL -lt 1) {
            $LsaProtectionRows += [PSCustomObject]@{ DC = $dc.Name; Value = $lsaPPL }
        }
        if (-not $credGuard) {
            $CredGuardRows += $dc.Name
        }
    } catch {
        Add-SkippedDCRecord -DC $dc.Name -Section "Credential Theft Hardening" -Reason $_.Exception.Message
    }
}

$WDigestCount    = @($WDigestRows).Count
$WDigestSeverity = if ($WDigestCount -gt 0) { "Critical" } else { "Low" }
$WDigestSample   = if ($WDigestCount -gt 0) { ($WDigestRows | Select-Object -First 5 | ForEach-Object { $_.DC }) -join ", " } else { "No DC with WDigest plaintext credentials enabled" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: WDigest plaintext credentials" -Severity $WDigestSeverity -Count $WDigestCount -Sample $WDigestSample -Recommendation "Set UseLogonCredential=0 in HKLM\...\WDigest on all DCs — prevents Mimikatz from extracting cleartext passwords from LSASS."
foreach ($row in $WDigestRows | Select-Object -First 20) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: WDigest plaintext credentials" -Target $row.DC -Detail "UseLogonCredential = 1 (plaintext credentials stored in LSASS)" -Severity "Critical"
}

$LsaProtectionCount    = @($LsaProtectionRows).Count
$LsaProtectionSeverity = if ($LsaProtectionCount -gt 0) { "High" } else { "Low" }
$LsaProtectionSample   = if ($LsaProtectionCount -gt 0) { ($LsaProtectionRows | Select-Object -First 5 | ForEach-Object { "$($_.DC): RunAsPPL=$($_.Value)" }) -join "; " } else { "LSA Protection (RunAsPPL) enabled on all reachable DCs" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: LSA Protection disabled" -Severity $LsaProtectionSeverity -Count $LsaProtectionCount -Sample $LsaProtectionSample -Recommendation "Enable RunAsPPL=1 on all DCs to prevent LSASS credential dumping — requires reboot to activate."
foreach ($row in $LsaProtectionRows | Select-Object -First 20) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: LSA Protection disabled" -Target $row.DC -Detail "RunAsPPL = $($row.Value) (LSASS not protected against credential dumping)" -Severity "High"
}

$CredGuardCount    = @($CredGuardRows).Count
$CredGuardSeverity = if ($CredGuardCount -gt 0) { "Medium" } else { "Low" }
$CredGuardSample   = if ($CredGuardCount -gt 0) { ($CredGuardRows | Select-Object -First 5) -join ", " } else { "Credential Guard running on all sampled DCs" }
Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: Credential Guard absent" -Severity $CredGuardSeverity -Count $CredGuardCount -Sample $CredGuardSample -Recommendation "Enable Virtualization-Based Security and Credential Guard on DCs running Windows Server 2016+ to isolate LSASS into a hypervisor-protected container."
foreach ($item in $CredGuardRows | Select-Object -First 20) {
    Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier1: Credential Guard absent" -Target $item -Detail "Credential Guard not running on this DC" -Severity "Medium"
}

# 47) ADCS / PKI - ESC checks
$CaServers = @()
try {
    $enrollmentBase = "CN=Enrollment Services,CN=Public Key Services,CN=Services,$($ForestInfo.ConfigurationNamingContext)"
    $CaServers = @(
        Get-ADObject -SearchBase $enrollmentBase -LDAPFilter "(objectClass=pKIEnrollmentService)" -Properties dNSHostName,cn -ErrorAction Stop |
            ForEach-Object {
                if ($_.dNSHostName) { [string]$_.dNSHostName } elseif ($_.cn) { [string]$_.cn } else { $null }
            } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
            Sort-Object -Unique
    )
} catch {
    $CaServers = @()
}

# ESC1 / ESC4 on certificate templates
try {
    $templatesBase = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$($ForestInfo.ConfigurationNamingContext)"
    $CertTemplates = @(Get-ADObject -SearchBase $templatesBase -Filter * -Properties msPKI-Certificate-Name-Flag,msPKI-Enrollment-Flag,msPKI-RA-Signature,pkiExtendedKeyUsage,nTSecurityDescriptor,displayName -ErrorAction Stop)

    $Esc1Rows = @()
    $Esc4Rows = @()
    foreach ($t in $CertTemplates) {
        $ekuList = @($t.pkiExtendedKeyUsage)
        $nameFlag = 0
        $enrollmentFlag = 0
        try { $nameFlag = [int]$t.'msPKI-Certificate-Name-Flag' } catch { $nameFlag = 0 }
        try { $enrollmentFlag = [int]$t.'msPKI-Enrollment-Flag' } catch { $enrollmentFlag = 0 }

        $esc1Matched = (($nameFlag -band 0x00000001) -ne 0) -and (($enrollmentFlag -band 0x00000020) -ne 0) -and (('1.3.6.1.5.5.7.3.2' -in $ekuList) -or ('2.5.29.37.0' -in $ekuList))
        if ($esc1Matched) {
            $Esc1Rows += [PSCustomObject]@{ Template = [string]$t.DisplayName; NameFlag = $nameFlag; EnrollmentFlag = $enrollmentFlag }
        }

        $acl = $null
        try { $acl = $t.nTSecurityDescriptor } catch { $acl = $null }
        if ($acl -and $acl.DiscretionaryAcl) {
            foreach ($ace in $acl.DiscretionaryAcl) {
                $sidValue = ""
                try { $sidValue = [string]$ace.SecurityIdentifier.Value } catch { $sidValue = "" }
                $isBroadPrincipal = ($sidValue -eq 'S-1-1-0' -or $sidValue -eq 'S-1-5-11' -or $sidValue -match '-513$')
                if (-not $isBroadPrincipal) { continue }

                $rights = $ace.ActiveDirectoryRights
                $hasDangerousRight = ($rights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteDacl) -or ($rights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner) -or ($rights -band [System.DirectoryServices.ActiveDirectoryRights]::GenericAll) -or ($rights -band [System.DirectoryServices.ActiveDirectoryRights]::GenericWrite)
                if ($hasDangerousRight) {
                    $Esc4Rows += [PSCustomObject]@{
                        Template = [string]$t.DisplayName
                        PrincipalSid = $sidValue
                        Rights = [string]$rights
                    }
                }
            }
        }
    }

    $Esc1Count = @($Esc1Rows).Count
    $Esc1Sample = if ($Esc1Count -gt 0) { (@($Esc1Rows | Select-Object -First 5 | ForEach-Object { $_.Template })) -join ", " } else { "No ESC1 pattern detected" }
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: ESC1 - Enrollee supplies subject" -Severity $(if ($Esc1Count -gt 0) { "Critical" } else { "Low" }) -Count $Esc1Count -Sample $Esc1Sample -Recommendation "Disable enrollee supplied subject and tighten authentication template controls."
    foreach ($r in $Esc1Rows | Select-Object -First 40) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: ESC1 - Enrollee supplies subject" -Target $r.Template -Detail "NameFlag=$($r.NameFlag), EnrollmentFlag=$($r.EnrollmentFlag)" -Severity "Critical"
    }

    $Esc4Count = @($Esc4Rows).Count
    $Esc4Sample = if ($Esc4Count -gt 0) { (@($Esc4Rows | Select-Object -First 5 | ForEach-Object { "$($_.Template):$($_.PrincipalSid)" })) -join "; " } else { "No ESC4 ACL write-abuse pattern detected" }
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: ESC4 - Template ACL write abuse" -Severity $(if ($Esc4Count -gt 0) { "Critical" } else { "Low" }) -Count $Esc4Count -Sample $Esc4Sample -Recommendation "Remove template write/owner/ACL rights from broad principals and enforce PKI least privilege."
    foreach ($r in $Esc4Rows | Select-Object -First 40) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: ESC4 - Template ACL write abuse" -Target $r.Template -Detail "Principal SID=$($r.PrincipalSid), Rights=$($r.Rights)" -Severity "Critical"
    }
} catch {
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: ESC1 - Enrollee supplies subject" -Severity "Low" -Count 0 -Sample "Check could not be completed" -Recommendation "Control unavailable: verify certificate template ESC1 conditions manually."
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: ESC4 - Template ACL write abuse" -Severity "Low" -Count 0 -Sample "Check could not be completed" -Recommendation "Control unavailable: review template ACL permissions manually."
}

# ESC6 registry flag on CA servers
try {
    $Esc6Rows = @()
    foreach ($ca in $CaServers) {
        try {
            $esc6Flag = Invoke-Command -ComputerName $ca -ScriptBlock {
                (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\CertSvc\Configuration\*" -ErrorAction SilentlyContinue).EditFlags -band 0x00040000
            } -ErrorAction Stop

            $flagEnabled = $false
            if ($esc6Flag -is [array]) {
                $flagEnabled = @($esc6Flag | Where-Object { [int]$_ -ne 0 }).Count -gt 0
            } elseif ($null -ne $esc6Flag) {
                $flagEnabled = ([int]$esc6Flag -ne 0)
            }

            if ($flagEnabled) {
                $Esc6Rows += [PSCustomObject]@{ CAServer = $ca }
            }
        } catch {
            Add-SkippedDCRecord -DC $ca -Section "ADCS ESC6" -Reason $_.Exception.Message
        }
    }

    $Esc6Count = @($Esc6Rows).Count
    $Esc6Sample = if ($Esc6Count -gt 0) { (@($Esc6Rows | Select-Object -First 5 -ExpandProperty CAServer)) -join ", " } else { "No ESC6 flag detected on reachable CA servers" }
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: ESC6 - SAN attribute injection flag" -Severity $(if ($Esc6Count -gt 0) { "Critical" } else { "Low" }) -Count $Esc6Count -Sample $Esc6Sample -Recommendation "Disable EDITF_ATTRIBUTESUBJECTALTNAME2 on enterprise CAs unless strictly required and governed."
    foreach ($r in $Esc6Rows | Select-Object -First 40) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier0: ESC6 - SAN attribute injection flag" -Target $r.CAServer -Detail "EDITF_ATTRIBUTESUBJECTALTNAME2 is enabled" -Severity "Critical"
    }
} catch {
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier0: ESC6 - SAN attribute injection flag" -Severity "Low" -Count 0 -Sample "Check could not be completed" -Recommendation "Control unavailable: verify CA EditFlags manually."
}

# ESC8 web enrollment relay surface
try {
    $Esc8Rows = @()
    foreach ($ca in $CaServers) {
        $portReachable = $false
        $urlHit = $false
        try {
            $t80 = Test-NetConnection -ComputerName $ca -Port 80 -WarningAction SilentlyContinue
            if ($t80 -and $t80.TcpTestSucceeded) { $portReachable = $true }
        } catch {}
        if (-not $portReachable) {
            try {
                $t443 = Test-NetConnection -ComputerName $ca -Port 443 -WarningAction SilentlyContinue
                if ($t443 -and $t443.TcpTestSucceeded) { $portReachable = $true }
            } catch {}
        }

        if ($portReachable) {
            try {
                $resp = Invoke-WebRequest -Uri ("http://{0}/certsrv/" -f $ca) -UseBasicParsing -Method Get -TimeoutSec 6 -ErrorAction Stop
                if ($resp -and $resp.StatusCode -ge 200 -and $resp.StatusCode -lt 500) { $urlHit = $true }
            } catch {
                try {
                    $respTls = Invoke-WebRequest -Uri ("https://{0}/certsrv/" -f $ca) -UseBasicParsing -Method Get -TimeoutSec 6 -ErrorAction Stop
                    if ($respTls -and $respTls.StatusCode -ge 200 -and $respTls.StatusCode -lt 500) { $urlHit = $true }
                } catch {
                    Add-SkippedDCRecord -DC $ca -Section "ADCS ESC8" -Reason $_.Exception.Message
                }
            }
        }

        if ($portReachable -and $urlHit) {
            $Esc8Rows += [PSCustomObject]@{ CAServer = $ca }
        }
    }

    $Esc8Count = @($Esc8Rows).Count
    $Esc8Sample = if ($Esc8Count -gt 0) { (@($Esc8Rows | Select-Object -First 5 -ExpandProperty CAServer)) -join ", " } else { "No reachable AD CS /certsrv endpoint detected" }
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: ESC8 - AD CS HTTP relay surface" -Severity $(if ($Esc8Count -gt 0) { "High" } else { "Low" }) -Count $Esc8Count -Sample $Esc8Sample -Recommendation "Limit or disable AD CS web enrollment and harden NTLM relay protections on CA web endpoints."
    foreach ($r in $Esc8Rows | Select-Object -First 40) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Tier1: ESC8 - AD CS HTTP relay surface" -Target $r.CAServer -Detail "HTTP(S) /certsrv endpoint reachable" -Severity "High"
    }
} catch {
    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Tier1: ESC8 - AD CS HTTP relay surface" -Severity "Low" -Count 0 -Sample "Check could not be completed" -Recommendation "Control unavailable: validate CA HTTP enrollment exposure manually."
}

# 48) Azure AD Connect / MSOL_ sync account exposure
$MsolAccounts = @($AllUsersRaw | Where-Object { $_.SamAccountName -match '^(MSOL_|Sync_|AAD_|AADC_)' })
$MsolPwdNeverExpires = @($MsolAccounts | Where-Object { $_.PasswordNeverExpires -eq $true })
$MsolCount = @($MsolAccounts).Count
$MsolSample = if ($MsolCount -gt 0) { ($MsolAccounts | Select-Object -First 4 -ExpandProperty SamAccountName) -join ", " } else { "No Azure AD Connect sync account detected" }
$MsolSeverity = if ($MsolPwdNeverExpires.Count -gt 0) { "High" } elseif ($MsolCount -gt 0) { "Medium" } else { "Low" }
Add-PingFinding -Category "Hygiene" -Rule "Azure AD Connect sync account exposure" -Severity $MsolSeverity -Count $MsolCount -Sample $MsolSample -Recommendation "Ensure MSOL_/Sync_ accounts have minimal permissions, verify no DCSync rights are granted, and restrict logon to the AD Connect server only."
foreach ($m in $MsolAccounts | Select-Object -First 20) {
    $mDetail = if ($m.PasswordNeverExpires) { "PasswordNeverExpires=True — verify DCSync rights and restrict logon workstations" } else { "Sync account present — verify permissions scope" }
    Add-PingDetail -Category "Hygiene" -Rule "Azure AD Connect sync account exposure" -Target $m.SamAccountName -Detail $mDetail -Severity $MsolSeverity
}

# 49) Domain / Forest Functional Level risk scoring
$DflRaw = if ($DomainInfo) { [string]$DomainInfo.DomainMode } else { "" }
$FflRaw = if ($ForestInfo) { [string]$ForestInfo.ForestMode } else { "" }
$DflRiskLevel = switch -Wildcard ($DflRaw) {
    "*2003*" { "Critical" }
    "*2008*" { "High"     }
    "*2012*" { "Medium"   }
    default  { "Low"      }
}
$FflRiskLevel = switch -Wildcard ($FflRaw) {
    "*2003*" { "Critical" }
    "*2008*" { "High"     }
    "*2012*" { "Medium"   }
    default  { "Low"      }
}
$FlSeverityOrder = @{ "Critical"=4; "High"=3; "Medium"=2; "Low"=1 }
$FlSeverity = if ($FlSeverityOrder[$DflRiskLevel] -ge $FlSeverityOrder[$FflRiskLevel]) { $DflRiskLevel } else { $FflRiskLevel }
$FlCount = if ($FlSeverity -ne "Low") { 1 } else { 0 }
$FlSample = "DFL: $DFL | FFL: $FFL"
Add-PingFinding -Category "Hygiene" -Rule "Domain/Forest Functional Level" -Severity $FlSeverity -Count $FlCount -Sample $FlSample -Recommendation "Raise DFL and FFL to Windows Server 2016+ to enable Protected Users improvements, Kerberos armoring, and deprecate legacy authentication paths."
if ($FlSeverity -ne "Low") {
    Add-PingDetail -Category "Hygiene" -Rule "Domain/Forest Functional Level" -Target "DFL" -Detail "$DFL — upgrade recommended for full modern security feature support" -Severity $FlSeverity
    Add-PingDetail -Category "Hygiene" -Rule "Domain/Forest Functional Level" -Target "FFL" -Detail "$FFL — upgrade recommended for full modern security feature support" -Severity $FlSeverity
}

# 50) Fine-Grained Password Policies (PSO) inventory
$AllFgppPolicies = @()
try {
    $AllFgppPolicies = @(Get-ADFineGrainedPasswordPolicy -Filter * -Properties Name,Precedence,MinPasswordLength,PasswordHistoryCount,MaxPasswordAge,MinPasswordAge,LockoutDuration,LockoutObservationWindow,LockoutThreshold,ComplexityEnabled,ReversibleEncryptionEnabled,AppliesTo -ErrorAction Stop)
} catch {
    $AllFgppPolicies = @()
}
$PsoCount = @($AllFgppPolicies).Count
$PsoSample = if ($PsoCount -gt 0) {
    ($AllFgppPolicies | Sort-Object Precedence | Select-Object -First 3 | ForEach-Object { "$($_.Name)(P=$($_.Precedence))" }) -join ", "
} else {
    "No PSO configured — default domain policy applies to all"
}
Add-PingFinding -Category "Hygiene" -Rule "Fine-Grained Password Policies (PSO)" -Severity "Low" -Count $PsoCount -Sample $PsoSample -Recommendation "Review all PSOs and ensure privileged account groups have stricter policies than the default domain policy."
foreach ($pso in $AllFgppPolicies | Sort-Object Precedence) {
    $psoDetail = "MinLen=$($pso.MinPasswordLength), MaxAge=$([string]$pso.MaxPasswordAge), Complexity=$($pso.ComplexityEnabled), Precedence=$($pso.Precedence), Targets=$(@($pso.AppliesTo).Count)"
    Add-PingDetail -Category "Hygiene" -Rule "Fine-Grained Password Policies (PSO)" -Target $pso.Name -Detail $psoDetail -Severity "Low"
}

# 51) Hybrid / Entra join coverage
$EntraDeviceCount = 0
$EntraContainerExists = $false
try {
    if ($DomainInfo) {
        $registeredDevicesBase = "CN=RegisteredDevices,$($DomainInfo.DistinguishedName)"
        $EntraDevices = @(Get-ADObject -SearchBase $registeredDevicesBase -Filter * -ResultSetSize $null -ErrorAction Stop)
        $EntraDeviceCount = @($EntraDevices).Count
        $EntraContainerExists = $true
    }
} catch {
    $EntraDeviceCount = 0
    $EntraContainerExists = $false
}
$TotalComputerCount = @($AllComputers).Count
$EntraHybridRatio = if ($TotalComputerCount -gt 0 -and $EntraDeviceCount -gt 0) { [int](($EntraDeviceCount / $TotalComputerCount) * 100) } else { 0 }
if ($EntraContainerExists) {
    $EntraSeverity = if ($EntraDeviceCount -eq 0 -and $MsolCount -gt 0) { "Medium" } else { "Low" }
    $EntraSample = "Hybrid-joined: $EntraDeviceCount / $TotalComputerCount computers ($EntraHybridRatio%)"
} else {
    $EntraSeverity = "Low"
    $EntraSample = "No RegisteredDevices container — hybrid join not configured or not in use"
}
Add-PingFinding -Category "Hygiene" -Rule "Hybrid/Entra join coverage" -Severity $EntraSeverity -Count $EntraDeviceCount -Sample $EntraSample -Recommendation "If Azure AD Connect is deployed, verify all target computers are hybrid-joined and monitor device registration health in Entra portal."
if ($EntraContainerExists -and $EntraDeviceCount -gt 0) {
    Add-PingDetail -Category "Hygiene" -Rule "Hybrid/Entra join coverage" -Target "RegisteredDevices" -Detail "$EntraDeviceCount devices registered ($EntraHybridRatio% of $TotalComputerCount computers)" -Severity "Low"
}

# Privileged groups and critical infrastructure are also scored as part of AD Risk Dashboard
$PrivilegedRiskRows = @($PrivilegedGroupReviewRows + $CriticalInfrastructureRows)
foreach ($row in $PrivilegedRiskRows) {
    $severity = Get-PrioritySeverity $row.Priority
    $usersCount = Get-IntOrZero $row.UsersMember
    $computerCount = Get-IntOrZero $row.ComputersMember
    $indirectCount = Get-IntOrZero $row.IndirectControl
    $unresolvedCount = Get-IntOrZero $row.UnresolvedMembers
    $exposureCount = $usersCount + $computerCount + $indirectCount + $unresolvedCount

    if (-not $row.Exists) {
        if ($severity -eq "Low") { $severity = "Medium" }
        if ($exposureCount -lt 1) { $exposureCount = 1 }
    }

    $sample = if (-not $row.Exists) {
        "Object not found or inaccessible"
    } else {
        "Users=$usersCount, Computers=$computerCount, Indirect=$indirectCount, Unresolved=$unresolvedCount"
    }

    Add-PingFinding -Category "Privileged Infrastructure" -Rule "Privileged Review: $($row.ObjectName)" -Severity $severity -Count $exposureCount -Sample $sample -Recommendation $row.Analysis

    if (-not $row.Exists) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Privileged Review: $($row.ObjectName)" -Target $row.ObjectName -Detail "Object could not be validated in directory" -Severity $severity
        continue
    }

    if ($usersCount -gt 0) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Privileged Review: $($row.ObjectName)" -Target $row.ObjectName -Detail "User members: $usersCount" -Severity $severity
    }
    if ($computerCount -gt 0) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Privileged Review: $($row.ObjectName)" -Target $row.ObjectName -Detail "Computer members: $computerCount" -Severity $severity
    }
    if ($indirectCount -gt 0) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Privileged Review: $($row.ObjectName)" -Target $row.ObjectName -Detail "Indirect control groups: $indirectCount" -Severity $severity
    }
    if ($unresolvedCount -gt 0) {
        Add-PingDetail -Category "Privileged Infrastructure" -Rule "Privileged Review: $($row.ObjectName)" -Target $row.ObjectName -Detail "Unresolved members: $unresolvedCount" -Severity $severity
    }
}

# Risk score model (PingCastle-like weighted summary)
$PingScoreCategoriesAll = @("Stale Objects", "Privileged Accounts", "Privileged Infrastructure", "Trusts", "Anomalies", "Hygiene")
$PingScoreCategoriesPrimary = @("Stale Objects", "Privileged Accounts", "Privileged Infrastructure", "Trusts", "Anomalies")
$PingCategoryScoreMap = @{}
$PingCategoryMatchedCountMap = @{}
$PingCategoryFindingsSortedMap = @{}
$CategoryPenaltyMap = @{}

foreach ($cat in $PingScoreCategoriesAll) {
    $catFindings = @($PingCastleFindings | Where-Object { $_.Category -eq $cat })
    $PingCategoryFindingsSortedMap[$cat] = @(
        $catFindings | Sort-Object @{ Expression = { Get-PingSeverityRank $_.Severity }; Descending = $true }, Rule
    )

    $catMatched = @($catFindings | Where-Object { Test-PingFindingMatched $_ })
    $PingCategoryMatchedCountMap[$cat] = $catMatched.Count

    if ($catMatched.Count -eq 0) {
        $PingCategoryScoreMap[$cat] = 0
    } else {
        $catScore = ($catMatched | ForEach-Object { Get-PingSeverityScore $_.Severity } | Measure-Object -Maximum).Maximum
        $PingCategoryScoreMap[$cat] = [int]$catScore
    }

    $CategoryPenaltyMap[$cat] = 0
}

$ScoreWeights = @{ "Critical" = 30; "High" = 15; "Medium" = 10; "Low" = 5 }

# PingCastle exact point overrides — each rule maps to its exact PingCastle point value
$PingPointOverrideMap = @{
    # Anomalies
    "krbtgt password age"                                    = 30
    "AD backup age"                                          = 15
    "DC audit posture"                                       = 10
    "DC coercion exposure"                                   = 10
    "DC spooler exposure"                                    = 10
    "Minimum password length"                                = 10
    "Hardened UNC paths not enforced"                        = 5
    "LDAP signing posture"                                   = 5
    "Pre-Windows 2000 compatible access members"             = 2
    "LLMNR not disabled via GPO"                             = 0
    "PowerShell script block logging not enabled"            = 0
    "CVE-2021-42291 dsHeuristics mitigation not applied"     = 0
    "No Fine-Grained Password Policy (PSO 20+ chars)"        = 0
    "Anonymous LDAP binding (rootDse) enabled"               = 0
    # Privileged Accounts
    "Native admin recent login"                              = 20
    "Privileged accounts delegatable"                        = 20
    "DA accounts with password never expires"                = 15
    "Schema Admins populated"                                = 10
    "Recycle Bin disabled"                                   = 10
    "Protected Users coverage"                               = 10
    "OUs without deletion protection"                        = 5
    "Admin accounts with email defined"                      = 5
    # Stale Objects
    "Old NTLM posture"                                       = 15
    "Inactive user accounts"                                 = 10
    "Machine account quota"                                  = 10
    "Kerberos armoring not configured"                       = 5
    "Obsolete Windows versions"                              = 5
    "DC subnet registration"                                 = 5
    "Password never expires (enabled users)"                 = 1
}

$RawPenalty = (
    $PingCastleFindings |
        Where-Object {
            $tmpVal = 0.0
            $cmp = (Get-CountComparableValue $_.Count)
            [void][double]::TryParse([string]$cmp, [ref]$tmpVal)
            $tmpVal -gt 0
        } |
        ForEach-Object {
            $pts = if ($PingPointOverrideMap.ContainsKey($_.Rule)) {
                [int]$PingPointOverrideMap[$_.Rule]
            } else { 0 }
            $CategoryPenaltyMap[$_.Category] = [int]($CategoryPenaltyMap[$_.Category]) + $pts
            $pts
        } |
        Measure-Object -Sum
).Sum
if ($null -eq $RawPenalty) { $RawPenalty = 0 }

$CategoryThresholdMap = @{
    "Stale Objects" = 80
    "Privileged Accounts" = 100
    "Privileged Infrastructure" = 120
    "Trusts" = 60
    "Anomalies" = 80
    "Hygiene" = 60
}

$CategoryWeightMap = @{
    "Stale Objects" = 20
    "Privileged Accounts" = 20
    "Privileged Infrastructure" = 20
    "Trusts" = 20
    "Anomalies" = 20
}

$CategoryRiskPctMap = @{}
foreach ($cat in $PingScoreCategoriesAll) {
    $catPenalty = [double]$CategoryPenaltyMap[$cat]
    $catRiskPct = [math]::Round([math]::Min(100.0, [math]::Max(0.0, $catPenalty)), 1)
    $CategoryRiskPctMap[$cat] = $catRiskPct
}

$DomainRiskScore = [int][math]::Round(
    (@("Stale Objects", "Privileged Accounts", "Trusts", "Anomalies") | ForEach-Object { [double]$CategoryRiskPctMap[$_] } | Measure-Object -Maximum).Maximum,
    0
)
$DomainRiskScore = [Math]::Max(0, [Math]::Min(100, $DomainRiskScore))

# KusoADCheck extended score for Privileged Infrastructure (not part of PingCastle domain score)
$_privInfraMatched = @($PingCastleFindings | Where-Object { $_.Category -eq "Privileged Infrastructure" -and (Test-PingFindingMatched $_) })
$_privInfraExtPenalty = (
    $_privInfraMatched | ForEach-Object {
        if ($ScoreWeights.ContainsKey($_.Severity)) { [int]$ScoreWeights[$_.Severity] } else { 0 }
    } | Measure-Object -Sum
).Sum
if ($null -eq $_privInfraExtPenalty) { $_privInfraExtPenalty = 0 }
$PrivInfraExtScore = [Math]::Min(100, [int]$_privInfraExtPenalty)

$RiskRating = switch ($DomainRiskScore) {
    { $_ -ge 80 } { "Critical" }
    { $_ -ge 60 } { "Poor" }
    { $_ -ge 40 } { "Acceptable" }
    default { "Good" }
}

$SkippedControlCount = @($SkippedDCs).Count
$SkippedHostCount = @(
    @($SkippedDCs |
        ForEach-Object { [string]$_.DC } |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
        Select-Object -Unique)
).Count

if ($SkippedControlCount -eq 0) {
    $RiskConfidenceLevel = "High"
    $RiskConfidenceNote = "No skipped/unreachable control execution detected."
} elseif ($SkippedControlCount -le 5) {
    $RiskConfidenceLevel = "Medium"
    $RiskConfidenceNote = "Some controls were skipped ($SkippedControlCount controls on $SkippedHostCount host(s)); review skipped checks before final sign-off."
} else {
    $RiskConfidenceLevel = "Low"
    $RiskConfidenceNote = "Many controls were skipped ($SkippedControlCount controls on $SkippedHostCount host(s)); risk score may be optimistic until connectivity is restored."
}

$PingGlobalRiskScore = $DomainRiskScore
$CategoryPenaltyRows = @($PingScoreCategoriesAll | ForEach-Object {
    [PSCustomObject]@{
        Category = $_
        Penalty = [int]($CategoryPenaltyMap[$_])
        Matched = [int]($PingCategoryMatchedCountMap[$_])
        RiskPct = [double]($CategoryRiskPctMap[$_])
    }
})
$CategoryPenaltyRows = @($CategoryPenaltyRows | Sort-Object -Property Penalty -Descending)

$RemediationCategoryActionMap = @{
    "Privileged Infrastructure" = "Harden Tier-0 assets first: lock down Domain Controllers, sensitive groups, and certificate infrastructure delegation."
    "Privileged Accounts" = "Reduce standing privilege: remove unnecessary admin rights, enforce PAW/JIT model, and rotate privileged credentials."
    "Anomalies" = "Investigate unusual identity/permission patterns and close unintended paths that allow privilege escalation."
    "Trusts" = "Review trust direction/filtering and remove legacy or overly permissive trust configurations."
    "Stale Objects" = "Disable and clean stale users/computers after business validation to shrink attack surface."
    "Hygiene" = "Improve baseline hygiene: enforce naming/ownership standards, remove orphaned settings, and maintain secure defaults."
}

$TopRiskCategories = @(
    $CategoryPenaltyRows |
        Where-Object { [double]$_.RiskPct -gt 0 } |
        Sort-Object @{ Expression = { [double]$_.RiskPct }; Descending = $true }, @{ Expression = { [int]$_.Matched }; Descending = $true } |
        Select-Object -First 3
)

$TopRiskCategorySummary = if ($TopRiskCategories.Count -gt 0) {
    ($TopRiskCategories | ForEach-Object { "{0} ({1}%)" -f $_.Category, $_.RiskPct }) -join ", "
} else {
    "No active risk pressure detected in scored categories."
}

$QuickRemediationItems = @()
foreach ($catRow in $TopRiskCategories) {
    $catName = [string]$catRow.Category
    $nextAction = if ($RemediationCategoryActionMap.ContainsKey($catName)) {
        [string]$RemediationCategoryActionMap[$catName]
    } else {
        "Review findings in this category and apply least-privilege and hardening controls."
    }

    $QuickRemediationItems += [PSCustomObject]@{
        Category = $catName
        RiskPct = [double]$catRow.RiskPct
        Action = $nextAction
    }
}

$PriorityRiskFindings = @(
    $PingCastleFindings |
        Where-Object {
            (Test-PingFindingMatched $_) -and ($_.Severity -eq "Critical" -or $_.Severity -eq "High")
        } |
        Sort-Object @{ Expression = { Get-PingSeverityRank $_.Severity }; Descending = $true }, @{ Expression = {
            $tmpCount = 0
            [void][int]::TryParse([string]$_.Count, [ref]$tmpCount)
            $tmpCount
        }; Descending = $true } |
        Select-Object -First 5
)

$QuickRemediationJson = @($QuickRemediationItems) | ConvertTo-Json -Depth 5 -Compress
if ([string]::IsNullOrWhiteSpace($QuickRemediationJson)) { $QuickRemediationJson = "[]" }
$PriorityRiskFindingsJson = @($PriorityRiskFindings) | ConvertTo-Json -Depth 6 -Compress
if ([string]::IsNullOrWhiteSpace($PriorityRiskFindingsJson)) { $PriorityRiskFindingsJson = "[]" }


$AttackChainNodes = @()
foreach ($f in ($PriorityRiskFindings | Select-Object -First 6)) {
    $AttackChainNodes += [PSCustomObject]@{
        Category = [string]$f.Category
        Rule = [string]$f.Rule
        Severity = [string]$f.Severity
    }
}
$AttackChainNodesJson = @($AttackChainNodes) | ConvertTo-Json -Depth 6 -Compress
if ([string]::IsNullOrWhiteSpace($AttackChainNodesJson)) { $AttackChainNodesJson = "[]" }

$PingModelMaxRows = 0
foreach ($cat in $PingScoreCategoriesPrimary) {
    $catRowCount = @($PingCategoryFindingsSortedMap[$cat]).Count
    if ($catRowCount -gt $PingModelMaxRows) { $PingModelMaxRows = $catRowCount }
}

# Build lookup data so each risk row can show actionable detail on click.
$PingRuleDetailsMap = @{}
foreach ($f in $PingCastleFindings) {
    $ruleInfo = Get-PingRuleInfo $f.Rule
    $ruleReference = Get-PingRuleReference $f.Rule
    $detailRows = @($PingCastleDetails | Where-Object { $_.Category -eq $f.Category -and $_.Rule -eq $f.Rule })
    $detailLines = @()
    foreach ($d in $detailRows | Select-Object -First 80) {
        $detailLines += "$($d.Target): $($d.Detail) [$($d.Severity)]"
    }

    $key = "$($f.Category)||$($f.Rule)"
    $PingRuleDetailsMap[$key] = [PSCustomObject]@{
        Category = $f.Category
        Rule = $f.Rule
        Severity = $f.Severity
        Count = $f.Count
        Sample = $f.Sample
        Recommendation = $f.Recommendation
        About = $ruleInfo.About
        AboutTR = $ruleInfo.AboutTR
        Source = $ruleInfo.Source
        Reference = $ruleReference
        Action = $ruleInfo.Action
        ActionTR = $ruleInfo.ActionTR
        Details = @($detailLines)
    }
}
$PingRuleDetailsJson = $PingRuleDetailsMap | ConvertTo-Json -Depth 8 -Compress
if ([string]::IsNullOrWhiteSpace($PingRuleDetailsJson)) {
    $PingRuleDetailsJson = "{}"
}

# 26) Baseline snapshot and diff for PingCastle-style findings
$PingSnapshotFile = Join-Path $PSScriptRoot "tools\\pingcastle_baseline_snapshot.json"
$PingBaselinePreviousDate = "N/A"
$PingBaselineCurrentDate = $Today.ToString("yyyy-MM-dd HH:mm:ss")
$PingDiffRows = @()

$CurrentPingSnapshot = [PSCustomObject]@{
    GeneratedAt = $PingBaselineCurrentDate
    DomainRiskScore = $DomainRiskScore
    RiskRating = $RiskRating
    CategoryRisk = @($CategoryPenaltyRows)
    Findings = @($PingCastleFindings | ForEach-Object {
        [PSCustomObject]@{
            Category = $_.Category
            Rule = $_.Rule
            Severity = $_.Severity
            Count = $_.Count
            Sample = $_.Sample
            Recommendation = $_.Recommendation
        }
    })
}

$CurrentByKey = @{}
foreach ($f in $CurrentPingSnapshot.Findings) {
    $key = "$($f.Category)|$($f.Rule)"
    $CurrentByKey[$key] = $f
}

$PreviousSnapshot = $null
if (Test-Path $PingSnapshotFile) {
    try {
        $PreviousSnapshot = Get-Content $PingSnapshotFile -Raw | ConvertFrom-Json
        if ($PreviousSnapshot.GeneratedAt) {
            $PingBaselinePreviousDate = $PreviousSnapshot.GeneratedAt
        }
    } catch {
        $PreviousSnapshot = $null
    }
}

$PreviousByKey = @{}
if ($PreviousSnapshot -and $PreviousSnapshot.Findings) {
    foreach ($f in $PreviousSnapshot.Findings) {
        $key = "$($f.Category)|$($f.Rule)"
        $PreviousByKey[$key] = $f
    }
}

foreach ($key in $CurrentByKey.Keys) {
    if (-not $PreviousByKey.ContainsKey($key)) {
        $curr = $CurrentByKey[$key]
        $PingDiffRows += [PSCustomObject]@{
            ChangeType = "New"
            Category = $curr.Category
            Rule = $curr.Rule
            PreviousSeverity = "N/A"
            CurrentSeverity = $curr.Severity
            PreviousCount = "N/A"
            CurrentCount = $curr.Count
            PreviousRecommendation = "N/A"
            CurrentRecommendation = $curr.Recommendation
            Notes = "New rule in current snapshot"
        }
        continue
    }

    $prev = $PreviousByKey[$key]
    $curr = $CurrentByKey[$key]

    $prevCountComparable = Get-CountComparableValue $prev.Count
    $currCountComparable = Get-CountComparableValue $curr.Count
    $isChanged = ($prev.Severity -ne $curr.Severity) -or ($prevCountComparable -ne $currCountComparable) -or ($prev.Recommendation -ne $curr.Recommendation)

    if ($isChanged) {
        $notes = @()
        if ($prev.Severity -ne $curr.Severity) {
            $notes += "Severity: $($prev.Severity) -> $($curr.Severity)"
        }
        if ($prevCountComparable -ne $currCountComparable) {
            $notes += "Count: $($prev.Count) -> $($curr.Count)"
        }
        if ($prev.Recommendation -ne $curr.Recommendation) {
            $notes += "Recommendation updated"
        }

        $PingDiffRows += [PSCustomObject]@{
            ChangeType = "Changed"
            Category = $curr.Category
            Rule = $curr.Rule
            PreviousSeverity = $prev.Severity
            CurrentSeverity = $curr.Severity
            PreviousCount = $prev.Count
            CurrentCount = $curr.Count
            PreviousRecommendation = $prev.Recommendation
            CurrentRecommendation = $curr.Recommendation
            Notes = ($notes -join " | ")
        }
    }
}

foreach ($key in $PreviousByKey.Keys) {
    if ($CurrentByKey.ContainsKey($key)) { continue }

    $prev = $PreviousByKey[$key]
    $PingDiffRows += [PSCustomObject]@{
        ChangeType = "Resolved"
        Category = $prev.Category
        Rule = $prev.Rule
        PreviousSeverity = $prev.Severity
        CurrentSeverity = "N/A"
        PreviousCount = $prev.Count
        CurrentCount = "N/A"
        PreviousRecommendation = $prev.Recommendation
        CurrentRecommendation = "N/A"
        Notes = "Rule not present in current snapshot"
    }
}

$PingDiffRows = @($PingDiffRows | Sort-Object Category, Rule, ChangeType)
$PingDiffNewCount = @($PingDiffRows | Where-Object { $_.ChangeType -eq "New" }).Count
$PingDiffChangedCount = @($PingDiffRows | Where-Object { $_.ChangeType -eq "Changed" }).Count
$PingDiffResolvedCount = @($PingDiffRows | Where-Object { $_.ChangeType -eq "Resolved" }).Count
$PingDiffNewPct = if ($PingDiffRows.Count -gt 0) { [math]::Round(($PingDiffNewCount * 100.0) / $PingDiffRows.Count, 1) } else { 0 }
$PingDiffChangedPct = if ($PingDiffRows.Count -gt 0) { [math]::Round(($PingDiffChangedCount * 100.0) / $PingDiffRows.Count, 1) } else { 0 }
$PingDiffResolvedPct = if ($PingDiffRows.Count -gt 0) { [math]::Round(($PingDiffResolvedCount * 100.0) / $PingDiffRows.Count, 1) } else { 0 }
$PingBaselineTopCategories = @(
    $PingDiffRows |
    Group-Object Category |
    Sort-Object Count -Descending |
    Select-Object -First 6 |
    ForEach-Object {
        [PSCustomObject]@{
            Category = $_.Name
            Count = $_.Count
            Percent = if ($PingDiffRows.Count -gt 0) { [math]::Round(($_.Count * 100.0) / $PingDiffRows.Count, 1) } else { 0 }
        }
    }
)
$PingTopNewRows = @($PingDiffRows | Where-Object { $_.ChangeType -eq 'New' } | Select-Object -First 5)
$PingTopChangedRows = @($PingDiffRows | Where-Object { $_.ChangeType -eq 'Changed' } | Select-Object -First 5)
$PingTopResolvedRows = @($PingDiffRows | Where-Object { $_.ChangeType -eq 'Resolved' } | Select-Object -First 5)

$PingBaselineSummary = [PSCustomObject]@{
    PreviousSnapshot = $PingBaselinePreviousDate
    CurrentSnapshot = $PingBaselineCurrentDate
    NewFindings = $PingDiffNewCount
    ChangedFindings = $PingDiffChangedCount
    ResolvedFindings = $PingDiffResolvedCount
    TotalDifferences = $PingDiffRows.Count
}

$PingTopNewRule = @($PingDiffRows | Where-Object { $_.ChangeType -eq 'New' } | Select-Object -First 1).Rule
if ([string]::IsNullOrWhiteSpace($PingTopNewRule)) { $PingTopNewRule = '-' }
$PingTopChangedRule = @($PingDiffRows | Where-Object { $_.ChangeType -eq 'Changed' } | Select-Object -First 1).Rule
if ([string]::IsNullOrWhiteSpace($PingTopChangedRule)) { $PingTopChangedRule = '-' }
$PingTopResolvedRule = @($PingDiffRows | Where-Object { $_.ChangeType -eq 'Resolved' } | Select-Object -First 1).Rule
if ([string]::IsNullOrWhiteSpace($PingTopResolvedRule)) { $PingTopResolvedRule = '-' }

$PingBaselineTimelineFile = Join-Path $PSScriptRoot "tools\pingcastle_baseline_timeline.json"
$PingBaselineTimelineRows = @()
if (Test-Path $PingBaselineTimelineFile) {
    try {
        $rawTimeline = Get-Content $PingBaselineTimelineFile -Raw | ConvertFrom-Json
        if ($rawTimeline -is [System.Array]) { $PingBaselineTimelineRows = @($rawTimeline) }
        elseif ($rawTimeline) { $PingBaselineTimelineRows = @($rawTimeline) }
    } catch {
        $PingBaselineTimelineRows = @()
    }
}

$PingBaselineTimelineRows += [PSCustomObject]@{
    GeneratedAt = $PingBaselineCurrentDate
    PreviousSnapshot = $PingBaselinePreviousDate
    TotalDifferences = $PingBaselineSummary.TotalDifferences
    NewFindings = $PingBaselineSummary.NewFindings
    ChangedFindings = $PingBaselineSummary.ChangedFindings
    ResolvedFindings = $PingBaselineSummary.ResolvedFindings
    DomainRiskScore = $DomainRiskScore
    RiskRating = $RiskRating
}

if ($PingBaselineTimelineRows.Count -gt 60) {
    $PingBaselineTimelineRows = @($PingBaselineTimelineRows | Select-Object -Last 60)
}

$toolsDir = Join-Path $PSScriptRoot "tools"
if (-not (Test-Path $toolsDir)) { New-Item -ItemType Directory -Path $toolsDir -Force | Out-Null }

$PingBaselineTimelineRows | ConvertTo-Json -Depth 6 | Out-File -FilePath $PingBaselineTimelineFile -Encoding UTF8
$PingBaselineTimelineRecentRows = @($PingBaselineTimelineRows | Select-Object -Last 12)

$CurrentPingSnapshot | ConvertTo-Json -Depth 5 | Out-File -FilePath $PingSnapshotFile -Encoding UTF8

$RiskHistoryFile = Join-Path $PSScriptRoot "tools\pingcastle_risk_history.json"
$RiskHistoryRows = @()
if (Test-Path $RiskHistoryFile) {
    try {
        $rawHistory = Get-Content $RiskHistoryFile -Raw | ConvertFrom-Json
        if ($rawHistory -is [System.Array]) { $RiskHistoryRows = @($rawHistory) }
        elseif ($rawHistory) { $RiskHistoryRows = @($rawHistory) }
    } catch {
        $RiskHistoryRows = @()
    }
}

$RiskHistoryRows += [PSCustomObject]@{
    GeneratedAt = $PingBaselineCurrentDate
    DomainRiskScore = $DomainRiskScore
    RiskRating = $RiskRating
    Critical = @($PingCastleFindings | Where-Object { $_.Severity -eq 'Critical' -and (Test-PingFindingMatched $_) }).Count
    High = @($PingCastleFindings | Where-Object { $_.Severity -eq 'High' -and (Test-PingFindingMatched $_) }).Count
    Medium = @($PingCastleFindings | Where-Object { $_.Severity -eq 'Medium' -and (Test-PingFindingMatched $_) }).Count
}

if ($RiskHistoryRows.Count -gt 36) {
    $RiskHistoryRows = @($RiskHistoryRows | Select-Object -Last 36)
}

$RiskHistoryRows | ConvertTo-Json -Depth 6 | Out-File -FilePath $RiskHistoryFile -Encoding UTF8
$RiskTrendJson = @($RiskHistoryRows | Select-Object GeneratedAt, DomainRiskScore, RiskRating, Critical, High, Medium) | ConvertTo-Json -Depth 5 -Compress
if ([string]::IsNullOrWhiteSpace($RiskTrendJson)) { $RiskTrendJson = "[]" }

# DC HEALTH & INFO (Shortened)
$FSMOOwner = @{}
$DomainFSMOs = if ($DomainInfo) { $DomainInfo | Select-Object PDCEmulator, RIDMaster, InfrastructureMaster } else { $null }
$ForestFSMOs = if ($ForestInfo) { $ForestInfo | Select-Object SchemaMaster, DomainNamingMaster } else { $null }

if ($DomainFSMOs -and $DomainFSMOs.PDCEmulator) { $PdcOwner = ($DomainFSMOs.PDCEmulator.Split('.')[0]).Trim() } else { $PdcOwner = "Bilinmiyor" }
if ($DomainFSMOs -and $DomainFSMOs.RIDMaster) { $RidOwner = ($DomainFSMOs.RIDMaster.Split('.')[0]).Trim() } else { $RidOwner = "Bilinmiyor" }
if ($DomainFSMOs -and $DomainFSMOs.InfrastructureMaster) { $InfraOwner = ($DomainFSMOs.InfrastructureMaster.Split('.')[0]).Trim() } else { $InfraOwner = "Bilinmiyor" }
if ($ForestFSMOs -and $ForestFSMOs.SchemaMaster) { $SchemaOwner = ($ForestFSMOs.SchemaMaster.Split('.')[0]).Trim() } else { $SchemaOwner = "Bilinmiyor" }
if ($ForestFSMOs -and $ForestFSMOs.DomainNamingMaster) { $NamingOwner = ($ForestFSMOs.DomainNamingMaster.Split('.')[0]).Trim() } else { $NamingOwner = "Bilinmiyor" }

$FSMOOwner.Add("PDC", $PdcOwner)
$FSMOOwner.Add("RID", $RidOwner)
$FSMOOwner.Add("Infra", $InfraOwner)
$FSMOOwner.Add("Schema", $SchemaOwner)
$FSMOOwner.Add("Naming", $NamingOwner)

$DCHealth = @()
$ReplicationFailureEvents = @()
$ReplicationTopologyLinks = @()
$ReplicationLookbackHours = 6

function Get-ReplicationPartnerLabel {
    param([string]$PartnerRaw)

    $value = "$PartnerRaw"
    if ([string]::IsNullOrWhiteSpace($value)) { return "UnknownPartner" }

    if ($value -match 'CN=([^,]+),CN=Servers') {
        return $matches[1]
    }

    if ($value -match '^[^,]+$') {
        return ($value.Split('.')[0]).Trim()
    }

    return $value
}
# DC Health Loop (Shortened)
foreach ($dc in $DCs) {
    # 1. Uptime Check (WMI/CIM ile)
    try {
        $OsInfo = Get-CimInstance -ClassName Win32_OperatingSystem -ComputerName $dc.Name -ErrorAction Stop
        $LastBoot = [datetime]$OsInfo.LastBootUpTime

        # Prefer remote clock to avoid timezone/skew artifacts when computing uptime.
        $NowRef = $null
        try {
            $NowRef = Invoke-Command -ComputerName $dc.Name -ScriptBlock { Get-Date } -ErrorAction Stop
        } catch {
            $NowRef = Get-Date
        }

        $Uptime = $NowRef - $LastBoot
        if ($Uptime.TotalMinutes -lt 0) {
            $Uptime = [timespan]::Zero
        }

        $UptimeString = "{0} Days, {1} Hours, {2} Mins" -f ([int]$Uptime.TotalDays), $Uptime.Hours, $Uptime.Minutes
    } catch {
        $UptimeString = "Unknown (WMI Unreachable)"
    }

    # 2. Sysvol Replikasyon Durumu
    $DCInfo = $AllComputers | Where-Object {$_.Name -eq $dc.Name} | Select -First 1
    $SysvolStatus = if ($DCInfo.OperatingSystem -match "2008|2012|2016|2019|2022") {
        "DFSR (OK)"
    } else {
        "FRS (EOL/Riskli)"
    }

    # 3. FSMO Roles Check
    $FSMOString = @()
    if ($FSMOOwner["PDC"] -eq $dc.Name) { $FSMOString += "PDC" }
    if ($FSMOOwner["RID"] -eq $dc.Name) { $FSMOString += "RID" }
    if ($FSMOOwner["Infra"] -eq $dc.Name) { $FSMOString += "Infra" }
    if ($FSMOOwner["Schema"] -eq $dc.Name) { $FSMOString += "Schema" }
    if ($FSMOOwner["Naming"] -eq $dc.Name) { $FSMOString += "Naming" }
    
    $FSMOString = if ($FSMOString.Count -gt 0) { $FSMOString -join ", " } else { "None" }
    
    # 4. Global Catalog
    $GCStatus = if ((Get-ADDomainController -Identity $dc.Name -ErrorAction SilentlyContinue).IsGlobalCatalog) { "Yes" } else { "No" }
    
    # 5. DC DNS Server List and Check (network setting check)
    $DC_IP = $dc.IPv4Address
    $DNS_Check_Status = "OK" # Default
    $DNS_Servers_String = ""
    try {
        # Fetch only network adapters where IPEnabled = True
        $NetAdapter = Get-CimInstance -ClassName Win32_NetworkAdapterConfiguration -ComputerName $dc.Name -Filter "IPEnabled = 'True'" -ErrorAction Stop | Select-Object -First 1
        $DNS_Servers = $NetAdapter.DNSServerSearchOrder
        $DNS_Servers_String = $DNS_Servers -join ", "
        
        # Policy update: primary DNS self-order warning is intentionally suppressed.
        if ($DNS_Servers.Count -gt 1) {
             # Secondary DNS should point to another DC or loopback.
             $OtherDC_IPs = $DCs | Where-Object {$_.IPv4Address -ne $DC_IP} | Select -ExpandProperty IPv4Address
             if (-not ($OtherDC_IPs -contains $DNS_Servers[1]) -and $DNS_Servers[1] -notmatch "127.0.0.1") {
                 $DNS_Check_Status = "ERROR (Secondary Not DC/Loopback)"
             }
        }
    } catch {
        $DNS_Servers_String = "WMI Unreachable"
        $DNS_Check_Status = "WMI Unreachable"
    }

    # 6. AD replication failure posture (last 6 hours)
    $Replication6hStatus = "OK (Last 6h)"
    $Replication6hDetail = "No replication failure detected in the last $ReplicationLookbackHours hour(s)."
    try {
        $repFailures = @()
        try {
            $repFailures = @(Get-ADReplicationFailure -Target $dc.Name -Scope Server -ErrorAction Stop)
        } catch {
            $repFailures = @()
        }

        $recentFailures = @()
        foreach ($rf in $repFailures) {
            $failureTime = $null
            foreach ($propName in @("FirstFailureTime", "FailureTime", "LastFailureTime", "LastErrorTime", "TimeOfLastFailure")) {
                if ($rf.PSObject.Properties[$propName] -and $rf.$propName) {
                    try {
                        $failureTime = [datetime]$rf.$propName
                        break
                    } catch {}
                }
            }

            $partnerRaw = if ($rf.PSObject.Properties["Partner"] -and $rf.Partner) { "$($rf.Partner)" } else { "UnknownPartner" }
            $partner = Get-ReplicationPartnerLabel $partnerRaw
            $lastErr = if ($rf.PSObject.Properties["LastError"] -and $rf.LastError) { "$($rf.LastError)" } else { "UnknownError" }
            $failCount = if ($rf.PSObject.Properties["FailureCount"] -and $rf.FailureCount) { "$($rf.FailureCount)" } else { "N/A" }

            if ($failureTime) {
                $ReplicationFailureEvents += [PSCustomObject]@{
                    Source = $dc.Name
                    Partner = $partner
                    Time = $failureTime
                    LastError = $lastErr
                    FailureCount = $failCount
                }
            }

            if ($failureTime -and $failureTime -ge (Get-Date).AddHours(-$ReplicationLookbackHours)) {
                $recentFailures += [PSCustomObject]@{
                    Partner = $partner
                    Time = $failureTime
                    LastError = $lastErr
                    FailureCount = $failCount
                }
            }
        }

        if ($recentFailures.Count -gt 0) {
            $Replication6hStatus = "ERROR ($($recentFailures.Count) in 6h)"
            $Replication6hDetail = (@($recentFailures | Select-Object -First 3 | ForEach-Object {
                "$($_.Partner) @ $($_.Time.ToString('yyyy-MM-dd HH:mm')) (FailCount=$($_.FailureCount), Err=$($_.LastError))"
            })) -join "; "
        } elseif ($repFailures.Count -gt 0) {
            $lastKnown = $null
            foreach ($rf in $repFailures) {
                foreach ($propName in @("FirstFailureTime", "FailureTime", "LastFailureTime", "LastErrorTime", "TimeOfLastFailure")) {
                    if ($rf.PSObject.Properties[$propName] -and $rf.$propName) {
                        try {
                            $candidate = [datetime]$rf.$propName
                            if (-not $lastKnown -or $candidate -gt $lastKnown) { $lastKnown = $candidate }
                        } catch {}
                    }
                }
            }
            if ($lastKnown) {
                $Replication6hStatus = "OK (Last 6h)"
                $Replication6hDetail = "No failure in last $ReplicationLookbackHours hour(s). Last known failure: $($lastKnown.ToString('yyyy-MM-dd HH:mm'))."
            }
        }
    } catch {
        $Replication6hStatus = "Access Error"
        $Replication6hDetail = "Replication status could not be collected: $($_.Exception.Message)"
    }

    try {
        $partnerRows = @(Get-ADReplicationPartnerMetadata -Target $dc.Name -Scope Server -ErrorAction Stop)
    } catch {
        $partnerRows = @()
    }

    foreach ($pr in $partnerRows) {
        $partnerName = Get-ReplicationPartnerLabel "$($pr.Partner)"

        $lastSuccess = $null
        if ($pr.PSObject.Properties["LastReplicationSuccess"] -and $pr.LastReplicationSuccess) {
            try { $lastSuccess = [datetime]$pr.LastReplicationSuccess } catch {}
        }

        $lastAttempt = $null
        if ($pr.PSObject.Properties["LastReplicationAttempt"] -and $pr.LastReplicationAttempt) {
            try { $lastAttempt = [datetime]$pr.LastReplicationAttempt } catch {}
        }

        $lastResult = $null
        if ($pr.PSObject.Properties["LastReplicationResult"]) {
            try { $lastResult = [int]$pr.LastReplicationResult } catch {}
        }

        $consecutiveFailures = 0
        if ($pr.PSObject.Properties["ConsecutiveReplicationFailures"] -and $pr.ConsecutiveReplicationFailures -ne $null) {
            try { $consecutiveFailures = [int]$pr.ConsecutiveReplicationFailures } catch { $consecutiveFailures = 0 }
        }

        $ReplicationTopologyLinks += [PSCustomObject]@{
            SourceDC = $dc.Name
            PartnerDC = $partnerName
            LastSuccess = $lastSuccess
            LastAttempt = $lastAttempt
            LastResult = $lastResult
            ConsecutiveFailures = $consecutiveFailures
        }
    }
    
    $DCHealth += [PSCustomObject]@{
        Name = $dc.Name
        OperatingSystem = $DCInfo.OperatingSystem
        Uptime = $UptimeString
        Sysvol = $SysvolStatus
        FSMORoles = $FSMOString
        IsGC = $GCStatus
        IPv4Address = $dc.IPv4Address
        DNS_Servers = $DNS_Servers_String
        DNS_Health = $DNS_Check_Status
        Replication_6h = $Replication6hStatus
        Replication_6h_Detail = $Replication6hDetail
    }
}

Write-Progress -Activity "KusoADCheck" -Status "Collecting Group Policy inventory..." -PercentComplete 80

# ---------------------
# Group Policy Data Collection
# ---------------------
$AllGPOs        = @()
$GPOLinkRows    = @()
$GPOSettingsMap = @{}
$GpcSettingsMap = @{}
$GPOModuleAvailable = $false
$GPOCollectError    = ""

try {
    Import-Module GroupPolicy -ErrorAction Stop
    $GPOModuleAvailable = $true
    $RawGPOs = Get-GPO -All -ErrorAction Stop | Sort-Object DisplayName

    $GpoIdNameMap = @{}
    foreach ($g in $RawGPOs) { $GpoIdNameMap[$g.Id.ToString().ToUpper()] = $g.DisplayName }

    function Build-GPOSettingsHtml([xml]$xmlDoc, [string]$side) {
        $exts = if ($side -eq 'Computer') { @($xmlDoc.GPO.Computer.ExtensionData | Where-Object { $_ }) }
                else { @($xmlDoc.GPO.User.ExtensionData | Where-Object { $_ }) }
        if ($exts.Count -eq 0) { return '<p style="color:#aaa;font-style:italic;padding:10px;">No settings configured.</p>' }

        $sb       = [System.Text.StringBuilder]::new()
        $tblStyle = "width:100%;border-collapse:collapse;font-size:12px;margin-bottom:14px;"
        $thStyle  = "background:#eef3f9;padding:6px 10px;text-align:left;font-weight:700;color:#1a3550;border:1px solid #d0dce9;"
        $tdStyle  = "padding:5px 10px;border:1px solid #e2eaf4;vertical-align:top;"
        $tdStyle2 = "padding:5px 10px;border:1px solid #e2eaf4;vertical-align:top;background:#f8fbff;"
        $hStyle   = "margin:12px 0 4px 0;font-size:12px;font-weight:700;color:#2563eb;text-transform:uppercase;letter-spacing:.04em;"
        $hStyle2  = "margin:8px 0 3px 10px;font-size:11px;font-weight:700;color:#334155;background:#f1f5f9;padding:4px 10px;border-radius:4px;border-left:3px solid #94a3b8;"

        foreach ($ext in $exts) {
            $extName = $ext.Name
            $node    = $ext.Extension
            if (-not $node) { continue }
            $handled = @{}

            # -- Account / Lockout / Kerberos policies — friendly names + categories --
            $accounts = @($node.ChildNodes | Where-Object { $_.LocalName -in @('Account','Lockout','Kerberos') })
            if ($accounts.Count -gt 0) {
                'Account','Lockout','Kerberos' | ForEach-Object { $handled[$_] = 1 }

                $acctMap = @{
                    'PasswordHistorySize'    = @{ Cat='Account Policies/Password Policy';        Label='Enforce password history';                              Fmt='passwords remembered'; Bool=$false }
                    'MaximumPasswordAge'     = @{ Cat='Account Policies/Password Policy';        Label='Maximum password age';                                  Fmt='days'; Bool=$false }
                    'MinimumPasswordAge'     = @{ Cat='Account Policies/Password Policy';        Label='Minimum password age';                                  Fmt='days'; Bool=$false }
                    'MinimumPasswordLength'  = @{ Cat='Account Policies/Password Policy';        Label='Minimum password length';                               Fmt='characters'; Bool=$false }
                    'PasswordComplexity'     = @{ Cat='Account Policies/Password Policy';        Label='Password must meet complexity requirements';            Fmt=''; Bool=$true }
                    'ClearTextPassword'      = @{ Cat='Account Policies/Password Policy';        Label='Store passwords using reversible encryption';           Fmt=''; Bool=$true }
                    'ObsoletePasswordChange' = @{ Cat='Account Policies/Password Policy';        Label='User must logon to change the password';               Fmt=''; Bool=$true }
                    'LockoutBadCount'        = @{ Cat='Account Policies/Account Lockout Policy'; Label='Account lockout threshold';                            Fmt='invalid logon attempts'; Bool=$false }
                    'LockoutDuration'        = @{ Cat='Account Policies/Account Lockout Policy'; Label='Account lockout duration';                             Fmt='minutes'; Bool=$false }
                    'ResetLockoutCount'      = @{ Cat='Account Policies/Account Lockout Policy'; Label='Reset account lockout counter after';                  Fmt='minutes'; Bool=$false }
                    'TicketValidateClient'   = @{ Cat='Account Policies/Kerberos Policy';        Label='Enforce user logon restrictions';                      Fmt=''; Bool=$true }
                    'MaxServiceAge'          = @{ Cat='Account Policies/Kerberos Policy';        Label='Maximum lifetime for service ticket';                  Fmt='minutes'; Bool=$false }
                    'MaxTicketAge'           = @{ Cat='Account Policies/Kerberos Policy';        Label='Maximum lifetime for user ticket';                     Fmt='hours'; Bool=$false }
                    'MaxRenewAge'            = @{ Cat='Account Policies/Kerberos Policy';        Label='Maximum lifetime for user ticket renewal';             Fmt='days'; Bool=$false }
                    'MaxClockSkew'           = @{ Cat='Account Policies/Kerberos Policy';        Label='Maximum tolerance for computer clock synchronization'; Fmt='minutes'; Bool=$false }
                }

                $byCat = [ordered]@{
                    'Account Policies/Password Policy'        = [System.Collections.Generic.List[hashtable]]::new()
                    'Account Policies/Account Lockout Policy' = [System.Collections.Generic.List[hashtable]]::new()
                    'Account Policies/Kerberos Policy'        = [System.Collections.Generic.List[hashtable]]::new()
                    '_Other'                                  = [System.Collections.Generic.List[hashtable]]::new()
                }

                foreach ($a in $accounts) {
                    $intName = [string]$a.Name
                    $info = $acctMap[$intName]
                    if ($info) {
                        if ($info.Bool) {
                            $bv = [string]$a.SettingBoolean
                            $val = if ($bv -eq 'true') { 'Enabled' } elseif ($bv -eq 'false') { 'Disabled' } else { '—' }
                        } else {
                            $nv = [string]$a.SettingNumber
                            $val = if ($nv -ne '' -and $null -ne $nv) {
                                if ($info.Fmt) { "$nv $($info.Fmt)" } else { $nv }
                            } else { '—' }
                        }
                        $byCat[$info.Cat].Add(@{ Label=$info.Label; Value=$val })
                    } else {
                        $bv = [string]$a.SettingBoolean; $nv = [string]$a.SettingNumber
                        $val = if ($bv -eq 'true') { 'Enabled' } elseif ($bv -eq 'false') { 'Disabled' } elseif ($nv) { $nv } else { '—' }
                        $byCat['_Other'].Add(@{ Label=$intName; Value=$val })
                    }
                }

                foreach ($cat in $byCat.Keys) {
                    if ($byCat[$cat].Count -eq 0) { continue }
                    $catLabel = if ($cat -eq '_Other') { 'Account Policies/Other' } else { $cat }
                    [void]$sb.Append("<p style='$hStyle'>$([System.Net.WebUtility]::HtmlEncode($catLabel))</p>")
                    [void]$sb.Append("<table style='$tblStyle'><tr><th style='$thStyle'>Policy</th><th style='$thStyle'>Setting</th></tr>")
                    $ri = 0
                    foreach ($item in $byCat[$cat]) {
                        $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                        [void]$sb.Append("<tr><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($item.Label))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($item.Value))</td></tr>")
                        $ri++
                    }
                    [void]$sb.Append("</table>")
                }
            }

            # -- Audit Policy --
            $audits = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'Audit' })
            if ($audits.Count -gt 0) {
                $handled['Audit'] = 1
                [void]$sb.Append("<p style='$hStyle'>Audit Policy</p><table style='$tblStyle'><tr><th style='$thStyle'>Event Category</th><th style='$thStyle'>Setting</th></tr>")
                $ri = 0
                foreach ($a in $audits) {
                    $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                    [void]$sb.Append("<tr><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$a.Name))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$a.AuditType))</td></tr>")
                    $ri++
                }
                [void]$sb.Append("</table>")
            }

            # -- User Rights Assignment --
            $uras = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'UserRightsAssignment' })
            if ($uras.Count -gt 0) {
                $handled['UserRightsAssignment'] = 1
                [void]$sb.Append("<p style='$hStyle'>User Rights Assignment</p><table style='$tblStyle'><tr><th style='$thStyle'>Right / Privilege</th><th style='$thStyle'>Granted To</th></tr>")
                $ri = 0
                foreach ($ura in $uras) {
                    $members = @($ura.Member | ForEach-Object {
                        $n = if ($_.Name) { $_.Name.'#text' } else { $null }
                        if ($n) { $n } elseif ($_.SID) { $_.SID.'#text' } else { '' }
                    } | Where-Object { $_ }) -join ', '
                    if (-not $members) { $members = '(none / empty)' }
                    $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                    [void]$sb.Append("<tr><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$ura.Name))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($members))</td></tr>")
                    $ri++
                }
                [void]$sb.Append("</table>")
            }

            # -- Security Options — grouped by sub-category --
            $secopts = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'SecurityOptions' })
            if ($secopts.Count -gt 0) {
                $handled['SecurityOptions'] = 1

                $sysAccessFriendly = @{
                    'ForceLogoffWhenHourExpire' = @{ Label='Network security: Force logoff when logon hours expire'; Cat='Network Security' }
                    'LSAAnonymousNameLookup'     = @{ Label='Network access: Allow anonymous SID/Name translation';  Cat='Network Access'  }
                    'EnableAdminAccount'         = @{ Label='Accounts: Administrator account status';                Cat='Accounts'        }
                    'EnableGuestAccount'         = @{ Label='Accounts: Guest account status';                        Cat='Accounts'        }
                    'LimitBlankPasswordUse'      = @{ Label='Accounts: Limit local account use of blank passwords to local logon only'; Cat='Accounts' }
                    'NewAdministratorName'       = @{ Label='Accounts: Rename administrator account';               Cat='Accounts'        }
                    'NewGuestName'               = @{ Label='Accounts: Rename guest account';                       Cat='Accounts'        }
                }

                $soBySubCat = [ordered]@{}
                foreach ($so in $secopts) {
                    $policyName = ''
                    $val = ''
                    $subCat = 'General'

                    # Type 1: registry-based — has Display/Name
                    $dispNode = $so.SelectSingleNode('*[local-name()="Display"]')
                    if ($dispNode) {
                        $nameNode = $dispNode.SelectSingleNode('*[local-name()="Name"]')
                        $boolNode = $dispNode.SelectSingleNode('*[local-name()="DisplayBoolean"]')
                        $strNode  = $dispNode.SelectSingleNode('*[local-name()="DisplayString"]')
                        $unitNode = $dispNode.SelectSingleNode('*[local-name()="Units"]')
                        if ($nameNode) { $policyName = $nameNode.InnerText }
                        $bv = if ($boolNode) { $boolNode.InnerText } else { '' }
                        $sv = if ($strNode)  { $strNode.InnerText  } else { '' }
                        $uv = if ($unitNode -and $unitNode.InnerText) { " $($unitNode.InnerText)" } else { '' }
                        $val = if ($bv -ne '') { if ($bv -eq 'true') { 'Enabled' } else { 'Disabled' } }
                               elseif ($sv)    { "$sv$uv" }
                               else {
                                   $numNode = $so.SelectSingleNode('*[local-name()="SettingNumber"]')
                                   if ($numNode) { $numNode.InnerText } else { '—' }
                               }
                        # Sub-category = text before first colon in policy name
                        $ci = $policyName.IndexOf(':')
                        $subCat = if ($ci -gt 0) { $policyName.Substring(0,$ci).Trim() } else { 'General' }
                    }

                    # Type 2: SystemAccessPolicyName
                    if (-not $policyName) {
                        $sanNode = $so.SelectSingleNode('*[local-name()="SystemAccessPolicyName"]')
                        $sanVal  = if ($sanNode) { $sanNode.InnerText } else { '' }
                        if ($sanVal) {
                            $m = $sysAccessFriendly[$sanVal]
                            if ($m) { $policyName = $m.Label; $subCat = $m.Cat }
                            else    { $policyName = $sanVal }
                            $numNode = $so.SelectSingleNode('*[local-name()="SettingNumber"]')
                            $nv = if ($numNode) { $numNode.InnerText } else { '' }
                            $val = if ($nv -eq '1') { 'Enabled' } elseif ($nv -eq '0') { 'Disabled' } elseif ($nv) { $nv } else { '—' }
                        }
                    }

                    if (-not $policyName) { continue }
                    if (-not $soBySubCat.Contains($subCat)) { $soBySubCat[$subCat] = [System.Collections.Generic.List[hashtable]]::new() }
                    $soBySubCat[$subCat].Add(@{ Name=$policyName; Value=$val })
                }

                if ($soBySubCat.Count -gt 0) {
                    [void]$sb.Append("<p style='$hStyle'>Local Policies/Security Options</p>")
                    foreach ($subCat in $soBySubCat.Keys) {
                        [void]$sb.Append("<p style='$hStyle2'>$([System.Net.WebUtility]::HtmlEncode($subCat))</p>")
                        [void]$sb.Append("<table style='$tblStyle'><tr><th style='$thStyle'>Policy</th><th style='$thStyle'>Setting</th></tr>")
                        $ri = 0
                        foreach ($item in $soBySubCat[$subCat]) {
                            $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                            [void]$sb.Append("<tr><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($item.Name))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($item.Value))</td></tr>")
                            $ri++
                        }
                        [void]$sb.Append("</table>")
                    }
                }
            }

            # -- Administrative Templates — GPMC style: category header + policy row + indented sub-settings --
            $policies = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'Policy' })
            if ($policies.Count -gt 0) {
                $handled['Policy'] = 1

                # Group by Category
                $byAdmxCat = [ordered]@{}
                foreach ($p in $policies) {
                    $cat = [string]$p.Category
                    if (-not $cat) { $cat = '(General)' }
                    if (-not $byAdmxCat.Contains($cat)) { $byAdmxCat[$cat] = [System.Collections.Generic.List[object]]::new() }
                    $byAdmxCat[$cat].Add($p)
                }

                [void]$sb.Append("<p style='$hStyle'>Administrative Templates</p>")

                foreach ($cat in $byAdmxCat.Keys) {
                    [void]$sb.Append("<p style='$hStyle2'>$([System.Net.WebUtility]::HtmlEncode($cat))</p>")
                    [void]$sb.Append("<table style='$tblStyle'><tr><th style='$thStyle;width:55%;'>Policy</th><th style='$thStyle;width:15%;'>Setting</th><th style='$thStyle;width:30%;'>Value</th></tr>")

                    foreach ($p in $byAdmxCat[$cat]) {
                        $pName = [System.Net.WebUtility]::HtmlEncode([string]$p.Name)
                        $pState = [string]$p.State
                        $stateColor = switch ($pState) { 'Enabled' { 'color:#1a7f4b;font-weight:700;' } 'Disabled' { 'color:#b91c1c;font-weight:700;' } default { 'color:#64748b;' } }

                        # Policy main row
                        [void]$sb.Append("<tr style='background:#f0f6ff;'><td style='$tdStyle;font-weight:600;color:#1a5fa8;'>$pName</td><td style='$tdStyle;$stateColor'>$([System.Net.WebUtility]::HtmlEncode($pState))</td><td style='$tdStyle;color:#94a3b8;font-size:11px;'></td></tr>")

                        # Sub-setting rows (indented)
                        foreach ($sub in @($p.ChildNodes | Where-Object { $_.LocalName -in @('DropDownList','CheckBox','TextBox','Numeric','ListBox','MultiText') })) {
                            $nameEl = $sub.SelectSingleNode('*[local-name()="Name"]')
                            $subLabel = if ($nameEl) { $nameEl.InnerText } else { $sub.LocalName }
                            $subVal = switch ($sub.LocalName) {
                                'DropDownList' { $vn = $sub.SelectSingleNode('*[local-name()="Value"]/*[local-name()="Name"]'); if ($vn) { $vn.InnerText } else { $sub.InnerText.Trim() } }
                                'CheckBox'     { $sub.InnerText.Trim() }
                                'TextBox'      { $vn = $sub.SelectSingleNode('*[local-name()="Value"]'); if ($vn) { $vn.InnerText } else { $sub.InnerText.Trim() } }
                                'Numeric'      { $vn = $sub.SelectSingleNode('*[local-name()="Value"]'); if ($vn) { $vn.InnerText } else { $sub.InnerText.Trim() } }
                                'ListBox'      { ($sub.SelectNodes('*[local-name()="Value"]') | ForEach-Object { $_.InnerText } | Where-Object {$_}) -join '; ' }
                                'MultiText'    { $vn = $sub.SelectSingleNode('*[local-name()="Value"]'); if ($vn) { $vn.InnerText } else { $sub.InnerText.Trim() } }
                                default        { $sub.InnerText.Trim() }
                            }
                            $subVal = if ($subVal) { $subVal.Trim() } else { '' }
                            if (-not $subVal) { continue }
                            [void]$sb.Append("<tr><td style='$tdStyle;padding-left:28px;font-size:12px;color:#4b5563;'>&#8627; $([System.Net.WebUtility]::HtmlEncode($subLabel))</td><td style='$tdStyle;'></td><td style='$tdStyle;color:#111827;font-weight:600;'>$([System.Net.WebUtility]::HtmlEncode($subVal))</td></tr>")
                        }
                    }
                    [void]$sb.Append("</table>")
                }
            }

            # -- Scripts --
            $scripts = @($node.ChildNodes | Where-Object { $_.LocalName -in @('Script','RunRestricted') })
            if ($scripts.Count -gt 0) {
                $handled['Script'] = 1; $handled['RunRestricted'] = 1
                [void]$sb.Append("<p style='$hStyle'>Scripts</p><table style='$tblStyle'><tr><th style='$thStyle'>Type</th><th style='$thStyle'>Command</th><th style='$thStyle'>Parameters</th></tr>")
                foreach ($sc in $scripts) {
                    [void]$sb.Append("<tr><td style='$tdStyle'>$([System.Net.WebUtility]::HtmlEncode([string]$sc.Type))</td><td style='$tdStyle;font-family:monospace;font-size:11px;'>$([System.Net.WebUtility]::HtmlEncode([string]$sc.Command))</td><td style='$tdStyle;font-family:monospace;font-size:11px;'>$([System.Net.WebUtility]::HtmlEncode([string]$sc.Parameters))</td></tr>")
                }
                [void]$sb.Append("</table>")
            }

            # -- Registry Settings --
            $regItems = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'RegistrySetting' })
            if ($regItems.Count -gt 0) {
                $handled['RegistrySetting'] = 1
                [void]$sb.Append("<p style='$hStyle'>Registry Settings ($($regItems.Count) item(s))</p><table style='$tblStyle'><tr><th style='$thStyle;width:38%;'>Registry Key</th><th style='$thStyle;width:18%;'>Value Name</th><th style='$thStyle;width:10%;'>Type</th><th style='$thStyle;width:34%;'>Data</th></tr>")
                $ri = 0
                foreach ($reg in $regItems) {
                    $keyPath = [string]$reg.KeyPath
                    $valName = if ($reg.ValueName) { [string]$reg.ValueName } else { '(Default)' }
                    $regType = [string]$reg.Type
                    $regData = if ($reg.Value.String)      { [string]$reg.Value.String }
                               elseif ($reg.Value.Number)  { [string]$reg.Value.Number }
                               elseif ($null -ne $reg.Value.Boolean) { [string]$reg.Value.Boolean }
                               elseif ($reg.Value.Binary)  { '(binary data)' }
                               elseif ($reg.Value.MultiString) { ([string]$reg.Value.MultiString -split "`n") -join '; ' }
                               elseif ($reg.Value) { $reg.Value.InnerText }
                               else { '—' }
                    $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                    [void]$sb.Append("<tr><td style='$td;font-size:10px;font-family:monospace;word-break:break-all;'>$([System.Net.WebUtility]::HtmlEncode($keyPath))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($valName))</td><td style='$td;font-size:11px;color:#6b7280;'>$([System.Net.WebUtility]::HtmlEncode($regType))</td><td style='$td;font-family:monospace;font-size:11px;'>$([System.Net.WebUtility]::HtmlEncode($regData))</td></tr>")
                    $ri++
                }
                [void]$sb.Append("</table>")
            }

            # -- Restricted Groups --
            $groups = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'Group' })
            if ($groups.Count -gt 0) {
                $handled['Group'] = 1
                [void]$sb.Append("<p style='$hStyle'>Restricted Groups</p><table style='$tblStyle'><tr><th style='$thStyle'>Group Name</th><th style='$thStyle'>Members (enforced)</th><th style='$thStyle'>Member Of</th></tr>")
                $ri = 0
                foreach ($grp in $groups) {
                    $grpName  = if ($grp.GroupName.Name.'#text') { [string]$grp.GroupName.Name.'#text' } elseif ($grp.GroupName.Name) { [string]$grp.GroupName.Name } else { $grp.GroupName.InnerText }
                    $members  = @($grp.Member  | ForEach-Object { $n = if ($_.'Name'.'#text') { $_.'Name'.'#text' } else { [string]$_.Name }; if ($n) { $n } } | Where-Object {$_}) -join ', '
                    $memberOf = @($grp.MemberOf | ForEach-Object { $n = if ($_.'Name'.'#text') { $_.'Name'.'#text' } else { [string]$_.Name }; if ($n) { $n } } | Where-Object {$_}) -join ', '
                    if (-not $members)  { $members  = '(none specified)' }
                    if (-not $memberOf) { $memberOf = '—' }
                    $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                    [void]$sb.Append("<tr><td style='$td;font-weight:600;'>$([System.Net.WebUtility]::HtmlEncode($grpName))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($members))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode($memberOf))</td></tr>")
                    $ri++
                }
                [void]$sb.Append("</table>")
            }

            # -- System Services --
            $services = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'NTService' })
            if ($services.Count -gt 0) {
                $handled['NTService'] = 1
                [void]$sb.Append("<p style='$hStyle'>System Services</p><table style='$tblStyle'><tr><th style='$thStyle'>Service Name</th><th style='$thStyle'>Startup Type</th><th style='$thStyle'>Service Action</th></tr>")
                $ri = 0
                foreach ($svc in $services) {
                    $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                    [void]$sb.Append("<tr><td style='$td;font-weight:600;'>$([System.Net.WebUtility]::HtmlEncode([string]$svc.Name))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$svc.StartupType))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$svc.ServiceAction))</td></tr>")
                    $ri++
                }
                [void]$sb.Append("</table>")
            }

            # -- Event Log Settings --
            $evtLogs = @($node.ChildNodes | Where-Object { $_.LocalName -eq 'EventLog' })
            if ($evtLogs.Count -gt 0) {
                $handled['EventLog'] = 1
                [void]$sb.Append("<p style='$hStyle'>Event Log Settings</p><table style='$tblStyle'><tr><th style='$thStyle'>Log</th><th style='$thStyle'>Max Size (KB)</th><th style='$thStyle'>Retention Policy</th></tr>")
                $ri = 0
                foreach ($el in $evtLogs) {
                    $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                    [void]$sb.Append("<tr><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$el.Name))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$el.MaximumLogSize))</td><td style='$td'>$([System.Net.WebUtility]::HtmlEncode([string]$el.AuditLogRetentionPeriod))</td></tr>")
                    $ri++
                }
                [void]$sb.Append("</table>")
            }

            # -- Generic fallback for any remaining unrecognised extension node types --
            # Skip meaningless placeholder nodes (Blocked, empty containers)
            $skipNodeNames = @('Blocked','blocked','BlockedSetting','NotConfigured')
            $unhandled = @($node.ChildNodes | Where-Object {
                $_ -and $_.LocalName -ne '#comment' -and $_.LocalName -ne '#text' `
                -and -not $handled.ContainsKey($_.LocalName) `
                -and $_.LocalName -notin $skipNodeNames
            })
            if ($unhandled.Count -gt 0) {
                $byType = $unhandled | Group-Object LocalName
                foreach ($tg in $byType) {
                    $rowsHtml = [System.Text.StringBuilder]::new()
                    $ri = 0
                    foreach ($item in $tg.Group) {
                        $parts = @()
                        foreach ($child in @($item.ChildNodes | Where-Object { $_ -and $_.LocalName -ne '#comment' -and $_.LocalName -ne '#text' } | Select-Object -First 15)) {
                            $cval = if ($child.'#text') { $child.'#text' }
                                    elseif (($child.ChildNodes | Where-Object { $_.LocalName -ne '#text' }).Count -le 1) { $child.InnerText.Trim() }
                                    else { '' }
                            if ($child.LocalName -and $cval) { $parts += "$($child.LocalName)`: $cval" }
                        }
                        if (-not $parts) {
                            $attrParts = @($item.Attributes | Where-Object { $_.LocalName -ne 'xmlns' } | ForEach-Object { "$($_.LocalName)=$($_.Value)" })
                            if ($attrParts) { $parts = $attrParts }
                        }
                        # Skip items with no readable data at all
                        if (-not $parts) { continue }
                        $td = if ($ri % 2 -eq 0) { $tdStyle } else { $tdStyle2 }
                        [void]$rowsHtml.Append("<tr><td colspan='2' style='$td;font-size:11px;'>$([System.Net.WebUtility]::HtmlEncode($parts -join ' | '))</td></tr>")
                        $ri++
                    }
                    # Only render section if at least one row has data
                    if ($rowsHtml.Length -gt 0) {
                        $friendlyType = $tg.Name -replace '([a-z])([A-Z])','$1 $2'
                        [void]$sb.Append("<p style='$hStyle'>$([System.Net.WebUtility]::HtmlEncode($extName)) — $([System.Net.WebUtility]::HtmlEncode($friendlyType))</p>")
                        [void]$sb.Append("<table style='$tblStyle'><tr><th style='$thStyle' colspan='2'>Settings</th></tr>")
                        [void]$sb.Append($rowsHtml.ToString())
                        [void]$sb.Append("</table>")
                    }
                }
            }
        }

        if ($sb.Length -eq 0) { return '<p style="color:#aaa;font-style:italic;padding:10px;">Settings exist but could not be parsed (unsupported extension type).</p>' }
        return $sb.ToString()
    }

    foreach ($g in $RawGPOs) {
        $compHtmlB64 = ''
        $userHtmlB64 = ''
        try {
            $xml = [xml](Get-GPOReport -Guid $g.Id -ReportType XML -ErrorAction Stop)
            $GpcSettingsMap[$g.Id.ToString().ToUpper()] = Get-GpoConflictSettings $xml
            $compExts = @($xml.GPO.Computer.ExtensionData | Where-Object { $_ -ne $null })
            $userExts = @($xml.GPO.User.ExtensionData | Where-Object { $_ -ne $null })
            $compNames = ($compExts | ForEach-Object { $_.Name } | Where-Object { $_ }) -join ', '
            $userNames = ($userExts | ForEach-Object { $_.Name } | Where-Object { $_ }) -join ', '
            $compHtml  = Build-GPOSettingsHtml -xmlDoc $xml -side 'Computer'
            $userHtml  = Build-GPOSettingsHtml -xmlDoc $xml -side 'User'
            $compHtmlB64 = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($compHtml))
            $userHtmlB64 = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($userHtml))
            $GPOSettingsMap[$g.Id.ToString().ToUpper()] = [PSCustomObject]@{
                CompSections = if ($compNames) { $compNames } else { '' }
                UserSections = if ($userNames) { $userNames } else { '' }
                CompCount    = $compExts.Count
                UserCount    = $userExts.Count
                IsEmpty      = ($compExts.Count -eq 0 -and $userExts.Count -eq 0)
                CompB64      = $compHtmlB64
                UserB64      = $userHtmlB64
            }
        } catch {
            $GPOSettingsMap[$g.Id.ToString().ToUpper()] = [PSCustomObject]@{
                CompSections = ''; UserSections = ''; CompCount = 0; UserCount = 0; IsEmpty = $false
                CompB64 = ''; UserB64 = ''
            }
        }
        $AllGPOs += [PSCustomObject]@{
            Name      = $g.DisplayName
            Id        = $g.Id.ToString().ToUpper()
            Status    = $g.GpoStatus.ToString()
            Created   = $g.CreationTime.ToString("dd/MM/yyyy")
            Modified  = $g.ModificationTime.ToString("dd/MM/yyyy")
            WmiFilter = if ($g.WmiFilter) { $g.WmiFilter.Name } else { "" }
        }
    }

    function Get-GpoConflictSettings([xml]$xmlDoc) {
        $result = @{}
        try {
            $exts = @($xmlDoc.GPO.Computer.ExtensionData | Where-Object { $_ })
            foreach ($ext in $exts) {
                $node = $ext.Extension
                if (-not $node) { continue }
                # Account / Lockout / Kerberos policies
                foreach ($a in @($node.ChildNodes | Where-Object { $_.LocalName -in @('Account','Lockout','Kerberos') })) {
                    $k = [string]$a.Name; if (-not $k) { continue }
                    $bv = [string]$a.SettingBoolean; $nv = [string]$a.SettingNumber
                    $v = if ($bv -eq 'true') { 'Enabled' } elseif ($bv -eq 'false') { 'Disabled' } elseif ($nv -ne '') { $nv } else { $null }
                    if ($null -ne $v) { $result["PassLock:$k"] = $v }
                }
                # Audit policy
                foreach ($a in @($node.ChildNodes | Where-Object { $_.LocalName -eq 'Audit' })) {
                    $k = [string]$a.Name; $v = [string]$a.AuditType
                    if ($k -and $v) { $result["Audit:$k"] = $v }
                }
                # User Rights Assignment
                foreach ($ura in @($node.ChildNodes | Where-Object { $_.LocalName -eq 'UserRightsAssignment' })) {
                    $k = [string]$ura.Name; if (-not $k) { continue }
                    $members = @($ura.Member | ForEach-Object {
                        $n = $null
                        if ($_.Name) { $n = if ($_.Name.'#text') { $_.Name.'#text' } else { [string]$_.Name } }
                        if (-not $n -and $_.SID) { $n = if ($_.SID.'#text') { $_.SID.'#text' } else { [string]$_.SID } }
                        $n
                    } | Where-Object { $_ } | Sort-Object)
                    $result["URA:$k"] = ($members -join ',')
                }
                # Security Options
                foreach ($so in @($node.ChildNodes | Where-Object { $_.LocalName -eq 'SecurityOptions' })) {
                    # Type 1: registry-based with Display/Name
                    $dispNode = $so.SelectSingleNode('*[local-name()="Display"]')
                    if ($dispNode) {
                        $nm = $dispNode.SelectSingleNode('*[local-name()="Name"]')
                        $bn = $dispNode.SelectSingleNode('*[local-name()="DisplayBoolean"]')
                        $sn = $dispNode.SelectSingleNode('*[local-name()="DisplayString"]')
                        $pn = if ($nm) { $nm.InnerText } else { $null }
                        $bv2 = if ($bn) { $bn.InnerText } else { '' }
                        $sv2 = if ($sn) { $sn.InnerText } else { '' }
                        $v2  = if ($bv2 -eq 'true') { 'Enabled' } elseif ($bv2 -eq 'false') { 'Disabled' } elseif ($sv2) { $sv2 } else { $null }
                        if (-not $v2) { $nn = $so.SelectSingleNode('*[local-name()="SettingNumber"]'); if ($nn) { $v2 = $nn.InnerText } }
                        if ($pn -and $null -ne $v2) { $result["SecOpt:$pn"] = $v2 }
                    }
                    # Type 2: SystemAccessPolicyName
                    $sanNode = $so.SelectSingleNode('*[local-name()="SystemAccessPolicyName"]')
                    if ($sanNode -and $sanNode.InnerText) {
                        $nn3 = $so.SelectSingleNode('*[local-name()="SettingNumber"]')
                        $nv3 = if ($nn3) { $nn3.InnerText } else { $null }
                        $v3  = if ($nv3 -eq '1') { 'Enabled' } elseif ($nv3 -eq '0') { 'Disabled' } elseif ($null -ne $nv3) { $nv3 } else { $null }
                        if ($null -ne $v3) { $result["SecOpt:$($sanNode.InnerText)"] = $v3 }
                    }
                }
            }
        } catch {}
        return $result
    }

    function Parse-GPLinks($gpLinkAttr) {
        $res = @()
        if ([string]::IsNullOrWhiteSpace($gpLinkAttr)) { return $res }
        $ms = [regex]::Matches($gpLinkAttr, '\[LDAP://[Cc][Nn]=(\{[0-9A-Fa-f\-]+\})[^;]*;(\d+)\]')
        $ord = 1
        foreach ($m in $ms) {
            $guid  = $m.Groups[1].Value.Trim('{}').ToUpper()
            $flags = [int]$m.Groups[2].Value
            $res  += [PSCustomObject]@{
                GpoId    = $guid
                GpoName  = if ($GpoIdNameMap.ContainsKey($guid)) { $GpoIdNameMap[$guid] } else { "Unknown ($guid)" }
                Enabled  = ($flags -band 1) -eq 0
                Enforced = ($flags -band 2) -ne 0
                Order    = $ord
            }
            $ord++
        }
        return $res
    }

    $DomainDN      = (Get-ADDomain).DistinguishedName
    $DomainGpLink  = (Get-ADObject -Identity $DomainDN -Properties gpLink -ErrorAction SilentlyContinue).gpLink
    foreach ($lnk in (Parse-GPLinks $DomainGpLink)) {
        $GPOLinkRows += [PSCustomObject]@{
            OUName = "Domain Root"; OUDN = $DomainDN; Depth = 0
            GpoId = $lnk.GpoId; GpoName = $lnk.GpoName
            Enabled = $lnk.Enabled; Enforced = $lnk.Enforced; Order = $lnk.Order
        }
    }

    # Full OU tree nodes (all OUs, for GPMC-style tree view)
    $OUTreeNodes = @()
    $DomainDNSRoot = (Get-ADDomain).DNSRoot
    $OUTreeNodes += [PSCustomObject]@{
        Id               = $DomainDN
        Name             = $DomainDNSRoot
        ParentId         = ""
        Type             = "domain"
        GpoLinks         = @(Parse-GPLinks $DomainGpLink)
        BlockInheritance = $false
    }

    $AllOUs = Get-ADOrganizationalUnit -Filter * -Properties gpLink, gpOptions, Name, DistinguishedName -ErrorAction SilentlyContinue | Sort-Object DistinguishedName
    foreach ($ou in $AllOUs) {
        $parentDN     = $ou.DistinguishedName -replace '^[^,]+,', ''
        $depth        = ([regex]::Matches($ou.DistinguishedName, ',OU=')).Count + 1
        $ouLinks      = @(Parse-GPLinks $ou.gpLink)
        $blockInherit = (([int]($ou.gpOptions) -band 1) -eq 1)
        $OUTreeNodes += [PSCustomObject]@{
            Id               = $ou.DistinguishedName
            Name             = $ou.Name
            ParentId         = $parentDN
            Type             = "ou"
            GpoLinks         = $ouLinks
            BlockInheritance = $blockInherit
        }
        foreach ($lnk in $ouLinks) {
            $GPOLinkRows += [PSCustomObject]@{
                OUName = $ou.Name; OUDN = $ou.DistinguishedName; Depth = $depth
                GpoId = $lnk.GpoId; GpoName = $lnk.GpoName
                Enabled = $lnk.Enabled; Enforced = $lnk.Enforced; Order = $lnk.Order
            }
        }
    }

} catch {
    $GPOCollectError = $_.Exception.Message
}

$LinkedGPOIds     = @($GPOLinkRows | Select-Object -ExpandProperty GpoId -Unique)
$GpoOrphanedList  = @($AllGPOs | Where-Object { $LinkedGPOIds -notcontains $_.Id })
$GpoEmptyList     = @($AllGPOs | Where-Object { $s = $GPOSettingsMap[$_.Id]; $s -and $s.IsEmpty })
$GpoDisabledList  = @($AllGPOs | Where-Object { $_.Status -eq "AllSettingsDisabled" })
$GpoOrphanedCount = $GpoOrphanedList.Count
$GpoEmptyCount    = $GpoEmptyList.Count
$GpoDisabledCount = $GpoDisabledList.Count
$GpoTotalCount    = $AllGPOs.Count

# --- Feature 1: extra banner counts ---
$GpoEnforcedCount = 0; $GpoCompOnlyCount = 0; $GpoUserOnlyCount = 0
foreach ($gpo in $AllGPOs) {
    $gId = $gpo.Id
    if (@($GPOLinkRows | Where-Object { $_.GpoId -eq $gId -and $_.Enforced }).Count -gt 0) { $GpoEnforcedCount++ }
    if ($gpo.Status -eq 'UserSettingsDisabled')     { $GpoCompOnlyCount++ }
    if ($gpo.Status -eq 'ComputerSettingsDisabled') { $GpoUserOnlyCount++ }
}

# --- Feature 5: Conflict Detection ---
$GpoConflictByOU  = @{}
$GpoConflictByGpo = @{}
foreach ($node in $OUTreeNodes) {
    $enabledLinks = @($node.GpoLinks | Where-Object { $_.Enabled })
    if ($enabledLinks.Count -lt 2) { continue }
    $secMap = @{}
    foreach ($lnk in $enabledLinks) {
        $s = $GPOSettingsMap[$lnk.GpoId]
        if (-not $s) { continue }
        $allSecs = @()
        if ($s.CompSections) { $allSecs += @($s.CompSections -split ',\s*') }
        if ($s.UserSections)  { $allSecs += @($s.UserSections  -split ',\s*') }
        foreach ($sec in ($allSecs | Where-Object { $_ })) {
            if (-not $secMap[$sec]) { $secMap[$sec] = @() }
            $secMap[$sec] += $lnk.GpoId
        }
    }
    $conflicts = @($secMap.GetEnumerator() | Where-Object { $_.Value.Count -gt 1 })
    if ($conflicts.Count -gt 0) {
        $GpoConflictByOU[$node.Id] = $conflicts
        foreach ($c in $conflicts) {
            foreach ($gId in $c.Value) {
                if (-not $GpoConflictByGpo[$gId]) { $GpoConflictByGpo[$gId] = @() }
                if ($GpoConflictByGpo[$gId] -notcontains $node.Id) { $GpoConflictByGpo[$gId] += $node.Id }
            }
        }
    }
}

# --- Feature 5b: Fine-grained GPO Setting Conflict Detection ---
$GpcConflictRows = [System.Collections.Generic.List[object]]::new()
$_GpcKeyLabel = @{
    'PassLock:PasswordHistorySize'   = 'Password history'
    'PassLock:MaximumPasswordAge'    = 'Maximum password age'
    'PassLock:MinimumPasswordAge'    = 'Minimum password age'
    'PassLock:MinimumPasswordLength' = 'Minimum password length'
    'PassLock:PasswordComplexity'    = 'Password complexity'
    'PassLock:ClearTextPassword'     = 'Reversible encryption'
    'PassLock:LockoutBadCount'       = 'Lockout threshold'
    'PassLock:LockoutDuration'       = 'Lockout duration'
    'PassLock:ResetLockoutCount'     = 'Reset lockout counter'
    'PassLock:MaxTicketAge'          = 'Kerberos ticket lifetime'
    'PassLock:MaxServiceAge'         = 'Kerberos service ticket lifetime'
    'PassLock:MaxClockSkew'          = 'Kerberos clock tolerance'
}
foreach ($node in $OUTreeNodes) {
    $enabledLinks = @($node.GpoLinks | Where-Object { $_.Enabled })
    if ($enabledLinks.Count -lt 2) { continue }
    $enfLinks  = @($enabledLinks | Where-Object {  $_.Enforced } | Sort-Object { [int]$_.Order })
    $normLinks = @($enabledLinks | Where-Object { -not $_.Enforced } | Sort-Object { [int]$_.Order })

    # Aggregate all settings per key
    $keyMap = @{}
    foreach ($lnk in $enabledLinks) {
        $s = $GpcSettingsMap[$lnk.GpoId]
        if (-not $s -or $s.Count -eq 0) { continue }
        foreach ($kv in $s.GetEnumerator()) {
            if (-not $keyMap[$kv.Key]) { $keyMap[$kv.Key] = [System.Collections.Generic.List[hashtable]]::new() }
            $keyMap[$kv.Key].Add(@{ GpoId=$lnk.GpoId; GpoName=$lnk.GpoName; Value=$kv.Value; Enforced=$lnk.Enforced; Order=$lnk.Order })
        }
    }

    foreach ($key in $keyMap.Keys) {
        $entries    = @($keyMap[$key])
        if ($entries.Count -lt 2) { continue }
        $uniqVals   = @($entries | Select-Object -ExpandProperty Value -Unique)
        if ($uniqVals.Count -lt 2) { continue }

        # Effective winner: enforced lowest-order first, then normal lowest-order
        $winnerEntry = $null; $winnerLabel = ''
        $enfE = @($entries | Where-Object { $_.Enforced } | Sort-Object { [int]$_.Order })
        if ($enfE.Count -gt 0) {
            $winnerEntry = $enfE[0]
            $winnerLabel = "$($winnerEntry.GpoName) [Enforced, Link $($winnerEntry.Order)]"
        } else {
            $normE = @($entries | Where-Object { -not $_.Enforced } | Sort-Object { [int]$_.Order })
            if ($normE.Count -gt 0) { $winnerEntry = $normE[0]; $winnerLabel = "$($winnerEntry.GpoName) [Link Order $($winnerEntry.Order)]" }
        }
        if (-not $winnerEntry) { continue }

        $loserArr = @($entries | Where-Object { $_.GpoId -ne $winnerEntry.GpoId -and $_.Value -ne $winnerEntry.Value } | Select-Object -First 1)
        if (-not $loserArr) { continue }
        $loser = $loserArr[0]

        $displayKey = if ($_GpcKeyLabel[$key]) { $_GpcKeyLabel[$key] } else { ($key -replace '^[^:]+:','') }
        $cat = ($key -split ':')[0]

        $GpcConflictRows.Add([PSCustomObject]@{
            OUName   = $node.Name
            OUDN     = $node.Id
            Category = $cat
            Setting  = $displayKey
            GpoAName = $winnerEntry.GpoName
            GpoAVal  = $winnerEntry.Value
            GpoBName = $loser.GpoName
            GpoBVal  = $loser.Value
            Winner   = $winnerLabel
        })
    }
}
$GpcConflictCount = $GpcConflictRows.Count

Write-Progress -Activity "KusoADCheck" -Status "Analyzing AD Tier Model compliance..." -PercentComplete 91

# --- OU Map JS data ---
$OuTreeDataJson = (ConvertTo-Json -InputObject @($OUTreeNodes) -Depth 5 -Compress) -replace '</script>','<\/script>'
$GpoSettingsForJs = [ordered]@{}
foreach ($gpo in $AllGPOs) {
    $s = $GPOSettingsMap[$gpo.Id]
    $GpoSettingsForJs[$gpo.Id] = [ordered]@{
        n = ($gpo.Name  -replace '\\','\\' -replace '"','\"')
        c = if ($s -and $s.CompSections) { $s.CompSections } else { '' }
        u = if ($s -and $s.UserSections) { $s.UserSections } else { '' }
    }
}
$GpoSettingsIndexJson = (ConvertTo-Json -InputObject $GpoSettingsForJs -Depth 3 -Compress) -replace '</script>','<\/script>'

# =====================================================
# AD TIER MODEL ANALYSIS — Data Collection & Scoring
# =====================================================

$TierFindings = @()

function Add-TierFinding {
    param(
        [string]$Id,
        [string]$Tier,          # "Tier0","Tier1","Tier2","OU"
        [string]$Severity,      # "Critical","Warning","Info","OK"
        [string]$Title,
        [string]$Description,
        [string]$Recommendation,
        [int]$AffectedCount,
        [string[]]$AffectedObjects,
        [string]$TitleTR        = "",
        [string]$DescTR         = "",
        [string]$RecTR          = ""
    )
    $script:TierFindings += [PSCustomObject]@{
        Id             = $Id
        Tier           = $Tier
        Severity       = $Severity
        Title          = $Title
        Description    = $Description
        Recommendation = $Recommendation
        AffectedCount  = $AffectedCount
        AffectedObjects= $AffectedObjects
        TitleTR        = $TitleTR
        DescTR         = $DescTR
        RecTR          = $RecTR
    }
}

# ---- Tier 0 Checks ----

# T0-1: Privileged accounts in CN=Users
$PrivSamAccounts = @($DomainAdmins + $SchemaAdmins + $EnterpriseAdmins | Sort-Object -Unique)
$PrivInDefaultContainer = @($AllUsersRaw | Where-Object {
    $PrivSamAccounts -contains $_.SamAccountName -and
    $_.DistinguishedName -match ',CN=Users,'
})
if ($PrivInDefaultContainer.Count -gt 0) {
    Add-TierFinding -Id "T0-1" -Tier "Tier0" -Severity "Critical" `
        -Title "Privileged accounts in default CN=Users container" `
        -Description "Domain Admins, Schema Admins, or Enterprise Admins accounts reside in the default CN=Users container. These accounts should be in a dedicated Tier 0 OU with restricted GPO and access controls." `
        -Recommendation "Create a dedicated 'Tier 0 Admins' OU (e.g., OU=T0-Admins,OU=Admin,DC=...) and move all privileged accounts there. Apply a restrictive GPO blocking internet access and enforcing logon restrictions." `
        -TitleTR "Ayrıcalıklı hesaplar varsayılan CN=Users konteynerinde" `
        -DescTR "Domain Admins, Schema Admins veya Enterprise Admins hesapları varsayılan CN=Users konteynerinde bulunuyor. Bu hesapların kısıtlı GPO ve erişim denetimleri olan özel bir Tier 0 OU'sunda olması gerekir." `
        -RecTR "Özel bir 'Tier 0 Admins' OU'su oluşturun (ör. OU=T0-Admins,OU=Admin,DC=...) ve tüm ayrıcalıklı hesapları oraya taşıyın. İnternet erişimini engelleyen ve oturum açma kısıtlamaları uygulayan kısıtlayıcı bir GPO ekleyin." `
        -AffectedCount $PrivInDefaultContainer.Count `
        -AffectedObjects @($PrivInDefaultContainer | Select-Object -ExpandProperty SamAccountName)
} else {
    Add-TierFinding -Id "T0-1" -Tier "Tier0" -Severity "OK" `
        -Title "Privileged accounts not in CN=Users container" `
        -Description "No Domain Admins, Schema Admins, or Enterprise Admins accounts found in the default CN=Users container." `
        -Recommendation "Continue to maintain privileged accounts in dedicated OUs." `
        -TitleTR "Ayrıcalıklı hesaplar CN=Users konteynerinde değil" `
        -DescTR "Varsayılan CN=Users konteynerinde Domain Admins, Schema Admins veya Enterprise Admins hesabı bulunamadı." `
        -RecTR "Ayrıcalıklı hesapları özel OU'larda tutmaya devam edin." `
        -AffectedCount 0 -AffectedObjects @()
}

# T0-2: Dedicated privileged/admin OU exists
$AdminOUPatterns = @('admin','tier0','t0-','privileged','secureAdmin','identityAdmin','_admin')
$AdminOUExists = @($OUTreeNodes | Where-Object {
    $_.Type -eq "ou" -and ($AdminOUPatterns | Where-Object { $OUTreeNodes.Name -like "*$_*" }).Count -gt 0
}) | Where-Object {
    $ouNameLower = $_.Name.ToLower()
    $AdminOUPatterns | Where-Object { $ouNameLower -match $_ }
}
$HasAdminOU = $AdminOUExists.Count -gt 0
if (-not $HasAdminOU) {
    Add-TierFinding -Id "T0-2" -Tier "Tier0" -Severity "Warning" `
        -Title "No dedicated Tier 0 / Admin OU detected" `
        -Description "No OU with naming patterns like 'Admin', 'Tier0', 'Privileged', or 'T0-' was found. A dedicated administrative OU is a Tier Model prerequisite for applying strict access controls and GPOs to privileged accounts." `
        -Recommendation "Create OU=Administration with sub-OUs: OU=T0-Admins, OU=T1-Admins, OU=T2-Admins. Apply Logon Restriction GPOs to each tier's OU." `
        -TitleTR "Özel Tier 0 / Admin OU tespit edilmedi" `
        -DescTR "'Admin', 'Tier0', 'Privileged' veya 'T0-' gibi isimlendirme kalıplarına sahip OU bulunamadı. Özel bir yönetim OU'su, ayrıcalıklı hesaplara sıkı erişim denetimleri ve GPO uygulamak için Tier Modeli ön koşuludur." `
        -RecTR "Alt OU'larıyla OU=Administration oluşturun: OU=T0-Admins, OU=T1-Admins, OU=T2-Admins. Her tier OU'suna Oturum Açma Kısıtlama GPO'ları uygulayın." `
        -AffectedCount 0 -AffectedObjects @()
} else {
    Add-TierFinding -Id "T0-2" -Tier "Tier0" -Severity "OK" `
        -Title "Dedicated admin/privileged OU found" `
        -Description "An OU with administrative naming conventions was detected, indicating separation of privileged accounts." `
        -Recommendation "Ensure all privileged accounts are consolidated in the dedicated admin OU." `
        -TitleTR "Özel yönetici/ayrıcalıklı OU bulundu" `
        -DescTR "Yönetim isimlendirme kuralına sahip bir OU tespit edildi; ayrıcalıklı hesapların ayrıştırıldığını gösteriyor." `
        -RecTR "Tüm ayrıcalıklı hesapların özel yönetici OU'sunda toplandığını doğrulayın." `
        -AffectedCount $AdminOUExists.Count -AffectedObjects @($AdminOUExists | Select-Object -ExpandProperty Name)
}

# T0-3: Domain Admin count
$DACount = @($DomainAdmins).Count
if ($DACount -gt 10) {
    Add-TierFinding -Id "T0-3" -Tier "Tier0" -Severity "Critical" `
        -Title "Domain Admins count excessive (>10 members)" `
        -Description "There are $DACount members in Domain Admins. This dramatically increases the attack surface. Each DA account is a potential full domain compromise vector." `
        -Recommendation "Reduce Domain Admins to 2-5 break-glass accounts. Use delegation and role-based access for day-to-day administration. Regularly audit and remove unnecessary DA accounts." `
        -TitleTR "Domain Admins sayısı çok yüksek ($DACount üye, >10)" `
        -DescTR "Domain Admins grubunda $DACount üye var. Bu, saldırı yüzeyini önemli ölçüde artırır. Her DA hesabı tam domain ele geçirme riski taşır." `
        -RecTR "Domain Admins'i 2-5 acil erişim hesabına indirin. Günlük yönetim için yetki devri ve rol tabanlı erişim kullanın. Gereksiz DA hesaplarını düzenli denetleyip kaldırın." `
        -AffectedCount $DACount -AffectedObjects @($DomainAdmins | Select-Object -First 20)
} elseif ($DACount -gt 5) {
    Add-TierFinding -Id "T0-3" -Tier "Tier0" -Severity "Warning" `
        -Title "Domain Admins count elevated (>5 members)" `
        -Description "There are $DACount members in Domain Admins. Best practice is 2-5 accounts maximum for break-glass scenarios." `
        -Recommendation "Review each Domain Admin account. Remove accounts that can be replaced with delegated permissions. Keep only break-glass emergency accounts." `
        -TitleTR "Domain Admins sayısı yüksek ($DACount üye, >5)" `
        -DescTR "Domain Admins grubunda $DACount üye var. Acil erişim senaryoları için en iyi uygulama maksimum 2-5 hesap tutmaktır." `
        -RecTR "Her Domain Admin hesabını gözden geçirin. Yetki devriyle değiştirilebilecek hesapları kaldırın. Yalnızca acil erişim hesaplarını koruyun." `
        -AffectedCount $DACount -AffectedObjects @($DomainAdmins)
} else {
    Add-TierFinding -Id "T0-3" -Tier "Tier0" -Severity "OK" `
        -Title "Domain Admins count acceptable ($DACount members)" `
        -Description "Domain Admins group has $DACount member(s), which is within the recommended range of 2-5." `
        -Recommendation "Continue to audit Domain Admin membership periodically." `
        -TitleTR "Domain Admins sayısı kabul edilebilir ($DACount üye)" `
        -DescTR "Domain Admins grubunda $DACount üye var; önerilen 2-5 aralığında." `
        -RecTR "Domain Admin üyeliğini düzenli aralıklarla denetlemeye devam edin." `
        -AffectedCount $DACount -AffectedObjects @($DomainAdmins)
}

# T0-4: Protected Users group utilization
$ProtectedUsersCount = @($ProtectedUsersMembers).Count
$PrivProtected = @($ProtectedUsersMembers | Where-Object {
    $sam = if ($_ -is [string]) { $_ } else { $_.SamAccountName }
    $PrivSamAccounts -contains $sam
})
if ($ProtectedUsersCount -eq 0) {
    Add-TierFinding -Id "T0-4" -Tier "Tier0" -Severity "Warning" `
        -Title "Protected Users group is empty" `
        -Description "The Protected Users security group has no members. This group enforces Kerberos-only authentication, prevents NTLM, disables credential caching, and enforces AES encryption for Tier 0 accounts." `
        -Recommendation "Add all Domain Admins, Schema Admins, and Enterprise Admins to the Protected Users group. Test compatibility before broad rollout." `
        -TitleTR "Protected Users grubu boş" `
        -DescTR "Protected Users güvenlik grubunun hiç üyesi yok. Bu grup; Tier 0 hesapları için yalnızca Kerberos kimlik doğrulaması, NTLM engeli, kimlik bilgisi önbelleğe alma engeli ve AES şifrelemesi zorlaması uygular." `
        -RecTR "Tüm Domain Admins, Schema Admins ve Enterprise Admins hesaplarını Protected Users grubuna ekleyin. Geniş çaplı dağıtımdan önce uyumluluğu test edin." `
        -AffectedCount $DACount -AffectedObjects @($DomainAdmins)
} elseif ($PrivProtected.Count -lt $PrivSamAccounts.Count) {
    $unprotected = @($PrivSamAccounts | Where-Object {
        $sam = $_
        -not ($ProtectedUsersMembers | Where-Object { ($_ -is [string] -and $_ -eq $sam) -or ($_.SamAccountName -eq $sam) })
    })
    Add-TierFinding -Id "T0-4" -Tier "Tier0" -Severity "Warning" `
        -Title "Some privileged accounts not in Protected Users" `
        -Description "$($unprotected.Count) of $($PrivSamAccounts.Count) privileged accounts are not in the Protected Users group. These accounts remain vulnerable to NTLM relay and credential caching attacks." `
        -Recommendation "Add all privileged accounts to Protected Users. The group membership takes effect at next logon." `
        -TitleTR "Bazı ayrıcalıklı hesaplar Protected Users grubunda değil" `
        -DescTR "$($PrivSamAccounts.Count) ayrıcalıklı hesabın $($unprotected.Count) tanesi Protected Users grubunda değil. Bu hesaplar NTLM relay ve kimlik bilgisi önbelleğe alma saldırılarına karşı savunmasız." `
        -RecTR "Tüm ayrıcalıklı hesapları Protected Users grubuna ekleyin. Grup üyeliği bir sonraki oturum açmada geçerli olur." `
        -AffectedCount $unprotected.Count -AffectedObjects $unprotected
} else {
    Add-TierFinding -Id "T0-4" -Tier "Tier0" -Severity "OK" `
        -Title "Protected Users group actively used for privileged accounts" `
        -Description "Privileged accounts are enrolled in the Protected Users group, enforcing strong Kerberos protections." `
        -Recommendation "Periodically verify Protected Users membership as privileged accounts are added." `
        -TitleTR "Protected Users grubu ayrıcalıklı hesaplar için aktif" `
        -DescTR "Ayrıcalıklı hesaplar Protected Users grubuna dahil; güçlü Kerberos korumaları uygulanıyor." `
        -RecTR "Yeni ayrıcalıklı hesaplar eklenirken Protected Users üyeliğini düzenli doğrulayın." `
        -AffectedCount $ProtectedUsersCount -AffectedObjects @()
}

# T0-5: Fine-grained password policy for Tier 0
if (-not $ServicePSOFound) {
    Add-TierFinding -Id "T0-5" -Tier "Tier0" -Severity "Warning" `
        -Title "No fine-grained password policy (PSO) configured" `
        -Description "No Fine-Grained Password Policy with MinPasswordLength >= 20 was found. Tier 0 accounts require stricter password policies than the domain default to resist brute force and credential stuffing." `
        -Recommendation "Create a PSO with MinPasswordLength=20, LockoutThreshold=3, and ComplexityEnabled=True. Apply it to Domain Admins and other Tier 0 accounts via a global security group." `
        -TitleTR "Hassas parola ilkesi (PSO) yapılandırılmamış" `
        -DescTR "MinPasswordLength >= 20 olan Hassas Parola İlkesi bulunamadı. Tier 0 hesapları, kaba kuvvet ve kimlik bilgisi doldurma saldırılarına karşı domain varsayılanından daha katı parola ilkeleri gerektirir." `
        -RecTR "MinPasswordLength=20, LockoutThreshold=3 ve ComplexityEnabled=True olan bir PSO oluşturun. Domain Admins ve diğer Tier 0 hesaplarına küresel güvenlik grubu aracılığıyla uygulayın." `
        -AffectedCount 1 -AffectedObjects @("No PSO found")
} else {
    Add-TierFinding -Id "T0-5" -Tier "Tier0" -Severity "OK" `
        -Title "Fine-grained password policy (PSO) exists" `
        -Description "At least one Fine-Grained Password Policy with MinPasswordLength >= 20 is configured, providing enhanced password controls for privileged accounts." `
        -Recommendation "Verify the PSO is applied to all Tier 0 accounts and that the precedence is correct." `
        -TitleTR "Hassas parola ilkesi (PSO) mevcut" `
        -DescTR "MinPasswordLength >= 20 olan en az bir Hassas Parola İlkesi yapılandırılmış; ayrıcalıklı hesaplar için gelişmiş parola denetimleri sağlanıyor." `
        -RecTR "PSO'nun tüm Tier 0 hesaplarına uygulandığını ve önceliğin doğru olduğunu doğrulayın." `
        -AffectedCount 0 -AffectedObjects @()
}

# T0-6: krbtgt password age
if ($KrbtgtAgeDays -gt 180) {
    Add-TierFinding -Id "T0-6" -Tier "Tier0" -Severity "Critical" `
        -Title "krbtgt password not rotated in $KrbtgtAgeDays days (>180)" `
        -Description "The krbtgt account password is $KrbtgtAgeDays days old. This account's password is used to encrypt all Kerberos tickets. If compromised (Golden Ticket attack), an attacker can forge tickets for any account. Rotation every 180 days is the minimum standard." `
        -Recommendation "Rotate the krbtgt password using a two-step process (rotate twice, 10 hours apart) to invalidate any forged tickets. Use Microsoft's New-KrbtgtKeys.ps1 script." `
        -TitleTR "krbtgt parolası $KrbtgtAgeDays gündür döndürülmedi (>180)" `
        -DescTR "krbtgt hesap parolası $KrbtgtAgeDays gün önce ayarlandı. Bu parolası tüm Kerberos biletlerini şifrelemek için kullanılır. Ele geçirilirse (Golden Ticket saldırısı) saldırgan herhangi bir hesap için bilet oluşturabilir. 180 günde bir döndürme minimum standarttır." `
        -RecTR "krbtgt parolasını iki aşamalı süreçle döndürün (10 saat arayla iki kez). Sahte biletleri geçersiz kılmak için Microsoft'un New-KrbtgtKeys.ps1 betiğini kullanın." `
        -AffectedCount 1 -AffectedObjects @("krbtgt: $KrbtgtAgeDays days old")
} elseif ($KrbtgtAgeDays -lt 0) {
    Add-TierFinding -Id "T0-6" -Tier "Tier0" -Severity "Warning" `
        -Title "krbtgt password age could not be determined" `
        -Description "Unable to read the krbtgt account's PasswordLastSet attribute. This may indicate a permissions issue." `
        -Recommendation "Verify access to the krbtgt account and check PasswordLastSet attribute." `
        -TitleTR "krbtgt parola yaşı belirlenemedi" `
        -DescTR "krbtgt hesabının PasswordLastSet özelliği okunamadı. Bu bir izin sorununa işaret edebilir." `
        -RecTR "krbtgt hesabına erişimi ve PasswordLastSet özelliğini doğrulayın." `
        -AffectedCount 1 -AffectedObjects @("krbtgt")
} else {
    Add-TierFinding -Id "T0-6" -Tier "Tier0" -Severity "OK" `
        -Title "krbtgt password rotated recently ($KrbtgtAgeDays days ago)" `
        -Description "The krbtgt account password was last rotated $KrbtgtAgeDays days ago, within the recommended 180-day window." `
        -Recommendation "Maintain a schedule to rotate the krbtgt password every 90-180 days." `
        -TitleTR "krbtgt parolası kısa süre önce döndürüldü ($KrbtgtAgeDays gün önce)" `
        -DescTR "krbtgt hesabı parolası $KrbtgtAgeDays gün önce döndürüldü; önerilen 180 günlük pencere içinde." `
        -RecTR "krbtgt parolasını her 90-180 günde bir döndürme planı oluşturun." `
        -AffectedCount 0 -AffectedObjects @()
}

# ---- Tier 1 Checks ----

# T1-1: Computers in default CN=Computers
$ComputersInDefaultContainer = @($AllComputers | Where-Object {
    $_.DistinguishedName -match ',CN=Computers,'
})
if ($ComputersInDefaultContainer.Count -gt 0) {
    Add-TierFinding -Id "T1-1" -Tier "Tier1" -Severity "Warning" `
        -Title "Computers in default CN=Computers container ($($ComputersInDefaultContainer.Count) objects)" `
        -Description "$($ComputersInDefaultContainer.Count) computer objects reside in the default CN=Computers container. This container is not an OU and cannot have GPOs applied directly, leaving these computers ungoverned by policy." `
        -Recommendation "Create OU=Servers and OU=Workstations under an appropriate parent OU. Move all computer objects out of CN=Computers. Use redircmp.exe to change the default computer container." `
        -TitleTR "Varsayılan CN=Computers konteynerinde bilgisayarlar ($($ComputersInDefaultContainer.Count) nesne)" `
        -DescTR "$($ComputersInDefaultContainer.Count) bilgisayar nesnesi varsayılan CN=Computers konteynerinde. Bu konteyner OU değildir ve doğrudan GPO uygulanamaz; bu bilgisayarlar ilke yönetiminin dışında kalır." `
        -RecTR "Uygun bir üst OU altında OU=Servers ve OU=Workstations oluşturun. Tüm bilgisayar nesnelerini CN=Computers'dan taşıyın. Varsayılan bilgisayar konteynerini değiştirmek için redircmp.exe kullanın." `
        -AffectedCount $ComputersInDefaultContainer.Count -AffectedObjects @($ComputersInDefaultContainer | Select-Object -First 15 -ExpandProperty Name)
} else {
    Add-TierFinding -Id "T1-1" -Tier "Tier1" -Severity "OK" `
        -Title "No computers in default CN=Computers container" `
        -Description "All computer objects have been moved from the default CN=Computers container into proper OUs." `
        -Recommendation "Set the default computer container to an appropriate OU using redircmp.exe." `
        -TitleTR "Varsayılan CN=Computers konteynerinde bilgisayar yok" `
        -DescTR "Tüm bilgisayar nesneleri CN=Computers konteynerinden uygun OU'lara taşınmış." `
        -RecTR "Gelecekte oluşturulan bilgisayarlar için varsayılan konteyneri redircmp.exe ile uygun bir OU'ya yönlendirin." `
        -AffectedCount 0 -AffectedObjects @()
}

# T1-2: Service accounts (SPN holders) in dedicated OU
$ServiceAcctOU = @($OUTreeNodes | Where-Object {
    $_.Type -eq "ou" -and ($_.Name -match 'service|svc|serviceaccount|sa_|gsa|gmsa|managed')
})
$HasServiceAcctOU = $ServiceAcctOU.Count -gt 0
$SpnUserCount = @($AllSpnUsers).Count
if ($SpnUserCount -gt 0 -and -not $HasServiceAcctOU) {
    Add-TierFinding -Id "T1-2" -Tier "Tier1" -Severity "Warning" `
        -Title "No dedicated Service Account OU found ($SpnUserCount SPN accounts exist)" `
        -Description "$SpnUserCount accounts with Service Principal Names (potential service accounts) were found, but no dedicated Service Account OU was detected. Service accounts mixed with user accounts create audit and security challenges." `
        -Recommendation "Create OU=ServiceAccounts and move all service accounts there. Apply a dedicated PSO for service account password requirements." `
        -TitleTR "Özel Servis Hesabı OU'su bulunamadı ($SpnUserCount SPN hesabı mevcut)" `
        -DescTR "SPN'e sahip $SpnUserCount hesap tespit edildi ancak özel Servis Hesabı OU'su bulunamadı. Servis hesaplarının kullanıcı hesaplarıyla karışması denetim ve güvenlik zorluklarına yol açar." `
        -RecTR "OU=ServiceAccounts oluşturun ve tüm servis hesaplarını oraya taşıyın. Servis hesabı parola gereksinimleri için özel bir PSO uygulayın." `
        -AffectedCount $SpnUserCount -AffectedObjects @($AllSpnUsers | Select-Object -First 10 -ExpandProperty SamAccountName)
} elseif ($SpnUserCount -eq 0) {
    Add-TierFinding -Id "T1-2" -Tier "Tier1" -Severity "OK" `
        -Title "No regular service accounts (SPN holders) found" `
        -Description "No regular user accounts with Service Principal Names were found (excluding krbtgt). This may indicate gMSA adoption." `
        -Recommendation "Continue using gMSA for service identities where possible." `
        -TitleTR "Normal servis hesabı (SPN sahibi) bulunamadı" `
        -DescTR "krbtgt dışında SPN'e sahip normal kullanıcı hesabı bulunamadı. Bu, gMSA kullanımına geçildiğine işaret edebilir." `
        -RecTR "Servis kimlikleri için mümkün olan her yerde gMSA kullanmaya devam edin." `
        -AffectedCount 0 -AffectedObjects @()
} else {
    Add-TierFinding -Id "T1-2" -Tier "Tier1" -Severity "OK" `
        -Title "Dedicated Service Account OU found" `
        -Description "A dedicated OU for service accounts was detected, indicating good account hygiene." `
        -Recommendation "Verify all service accounts are placed in the dedicated OU and have appropriate PSOs applied." `
        -TitleTR "Özel Servis Hesabı OU'su bulundu" `
        -DescTR "Servis hesapları için özel OU tespit edildi; iyi hesap yönetimini gösteriyor." `
        -RecTR "Tüm servis hesaplarının özel OU'da bulunduğunu ve uygun PSO'ların uygulandığını doğrulayın." `
        -AffectedCount $ServiceAcctOU.Count -AffectedObjects @($ServiceAcctOU | Select-Object -ExpandProperty Name)
}

# T1-3: Service accounts with stale passwords (>180 days, not gMSA)
$StaleServiceAccounts = @($AllSpnUsers | Where-Object {
    $pwdAge = if ($_.PasswordLastSet) { [int](New-TimeSpan -Start $_.PasswordLastSet -End (Get-Date)).TotalDays } else { 9999 }
    $pwdAge -gt 180 -and $_.Enabled -eq $true
})
if ($StaleServiceAccounts.Count -gt 0) {
    Add-TierFinding -Id "T1-3" -Tier "Tier1" -Severity "Warning" `
        -Title "Service accounts with stale passwords >180 days ($($StaleServiceAccounts.Count) accounts)" `
        -Description "$($StaleServiceAccounts.Count) enabled service accounts (SPN holders) have passwords older than 180 days. These are prime Kerberoasting targets. A stale password increases the window for offline cracking attacks." `
        -Recommendation "Migrate service accounts to gMSA (Group Managed Service Accounts) which auto-rotate passwords every 30 days. For accounts that cannot use gMSA, enforce regular password rotation via PSO." `
        -TitleTR "180 günden eski parolaya sahip servis hesapları ($($StaleServiceAccounts.Count) hesap)" `
        -DescTR "$($StaleServiceAccounts.Count) etkin servis hesabının (SPN sahibi) parolası 180 günden eski. Bunlar birincil Kerberoasting hedefleridir. Eski parola çevrimdışı kırma saldırıları için pencereyi genişletir." `
        -RecTR "Servis hesaplarını parolalarını 30 günde bir otomatik döndüren gMSA'ya taşıyın. gMSA kullanamayan hesaplar için PSO aracılığıyla düzenli parola döndürme zorunlu kılın." `
        -AffectedCount $StaleServiceAccounts.Count -AffectedObjects @($StaleServiceAccounts | Select-Object -First 10 -ExpandProperty SamAccountName)
} else {
    Add-TierFinding -Id "T1-3" -Tier "Tier1" -Severity "OK" `
        -Title "No service accounts with stale passwords found" `
        -Description "All enabled service accounts have passwords set within the last 180 days, reducing Kerberoasting exposure." `
        -Recommendation "Consider migrating all service accounts to gMSA for automatic password management." `
        -TitleTR "Eski parolaya sahip servis hesabı bulunamadı" `
        -DescTR "Tüm etkin servis hesaplarının parolaları son 180 gün içinde ayarlanmış; Kerberoasting riski azaltılmış." `
        -RecTR "Otomatik parola yönetimi için tüm servis hesaplarını gMSA'ya taşımayı değerlendirin." `
        -AffectedCount 0 -AffectedObjects @()
}

# T1-4: Servers vs Workstations separation
$ServerOU  = @($OUTreeNodes | Where-Object { $_.Type -eq "ou" -and $_.Name -match 'server|srv' })
$WkstnOU   = @($OUTreeNodes | Where-Object { $_.Type -eq "ou" -and $_.Name -match 'workstation|desktop|wks|client|laptop' })
$ServerComputers  = @($AllComputers | Where-Object { $_.OperatingSystem -match 'Server' })
$ClientComputers  = @($AllComputers | Where-Object { $_.OperatingSystem -notmatch 'Server' -and $_.OperatingSystem })
$HasSeparation = ($ServerOU.Count -gt 0 -and $WkstnOU.Count -gt 0) -or ($ServerComputers.Count -eq 0) -or ($ClientComputers.Count -eq 0)
if (-not $HasSeparation) {
    Add-TierFinding -Id "T1-4" -Tier "Tier1" -Severity "Warning" `
        -Title "Servers and Workstations not separated into dedicated OUs" `
        -Description "No dedicated Server OU or Workstation OU was detected despite having both server ($($ServerComputers.Count)) and client ($($ClientComputers.Count)) computers. Mixing these in the same OU prevents granular GPO application (e.g., Windows Defender settings, update rings)." `
        -Recommendation "Create OU=Servers and OU=Workstations. Organize server sub-OUs by role (OU=FileServers, OU=WebServers, etc.). Apply role-specific GPOs at each level." `
        -TitleTR "Sunucular ve İş İstasyonları ayrı OU'lara ayrılmamış" `
        -DescTR "Her ikisi de mevcut olmasına rağmen ($($ServerComputers.Count) sunucu, $($ClientComputers.Count) istemci) özel Sunucu veya İş İstasyonu OU'su tespit edilmedi. Aynı OU'da karışık bulundurma, ayrıntılı GPO uygulamasını (Windows Defender, güncelleme halkaları vb.) engeller." `
        -RecTR "OU=Servers ve OU=Workstations oluşturun. Sunucu alt OU'larını role göre düzenleyin (OU=FileServers, OU=WebServers vb.). Her düzeyde role özel GPO'lar uygulayın." `
        -AffectedCount ($ServerComputers.Count + $ClientComputers.Count) -AffectedObjects @()
} else {
    Add-TierFinding -Id "T1-4" -Tier "Tier1" -Severity "OK" `
        -Title "Servers and Workstations are separated into dedicated OUs" `
        -Description "Dedicated Server and Workstation OUs are present, enabling granular policy application per computer role." `
        -Recommendation "Ensure servers are further organized by role for maximum policy granularity." `
        -TitleTR "Sunucular ve İş İstasyonları ayrı OU'lara ayrılmış" `
        -DescTR "Özel Sunucu ve İş İstasyonu OU'ları mevcut; bilgisayar rolüne göre ayrıntılı ilke uygulaması mümkün." `
        -RecTR "Maksimum ilke ayrıntısı için sunucuların role göre daha da düzenlendiğinden emin olun." `
        -AffectedCount 0 -AffectedObjects @()
}

# ---- Tier 2 Checks ----

# T2-1: Regular users in CN=Users
$UsersInDefaultContainer = @($AllUsersRaw | Where-Object {
    $_.DistinguishedName -match ',CN=Users,' -and
    $_.Enabled -eq $true -and
    -not ($PrivSamAccounts -contains $_.SamAccountName) -and
    $_.SamAccountName -notmatch '^(Administrator|Guest|krbtgt|DefaultAccount|WDAGUtilityAccount)$'
})
if ($UsersInDefaultContainer.Count -gt 0) {
    Add-TierFinding -Id "T2-1" -Tier "Tier2" -Severity "Warning" `
        -Title "Regular users in default CN=Users container ($($UsersInDefaultContainer.Count) accounts)" `
        -Description "$($UsersInDefaultContainer.Count) enabled, non-privileged user accounts remain in the default CN=Users container. This container cannot be targeted by GPOs directly, leaving these users without appropriate user policies." `
        -Recommendation "Move all regular user accounts into appropriate department or location OUs. Use redirusr.exe to redirect new user creation to a staging OU." `
        -TitleTR "Varsayılan CN=Users konteynerinde normal kullanıcılar ($($UsersInDefaultContainer.Count) hesap)" `
        -DescTR "$($UsersInDefaultContainer.Count) etkin, ayrıcalıksız kullanıcı hesabı varsayılan CN=Users konteynerinde. Bu konteyner doğrudan GPO'larla hedeflenemez; bu kullanıcılar uygun kullanıcı ilkelerinden yoksun kalır." `
        -RecTR "Tüm normal kullanıcı hesaplarını uygun departman veya konum OU'larına taşıyın. Yeni kullanıcı oluşturmayı bir hazırlama OU'suna yönlendirmek için redirusr.exe kullanın." `
        -AffectedCount $UsersInDefaultContainer.Count -AffectedObjects @($UsersInDefaultContainer | Select-Object -First 10 -ExpandProperty SamAccountName)
} else {
    Add-TierFinding -Id "T2-1" -Tier "Tier2" -Severity "OK" `
        -Title "No regular users in default CN=Users container" `
        -Description "All enabled regular user accounts have been moved from the default CN=Users container into proper OUs." `
        -Recommendation "Set the default user creation container using redirusr.exe." `
        -TitleTR "Varsayılan CN=Users konteynerinde normal kullanıcı yok" `
        -DescTR "Tüm etkin normal kullanıcı hesapları CN=Users konteynerinden uygun OU'lara taşınmış." `
        -RecTR "Yeni kullanıcı oluşturma için varsayılan konteyneri redirusr.exe ile ayarlayın." `
        -AffectedCount 0 -AffectedObjects @()
}

# T2-2: Disabled accounts in dedicated OU
$DisabledUsers   = @($AllUsersRaw | Where-Object { $_.Enabled -eq $false -and $_.SamAccountName -notmatch '^(Guest|WDAGUtilityAccount|DefaultAccount)$' })
$DisabledOU = @($OUTreeNodes | Where-Object { $_.Type -eq "ou" -and $_.Name -match 'disabled|inactive|retired|decommission|archive' })
$DisabledUsersInDisabledOU = 0
if ($DisabledOU.Count -gt 0) {
    foreach ($du in $DisabledUsers) {
        foreach ($dou in $DisabledOU) {
            if ($du.DistinguishedName -like "*,$($dou.Id)") {
                $DisabledUsersInDisabledOU++
                break
            }
        }
    }
}
if ($DisabledUsers.Count -gt 0 -and $DisabledOU.Count -eq 0) {
    Add-TierFinding -Id "T2-2" -Tier "Tier2" -Severity "Info" `
        -Title "No dedicated Disabled/Inactive OU found ($($DisabledUsers.Count) disabled accounts exist)" `
        -Description "$($DisabledUsers.Count) disabled accounts were found, but no dedicated 'Disabled' or 'Inactive' OU exists. Mixing disabled accounts with active accounts makes cleanup and auditing difficult and may cause confusion." `
        -Recommendation "Create OU=Disabled-Users and OU=Disabled-Computers. Move all disabled objects there. A scheduled task or Identity Governance solution should automate this movement upon account disable." `
        -TitleTR "Özel Devre Dışı/Etkin Olmayan OU bulunamadı ($($DisabledUsers.Count) devre dışı hesap mevcut)" `
        -DescTR "$($DisabledUsers.Count) devre dışı hesap bulundu ancak özel 'Disabled' veya 'Inactive' OU yok. Devre dışı hesapların aktif hesaplarla karışması temizlik ve denetimi zorlaştırır." `
        -RecTR "OU=Disabled-Users ve OU=Disabled-Computers oluşturun. Tüm devre dışı nesneleri oraya taşıyın. Hesap devre dışı bırakıldığında bu taşımayı otomatikleştirmek için zamanlanmış görev kullanın." `
        -AffectedCount $DisabledUsers.Count -AffectedObjects @($DisabledUsers | Select-Object -First 10 -ExpandProperty SamAccountName)
} elseif ($DisabledUsers.Count -gt 0 -and $DisabledUsersInDisabledOU -lt $DisabledUsers.Count) {
    Add-TierFinding -Id "T2-2" -Tier "Tier2" -Severity "Info" `
        -Title "Disabled accounts not fully consolidated in Disabled OU" `
        -Description "$($DisabledUsers.Count - $DisabledUsersInDisabledOU) of $($DisabledUsers.Count) disabled accounts are not in a dedicated Disabled/Inactive OU." `
        -Recommendation "Move all disabled accounts to the dedicated Disabled OU. Automate this process using a scheduled cleanup script." `
        -TitleTR "Devre dışı hesaplar tamamen Disabled OU'sunda değil" `
        -DescTR "$($DisabledUsers.Count) devre dışı hesabın $($DisabledUsers.Count - $DisabledUsersInDisabledOU) tanesi özel Disabled/Inactive OU'sunda değil." `
        -RecTR "Tüm devre dışı hesapları özel Disabled OU'suna taşıyın. Bu işlemi zamanlanmış temizlik betiğiyle otomatikleştirin." `
        -AffectedCount ($DisabledUsers.Count - $DisabledUsersInDisabledOU) -AffectedObjects @()
} else {
    Add-TierFinding -Id "T2-2" -Tier "Tier2" -Severity "OK" `
        -Title "Disabled accounts managed in dedicated OUs" `
        -Description "Disabled accounts are properly isolated in dedicated Disabled/Inactive OUs." `
        -Recommendation "Implement a lifecycle policy to delete accounts in the Disabled OU after 90+ days." `
        -TitleTR "Devre dışı hesaplar özel OU'larda yönetiliyor" `
        -DescTR "Devre dışı hesaplar özel Disabled/Inactive OU'larında düzgün şekilde izole edilmiş." `
        -RecTR "Disabled OU'sundaki hesapları 90+ günden sonra silmek için bir yaşam döngüsü ilkesi uygulayın." `
        -AffectedCount $DisabledUsersInDisabledOU -AffectedObjects @()
}

# T2-3: Admin account naming separation
$AdminNamePatterns = @('^admin\.','^\badmin\b','\.admin$','^adm\.','\.adm$','^a-','^adm-','^admin-','_adm$','_admin$')
$LikelyAdminAccounts = @($AllUsersRaw | Where-Object {
    $sam = $_.SamAccountName.ToLower()
    $AdminNamePatterns | Where-Object { $sam -match $_ }
} | Where-Object { -not ($PrivSamAccounts -contains $_.SamAccountName) })
$NamingScore = "OK"
if ($LikelyAdminAccounts.Count -gt 0) {
    Add-TierFinding -Id "T2-3" -Tier "Tier2" -Severity "Info" `
        -Title "Possible Tier 2 admin accounts detected with dedicated naming ($($LikelyAdminAccounts.Count) accounts)" `
        -Description "$($LikelyAdminAccounts.Count) accounts with admin-style naming (admin., adm-, etc.) found that are not members of Tier 0 privileged groups. This suggests workstation admin accounts exist separately from regular user accounts — a positive Tier Model indicator." `
        -Recommendation "Ensure these Tier 2 admin accounts are in a dedicated OU (e.g., OU=T2-Admins) and are covered by a Logon Workstations restriction GPO preventing them from logging into servers." `
        -TitleTR "Adlandırılmış Tier 2 yönetici hesapları tespit edildi ($($LikelyAdminAccounts.Count) hesap)" `
        -DescTR "Tier 0 ayrıcalıklı gruplarda yer almayan $($LikelyAdminAccounts.Count) yönetici tarzı adlandırmaya (admin., adm- vb.) sahip hesap bulundu. Bu, iş istasyonu yönetici hesaplarının normal kullanıcılardan ayrı tutulduğunu gösterir — olumlu bir Tier Modeli göstergesi." `
        -RecTR "Bu Tier 2 yönetici hesaplarının özel OU'da (ör. OU=T2-Admins) bulunduğundan ve sunucularda oturum açmayı engelleyen Oturum Açma kısıtlama GPO'suyla kapsandığından emin olun." `
        -AffectedCount $LikelyAdminAccounts.Count -AffectedObjects @($LikelyAdminAccounts | Select-Object -First 10 -ExpandProperty SamAccountName)
} else {
    Add-TierFinding -Id "T2-3" -Tier "Tier2" -Severity "Info" `
        -Title "No dedicated Tier 2 admin accounts detected" `
        -Description "No accounts with admin-style naming (admin., adm-, etc.) outside of Tier 0 groups were found. This may indicate local admin is managed via LAPS rather than dedicated admin accounts, or that named admin accounts use non-standard naming." `
        -Recommendation "Implement LAPS for local administrator management on workstations and use a jump host / PAW model for server administration." `
        -TitleTR "Özel Tier 2 yönetici hesabı tespit edilmedi" `
        -DescTR "Tier 0 grupları dışında yönetici tarzı adlandırmaya (admin., adm- vb.) sahip hesap bulunamadı. Bu, yerel yöneticinin LAPS aracılığıyla yönetildiğine ya da standart dışı isimlendirme kullanıldığına işaret edebilir." `
        -RecTR "İş istasyonlarındaki yerel yönetici yönetimi için LAPS kullanın, sunucu yönetimi için atlama sunucusu / PAW modeli uygulayın." `
        -AffectedCount 0 -AffectedObjects @()
}

# ---- OU Structure Checks ----

# OU-1: Empty OUs
$AllOUIds = @($OUTreeNodes | Where-Object { $_.Type -eq "ou" } | Select-Object -ExpandProperty Id)
$EmptyOUs = @()
foreach ($ou in ($OUTreeNodes | Where-Object { $_.Type -eq "ou" })) {
    $hasChildOU = @($OUTreeNodes | Where-Object { $_.ParentId -eq $ou.Id -and $_.Type -eq "ou" }).Count -gt 0
    $hasUserObj = @($AllUsersRaw | Where-Object { $_.DistinguishedName -match ",$($ou.Id)$" }).Count -gt 0
    $hasCompObj = @($AllComputers | Where-Object { $_.DistinguishedName -match ",$($ou.Id)$" }).Count -gt 0
    if (-not $hasChildOU -and -not $hasUserObj -and -not $hasCompObj) {
        $EmptyOUs += $ou
    }
}
if ($EmptyOUs.Count -gt 0) {
    Add-TierFinding -Id "OU-1" -Tier "OU" -Severity "Info" `
        -Title "Empty OUs detected ($($EmptyOUs.Count) OUs)" `
        -Description "$($EmptyOUs.Count) OUs contain no child OUs, users, or computers. Empty OUs clutter the directory, create confusion during administration, and may represent remnants of decommissioned organizational units." `
        -Recommendation "Review and remove OUs that are genuinely unused. If an OU is a placeholder for future use, add a description to document its purpose." `
        -TitleTR "Boş OU'lar tespit edildi ($($EmptyOUs.Count) OU)" `
        -DescTR "$($EmptyOUs.Count) OU; alt OU, kullanıcı veya bilgisayar içermiyor. Boş OU'lar dizini karmaşıklaştırır, yönetim sırasında kafa karışıklığı yaratır ve kullanımdan kaldırılan birimlerin kalıntılarını temsil edebilir." `
        -RecTR "Gerçekten kullanılmayan OU'ları gözden geçirip silin. OU gelecek için yer tutucuysa amacını belgelemek üzere açıklama ekleyin." `
        -AffectedCount $EmptyOUs.Count -AffectedObjects @($EmptyOUs | Select-Object -First 10 -ExpandProperty Name)
} else {
    Add-TierFinding -Id "OU-1" -Tier "OU" -Severity "OK" `
        -Title "No empty OUs found" `
        -Description "All OUs contain at least one child OU or object, keeping the directory clean." `
        -Recommendation "Periodically audit for empty OUs as objects are moved or deleted." `
        -TitleTR "Boş OU bulunamadı" `
        -DescTR "Tüm OU'lar en az bir alt OU veya nesne içeriyor; dizin temiz tutuluyor." `
        -RecTR "Nesneler taşındıkça veya silinirken boş OU'lar için dönemsel denetim yapın." `
        -AffectedCount 0 -AffectedObjects @()
}

# OU-2: Excessive OU depth
$DeepOUs = @($OUTreeNodes | Where-Object {
    $_.Type -eq "ou" -and
    ([regex]::Matches($_.Id, ',OU=')).Count -gt 7
})
if ($DeepOUs.Count -gt 0) {
    Add-TierFinding -Id "OU-2" -Tier "OU" -Severity "Warning" `
        -Title "Excessively deep OU nesting found ($($DeepOUs.Count) OUs deeper than 7 levels)" `
        -Description "$($DeepOUs.Count) OUs are nested more than 7 levels deep. Excessive depth makes administration complex, slows Group Policy processing, and increases the chance of GPO inheritance issues. Microsoft recommends 3-5 levels." `
        -Recommendation "Flatten the OU hierarchy where possible. Aim for a maximum of 5 levels. Use descriptive names at each level to compensate for reduced depth." `
        -TitleTR "Aşırı derin OU iç içe geçmesi ($($DeepOUs.Count) OU, 7 seviyeden derin)" `
        -DescTR "$($DeepOUs.Count) OU 7 seviyeden daha derin iç içe geçmiş. Aşırı derinlik yönetimi karmaşıklaştırır, Grup İlkesi işlemini yavaşlatır ve GPO devralma sorunlarını artırır. Microsoft 3-5 seviye öneriyor." `
        -RecTR "OU hiyerarşisini mümkün olan yerlerde düzleştirin. Maksimum 5 seviye hedefleyin. Azalan derinliği telafi etmek için her seviyede açıklayıcı isimler kullanın." `
        -AffectedCount $DeepOUs.Count -AffectedObjects @($DeepOUs | Select-Object -First 10 -ExpandProperty Name)
} else {
    Add-TierFinding -Id "OU-2" -Tier "OU" -Severity "OK" `
        -Title "OU depth within recommended range" `
        -Description "All OUs are nested within 7 levels, keeping the directory hierarchy manageable." `
        -Recommendation "Target 3-5 levels of OU depth for optimal administrative clarity." `
        -TitleTR "OU derinliği önerilen aralıkta" `
        -DescTR "Tüm OU'lar 7 seviye içinde iç içe geçmiş; dizin hiyerarşisi yönetilebilir durumda." `
        -RecTR "Optimum yönetim netliği için 3-5 seviye OU derinliği hedefleyin." `
        -AffectedCount 0 -AffectedObjects @()
}

# OU-3: Naming convention consistency
$OUNames = @($OUTreeNodes | Where-Object { $_.Type -eq "ou" } | Select-Object -ExpandProperty Name)
$UpperCount   = @($OUNames | Where-Object { $_ -cmatch '^[A-Z][A-Z\s\-_0-9]+$' }).Count
$LowerCount   = @($OUNames | Where-Object { $_ -cmatch '^[a-z]' }).Count
$CamelCount   = @($OUNames | Where-Object { $_ -cmatch '^[A-Z][a-z]' }).Count
$MixedNaming  = ($UpperCount -gt 0 -and $LowerCount -gt 0) -or ($UpperCount -gt 0 -and $CamelCount -gt 0 -and $LowerCount -gt 0)
if ($MixedNaming -and $OUNames.Count -gt 5) {
    Add-TierFinding -Id "OU-3" -Tier "OU" -Severity "Info" `
        -Title "Inconsistent OU naming conventions detected" `
        -Description "OUs use a mix of naming styles (UPPERCASE: $UpperCount, CamelCase: $CamelCount, lowercase: $LowerCount). Inconsistent naming makes it difficult to sort, search, and understand the OU structure at a glance." `
        -Recommendation "Adopt a consistent naming convention (recommend CamelCase or UPPERCASE for OUs). Document the standard in your AD design document and enforce it with a process for OU creation approval." `
        -TitleTR "Tutarsız OU isimlendirme kuralları tespit edildi" `
        -DescTR "OU'lar karışık isimlendirme stilleri kullanıyor (BÜYÜK HARF: $UpperCount, CamelCase: $CamelCount, küçük harf: $LowerCount). Tutarsız isimlendirme OU yapısının bir bakışta anlaşılmasını zorlaştırır." `
        -RecTR "Tutarlı bir isimlendirme kuralı benimseyin (OU'lar için CamelCase veya BÜYÜK HARF önerilir). Standardı AD tasarım belgenizde belgeleyin ve OU oluşturma onay süreciyle zorunlu kılın." `
        -AffectedCount $OUNames.Count -AffectedObjects @($OUNames | Select-Object -First 5)
} else {
    Add-TierFinding -Id "OU-3" -Tier "OU" -Severity "OK" `
        -Title "OU naming convention is consistent" `
        -Description "OUs follow a consistent naming style across the directory." `
        -Recommendation "Document the naming convention so future administrators follow the same standard." `
        -TitleTR "OU isimlendirme kuralı tutarlı" `
        -DescTR "OU'lar dizin genelinde tutarlı bir isimlendirme stili izliyor." `
        -RecTR "Gelecekteki yöneticilerin aynı standardı takip edebilmesi için isimlendirme kuralını belgeleyin." `
        -AffectedCount 0 -AffectedObjects @()
}

# OU-4: Objects directly under domain root (in no OU)
$ObjectsInDomainRoot = @($AllUsersRaw | Where-Object {
    $dn = $_.DistinguishedName
    $dn -match "^CN=[^,]+,$([regex]::Escape($DomainDN))$" -and
    $dn -notmatch ',OU=' -and $dn -notmatch ',CN=Users' -and $dn -notmatch ',CN=Computers'
})
$CompsInDomainRoot = @($AllComputers | Where-Object {
    $dn = $_.DistinguishedName
    $dn -match "^CN=[^,]+,$([regex]::Escape($DomainDN))$" -and
    $dn -notmatch ',OU=' -and $dn -notmatch ',CN=Computers'
})
$TotalRootObjects = $ObjectsInDomainRoot.Count + $CompsInDomainRoot.Count
if ($TotalRootObjects -gt 0) {
    Add-TierFinding -Id "OU-4" -Tier "OU" -Severity "Warning" `
        -Title "Objects found directly under domain root ($TotalRootObjects objects)" `
        -Description "$TotalRootObjects objects (users: $($ObjectsInDomainRoot.Count), computers: $($CompsInDomainRoot.Count)) are stored directly in the domain root, outside any OU. These objects inherit only domain-level GPOs and cannot be managed with OU-scoped policies." `
        -Recommendation "Move all objects into appropriate OUs. Configure redircmp and redirusr to prevent future objects from landing in root containers." `
        -TitleTR "Domain kökünde doğrudan nesne bulundu ($TotalRootObjects nesne)" `
        -DescTR "$TotalRootObjects nesne (kullanıcı: $($ObjectsInDomainRoot.Count), bilgisayar: $($CompsInDomainRoot.Count)) herhangi bir OU dışında, doğrudan domain kökünde depolanıyor. Bu nesneler yalnızca domain düzeyindeki GPO'ları devralır ve OU kapsamlı ilkelerle yönetilemez." `
        -RecTR "Tüm nesneleri uygun OU'lara taşıyın. Gelecekte nesnelerin kök konteynerlere düşmesini önlemek için redircmp ve redirusr'u yapılandırın." `
        -AffectedCount $TotalRootObjects -AffectedObjects @($ObjectsInDomainRoot | Select-Object -First 5 -ExpandProperty SamAccountName)
} else {
    Add-TierFinding -Id "OU-4" -Tier "OU" -Severity "OK" `
        -Title "No objects found directly in domain root" `
        -Description "All objects are placed inside OUs, enabling proper GPO targeting and administration." `
        -Recommendation "Use redircmp and redirusr to enforce this for new objects." `
        -TitleTR "Domain kökünde doğrudan nesne bulunamadı" `
        -DescTR "Tüm nesneler OU'ların içine yerleştirilmiş; düzgün GPO hedefleme ve yönetim mümkün." `
        -RecTR "Yeni nesnelerde bunu uygulamak için redircmp ve redirusr kullanın." `
        -AffectedCount 0 -AffectedObjects @()
}

# OU-5: OU breadth (too many OUs at same level)
$ParentGroups = $OUTreeNodes | Where-Object { $_.Type -eq "ou" } | Group-Object ParentId
$TooWideOUs = @($ParentGroups | Where-Object { $_.Count -gt 20 })
if ($TooWideOUs.Count -gt 0) {
    $wideParentNames = @($TooWideOUs | ForEach-Object {
        $pid = $_.Name
        ($OUTreeNodes | Where-Object { $_.Id -eq $pid } | Select-Object -First 1).Name
    } | Where-Object { $_ })
    Add-TierFinding -Id "OU-5" -Tier "OU" -Severity "Info" `
        -Title "Excessive OU breadth at some levels (>20 OUs under same parent)" `
        -Description "$($TooWideOUs.Count) container(s) have more than 20 child OUs. An overly wide OU structure makes navigation and delegation assignment difficult." `
        -Recommendation "Introduce intermediate grouping OUs to organize wide hierarchies. For example, group country-level OUs under a region-level OU." `
        -TitleTR "Bazı seviyelerde aşırı OU genişliği (aynı üst öğe altında >20 OU)" `
        -DescTR "$($TooWideOUs.Count) konteyner 20'den fazla alt OU içeriyor. Aşırı geniş OU yapısı gezinmeyi ve yetki devir atamasını zorlaştırır." `
        -RecTR "Geniş hiyerarşileri düzenlemek için ara gruplama OU'ları ekleyin. Örneğin ülke düzeyindeki OU'ları bölge düzeyindeki OU altında gruplayın." `
        -AffectedCount $TooWideOUs.Count -AffectedObjects $wideParentNames
} else {
    Add-TierFinding -Id "OU-5" -Tier "OU" -Severity "OK" `
        -Title "OU breadth within acceptable range" `
        -Description "No container has more than 20 direct child OUs, keeping navigation manageable." `
        -Recommendation "If the directory grows significantly, revisit the breadth with a geographic or functional grouping." `
        -TitleTR "OU genişliği kabul edilebilir aralıkta" `
        -DescTR "Hiçbir konteyner 20'den fazla doğrudan alt OU'ya sahip değil; gezinme yönetilebilir durumda." `
        -RecTR "Dizin önemli ölçüde büyürse genişliği coğrafi veya fonksiyonel gruplama ile yeniden değerlendirin." `
        -AffectedCount 0 -AffectedObjects @()
}

# ---- Compute Tier Compliance Score ----
$TierScoreDeductions = @{
    "Critical" = 20
    "Warning"  = 8
    "Info"     = 2
    "OK"       = 0
}
$TierRawDeduction = 0
foreach ($f in $TierFindings) {
    $TierRawDeduction += $TierScoreDeductions[$f.Severity]
}
$TierComplianceScore = [math]::Max(0, [math]::Min(100, 100 - $TierRawDeduction))
$TierScoreColor = if ($TierComplianceScore -ge 80) { '#22c55e' } elseif ($TierComplianceScore -ge 60) { '#eab308' } elseif ($TierComplianceScore -ge 40) { '#f97316' } else { '#ef4444' }
$TierScoreLabel = if ($TierComplianceScore -ge 80) { 'Good' } elseif ($TierComplianceScore -ge 60) { 'Needs Improvement' } elseif ($TierComplianceScore -ge 40) { 'Poor' } else { 'Critical' }

$TierCriticalCount = @($TierFindings | Where-Object { $_.Severity -eq "Critical" }).Count
$TierWarningCount  = @($TierFindings | Where-Object { $_.Severity -eq "Warning"  }).Count
$TierInfoCount     = @($TierFindings | Where-Object { $_.Severity -eq "Info"     }).Count
$TierOKCount       = @($TierFindings | Where-Object { $_.Severity -eq "OK"       }).Count

$Tier0CritCount = @($TierFindings | Where-Object { $_.Tier -eq "Tier0" -and $_.Severity -eq "Critical" }).Count
$Tier0WarnCount = @($TierFindings | Where-Object { $_.Tier -eq "Tier0" -and $_.Severity -eq "Warning"  }).Count
$Tier1CritCount = @($TierFindings | Where-Object { $_.Tier -eq "Tier1" -and $_.Severity -eq "Critical" }).Count
$Tier1WarnCount = @($TierFindings | Where-Object { $_.Tier -eq "Tier1" -and $_.Severity -eq "Warning"  }).Count
$Tier2CritCount = @($TierFindings | Where-Object { $_.Tier -eq "Tier2" -and $_.Severity -eq "Critical" }).Count
$Tier2WarnCount = @($TierFindings | Where-Object { $_.Tier -eq "Tier2" -and $_.Severity -eq "Warning"  }).Count
$OUCritCount    = @($TierFindings | Where-Object { $_.Tier -eq "OU"    -and $_.Severity -eq "Critical" }).Count
$OUWarnCount    = @($TierFindings | Where-Object { $_.Tier -eq "OU"    -and $_.Severity -eq "Warning"  }).Count

$_tierArc = [math]::Round($TierComplianceScore * 251.2 / 100, 1)

Write-Progress -Activity "KusoADCheck" -Status "Generating HTML report..." -PercentComplete 92

# ---------------------
# HTML Start (Shortened)
# ---------------------
$ReportDate = (Get-Date).ToString("dd MMM yyyy  HH:mm")
$HeaderDCCount = @($DCs).Count
$HeaderUserCount = @($Users).Count
$HeaderRiskPillClass = switch ($RiskRating) {
    "Good"       { "header-meta-pill pill-risk-ok" }
    "Acceptable" { "header-meta-pill pill-risk-ok" }
    "Poor"       { "header-meta-pill pill-risk-poor" }
    default      { "header-meta-pill pill-risk-critical" }
}
$Html = @"
