function safeArray(input){
    return Array.isArray(input) ? input : (input ? [input] : []);
}

function scrollRiskStoryboard(anchorId){
    var node = document.getElementById(anchorId);
    if (!node) return;
    var el = node.parentElement;
    while (el) { if (el.tagName === 'DETAILS') el.open = true; el = el.parentElement; }
    if (node.tagName === 'DETAILS') node.open = true;
    if (node.tagName === 'SUMMARY' && node.parentElement) node.parentElement.open = true;
    try {
        node.scrollIntoView({ behavior: 'smooth', block: 'start' });
    } catch (e) {
        node.scrollIntoView(true);
    }
}

function escapeHtml(text){
    return String(text || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function invFilterInactive(tableId, minDays, maxDays, btn) {
    if (btn) {
        var chips = btn.parentElement.querySelectorAll('.inv-chip');
        chips.forEach(function(c){ c.classList.remove('active'); });
        btn.classList.add('active');
    }
    var table = document.getElementById(tableId);
    if (!table) return;
    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    rows.forEach(function(row){
        var d = parseInt(row.getAttribute('data-days') || '0', 10);
        var show = (d >= minDays) && (maxDays == null || d <= maxDays);
        row.style.display = show ? '' : 'none';
    });
}

function setRqjActive(btn) {
    var nav = btn.closest('.risk-quick-nav');
    if (!nav) return;
    nav.querySelectorAll('.risk-quick-jump, .rqj-cat').forEach(function(b){ b.classList.remove('rqj-active'); });
    btn.classList.add('rqj-active');
}

function invFilterInactiveCustom(tableId, inputId) {
    var val = parseInt(document.getElementById(inputId).value, 10);
    if (isNaN(val) || val < 1) return;
    var chips = document.querySelectorAll('#' + inputId + '-chips .inv-chip');
    chips.forEach(function(c){ c.classList.remove('active'); });
    invFilterInactive(tableId, val, null, null);
}

function diFilter(val, btn) {
    var chips = document.querySelectorAll('#diChips .inv-chip');
    chips.forEach(function(c){ c.classList.remove('active'); });
    if (btn) {
        btn.classList.add('active');
    } else {
        // card click — activate matching chip if present
        chips.forEach(function(c){ if (c.textContent.trim().startsWith(val === 'Safe' ? 'Safe' : val)) c.classList.add('active'); });
    }
    document.querySelectorAll('#diTable tr[data-risk]').forEach(function(r){
        var risk = r.getAttribute('data-risk');
        var type = r.getAttribute('data-type');
        var show = (val === 'all') || (risk === val) || (type === val);
        r.style.display = show ? '' : 'none';
    });
}

function invFilterGroupCat(tableId, cat, btn) {
    if (btn && btn.classList && btn.classList.contains('inv-chip')) {
        var chips = btn.parentElement.querySelectorAll('.inv-chip');
        chips.forEach(function(c){ c.classList.remove('active'); });
        btn.classList.add('active');
    } else if (btn && btn.classList && btn.classList.contains('section-stat-card')) {
        btn.parentElement.querySelectorAll('.section-stat-card').forEach(function(c){ c.style.outline='none'; });
        if (cat !== 'all') btn.style.outline = '2px solid #2563eb';
    }
    var table = document.getElementById(tableId);
    if (!table) return;
    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    rows.forEach(function(row){
        var gc = row.getAttribute('data-groupcat') || '';
        var isEmpty = row.getAttribute('data-empty') === '1';
        var show = cat === 'all' || gc === cat || (cat === 'empty' && isEmpty);
        row.style.display = show ? '' : 'none';
    });
}

function invFilterExchange(tableId, mode, card) {
    if (card) {
        var grid = card.parentElement;
        grid.querySelectorAll('.section-stat-card').forEach(function(c){ c.style.outline='none'; });
        if (mode !== 'all') card.style.outline = '2px solid #2563eb';
    }
    var table = document.getElementById(tableId);
    if (!table) return;
    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    rows.forEach(function(row){
        var t = (row.getAttribute('data-mailtype') || '').toLowerCase();
        row.style.display = (mode === 'all' || t === mode) ? '' : 'none';
    });
}

function invFilterOs(tableId, mode, btn) {
    var chips = btn.parentElement.querySelectorAll('.inv-chip');
    chips.forEach(function(c){ c.classList.remove('active'); });
    btn.classList.add('active');
    var table = document.getElementById(tableId);
    if (!table) return;
    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    rows.forEach(function(row){
        if (mode === 'all') { row.style.display = ''; return; }
        var dot = row.querySelector('.activity-dot');
        var show = false;
        if (!dot) { show = (mode === 'all'); }
        else if (mode === 'active') show = dot.classList.contains('activity-dot--active');
        else if (mode === 'stale')  show = dot.classList.contains('activity-dot--warn') || dot.classList.contains('activity-dot--dead');
        else if (mode === 'never')  show = dot.classList.contains('activity-dot--never');
        row.style.display = show ? '' : 'none';
    });
}

function invFilterUsers(tableId, mode, btn) {
    var chips = btn.parentElement.querySelectorAll('.inv-chip');
    chips.forEach(function(c){ c.classList.remove('active'); });
    btn.classList.add('active');
    var table = document.getElementById(tableId);
    if (!table) return;
    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    rows.forEach(function(row){
        if (mode === 'all') { row.style.display = ''; return; }
        var cells = row.querySelectorAll('td');
        var show = false;
        if (mode === 'privileged') {
            show = (cells[4] && (cells[4].getAttribute('data-raw') === 'Yes' || cells[4].innerText.trim() === 'Yes')) ||
                   (cells[5] && (cells[5].getAttribute('data-raw') === 'Yes' || cells[5].innerText.trim() === 'Yes')) ||
                   (cells[6] && (cells[6].getAttribute('data-raw') === 'Yes' || cells[6].innerText.trim() === 'Yes'));
        } else if (mode === 'disabled') {
            show = cells[1] && cells[1].innerText.trim() === 'No';
        } else if (mode === 'pwdne') {
            show = cells[2] && cells[2].innerText.trim() === 'Yes';
        }
        row.style.display = show ? '' : 'none';
    });
}

function safeBase64Encode(str){
    try {
        return btoa(unescape(encodeURIComponent(String(str || ''))));
    } catch (e) {
        return '';
    }
}

function safeBase64Decode(str){
    try {
        return decodeURIComponent(escape(atob(String(str || ''))));
    } catch (e) {
        return '';
    }
}

function updateHashFromState(){
    var state = {
        c: currentContainerId || 'pingCastleRisksContainer',
        rf: currentRiskFocusMode || 'all',
        tf: currentTrackingFilter || 'all',
        dm: document.body.classList.contains('dark-mode') ? 1 : 0,
        lg: currentLanguage || 'en'
    };
    var encoded = safeBase64Encode(JSON.stringify(state));
    if (encoded) window.location.hash = encoded;
}

function readHashState(){
    var h = (window.location.hash || '').replace(/^#/, '');
    if (!h) return null;
    var text = safeBase64Decode(h);
    if (!text) return null;
    try {
        return JSON.parse(text);
    } catch (e) {
        return null;
    }
}

function applyDarkMode(enabled){
    if (enabled) document.body.classList.add('dark-mode');
    else document.body.classList.remove('dark-mode');
    try { localStorage.setItem('adcheck-dark-mode', enabled ? '1' : '0'); } catch(e){}
}

function toggleDarkMode(){
    var enabled = !document.body.classList.contains('dark-mode');
    applyDarkMode(enabled);
    updateHashFromState();
}

function copyPermalinkState(){
    updateHashFromState();
    var url = window.location.href;
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(function(){
            alert(textFor('alert.permalinkCopied', 'Permalink copied to clipboard.'));
        }).catch(function(){
            alert(textFor('alert.permalinkFallback', 'Permalink: ') + url);
        });
    } else {
        alert(textFor('alert.permalinkFallback', 'Permalink: ') + url);
    }
}

function drawRiskTrendSparkline(){
    var svg = document.getElementById('riskTrendSparkline');
    var currentBadge = document.getElementById('riskTrendCurrentBadge');
    if (!svg) return;
    var rows = safeArray(riskTrendSeries).slice(-24);
    if (!rows.length) {
        if (currentBadge) currentBadge.innerText = 'Current: -/100';
        svg.innerHTML = '<text x="12" y="56" fill="#5a6f84" font-size="12">No trend data available yet.</text>';
        return;
    }

    var w = 640, h = 120, padX = 18, padY = 20;
    var scores = rows.map(function(r){
        var v = parseFloat(r.DomainRiskScore);
        if (isNaN(v)) v = 0;
        return Math.max(0, Math.min(100, v));
    });

    var pathParts = [];
    for (var i = 0; i < scores.length; i++) {
        var x = padX + ((w - (padX * 2)) * (scores.length === 1 ? 0.5 : (i / (scores.length - 1))));
        var y = (h - padY) - ((h - (padY * 2)) * (scores[i] / 100));
        pathParts.push((i === 0 ? 'M' : 'L') + x.toFixed(2) + ' ' + y.toFixed(2));
    }

    var grid = '';
    [0,25,50,75,100].forEach(function(v){
        var gy = (h - padY) - ((h - (padY * 2)) * (v / 100));
        grid += '<line class="risk-trend-axis" x1="' + padX + '" y1="' + gy.toFixed(2) + '" x2="' + (w-padX) + '" y2="' + gy.toFixed(2) + '" />';
    });

    var points = '';
    scores.forEach(function(s, i){
        var x = padX + ((w - (padX * 2)) * (scores.length === 1 ? 0.5 : (i / (scores.length - 1))));
        var y = (h - padY) - ((h - (padY * 2)) * (s / 100));
        var cls = (i === scores.length - 1) ? 'risk-trend-point risk-trend-last' : 'risk-trend-point';
        points += '<circle class="' + cls + '" cx="' + x.toFixed(2) + '" cy="' + y.toFixed(2) + '" r="3.4" />';
    });

    var firstLabel = rows[0].GeneratedAt || '-';
    var lastLabel = rows[rows.length - 1].GeneratedAt || '-';
    var lastScore = scores[scores.length - 1];
    if (currentBadge) currentBadge.innerText = 'Current: ' + lastScore.toFixed(0) + '/100';

    svg.innerHTML =
        grid +
        '<path class="risk-trend-line" d="' + pathParts.join(' ') + '"></path>' +
        points +
        '<text x="' + padX + '" y="114" fill="#5a6f84" font-size="11">' + String(firstLabel).replace(/</g,'&lt;') + '</text>' +
        '<text x="' + (w - padX) + '" y="114" fill="#5a6f84" font-size="11" text-anchor="end">' + String(lastLabel).replace(/</g,'&lt;') + '</text>';
}

function buildAttackChainGraph(){
    var graphNode = document.getElementById('attackChainGraph');
    var whyList = document.getElementById('attackChainWhyList');
    if (!graphNode) return;

    var nodes = safeArray(attackChainNodes).slice(0, 3);
    var isTR = (currentLanguage === 'tr');
    function reasonForNode(n){
        var cat = String((n && n.Category) || '').toLowerCase();
        var sev = String((n && n.Severity) || '').toLowerCase();
        if (isTR) {
            if (cat.indexOf('privileged') >= 0) return 'Ayrıcalıklı kimlik/kontrol katmanını doğrudan etkiler; eskalasyona zemin hazırlar.';
            if (cat.indexOf('trust') >= 0) return 'Güven duruşu saldırganın sınırlar arası hareketini genişletebilir.';
            if (cat.indexOf('anomal') >= 0) return 'Davranış/yapılandırma anomalisi, istismar edilebilir kimlik kaymasına işaret eder.';
            if (cat.indexOf('stale') >= 0) return 'Hareketsiz nesneler gereksiz erişim yollarını korur.';
            if (sev === 'critical') return 'Kritik önem derecesi — çözümlenmezse yüksek patlama yarıçapı riski.';
            if (sev === 'high') return 'Yüksek önem derecesi — gerçekçi istismar potansiyeli taşıyor.';
            return 'Domain ele geçirilmesine giden birikimli yola katkıda bulunur.';
        }
        if (cat.indexOf('privileged') >= 0) return 'Directly impacts privileged identity/control plane, enabling escalation.';
        if (cat.indexOf('trust') >= 0) return 'Trust posture can expand attacker movement across boundaries.';
        if (cat.indexOf('anomal') >= 0) return 'Behavior/config anomaly often signals exploitable identity drift.';
        if (cat.indexOf('stale') >= 0) return 'Dormant objects preserve unnecessary access paths.';
        if (sev === 'critical') return 'Critical severity with high blast radius if left unresolved.';
        if (sev === 'high') return 'High severity with realistic exploitation potential.';
        return 'Contributes to cumulative path toward domain compromise.';
    }

    var noFindingsLabel = isTR ? 'Aktif Kritik/Yüksek bulgu yok' : 'No active Critical/High findings';
    var baselineLabel   = isTR ? 'Temel kontrolleri koru' : 'Keep baseline controls';
    var noChainMsg      = isTR ? '<li>Aktif Kritik/Yüksek zincir tespit edilmedi.</li>' : '<li>No active Critical/High chain detected.</li>';
    var initialAccess   = isTR ? 'İlk Erişim' : 'Initial Access';
    var identityFH      = isTR ? 'Kimlik Tutunma Noktası' : 'Identity Foothold';
    var domainRisk      = isTR ? 'Domain Ele Geçirme Riski' : 'Domain Dominance Risk';
    var stepLabel       = isTR ? 'Adım ' : 'Step ';

    var html = '<div class="ac-flow">';
    html += '<div class="ac-node ac-node-start"><div class="ac-node-label">' + escapeHtml(initialAccess) + '</div></div>';
    if (!nodes.length) {
        html += '<div class="ac-arrow">&#8594;</div>';
        html += '<div class="ac-node ac-node-good"><div class="ac-node-label">' + escapeHtml(noFindingsLabel) + '</div></div>';
        if (whyList) whyList.innerHTML = noChainMsg;
    } else {
        var reasons = [];
        for (var i = 0; i < nodes.length; i++) {
            var n = nodes[i] || {};
            var sev = String(n.Severity || '').toLowerCase();
            var sevClass = (sev === 'critical') ? 'ac-node-critical' : 'ac-node-high';
            var arrowColor = (sev === 'critical') ? '#ef4444' : '#f97316';
            var why = reasonForNode(n);
            html += '<div class="ac-arrow" style="color:' + arrowColor + '">&#8594;</div>';
            html += '<div class="ac-node ' + sevClass + '">';
            html += '<div class="ac-step-lbl">' + stepLabel + (i + 1) + '</div>';
            html += '<div class="ac-node-cat">' + escapeHtml(String(n.Category || '')) + '</div>';
            html += '<div class="ac-node-rule">' + escapeHtml(String(n.Rule || '')) + '</div>';
            html += '<div class="ac-node-why">' + escapeHtml(why) + '</div>';
            html += '</div>';
            reasons.push('<li><b>' + stepLabel + (i + 1) + ' &mdash; ' + escapeHtml(String(n.Rule || '')) + ':</b> ' + escapeHtml(why) + '</li>');
        }
        if (whyList) whyList.innerHTML = reasons.join('');
    }
    html += '<div class="ac-arrow" style="color:#ef4444">&#8594;</div>';
    html += '<div class="ac-node ac-node-end"><div class="ac-node-label">' + escapeHtml(domainRisk) + '</div></div>';
    html += '</div>';
    graphNode.innerHTML = html;
}


function loadRemediationTracking(){
    try {
        var raw = localStorage.getItem('adcheck-remediation-tracking');
        remediationTrackingStore = raw ? JSON.parse(raw) : {};
    } catch (e) {
        remediationTrackingStore = {};
    }
}

function getTrackingEntry(key){
    var raw = remediationTrackingStore[key];
    if (typeof raw === 'string') return { status: String(raw || 'open').toLowerCase(), reason: '' };
    if (raw && typeof raw === 'object') {
        return {
            status: String(raw.status || 'open').toLowerCase(),
            reason: String(raw.reason || '')
        };
    }
    return { status: 'open', reason: '' };
}

function setTrackingEntry(key, entry){
    remediationTrackingStore[key] = {
        status: String((entry && entry.status) || 'open').toLowerCase(),
        reason: String((entry && entry.reason) || '')
    };
}

function buildTrackingCell(entry){
    var st = String((entry && entry.status) || 'open').toLowerCase();
    var rs = String((entry && entry.reason) || '');
    var meta = remediationStatusMeta(st);
    var reasonChip = '';
    if (st === 'exception' && rs.trim()) {
        reasonChip = ' <span class="exception-reason-chip" title="' + escapeHtml(rs) + '">Reason: ' + escapeHtml(rs) + '</span>';
    }
    return '<select class="risk-action-btn" style="padding:4px 6px;font-size:11px;" onchange="setFindingStatus(this)">' +
        '<option value="open"' + (st === 'open' ? ' selected' : '') + '>Open</option>' +
        '<option value="fix"' + (st === 'fix' ? ' selected' : '') + '>Fixed</option>' +
        '<option value="accepted"' + (st === 'accepted' ? ' selected' : '') + '>Accepted</option>' +
        '<option value="exception"' + (st === 'exception' ? ' selected' : '') + '>Exception</option>' +
        '</select> <span class="' + meta.cls + '">' + meta.label + '</span>' + reasonChip;
}

function saveRemediationTracking(){
    try { localStorage.setItem('adcheck-remediation-tracking', JSON.stringify(remediationTrackingStore)); } catch(e){}
}

function remediationStatusMeta(status){
    var s = String(status || 'open').toLowerCase();
    if (s === 'fix') return { cls: 'remediation-status-pill remediation-status-fix', label: 'Fixed' };
    if (s === 'accepted') return { cls: 'remediation-status-pill remediation-status-accepted', label: 'Accepted' };
    if (s === 'exception') return { cls: 'remediation-status-pill remediation-status-exception', label: 'Exception' };
    return { cls: 'remediation-status-pill remediation-status-open', label: 'Open' };
}

function findingKeyFromRow(row){
    if (!row || !row.cells || row.cells.length < 3) return '';
    var category = (row.cells[0].innerText || '').trim();
    var rule = (row.cells[2].innerText || '').trim();
    return category + '||' + rule;
}

function initRemediationTracking(){
    loadRemediationTracking();
    var table = document.getElementById('pingCastleRiskTable');
    if (!table) return;

    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    rows.forEach(function(row){
        if (!row.cells || row.cells.length < 8) return;
        var key = findingKeyFromRow(row);
        var statusCell = row.cells[6];
        if (!statusCell) return;

        var entry = getTrackingEntry(key);
        statusCell.innerHTML = buildTrackingCell(entry);
    });

    filterRemediationStatus(currentTrackingFilter || 'all');
}

function setFindingStatus(selectEl){
    var row = selectEl;
    while (row && row.tagName !== 'TR') row = row.parentElement;
    if (!row) return;
    var key = findingKeyFromRow(row);
    var status = (selectEl.value || 'open').toLowerCase();
    var entry = getTrackingEntry(key);
    var previousStatus = entry.status;

    if (status === 'exception') {
        var reasonInput = prompt('Exception reason is required for audit. Enter reason:', entry.reason || '');
        if (reasonInput === null) {
            selectEl.value = previousStatus;
            return;
        }
        reasonInput = String(reasonInput || '').trim();
        if (!reasonInput) {
            alert('Exception requires a reason. Status change cancelled.');
            selectEl.value = previousStatus;
            return;
        }
        entry.reason = reasonInput;
    } else {
        entry.reason = '';
    }

    entry.status = status;
    setTrackingEntry(key, entry);
    saveRemediationTracking();

    var statusCell = row.cells[6];
    if (statusCell) {
        statusCell.innerHTML = buildTrackingCell(entry);
    }

    filterRemediationStatus(currentTrackingFilter || 'all');
}

function filterRemediationStatus(mode){
    currentTrackingFilter = mode || 'all';
    var table = document.getElementById('pingCastleRiskTable');
    if (!table) return;
    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    var visible = 0;

    rows.forEach(function(row){
        var key = findingKeyFromRow(row);
        var status = getTrackingEntry(key).status;
        var show = (currentTrackingFilter === 'all') || (status === currentTrackingFilter);
        row.style.display = show ? '' : 'none';
        if (show) visible++;
    });

    var chips = Array.from(document.querySelectorAll('.track-focus-chip'));
    chips.forEach(function(chip){
        var v = chip.getAttribute('data-track') || 'all';
        if (v === currentTrackingFilter) chip.classList.add('active');
        else chip.classList.remove('active');
    });

    var summary = document.getElementById('trackingSummary');
    if (summary) summary.innerText = visible + ' findings shown | filter: ' + currentTrackingFilter;
    updateHashFromState();
}

function exportRemediationTrackingJson(){
    var table = document.getElementById('pingCastleRiskTable');
    if (!table) return;
    var rows = Array.from(table.querySelectorAll('tr')).slice(1);
    var payload = rows.map(function(row){
        var key = findingKeyFromRow(row);
        var entry = getTrackingEntry(key);
        return {
            Category: (row.cells[0] ? row.cells[0].innerText.trim() : ''),
            Severity: (row.cells[1] ? row.cells[1].innerText.trim() : ''),
            Rule: (row.cells[2] ? row.cells[2].innerText.trim() : ''),
            Count: (row.cells[3] ? row.cells[3].innerText.trim() : ''),
            Status: entry.status || 'open',
            ExceptionReason: entry.reason || ''
        };
    });

    var blob = new Blob([JSON.stringify({ GeneratedAt: new Date().toISOString(), Findings: payload }, null, 2)], { type: 'application/json' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'remediation_tracking.json';
    a.click();
    URL.revokeObjectURL(a.href);
}

function _pdfFromCanvas(canvas, fileName){
    var jsPDF = (window.jspdf || {}).jsPDF;
    if (!jsPDF) { alert('jsPDF not loaded yet, try again in a moment.'); return; }
    var pdf = new jsPDF({ orientation: 'l', unit: 'mm', format: 'a4' });
    var pageW = pdf.internal.pageSize.getWidth();
    var pageH = pdf.internal.pageSize.getHeight();
    var imgW = pageW;
    var imgH = (canvas.height * pageW) / canvas.width;
    var heightLeft = imgH;
    var pos = 0;
    var imgData = canvas.toDataURL('image/png');
    pdf.addImage(imgData,'PNG',0,pos,imgW,imgH);
    heightLeft -= pageH;
    while(heightLeft > 0){
        pos -= pageH;
        pdf.addPage();
        pdf.setFillColor(255,255,255);
        pdf.rect(0,0,pageW,pageH,'F');
        pdf.addImage(imgData,'PNG',0,pos,imgW,imgH);
        heightLeft -= pageH;
    }
    pdf.save(fileName + '.pdf');
}

function _showPdfLoader(show){
    var ov = document.getElementById('loadingOverlay');
    if(!ov) return;
    if(show){ ov.style.display='flex'; ov.classList.add('visible'); }
    else { ov.classList.remove('visible'); setTimeout(function(){ ov.style.display='none'; },320); }
}

function openPrintHtml(title, htmlBody){
    var holder = document.createElement('div');
    holder.style.cssText = 'position:fixed;left:-9999px;top:0;width:794px;padding:24px 28px;background:#fff;font-family:Segoe UI,Arial,sans-serif;color:#1c2d3f;font-size:13px;line-height:1.5;';
    holder.innerHTML = '<style>h1{margin:0 0 8px 0;font-size:20px;}h2{margin:16px 0 6px 0;font-size:14px;}ul,ol{margin:4px 0 10px 18px;}li{margin-bottom:5px;}.small{font-size:11px;color:#4a5f75;}</style>' + htmlBody;
    document.body.appendChild(holder);
    _showPdfLoader(true);
    setTimeout(function(){
        html2canvas(holder,{scale:1.5,useCORS:true,logging:false,width:794,height:holder.scrollHeight,windowWidth:794}).then(function(canvas){
            document.body.removeChild(holder);
            _pdfFromCanvas(canvas, title);
            _showPdfLoader(false);
        }).catch(function(err){
            document.body.removeChild(holder);
            _showPdfLoader(false);
            alert('PDF error: ' + err.message);
        });
    },200);
}

function exportExecutiveSummaryPdf(){
    var scoreText = (document.querySelector('.risk-gauge-score') || {}).innerText || '-';
    var levelText = (document.querySelector('.risk-score-text h3') || {}).innerText || 'Domain Risk Level';
    var topRows = Array.from(document.querySelectorAll('#pingCastleRiskTable tr')).slice(1, 6);
    var listHtml = '<ul>';
    topRows.forEach(function(row){
        if (!row.cells || row.cells.length < 6) return;
        listHtml += '<li><b>[' + row.cells[1].innerText + ']</b> ' + row.cells[2].innerText + ' - ' + row.cells[5].innerText + '</li>';
    });
    listHtml += '</ul>';

    var body = '';
    body += '<h1>Executive AD Risk Summary</h1>';
    body += '<p class="small">Generated: ' + new Date().toLocaleString() + '</p>';
    body += '<h2>' + levelText + ' (Score: ' + scoreText + '/100)</h2>';
    body += '<p>Primary objective: close Critical/High findings, then re-run baseline to confirm downward trend.</p>';
    body += '<h2>Top 5 Active Risks</h2>' + listHtml;
    body += '<h2>Recommended Sequence</h2><ol><li>Contain Tier-0 and privileged account exposure.</li><li>Close delegation and ACL abuse paths.</li><li>Clean stale identities and enforce hygiene controls.</li><li>Track remediation status and exceptions with owner/date.</li><li>Re-run report and compare baseline diff.</li></ol>';
    openPrintHtml('Executive_AD_Risk_Summary', body);
}

function exportRemediationChecklistPdf(){
    var items = safeArray(quickRemediationItems);
    var findings = safeArray(priorityRiskFindings);
    var body = '';
    body += '<h1>Remediation Checklist</h1>';
    body += '<p class="small">Generated: ' + new Date().toLocaleString() + '</p>';
    body += '<h2>Category Actions</h2><ul>';
    if (!items.length) {
        body += '<li>No category action item available.</li>';
    } else {
        items.forEach(function(i){
            body += '<li>[ ] <b>' + String(i.Category || '-') + ' (' + String(i.RiskPct || 0) + '%)</b> - ' + String(i.Action || '').replace(/</g,'&lt;') + '</li>';
        });
    }
    body += '</ul><h2>Critical/High Findings</h2><ul>';
    if (!findings.length) {
        body += '<li>No active Critical/High finding.</li>';
    } else {
        findings.forEach(function(f){
            body += '<li>[ ] <b>[' + String(f.Severity || '-') + ']</b> ' + String(f.Rule || '-') + ' - ' + String(f.Recommendation || '').replace(/</g,'&lt;') + '</li>';
        });
    }
    body += '</ul><h2>Closure</h2><ul><li>[ ] Evidence attached</li><li>[ ] Owner assigned</li><li>[ ] Re-test scheduled</li></ul>';
    openPrintHtml('Remediation_Checklist', body);
}

function showMembers(groupName, samAccountName) {
    var members = GroupMembers[samAccountName] || [];
    var overlay = document.getElementById('grpDrawerOverlay');
    var drawer  = document.getElementById('grpDrawer');
    var titleEl = document.getElementById('grpDrawerTitle');
    var metaEl  = document.getElementById('grpDrawerMeta');
    var listEl  = document.getElementById('grpDrawerList');
    var searchEl= document.getElementById('grpDrawerSearch');

    titleEl.innerHTML = '<i class="fa-solid fa-shield-halved" style="color:#3b82f6;font-size:14px;"></i> ' + groupName;

    var countBadge = '<span style="display:inline-block;padding:2px 9px;border-radius:999px;background:#dbeafe;color:#1d4ed8;font-size:10px;font-weight:700;">' + members.length + (currentLanguage === 'tr' ? ' üye' : ' members') + '</span>';
    var samBadge   = '<span style="font-size:11px;color:#64748b;font-family:monospace;">' + samAccountName + '</span>';
    metaEl.innerHTML = countBadge + samBadge;

    searchEl.value = '';

    if (members.length === 0) {
        listEl.innerHTML = '<div class="grp-drawer-empty"><i class="fa-solid fa-users-slash" style="display:block;font-size:28px;margin-bottom:10px;color:#cbd5e1;"></i>' + (currentLanguage === 'tr' ? 'Bu grubun üyesi bulunmuyor.' : 'This group has no members.') + '</div>';
    } else {
        var html = '';
        var colors = ['#dbeafe','#dcfce7','#fef3c7','#ede9fe','#fee2e2','#f0fdf4'];
        var textColors = ['#1d4ed8','#166534','#92400e','#5b21b6','#991b1b','#166534'];
        members.forEach(function(m, i) {
            var words = m.trim().split(/\s+/);
            var initials = (words.length >= 2 ? words[0][0] + words[words.length-1][0] : m.substring(0,2)).toUpperCase();
            var ci = i % colors.length;
            html += '<div class="grp-drawer-item" data-member="' + m.toLowerCase() + '">' +
                '<div class="grp-drawer-avatar" style="background:' + colors[ci] + ';color:' + textColors[ci] + ';">' + initials + '</div>' +
                '<span class="grp-drawer-member-name">' + m + '</span>' +
                '</div>';
        });
        if (members.length >= 300) {
            html += '<div style="font-size:11px;color:#94a3b8;padding:10px 0;text-align:center;border-top:1px solid #e8f0f8;margin-top:6px;">' + (currentLanguage === 'tr' ? 'İlk 300 üye gösteriliyor' : 'Showing first 300 members') + '</div>';
        }
        listEl.innerHTML = html;
    }

    overlay.classList.add('open');
    drawer.classList.add('open');
    document.body.style.overflow = 'hidden';
}

