function showPingFindingDetails(category, rule) {
    var key = category + '||' + rule;
    var data = PingRuleDetailsMap[key];
    if (!data) { return; }

    var sev = (data.Severity || 'Low').toLowerCase();
    var badge = document.getElementById('pdmBadge');
    badge.className = 'pdm-badge pdm-badge-' + sev;
    badge.textContent = (data.Severity || 'Low').toUpperCase();

    document.getElementById('pdmRule').textContent = data.Rule || rule;
    document.getElementById('pdmMeta').innerHTML =
        '<span>Category: <b>' + (data.Category || category) + '</b></span>' +
        '<span>Count: <b>' + (data.Count !== undefined ? data.Count : '-') + '</b></span>' +
        (data.Reference ? '<span>Ref: <b>' + data.Reference + '</b></span>' : '') +
        '<span>Sample: <b>' + (data.Sample || '-') + '</b></span>';

    var whySec = document.getElementById('pdmWhy');
    whySec.className = 'pdm-section' + (sev === 'critical' ? ' pdm-section-critical' : sev === 'high' ? ' pdm-section-high' : '');
    var isTR = (typeof currentLanguage !== 'undefined' && currentLanguage === 'tr');
    var lblWhy = document.getElementById('pdmWhyLabel'); if (lblWhy) lblWhy.innerHTML = '&#9888; ' + (isTR ? 'Neden Önemli' : 'Why This Matters');
    var lblSrc = document.getElementById('pdmSourceLabel'); if (lblSrc) lblSrc.innerHTML = '&#128269; ' + (isTR ? 'Tespit Kaynağı' : 'Detection Source');
    var lblAct = document.getElementById('pdmActionLabel'); if (lblAct) lblAct.innerHTML = '&#10003; ' + (isTR ? 'Ne Yapmalı' : 'What To Do');
    var lblObj = document.getElementById('pdmObjectsLabel'); if (lblObj) lblObj.innerHTML = '&#127919; ' + (isTR ? 'Etkilenen Nesneler' : 'Affected Objects');
    document.getElementById('pdmWhyText').textContent = (isTR && data.AboutTR) ? data.AboutTR : (data.About || 'No rationale available.');
    document.getElementById('pdmSourceText').textContent = data.Source || '-';
    document.getElementById('pdmActionText').textContent = (isTR && data.ActionTR) ? data.ActionTR : (data.Action || data.Recommendation || 'No action defined.');

    var details = Array.isArray(data.Details) ? data.Details.slice() : [];
    if (rule.indexOf('Privileged Review: ') === 0) {
        var objectName = rule.replace('Privileged Review: ', '').trim();
        var detailKey = objectName.replace(/[^a-zA-Z0-9_-]/g, '_');
        var usersRaw = ObjectRiskDetails[detailKey + '|users'];
        var compsRaw = ObjectRiskDetails[detailKey + '|computers'];
        var indirectRaw = ObjectRiskDetails[detailKey + '|indirect'];
        var unresolvedRaw = ObjectRiskDetails[detailKey + '|unresolved'];
        var users = Array.isArray(usersRaw) ? usersRaw : (usersRaw ? [String(usersRaw)] : []);
        var comps = Array.isArray(compsRaw) ? compsRaw : (compsRaw ? [String(compsRaw)] : []);
        var indirect = Array.isArray(indirectRaw) ? indirectRaw : (indirectRaw ? [String(indirectRaw)] : []);
        var unresolved = Array.isArray(unresolvedRaw) ? unresolvedRaw : (unresolvedRaw ? [String(unresolvedRaw)] : []);
        if (users.length) details.push('Users: ' + users.join(', '));
        if (comps.length) details.push('Computers: ' + comps.join(', '));
        if (indirect.length) details.push('Indirect groups: ' + indirect.join(', '));
        if (unresolved.length) details.push('Unresolved: ' + unresolved.join(', '));
    }

    var list = document.getElementById('pdmObjectsList');
    list.innerHTML = '';
    if (details.length > 0) {
        details.forEach(function(d) {
            var li = document.createElement('li');
            li.textContent = d;
            list.appendChild(li);
        });
    } else {
        list.innerHTML = '<li class="pdm-empty">No specific objects listed for this finding.</li>';
    }

    document.getElementById('pingDetailModal').classList.add('open');
}

