# ---------------------
# GROUPS & SITES & INACTIVE OBJECTS (Shortened)
# ---------------------
# Security Groups
$SecurityBuiltinGroups  = @($SecurityGroups | Where-Object { $_.DistinguishedName -match ',CN=Builtin,' })
$SecurityDefaultGroups  = @($SecurityGroups | Where-Object { $_.DistinguishedName -notmatch ',CN=Builtin,' -and $_.DistinguishedName -notmatch ',OU=' })
$SecurityCustomGroups   = @($SecurityGroups | Where-Object { $_.DistinguishedName -match ',OU=' })
$SecurityEmptyGroupCount = @($SecurityGroups | Where-Object { [int]$_.MemberCount -eq 0 }).Count
$SecurityTopGroup = @($SecurityGroups | Sort-Object {[int]$_.MemberCount} -Descending | Select-Object -First 1)
$SecurityTopGroupText = if ($SecurityTopGroup) { "$($SecurityTopGroup[0].Name) ($($SecurityTopGroup[0].MemberCount) members)" } else { '-' }

# ─── Group Risk Analysis ────────────────────────────────────────────────
# Only flag custom OU groups that are genuine deletion candidates.
# Excluded: CN=Builtin, CN=Users (domain defaults), Exchange Security Groups OU,
# and known privileged groups whose empty state is intentional/healthy.
$_HygienePrivBuiltin = @(
    'Account Operators','Backup Operators','Print Operators','Server Operators',
    'Schema Admins','Enterprise Admins','Group Policy Creator Owners','DnsAdmins',
    'DnsUpdateProxy','RAS and IAS Servers','Cert Publishers','Windows Authorization Access Group',
    'Terminal Server License Servers','Allowed RODC Password Replication Group',
    'Denied RODC Password Replication Group','Enterprise Key Admins','Key Admins',
    'Protected Users'
)
$HygieneCustomGroups = @($AllGroups | Where-Object {
    $dn = $_.DistinguishedName
    $dn -match ',OU=' -and
    $dn -notmatch 'OU=Microsoft Exchange Security Groups' -and
    $dn -notmatch 'OU=Microsoft Exchange System Objects' -and
    $_HygienePrivBuiltin -notcontains $_.Name
})
$HygieneEmptyGroups  = @($HygieneCustomGroups | Where-Object { [int]$_.MemberCount -eq 0 } | Sort-Object Name)
$HygieneSingleGroups = @($HygieneCustomGroups | Where-Object { [int]$_.MemberCount -eq 1 } | Sort-Object Name)

# Circular nesting — build group-child map then DFS per group
$script:_GrpDNtoSam = @{}
foreach ($g in $AllGroups) { $script:_GrpDNtoSam[$g.DistinguishedName] = $g.SamAccountName }

$script:_GrpChildMap = @{}
foreach ($g in $AllGroups) {
    $script:_GrpChildMap[$g.SamAccountName] = @(
        $g.MemberDNs | ForEach-Object { if ($_ -and $script:_GrpDNtoSam.ContainsKey($_)) { $script:_GrpDNtoSam[$_] } }
    )
}

function Find-CircularGroup([string]$Start, [string]$Current, [System.Collections.Generic.HashSet[string]]$Visited) {
    foreach ($child in $script:_GrpChildMap[$Current]) {
        if (-not $child) { continue }
        if ($child -eq $Start) { return $true }
        if ($Visited.Add($child)) {
            if (Find-CircularGroup $Start $child $Visited) { return $true }
        }
    }
    return $false
}

$CircularGroups = @()
foreach ($g in $AllGroups) {
    $vis = [System.Collections.Generic.HashSet[string]]::new()
    $vis.Add($g.SamAccountName) | Out-Null
    if (Find-CircularGroup $g.SamAccountName $g.SamAccountName $vis) {
        $CircularGroups += $g.SamAccountName
    }
}
$CircularGroups = @($CircularGroups | Sort-Object -Unique)

# Token bloat — reverse membership map + BFS transitive count per enabled user
$script:_MemberOfMap = @{}
foreach ($g in $AllGroups) {
    foreach ($mDN in $g.MemberDNs) {
        if (-not $mDN) { continue }
        if (-not $script:_MemberOfMap.ContainsKey($mDN)) {
            $script:_MemberOfMap[$mDN] = [System.Collections.Generic.List[string]]::new()
        }
        $script:_MemberOfMap[$mDN].Add($g.DistinguishedName)
    }
}

$TokenBloatThreshold = 1000
$TokenBloatUsers = @()
foreach ($u in $AllUsersRaw | Where-Object { $_.Enabled }) {
    $uDN = $u.DistinguishedName
    if (-not $uDN -or -not $script:_MemberOfMap.ContainsKey($uDN)) { continue }
    $vis   = [System.Collections.Generic.HashSet[string]]::new()
    $queue = [System.Collections.Generic.Queue[string]]::new()
    foreach ($gDN in $script:_MemberOfMap[$uDN]) { $queue.Enqueue($gDN) }
    while ($queue.Count -gt 0) {
        $cur = $queue.Dequeue()
        if (-not $vis.Add($cur)) { continue }
        if ($script:_MemberOfMap.ContainsKey($cur)) {
            foreach ($pDN in $script:_MemberOfMap[$cur]) { $queue.Enqueue($pDN) }
        }
    }
    if ($vis.Count -ge $TokenBloatThreshold) {
        $TokenBloatUsers += [PSCustomObject]@{ Name = [string]$u.Name; Sam = [string]$u.SamAccountName; GroupCount = $vis.Count }
    }
}
$TokenBloatUsers = @($TokenBloatUsers | Sort-Object GroupCount -Descending)
$HygieneIssueCount = $HygieneEmptyGroups.Count + $HygieneSingleGroups.Count + $CircularGroups.Count + $TokenBloatUsers.Count

$Html += "<div class='container' id='securityGroupsContainer' style='display:none;'><div class='content-card'>"
