$Html += "<div class='section-stat-card card--gray' style='cursor:pointer;' onclick='invFilterGroupCat(""securityGroupsTable"",""builtin"",this)'><div class='section-stat-icon'><i class='fa-solid fa-windows'></i></div><div class='section-stat-label'>Windows Built-in</div><div class='section-stat-value'>$($SecurityBuiltinGroups.Count)</div><div class='section-stat-note'>CN=Builtin — created by the OS</div></div>"
