    $Html += "<tr data-groupcat='$_cat'$_emptyRow><td class='group-name-cell' data-no-translate onclick=""showMembers('$GroupNameEscaped', '$SamAccountName')"">$($g.Name)</td><td>$_catBadge</td><td>$($g.GroupScope)</td><td>$($g.MemberCount)</td><td data-no-translate>$($g.ManagedBy)</td></tr>"
