# Helper: collapsible section builder
function New-HygieneSection($Id, $Title, $Severity, $BadgeColor, $Count, $BodyHtml) {
    $sev = "<span style='display:inline-block;padding:2px 9px;border-radius:5px;font-size:10px;font-weight:800;background:$BadgeColor;color:#fff;margin-left:8px;'>$Severity</span>"
    $cnt = "<span style='font-size:12px;color:#64748b;margin-left:6px;'>($Count)</span>"
    $out  = "<div class='risk-collapse' style='margin:10px 0;'>"
    $out += "<div onclick='this.nextElementSibling.style.display=this.nextElementSibling.style.display===""none""?""block"":""none""' style='cursor:pointer;padding:11px 14px;display:flex;align-items:center;justify-content:space-between;background:#f8fafd;border-radius:8px;'>"
    $out += "<span style='font-weight:700;font-size:13px;'>$Title$sev$cnt</span>"
    $out += "<i class='fa-solid fa-chevron-down' style='color:#94a3b8;font-size:12px;'></i>"
    $out += "</div>"
    $out += "<div style='display:none;padding:0 4px 6px 4px;'>$BodyHtml</div>"
    $out += "</div>"
    return $out
}

# 1 — Empty groups table
$_emptyBody = "<table class='user-table' style='margin-top:6px;'><tr><th>Group Name</th><th>Scope</th><th>Category</th><th>Distinguished Name</th></tr>"
if ($HygieneEmptyGroups.Count -eq 0) {
    $_emptyBody += "<tr><td colspan='4' style='color:#22c55e;text-align:center;'>No empty groups found</td></tr>"
} else {
    foreach ($eg in $HygieneEmptyGroups | Select-Object -First 200) {
        $_emptyBody += "<tr><td>$($eg.Name)</td><td>$($eg.GroupScope)</td><td>$($eg.GroupCategory)</td><td style='font-size:10px;color:#64748b;font-family:monospace;'>$($eg.DistinguishedName)</td></tr>"
    }
    if ($HygieneEmptyGroups.Count -gt 200) { $_emptyBody += "<tr><td colspan='4' style='color:#94a3b8;text-align:center;'>… and $($HygieneEmptyGroups.Count - 200) more</td></tr>" }
}
$_emptyBody += "</table>"
$Html += New-HygieneSection "hyg-empty" "Empty Groups" "Medium" "#f59e0b" $HygieneEmptyGroups.Count $_emptyBody

# 2 — Single-member groups table
$_singleBody = "<table class='user-table' style='margin-top:6px;'><tr><th>Group Name</th><th>Scope</th><th>Member</th></tr>"
if ($HygieneSingleGroups.Count -eq 0) {
    $_singleBody += "<tr><td colspan='3' style='color:#22c55e;text-align:center;'>No single-member groups found</td></tr>"
} else {
    foreach ($sg in $HygieneSingleGroups | Select-Object -First 200) {
        $_memberName = if ($sg.MemberDNs) { (@($sg.MemberDNs)[0] -replace '^CN=([^,]+),.*$','$1') } else { '-' }
        $_singleBody += "<tr><td>$($sg.Name)</td><td>$($sg.GroupScope)</td><td>$_memberName</td></tr>"
    }
    if ($HygieneSingleGroups.Count -gt 200) { $_singleBody += "<tr><td colspan='3' style='color:#94a3b8;text-align:center;'>… and $($HygieneSingleGroups.Count - 200) more</td></tr>" }
}
$_singleBody += "</table>"
$Html += New-HygieneSection "hyg-single" "Single-Member Groups" "Medium" "#f59e0b" $HygieneSingleGroups.Count $_singleBody

# 3 — Circular nesting
$_circBody = "<table class='user-table' style='margin-top:6px;'><tr><th>Group (SamAccountName)</th></tr>"
