}
$_circBody += "</table>"
$Html += New-HygieneSection "hyg-circ" "Circular Nesting" "High" "#ef4444" $CircularGroups.Count $_circBody

# 4 — Token bloat
$_tokenBody = "<table class='user-table' style='margin-top:6px;'><tr><th>User</th><th>SamAccountName</th><th>Transitive Group Count</th></tr>"
if ($TokenBloatUsers.Count -eq 0) {
