    $Html += "<div class='site-content'>"
    # DC section
    $Html += "<div class='site-section'>"
    $Html += "<div class='site-section-title'><i class='fa-solid fa-server'></i> Domain Controllers ($DCCount)</div>"
    $Html += "<ul class='server-list'>"
    if ($DCCount -eq 0) { $Html += "<li class='server-list-empty'>No DC found in this site.</li>" }
    foreach ($dc in $SiteInfo.DCs | Sort Name) {
        $_osShort = ([string]$dc.OperatingSystem) -replace 'Windows Server ','' -replace 'Windows ',''
        $Html += "<li><i class='fa-solid fa-server'></i><strong>$($dc.Name)</strong><span class='server-list-os'>$_osShort</span></li>"
    }
    $Html += "</ul></div>"
    # Member Servers section
    $Html += "<div class='site-section'>"
    $Html += "<div class='site-section-title'><i class='fa-solid fa-database'></i> Member Servers ($ServerCount)</div>"
    $Html += "<ul class='server-list'>"
