$_DIRiskyColor  = if ($_DIRisky  -gt 0) { 'card--red'    } else { 'card--green' }
$_DIReviewColor = if ($_DIReview -gt 0) { 'card--orange' } else { 'card--green' }
$Html += "<div class='section-stat-grid'>"
