$Html += "<div class='section-stat-card $_DIReviewColor' style='cursor:pointer;' onclick='diFilter(""Review"",null)' title='Click to filter'><div class='section-stat-icon'><i class='fa-solid fa-magnifying-glass'></i></div><div class='section-stat-label'>Review First</div><div class='section-stat-value'>$_DIReview</div><div class='section-stat-note'>1 dependency detected</div></div>"
$Html += "<div class='section-stat-card card--green' style='cursor:pointer;' onclick='diFilter(""Safe"",null)' title='Click to filter'><div class='section-stat-icon'><i class='fa-solid fa-circle-check'></i></div><div class='section-stat-label'>Safe to Delete</div><div class='section-stat-value'>$_DISafe</div><div class='section-stat-note'>No dependencies found</div></div>"
