$Html += "<th>Dependencies</th>"
$Html += "</tr>"

$_DIAllSorted = $_DIAll | Sort-Object { @{'Risky'=0;'Review'=1;'Safe'=2}[$_.Risk] }, Name
if ($_DIAllSorted.Count -eq 0) {
    $Html += "<tr><td colspan='4' style='color:#22c55e;text-align:center;'>No inactive objects found</td></tr>"
} else {
    foreach ($di in $_DIAllSorted) {
        $badge = switch ($di.Risk) {
            "Risky"  { "<span style='display:inline-block;padding:2px 10px;border-radius:5px;font-size:10px;font-weight:800;background:#ef4444;color:#fff;'>Risky</span>" }
            "Review" { "<span style='display:inline-block;padding:2px 10px;border-radius:5px;font-size:10px;font-weight:800;background:#f59e0b;color:#fff;'>Review First</span>" }
            default  { "<span style='display:inline-block;padding:2px 10px;border-radius:5px;font-size:10px;font-weight:800;background:#22c55e;color:#fff;'>Safe</span>" }
        }
        $typeIcon = if ($di.Type -eq "User") { "<i class='fa-solid fa-user' style='margin-right:5px;color:#64748b;font-size:11px;'></i>" } else { "<i class='fa-solid fa-computer' style='margin-right:5px;color:#64748b;font-size:11px;'></i>" }
        $depsText = if ($di.Deps) { "<span style='font-size:11px;color:#475569;'>$($di.Deps)</span>" } else { "<span style='font-size:11px;color:#22c55e;'>No dependencies</span>" }
        $Html += "<tr data-risk='$($di.Risk)' data-type='$($di.Type)'>"
        $Html += "<td><span style='font-weight:600;'>$($di.Name)</span><br><span style='font-size:10px;color:#94a3b8;font-family:monospace;'>$($di.Sam)</span></td>"
        $Html += "<td>$typeIcon$($di.Type)</td>"
        $Html += "<td>$badge</td>"
        $Html += "<td>$depsText</td>"
        $Html += "</tr>"
    }
}
$Html += "</table></div></div></div>"

