$_catNavOrder = @("Privileged Accounts","Privileged Infrastructure","Anomalies","Stale Objects","Trusts","Hygiene")
$_catNavIcons = @{
    'Privileged Accounts'       = 'fa-key'
    'Privileged Infrastructure' = 'fa-sitemap'
    'Anomalies'                 = 'fa-triangle-exclamation'
    'Stale Objects'             = 'fa-hourglass-half'
    'Trusts'                    = 'fa-handshake'
    'Hygiene'                   = 'fa-broom'
}
$_catNavShort = @{
