    'Privileged Infrastructure' = 'Priv. Infra'
    'Anomalies'                 = 'Anomalies'
    'Stale Objects'             = 'Stale Objects'
    'Trusts'                    = 'Trusts'
    'Hygiene'                   = 'Hygiene'
}
$Html += "<div class='container' id='pingCastleRisksContainer' style='display:none;'><div class='content-card'>"
$Html += "<div class='risk-top-bar'>"
$Html += "<div class='risk-quick-nav'>"
