$Html += "<button class='risk-quick-jump rqj-active' onclick='scrollRiskStoryboard(""scoreBreakdownAnchor"");setRqjActive(this)'><i class='fa-solid fa-gauge-high'></i>Score</button>"
$Html += "<button class='risk-quick-jump' onclick='scrollRiskStoryboard(""riskModelAnchor"");setRqjActive(this)'><i class='fa-solid fa-table-columns'></i>Board</button>"
$Html += "<button class='risk-quick-jump' onclick='scrollRiskStoryboard(""riskActionAnchor"");setRqjActive(this)'><i class='fa-solid fa-bolt'></i>Actions</button>"
$Html += "<span class='rqj-sep'></span>"
foreach ($cn in $_catNavOrder) {
