    $cnShort = if ($_catNavShort[$cn]) { $_catNavShort[$cn] } else { $cn }
    $cnCount = @($PingCastleFindings | Where-Object { $_.Category -eq $cn -and (Test-PingFindingMatched $_) }).Count
    if ($cnCount -eq 0) { continue }
    $Html += "<button class='rqj-cat' onclick='scrollRiskStoryboard(""cat-$cnSafe"");setRqjActive(this)'><i class='fa-solid $cnIcon'></i>$cnShort</button>"
}
$Html += "</div>"
$Html += "<div class='risk-export-group'>"
$Html += "<button class='risk-export-btn' onclick='printSection(currentContainerId)' title='Save as PDF'><i class='fa-solid fa-file-pdf'></i><span>PDF</span></button>"
$Html += "<button class='risk-export-btn' onclick='exportRemediationChecklistPdf()' title='Remediation Checklist PDF'><i class='fa-solid fa-list-check'></i><span>Checklist</span></button>"
$Html += "<button class='risk-export-btn' onclick='copyPermalinkState()' title='Copy link'><i class='fa-solid fa-link'></i><span>Copy Link</span></button>"
$Html += "</div>"
$Html += "</div>"
$PingCriticalCount = @($PingCastleFindings | Where-Object { $_.Severity -eq 'Critical' -and (Test-PingFindingMatched $_) }).Count
$PingHighCount = @($PingCastleFindings | Where-Object { $_.Severity -eq 'High' -and (Test-PingFindingMatched $_) }).Count
$PingMediumCount = @($PingCastleFindings | Where-Object { $_.Severity -eq 'Medium' -and (Test-PingFindingMatched $_) }).Count

$PingSeverityTotal = [Math]::Max(1, ($PingCriticalCount + $PingHighCount + $PingMediumCount))
$PingCriticalPct = [int][math]::Round(($PingCriticalCount * 100.0) / $PingSeverityTotal, 0)
$PingHighPct = [int][math]::Round(($PingHighCount * 100.0) / $PingSeverityTotal, 0)
$PingMediumPct = [int][math]::Round(($PingMediumCount * 100.0) / $PingSeverityTotal, 0)
$PingActionableCount = $PingCriticalCount + $PingHighCount
$TopRuleFinding = @($PingCastleFindings | Sort-Object @{Expression={ Get-PingSeverityRank $_.Severity }; Descending=$true}, @{Expression={ $safeCount = 0; [void][int]::TryParse([string]$_.Count, [ref]$safeCount); $safeCount }; Descending=$true}) | Select-Object -First 1
$TopRuleName = if ($TopRuleFinding) { $TopRuleFinding.Rule } else { '-' }
$TopRuleCount = if ($TopRuleFinding) { [int]$TopRuleFinding.Count } else { 0 }
$Html += "<div class='risk-exec-grid'>"
$Html += "<div class='risk-exec-card' style='cursor:pointer;' title='Click to filter Critical findings' onclick='applyPingRiskFocus(""critical""); scrollRiskStoryboard(""riskFindingsAnchor"")'><div class='risk-exec-label'>Critical Findings</div><div class='risk-exec-value'>$PingCriticalCount</div><div class='risk-exec-note'>Act within 72 hours</div><div class='risk-exec-progress'><span class='risk-exec-progress-fill risk-exec-progress-critical' style='width:$($PingCriticalPct)%'></span></div></div>"
$Html += "<div class='risk-exec-card' style='cursor:pointer;' title='Click to filter High findings' onclick='applyPingRiskFocus(""criticalhigh""); scrollRiskStoryboard(""riskFindingsAnchor"")'><div class='risk-exec-label'>High Findings</div><div class='risk-exec-value'>$PingHighCount</div><div class='risk-exec-note'>Address within 30 days</div><div class='risk-exec-progress'><span class='risk-exec-progress-fill risk-exec-progress-high' style='width:$($PingHighPct)%'></span></div></div>"
$Html += "<div class='risk-exec-card' style='cursor:pointer;' title='Click to filter Medium findings' onclick='applyPingRiskFocus(""medium""); scrollRiskStoryboard(""riskFindingsAnchor"")'><div class='risk-exec-label'>Medium Findings</div><div class='risk-exec-value'>$PingMediumCount</div><div class='risk-exec-note'>Monitor and close within 90 days</div><div class='risk-exec-progress'><span class='risk-exec-progress-fill risk-exec-progress-medium' style='width:$($PingMediumPct)%'></span></div></div>"
$Html += "<div class='risk-exec-card'><div class='risk-exec-label'>Top Risk Rule</div><div class='risk-exec-value' style='font-size:15px;'>$TopRuleName</div><div class='risk-exec-note'>Observed count: $TopRuleCount | Critical+High: $PingActionableCount</div></div>"
$Html += "</div>"
$GlobalChipClass = switch ($RiskRating) {
    "Good" { "risk-chip risk-chip-low" }
    "Acceptable" { "risk-chip risk-chip-med" }
    "Poor" { "risk-chip risk-chip-poor" }
    default { "risk-chip risk-chip-high" }
}
$GlobalLevelText = $RiskRating
$GaugeRadius = 62
$GaugeCircumference = [math]::Round((2 * [math]::PI * $GaugeRadius), 2)
$GaugeOffset = [math]::Round($GaugeCircumference * (1 - ($DomainRiskScore / 100.0)), 2)
$GaugeClass = switch ($RiskRating) {
    "Good" { "risk-gauge-good" }
    "Acceptable" { "risk-gauge-acceptable" }
    "Poor" { "risk-gauge-poor" }
    default { "risk-gauge-critical" }
}
$RiskConfidenceChipClass = switch ($RiskConfidenceLevel) {
    "High" { "risk-confidence-chip risk-confidence-high" }
    "Medium" { "risk-confidence-chip risk-confidence-medium" }
    default { "risk-confidence-chip risk-confidence-low" }
}
$RiskVerdictText = if ($DomainRiskScore -ge 70) {
    "Score is critical — immediate remediation required. Focus on Critical and High findings first."
} elseif ($DomainRiskScore -ge 40) {
    "Score is high — address Critical and High findings within 30 days."
} elseif ($DomainRiskScore -ge 20) {
    "Score is moderate — work through findings in priority order."
} else {
    "Score is acceptable — maintain controls and continue periodic review."
}

$Html += "<div id='riskNowAnchor' class='risk-score-card'>"
$Html += "<div class='risk-score-main'>"
$Html += "<div class='risk-gauge-wrap'>"
$Html += "<svg class='risk-gauge-svg' viewBox='0 0 170 170' aria-label='Domain risk score gauge'>"
$Html += "<circle class='risk-gauge-bg' cx='85' cy='85' r='$GaugeRadius'></circle>"
$Html += "<circle class='$GaugeClass' cx='85' cy='85' r='$GaugeRadius' style='stroke-dasharray:$GaugeCircumference;stroke-dashoffset:$GaugeOffset;'></circle>"
$Html += "</svg>"
$Html += "<div class='risk-gauge-center'><div class='risk-gauge-score'>$DomainRiskScore</div><div class='risk-gauge-max'>/100</div></div>"
$Html += "</div>"
$Html += "<div class='risk-score-text'>"
$Html += "<h3>Domain Risk Level: $DomainRiskScore / 100</h3>"
$Html += "<p class='risk-score-verdict'>$RiskVerdictText</p>"
$Html += "<p style='margin-top:8px;'><span class='$GlobalChipClass'>$GlobalLevelText</span><span class='$RiskConfidenceChipClass'>Confidence: $RiskConfidenceLevel</span></p>"
$Html += "<p class='risk-confidence-note'>$([System.Net.WebUtility]::HtmlEncode([string]$RiskConfidenceNote))</p>"
$Html += "</div></div>"

$Html += "</div>"
$Html += "<details id='scoreBreakdownAnchor' class='risk-collapse'><summary class='risk-collapse-summary'>Score Breakdown &amp; Analysis</summary>"

# --- Radar chart SVG (6-category hexagon) ---
$_rcCx = 190; $_rcCy = 165; $_rcR = 115
$_rfColor = if ($DomainRiskScore -ge 80) { "#ef4444" } elseif ($DomainRiskScore -ge 60) { "#f97316" } elseif ($DomainRiskScore -ge 40) { "#eab308" } else { "#22c55e" }
$_hexCats   = @("Anomalies","Privileged Accounts","Stale Objects","Privileged Infrastructure","Trusts","Hygiene")
$_hexAngDeg = @(-90, -30, 30, 90, 150, 210)
$_hexShort  = @("Anomalies","Priv. Accounts","Stale Objects","Priv. Infra.","Trusts","Hygiene")
$_lblR = 138  # label radius (outside the max ring)
# label anchor per vertex: top=middle, tr=start, br=start, bot=middle, bl=end, tl=end
$_hexAnchor = @("middle","start","start","middle","end","end")
# value label offset per vertex [dx, dy]
$_hexVoff = @(@(0,-10),@(10,5),@(10,5),@(0,16),@(-10,5),@(-10,-10))
$_hexVanc = @("middle","start","start","middle","end","end")

# Grid hexagons
$_rGrid = ""
foreach ($_lv in @(25,50,75,100)) {
    $_fr = $_lv / 100.0
    $_gpts = ""
    foreach ($_ad in $_hexAngDeg) {
        $_rad = $_ad * [math]::PI / 180.0
        $_gpts += "$([math]::Round($_rcCx + $_rcR * $_fr * [math]::Cos($_rad),1)),$([math]::Round($_rcCy + $_rcR * $_fr * [math]::Sin($_rad),1)) "
    }
    $_sw = if ($_lv -eq 100) { "1.5" } else { "1" }; $_so = if ($_lv -eq 100) { "0.35" } else { "0.18" }
    $_rGrid += "<polygon points='$($_gpts.Trim())' fill='none' stroke='#7ca8c8' stroke-width='$_sw' stroke-opacity='$_so'/>"
    $_lblY = [math]::Round($_rcCy - $_rcR * $_fr - 3, 1)
    $_rGrid += "<text x='$($_rcCx+3)' y='$_lblY' font-size='8' fill='#7ca8c8' fill-opacity='0.65'>$_lv</text>"
}

# Axis lines + labels
$_rAxes = ""; $_rLabels = ""
for ($_i = 0; $_i -lt 6; $_i++) {
    $_rad = $_hexAngDeg[$_i] * [math]::PI / 180.0
    $_tx = [math]::Round($_rcCx + $_rcR * [math]::Cos($_rad), 1)
    $_ty = [math]::Round($_rcCy + $_rcR * [math]::Sin($_rad), 1)
    $_rAxes += "<line x1='$_rcCx' y1='$_rcCy' x2='$_tx' y2='$_ty' stroke='#7ca8c8' stroke-width='1' stroke-opacity='0.25' stroke-dasharray='3,3'/>"
    $_lx = [math]::Round($_rcCx + $_lblR * [math]::Cos($_rad), 1)
    $_ly = [math]::Round($_rcCy + $_lblR * [math]::Sin($_rad), 1)
    $_rLabels += "<text x='$_lx' y='$_ly' text-anchor='$($_hexAnchor[$_i])' dominant-baseline='middle' font-size='10' font-weight='700' fill='#4b627a'>$($_hexShort[$_i])</text>"
}

# Score polygon + dots + value labels
$_scorePts = ""; $_rDots = ""
for ($_i = 0; $_i -lt 6; $_i++) {
    $_cat = $_hexCats[$_i]
    $_pct = [math]::Max(0.025, [double]$CategoryRiskPctMap[$_cat] / 100.0)
    $_rad = $_hexAngDeg[$_i] * [math]::PI / 180.0
    $_px  = [math]::Round($_rcCx + $_rcR * $_pct * [math]::Cos($_rad), 1)
    $_py  = [math]::Round($_rcCy + $_rcR * $_pct * [math]::Sin($_rad), 1)
    $_scorePts += "$_px,$_py "
    $_val = [int]$CategoryRiskPctMap[$_cat]
    $_vx  = [math]::Round($_px + $_hexVoff[$_i][0], 1)
    $_vy  = [math]::Round($_py + $_hexVoff[$_i][1], 1)
    $_rDots += "<circle cx='$_px' cy='$_py' r='4' fill='$_rfColor' stroke='white' stroke-width='1.5'/>"
    $_rDots += "<text x='$_vx' y='$_vy' text-anchor='$($_hexVanc[$_i])' font-size='11' font-weight='900' fill='$_rfColor'>$_val</text>"
}
$_radarSvg = "<svg class='risk-radar-svg' viewBox='0 0 380 330' aria-label='Risk category radar'>$_rGrid$_rAxes<polygon points='$($_scorePts.Trim())' fill='$_rfColor' fill-opacity='0.18' stroke='$_rfColor' stroke-width='2.5' stroke-linejoin='round'/>$_rDots$_rLabels</svg>"

# --- Category cards ---
$_catIcons = @{
    "Anomalies"                 = "M12 2L1 21h22L12 2zm0 3.5L20.5 19h-17L12 5.5zM11 10v4h2v-4h-2zm0 6v2h2v-2h-2z"
    "Privileged Accounts"       = "M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 4l6 2.67V11c0 3.97-2.67 7.7-6 8.93C8.67 18.7 6 15 6 11V7.67L12 5z"
    "Stale Objects"             = "M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67V7z"
    "Trusts"                    = "M3.9 12c0-1.71 1.39-3.1 3.1-3.1h4V7H7c-2.76 0-5 2.24-5 5s2.24 5 5 5h4v-1.9H7c-1.71 0-3.1-1.39-3.1-3.1zM8 13h8v-2H8v2zm9-6h-4v1.9h4c1.71 0 3.1 1.39 3.1 3.1s-1.39 3.1-3.1 3.1h-4V17h4c2.76 0 5-2.24 5-5s-2.24-5-5-5z"
    "Hygiene"                   = "M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"
    "Privileged Infrastructure" = "M20 3H4v10c0 2.21 1.79 4 4 4h6c2.21 0 4-1.79 4-4v-3h2c1.11 0 2-.89 2-2V5c0-1.11-.89-2-2-2zm0 5h-2V5h2v3zM4 19h16v2H4z"
}
$_cOrder  = @("Anomalies","Privileged Accounts","Stale Objects","Privileged Infrastructure","Trusts","Hygiene")
$_primary = @("Anomalies","Privileged Accounts","Stale Objects","Trusts")
$_cardsHtml = ""
foreach ($_c in $_cOrder) {
    $_pen   = [int]$CategoryPenaltyMap[$_c]
    $_match = [int]$PingCategoryMatchedCountMap[$_c]
    $_ico   = $_catIcons[$_c]

    if ($_c -eq "Privileged Infrastructure") {
        # Use KusoADCheck extended score — PingCastle doesn't cover this category
        $_si   = [int]$PrivInfraExtScore
        $_rpct = [double]$PrivInfraExtScore
        $_col  = if ($_si -ge 80) { "#ef4444" } elseif ($_si -ge 60) { "#f97316" } elseif ($_si -ge 40) { "#eab308" } elseif ($_si -gt 0) { "#a855f7" } else { "#22c55e" }
        $_bar  = if ($_si -ge 80) { "linear-gradient(90deg,#ef4444,#dc2626)" } elseif ($_si -ge 60) { "linear-gradient(90deg,#f97316,#ea580c)" } elseif ($_si -ge 40) { "linear-gradient(90deg,#eab308,#ca8a04)" } elseif ($_si -gt 0) { "linear-gradient(90deg,#a855f7,#9333ea)" } else { "linear-gradient(90deg,#22c55e,#16a34a)" }
        $_zero  = if ($_si -eq 0) { " risk-cat-zero" } else { "" }
        $_badge = "<span class='risk-cat-badge risk-cat-badge-ext' title='This score uses KusoADCheck severity weights, not PingCastle points. PingCastle does not cover this category.'>EXTENDED</span>"
        $_bw    = [math]::Max(1, $_si)
        $_cardsHtml += "<div class='risk-cat-card$_zero' style='border-left-color:$_col;cursor:pointer;' onclick='filterPingByCategory(""Privileged Infrastructure"")' title='Click to filter findings'>"
        $_cardsHtml += "<div class='risk-cat-header'><svg class='risk-cat-icon' viewBox='0 0 24 24' style='fill:$_col'><path d='$_ico'/></svg><span class='risk-cat-name'>$_c</span>$_badge</div>"
        $_cardsHtml += "<div class='risk-cat-score' style='color:$_col'>$_si<span class='risk-cat-score-unit'>%</span></div>"
        $_cardsHtml += "<div class='risk-cat-bar-wrap'><div class='risk-cat-bar-fill' style='width:$_bw%;background:$_bar'></div></div>"
        $_cardsHtml += "<div class='risk-cat-meta'>$_match rules &nbsp;&bull;&nbsp; <span style='color:#a855f7;font-style:italic;'>KusoADCheck scope</span></div>"
        $_cardsHtml += "</div>"
    } else {
        $_rpct  = [double]$CategoryRiskPctMap[$_c]
        $_col   = if ($_rpct -ge 80) { "#ef4444" } elseif ($_rpct -ge 60) { "#f97316" } elseif ($_rpct -ge 40) { "#eab308" } elseif ($_rpct -gt 0) { "#3b82f6" } else { "#22c55e" }
        $_bar   = if ($_rpct -ge 80) { "linear-gradient(90deg,#ef4444,#dc2626)" } elseif ($_rpct -ge 60) { "linear-gradient(90deg,#f97316,#ea580c)" } elseif ($_rpct -ge 40) { "linear-gradient(90deg,#eab308,#ca8a04)" } elseif ($_rpct -gt 0) { "linear-gradient(90deg,#3b82f6,#2563eb)" } else { "linear-gradient(90deg,#22c55e,#16a34a)" }
        $_zero  = if ($_rpct -eq 0) { " risk-cat-zero" } else { "" }
        $_badge = if ($_primary -contains $_c) { "<span class='risk-cat-badge'>SCORED</span>" } else { "" }
        $_bw    = [math]::Max(1,[int]$_rpct)
        $_si    = [int]$_rpct
        $_cSafe = $_c -replace '"','&quot;'
        $_cardsHtml += "<div class='risk-cat-card$_zero' style='border-left-color:$_col;cursor:pointer;' onclick='filterPingByCategory(""$_cSafe"")' title='Click to filter findings'>"
        $_cardsHtml += "<div class='risk-cat-header'><svg class='risk-cat-icon' viewBox='0 0 24 24' style='fill:$_col'><path d='$_ico'/></svg><span class='risk-cat-name'>$_c</span>$_badge</div>"
        $_cardsHtml += "<div class='risk-cat-score' style='color:$_col'>$_si<span class='risk-cat-score-unit'>%</span></div>"
        $_cardsHtml += "<div class='risk-cat-bar-wrap'><div class='risk-cat-bar-fill' style='width:$_bw%;background:$_bar'></div></div>"
        $_cardsHtml += "<div class='risk-cat-meta'>$_pen pts &nbsp;&bull;&nbsp; $_match rules</div>"
        $_cardsHtml += "</div>"
    }
}

$Html += "<div class='risk-visual-layout'>"
$Html += "<div class='risk-radar-panel'><p class='risk-radar-heading'>Risk Radar &mdash; Primary Categories</p>$_radarSvg</div>"
$Html += "<div class='risk-cat-grid'>$_cardsHtml</div>"
$Html += "</div>"
$Html += "<details style='margin-top:10px;'><summary style='cursor:pointer;font-size:12px;color:#4b627a;font-weight:700;padding:4px 0;list-style:none;'>&rsaquo; Raw Score Data</summary>"
$Html += "<div class='table-wrapper' style='margin-top:8px;'>"
$Html += "<table class='risk-breakdown-table'><tr><th>Category</th><th>Penalty Points</th><th>Category Risk %</th><th>Matched Rules</th></tr>"
foreach ($row in $CategoryPenaltyRows) {
    $Html += "<tr><td>$($row.Category)</td><td>$($row.Penalty)</td><td>$($row.RiskPct)%</td><td>$($row.Matched)</td></tr>"
}
$Html += "</table></div></details>"
$Html += "</details>"

$Html += "<details class='risk-collapse'><summary id='riskModelAnchor' class='risk-collapse-summary'>Category Finding Board</summary>"
$Html += "<p class='risk-model-note' style='margin-top:8px;'>Click any card to jump directly to that finding.</p>"
$Html += "<div class='risk-kanban'>"
$_kanbanOrder = $PingScoreCategoriesAll | Sort-Object {
    $s = if ($_ -eq "Privileged Infrastructure") { [double]$PrivInfraExtScore } else { [double]$CategoryRiskPctMap[$_] }
    -$s
}
foreach ($cat in $_kanbanOrder) {
    $catRules   = @($PingCategoryFindingsSortedMap[$cat])
    $catMatched = @($catRules | Where-Object { Test-PingFindingMatched $_ })
    if ($catMatched.Count -eq 0) { continue }
    $catScore   = [int]$CategoryRiskPctMap[$cat]
    $isExt      = ($cat -eq "Privileged Infrastructure")
    $dispScore  = if ($isExt) { [int]$PrivInfraExtScore } else { $catScore }
    $scoreColor = if ($dispScore -ge 80) { "#ef4444" } elseif ($dispScore -ge 60) { "#f97316" } elseif ($dispScore -ge 40) { "#eab308" } elseif ($dispScore -gt 0) { if ($isExt) { "#a855f7" } else { "#3b82f6" } } else { "#22c55e" }
    $Html += "<div class='risk-kanban-col'>"
    $Html += "<div class='risk-kanban-header' style='border-top-color:$scoreColor'>"
    $Html += "<div class='risk-kanban-cat'>$cat$(if ($isExt) { " <span style='font-size:8px;background:#7e22ce;color:#fff;border-radius:3px;padding:1px 4px;vertical-align:middle;'>EXT</span>" })</div>"
    $Html += "<div class='risk-kanban-stats'><span class='risk-kanban-score' style='color:$scoreColor'>$dispScore%</span><span class='risk-kanban-count'>$($catMatched.Count) findings</span></div>"
    $Html += "</div>"
    $Html += "<div class='risk-kanban-body'>"
    if ($catMatched.Count -eq 0) {
        $Html += "<div class='risk-kanban-empty'>No matched findings</div>"
    } else {
        foreach ($rf in $catMatched) {
            $sevColor = switch ($rf.Severity) {
                "Critical" { "#ef4444" }
                "High"     { "#f97316" }
                "Medium"   { "#eab308" }
                default    { "#22c55e" }
            }
            $ruleSafe = ($rf.Rule -replace "'","\\'" -replace '"','&quot;')
            $Html += "<div class='risk-kanban-card' style='border-left-color:$sevColor' onclick='focusPingRule(""$ruleSafe"")' title='Count: $($rf.Count)'>"
            $Html += "<div class='risk-kanban-rule'>$($rf.Rule)</div>"
            $Html += "<div class='risk-kanban-foot'><span class='risk-kanban-badge' style='background:$sevColor'>$($rf.Severity)</span><span class='risk-kanban-cnt'>$($rf.Count)</span></div>"
            $Html += "</div>"
        }
    }
    $Html += "</div></div>"
}
$Html += "</div>"
$Html += "</details>"

$Html += "<div class='risk-focus-bar' id='pingRiskFocusBar'>"
