# ---------------------
# DC HEALTH & INFO CONTAINER (Shortened)
# ---------------------
$DcDnsOkCount = @($DCHealth | Where-Object { $_.DNS_Health -eq 'OK' }).Count
$DcDnsAccessErrorCount = @($DCHealth | Where-Object { $_.DNS_Health -eq 'WMI Unreachable' }).Count
$DcDnsErrorCount = @($DCHealth | Where-Object { $_.DNS_Health -match 'ERROR' }).Count
$DcGcCount = @($DCHealth | Where-Object { [string]$_.IsGC -match 'True|Yes' }).Count
$DcReplicationOkCount = @($DCHealth | Where-Object { [string]$_.Replication_6h -match '^OK' }).Count
$DcReplicationWarnCount = @($DCHealth | Where-Object { [string]$_.Replication_6h -match '^WARN' }).Count
$DcReplication6hErrorCount = @($DCHealth | Where-Object { [string]$_.Replication_6h -match '^ERROR|Access Error' }).Count

$Html += "<div class='container' id='dcHealthContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>DC Health & FSMO Roles</h2>"
$Html += "<p class='section-intro'>Domain controller service health, DNS posture, and role placement overview.</p>"

# Stat cards
$Html += "<div class='section-stat-grid'>"
$Html += "<div class='section-stat-card card--blue'><div class='section-stat-icon'>🖧</div><div class='section-stat-label'>Total DC</div><div class='section-stat-value'>$(@($DCHealth).Count)</div><div class='section-stat-note'>Controllers discovered</div></div>"
$_dnsOkColor  = if ($DcDnsOkCount -eq @($DCHealth).Count) { 'card--green' } elseif ($DcDnsOkCount -gt 0) { 'card--orange' } else { 'card--red' }
$Html += "<div class='section-stat-card $_dnsOkColor'><div class='section-stat-icon'>✅</div><div class='section-stat-label'>DNS OK</div><div class='section-stat-value'>$DcDnsOkCount</div><div class='section-stat-note'>Healthy resolver config</div></div>"
$_dnsErrColor = if ($DcDnsErrorCount -eq 0) { 'card--green' } else { 'card--red' }
$Html += "<div class='section-stat-card $_dnsErrColor'><div class='section-stat-icon'>⚠️</div><div class='section-stat-label'>DNS Error</div><div class='section-stat-value'>$DcDnsErrorCount</div><div class='section-stat-note'>Immediate remediation</div></div>"
$_replOkColor = if ($DcReplicationOkCount -eq @($DCHealth).Count) { 'card--green' } elseif ($DcReplicationOkCount -gt 0) { 'card--orange' } else { 'card--red' }
$Html += "<div class='section-stat-card $_replOkColor'><div class='section-stat-icon'>🔄</div><div class='section-stat-label'>Replication OK</div><div class='section-stat-value'>$DcReplicationOkCount</div><div class='section-stat-note'>Successful in last 6h</div></div>"
$_replErrColor = if ($DcReplication6hErrorCount -eq 0) { 'card--green' } else { 'card--red' }
$Html += "<div class='section-stat-card $_replErrColor'><div class='section-stat-icon'>❌</div><div class='section-stat-label'>Replication Error</div><div class='section-stat-value'>$DcReplication6hErrorCount</div><div class='section-stat-note'>AD sync failed</div></div>"
$_gcColor = if ($DcGcCount -eq @($DCHealth).Count) { 'card--green' } elseif ($DcGcCount -gt 0) { 'card--orange' } else { 'card--gray' }
$Html += "<div class='section-stat-card $_gcColor'><div class='section-stat-icon'>🌐</div><div class='section-stat-label'>Global Catalog</div><div class='section-stat-value'>$DcGcCount</div><div class='section-stat-note'>DCs with GC role</div></div>"
$Html += "</div>"

# DFL / FFL visual badges
$_dflColor = if ($DFL -match '2016|2019|2022|2025') { '#22c55e' } elseif ($DFL -match '2012|2008') { '#f97316' } else { '#ef4444' }
$_fflColor = if ($FFL -match '2016|2019|2022|2025') { '#22c55e' } elseif ($FFL -match '2012|2008') { '#f97316' } else { '#ef4444' }
$_schColor = if ($SchemaVerNum -ge 87) { '#22c55e' } elseif ($SchemaVerNum -ge 69) { '#f97316' } elseif ($SchemaVerNum -ge 0) { '#ef4444' } else { '#94a3b8' }
$Html += "<div style='display:flex;gap:12px;flex-wrap:wrap;margin:12px 0;'>"
$Html += "<div style='display:flex;align-items:center;gap:10px;background:#f8fafd;border:1px solid #d0dce9;border-radius:10px;padding:10px 16px;border-left:4px solid $_dflColor;'><span style='font-size:11px;font-weight:700;color:#5a6f84;text-transform:uppercase;'>Domain Functional Level</span><span style='font-size:16px;font-weight:900;color:$_dflColor;'>$DFL</span></div>"
$Html += "<div style='display:flex;align-items:center;gap:10px;background:#f8fafd;border:1px solid #d0dce9;border-radius:10px;padding:10px 16px;border-left:4px solid $_fflColor;'><span style='font-size:11px;font-weight:700;color:#5a6f84;text-transform:uppercase;'>Forest Functional Level</span><span style='font-size:16px;font-weight:900;color:$_fflColor;'>$FFL</span></div>"
$Html += "<div style='display:flex;align-items:center;gap:10px;background:#f8fafd;border:1px solid #d0dce9;border-radius:10px;padding:10px 16px;border-left:4px solid $_schColor;'><span style='font-size:11px;font-weight:700;color:#5a6f84;text-transform:uppercase;'>AD Schema Version</span><span style='font-size:16px;font-weight:900;color:$_schColor;'>$SchemaVer</span></div>"
$Html += "</div>"

# DC cards
$Html += "<h3 style='margin:14px 0 10px 0;font-size:15px;color:#0f2f4f;'>Domain Controller Status</h3>"
$Html += "<div class='dc-card-grid'>"
foreach ($d in $DCHealth | Sort Name) {
    $_dnsOk      = [string]$d.DNS_Health -eq 'OK'
    $_dnsUnknown = [string]$d.DNS_Health -eq 'WMI Unreachable'
    $_replOk  = [string]$d.Replication_6h -match '^OK'
    $_sysOk   = [string]$d.Sysvol -match 'OK|Normal|Running'
    $_isGC    = [string]$d.IsGC -match 'True|Yes'
    $_issues  = @()
    if (-not $_dnsOk -and -not $_dnsUnknown) { $_issues += "DNS Error" }
    if (-not $_replOk) { $_issues += "Replication Warning" }
    if (-not $_sysOk)  { $_issues += "SYSVOL Issue" }
    $_topColor  = if ($_issues.Count -eq 0) { '#22c55e' } elseif ($_issues.Count -eq 1) { '#f97316' } else { '#ef4444' }
    $_statusIcon = if ($_issues.Count -eq 0) { "<i class='fa-solid fa-circle-check' style='color:#22c55e'></i>" } elseif ($_issues.Count -eq 1) { "<i class='fa-solid fa-triangle-exclamation' style='color:#f97316'></i>" } else { "<i class='fa-solid fa-circle-xmark' style='color:#ef4444'></i>" }
    $_statusText = if ($_issues.Count -eq 0) { "Healthy" } else { $($_issues -join ' · ') }
    $_statusColor = $_topColor
    $_fsmoShort = if ([string]$d.FSMORoles -match '\w') { [string]$d.FSMORoles } else { "—" }
    $_gcBadge   = if ($_isGC) { "<span style='display:inline-block;padding:1px 7px;border-radius:4px;background:#dbeafe;color:#1d4ed8;font-size:9px;font-weight:800;letter-spacing:.04em;'>GC</span>" } else { "" }
    $_fsmoBadge = if ([string]$d.FSMORoles -match 'PDC') { "<span style='display:inline-block;padding:1px 7px;border-radius:4px;background:#fef3c7;color:#92400e;font-size:9px;font-weight:800;'>PDC</span>" } else { "" }
    $ReplicationDetailJs = ([string]$d.Replication_6h_Detail -replace "'", "\\'" -replace "`r", " " -replace "`n", " ")
    $ReplicationDcJs = ([string]$d.Name -replace "'", "\\'")
    $Html += "<div class='dc-card' style='border-top-color:$_topColor;cursor:pointer;' onclick=""showReplicationHealth('$ReplicationDcJs','$ReplicationDetailJs')"">"
    $Html += "<div class='dc-card-name'><i class='fa-solid fa-server' style='color:$_topColor;font-size:12px;'></i>$($d.Name) $_gcBadge $_fsmoBadge</div>"
    $Html += "<div class='dc-card-status' style='color:$_statusColor;'>$_statusIcon $_statusText</div>"
    $Html += "<div class='dc-card-meta'>"
    $Html += "<b>OS</b> $($d.OperatingSystem)<br>"
    $Html += "<b>IP</b> $($d.IPv4Address)<br>"
    $Html += "<b>Uptime</b> $($d.Uptime)<br>"
    $Html += "<b>DNS</b> $($d.DNS_Health)<br>"
    $Html += "<b>Replication</b> $($d.Replication_6h)"
    if ($_fsmoShort -ne '—') { $Html += "<br><b>FSMO</b> $_fsmoShort" }
    $Html += "</div>"
    $Html += "</div>"
}
$Html += "</div>"

# Detay tablosu (açılabilir)
$Html += "<details style='margin-top:14px;'><summary style='cursor:pointer;font-size:13px;font-weight:700;color:#1b4f7c;padding:6px 0;'>Full Details (Table View)</summary>"
$Html += "<div class='table-wrapper' style='margin-top:10px;'>"
$Html += "<table class='user-table' id='dcHealthTable'><tr>
<th onclick='sortTable(""dcHealthTable"",0)'>DC Name</th>
<th onclick='sortTable(""dcHealthTable"",1)'>OS</th>
<th onclick='sortTable(""dcHealthTable"",2)'>Uptime</th>
<th onclick='sortTable(""dcHealthTable"",3)'>Sysvol</th>
<th onclick='sortTable(""dcHealthTable"",4)'>FSMO Roles</th>
<th onclick='sortTable(""dcHealthTable"",5)'>Global Catalog</th>
<th onclick='sortTable(""dcHealthTable"",6)'>IP Address</th>
<th onclick='sortTable(""dcHealthTable"",7)'>DNS Servers</th>
<th onclick='sortTable(""dcHealthTable"",8)'>DNS Status</th>
<th onclick='sortTable(""dcHealthTable"",9)'>Replication (Last 6h)</th>
</tr>"
foreach ($d in $DCHealth | Sort Name) {
    $DNSClass = switch ($d.DNS_Health) {
        "OK" { "status-ok" }
        "ERROR (Secondary Not DC/Loopback)" { "status-hata" }
        "WMI Unreachable" { "status-uyari" }
        default { "" }
    }
    $ReplicationClass = if ([string]$d.Replication_6h -match '^OK') { "status-ok" } elseif ([string]$d.Replication_6h -match '^WARN') { "status-uyari" } else { "status-hata" }
    $ReplicationTitle = [System.Net.WebUtility]::HtmlEncode([string]$d.Replication_6h_Detail)
    $ReplicationDetailJs = ([string]$d.Replication_6h_Detail -replace "'", "\\'" -replace "`r", " " -replace "`n", " ")
    $ReplicationDcJs = ([string]$d.Name -replace "'", "\\'")
    $Html += "<tr><td>$($d.Name)</td><td>$($d.OperatingSystem)</td><td>$($d.Uptime)</td><td>$($d.Sysvol)</td><td>$($d.FSMORoles)</td><td>$($d.IsGC)</td><td>$($d.IPv4Address)</td><td>$($d.DNS_Servers)</td><td class='$DNSClass'>$($d.DNS_Health)</td><td class='$ReplicationClass' title='$ReplicationTitle'><span class='group-name-cell' onclick=""showReplicationHealth('$ReplicationDcJs','$ReplicationDetailJs')"">$($d.Replication_6h)</span></td></tr>"
}
$Html += "</table></div></details>"

$totalDcHealth = [math]::Max(@($DCHealth).Count, 1)
$Html += "<div class='adrep-wrap'>"
$Html += "<style>"
$Html += ".adrep-wrap{margin-top:14px;background:#f7fbff;border:1px solid #c9daee;border-radius:12px;padding:14px;color:#16324f;}"
$Html += ".adrep-title{font-size:12px;font-weight:700;margin:0 0 8px 0;color:#12395f;letter-spacing:.2px;}"
$Html += ".adrep-tl{background:#ffffff;border:1px solid #c9daee;border-radius:10px;padding:12px 12px 18px 12px;}"
$Html += ".adrep-tl-ticks{display:flex;justify-content:space-between;color:#5b7289;font-size:10px;font-family:'JetBrains Mono',Consolas,monospace;margin:0 0 8px 170px;}"
$Html += ".adrep-tl-row{display:flex;align-items:center;gap:12px;margin:0 0 28px 0;} .adrep-tl-row:last-child{margin-bottom:0;}"
$Html += ".adrep-tl-label{width:160px;color:#3f5d79;font-size:11px;font-family:'JetBrains Mono',Consolas,monospace;}"
$Html += ".adrep-tl-bar{position:relative;height:10px;background:#eaf2fb;border-radius:999px;flex:1;overflow:visible;}"
$Html += ".adrep-evt{position:absolute;top:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;cursor:pointer;}"
$Html += ".adrep-evt-dot{width:10px;height:10px;border-radius:50%;transform:translateY(-50%);}"
$Html += ".adrep-evt-dot.ok{background:#3fb950;box-shadow:0 0 8px #3fb950;} .adrep-evt-dot.err{background:#f85149;box-shadow:0 0 8px #f85149;} .adrep-evt-dot.warn{background:#e3b341;box-shadow:0 0 8px #e3b341;}"
$Html += ".adrep-evt-txt{margin-top:8px;font-size:11px;line-height:1.25;text-align:center;font-family:'JetBrains Mono',Consolas,monospace;white-space:normal;min-width:58px;max-width:130px;padding:2px 6px;border-radius:6px;background:rgba(255,255,255,.9);border:1px solid #c9daee;}"
$Html += ".adrep-evt-txt.ok{color:#2f4f6f;} .adrep-evt-txt.err{color:#d83a35;} .adrep-evt-txt.warn{color:#a66d00;}"
$Html += ".adrep-tooltip{position:fixed;z-index:9999;display:none;background:#ffffff;color:#16324f;border:1px solid #c9daee;border-radius:8px;padding:9px 10px;font-size:11px;box-shadow:0 8px 20px rgba(7,38,66,.22);min-width:180px;}"
$Html += ".adrep-tooltip b{color:#58a6ff;}"
$Html += "#pingDetailModal{position:fixed;inset:0;z-index:9500;background:rgba(10,30,55,.58);display:none;align-items:center;justify-content:center;}"
$Html += "#pingDetailModal.open{display:flex;}"
$Html += ".pdm-card{background:#fff;border-radius:14px;max-width:700px;width:94%;max-height:88vh;overflow-y:auto;box-shadow:0 24px 64px rgba(0,0,0,.32);display:flex;flex-direction:column;}"
$Html += ".pdm-header{padding:20px 24px 16px;border-bottom:1px solid #dde9f5;display:flex;justify-content:space-between;align-items:flex-start;gap:12px;position:sticky;top:0;background:#fff;z-index:1;border-radius:14px 14px 0 0;}"
$Html += ".pdm-header-left{display:flex;flex-direction:column;gap:6px;flex:1;min-width:0;}"
$Html += ".pdm-badge{display:inline-flex;align-items:center;padding:3px 11px;border-radius:20px;font-size:11px;font-weight:700;letter-spacing:.4px;width:fit-content;}"
$Html += ".pdm-badge-critical{background:#fde8e8;color:#a01010;}"
$Html += ".pdm-badge-high{background:#fff0e0;color:#8a4500;}"
$Html += ".pdm-badge-medium{background:#fffbe0;color:#7a5500;}"
$Html += ".pdm-badge-low{background:#e8f8f0;color:#1a6c40;}"
$Html += ".pdm-rule{margin:0;font-size:16px;font-weight:700;color:#0d2b47;line-height:1.3;}"
$Html += ".pdm-meta{font-size:12px;color:#5a7a90;display:flex;gap:14px;flex-wrap:wrap;}"
$Html += ".pdm-close{background:none;border:none;font-size:22px;cursor:pointer;color:#8a9fb5;padding:0 2px;line-height:1;flex-shrink:0;}"
$Html += ".pdm-close:hover{color:#0d2b47;}"
$Html += ".pdm-body{padding:20px 24px;display:flex;flex-direction:column;gap:14px;}"
$Html += ".pdm-section{background:#f5f9fe;border-left:3px solid #3a7bbf;border-radius:0 8px 8px 0;padding:12px 14px;}"
$Html += ".pdm-section-critical{border-left-color:#d83a35;background:#fdf4f4;}"
$Html += ".pdm-section-high{border-left-color:#e07200;background:#fdf6ee;}"
$Html += ".pdm-section-label{font-size:11px;font-weight:700;letter-spacing:.5px;color:#5a7a90;margin-bottom:5px;text-transform:uppercase;}"
$Html += ".pdm-section-text{font-size:13px;color:#1c3550;line-height:1.55;}"
$Html += ".pdm-objects-list{margin:6px 0 0 0;padding:0;list-style:none;display:flex;flex-direction:column;gap:3px;}"
$Html += ".pdm-objects-list li{font-size:12px;font-family:Consolas,monospace;color:#1c3550;background:#e8f0f8;border-radius:5px;padding:3px 8px;}"
$Html += ".pdm-empty{font-size:13px;color:#8a9fb5;font-style:italic;}"
$Html += "</style>"

$nowRef = Get-Date
$timelineStart = $nowRef.AddHours(-6)
$timelineWindowSec = 21600.0
$recent3hThreshold = $nowRef.AddHours(-3)

$UniqueLinks = @{}
foreach ($ln in ($ReplicationTopologyLinks | Sort-Object SourceDC, PartnerDC, LastAttempt -Descending)) {
    $lnKey = "$($ln.SourceDC)|$($ln.PartnerDC)"
    if (-not $UniqueLinks.ContainsKey($lnKey)) {
        $UniqueLinks[$lnKey] = $ln
    }
}
$ReplicationLinkRows = @($UniqueLinks.Values | Sort-Object SourceDC, PartnerDC)

$ReplicationLinkStatusRows = @()

foreach ($ln in $ReplicationLinkRows) {
    $lnKey = "$($ln.SourceDC)|$($ln.PartnerDC)"
    $linkFailures = @($ReplicationFailureEvents | Where-Object { "$($_.Source)|$($_.Partner)" -eq $lnKey } | Sort-Object Time -Descending)
    $lastFailure = if ($linkFailures.Count -gt 0) { $linkFailures[0] } else { $null }

    $isCurrentError = $false
    if ($ln.LastResult -ne $null -and [int]$ln.LastResult -ne 0) { $isCurrentError = $true }
    if ([int]$ln.ConsecutiveFailures -gt 0) { $isCurrentError = $true }

    $hasRecentFailure3h = $false
    if ($lastFailure -and $lastFailure.Time -ge $recent3hThreshold) {
        $hasRecentFailure3h = $true
    }

    if ($isCurrentError) {
        $badgeText = 'ERROR NOW'
        $stateClass = 'err'
    } elseif ($hasRecentFailure3h) {
        $badgeText = 'HEALTHY (Recovered <= 3H)'
        $stateClass = 'ok'
    } else {
        $badgeText = 'HEALTHY'
        $stateClass = 'ok'
    }

    $lastSuccessText = if ($ln.LastSuccess) { ([datetime]$ln.LastSuccess).ToString('yyyy-MM-dd HH:mm') } else { 'N/A' }
    $lastAttemptText = if ($ln.LastAttempt) { ([datetime]$ln.LastAttempt).ToString('yyyy-MM-dd HH:mm') } else { 'N/A' }
    $lastFailureText = if ($lastFailure) { ([datetime]$lastFailure.Time).ToString('yyyy-MM-dd HH:mm') } else { 'No failure record' }
    $lastErrorText = if ($lastFailure) { [System.Net.WebUtility]::HtmlEncode([string]$lastFailure.LastError) } else { '-' }

    $ReplicationLinkStatusRows += [PSCustomObject]@{
        SourceDC = $ln.SourceDC
        PartnerDC = $ln.PartnerDC
        StateClass = $stateClass
        BadgeText = $badgeText
        LastSuccessText = $lastSuccessText
        LastAttemptText = $lastAttemptText
        LastFailureText = $lastFailureText
        LastErrorText = $lastErrorText
        LastFailureTime = if ($lastFailure) { [datetime]$lastFailure.Time } else { $null }
    }

}

$ProblemDcRows = @($DCHealth | Where-Object { [string]$_.Replication_6h -notmatch '^OK' } | Sort-Object Name)
if ($ProblemDcRows.Count -gt 0) {
    $Html += "<div class='table-wrapper' style='margin-top:10px;'><table class='user-table' id='replicationFaultTable'><tr><th>Problem DC</th><th>Status</th><th>Detail</th></tr>"
    foreach ($p in $ProblemDcRows) {
        $faultClass = if ([string]$p.Replication_6h -match '^WARN') { 'status-uyari' } else { 'status-hata' }
        $faultDetail = [System.Net.WebUtility]::HtmlEncode([string]$p.Replication_6h_Detail)
        $Html += "<tr><td>$($p.Name)</td><td class='$faultClass'>$($p.Replication_6h)</td><td>$faultDetail</td></tr>"
    }
    $Html += "</table></div>"
} else {
    $Html += "<p style='margin:8px 0 0 0;font-size:12px;color:#155724;font-weight:700;'>No DC replication issue detected in the last 6 hours.</p>"
}

$Html += "</div>"

# --- SYSVOL / NETLOGON subsection (embedded in DC Health) ---
$_svReachCount  = @($SysvolDcDetails | Where-Object {  $_.SysvolReach   }).Count
$_nlReachCount  = @($SysvolDcDetails | Where-Object {  $_.NetlogonReach }).Count
$_svUnreach     = @($SysvolDcDetails | Where-Object { -not $_.SysvolReach   }).Count
$_nlUnreach     = @($SysvolDcDetails | Where-Object { -not $_.NetlogonReach }).Count
$_dfsrErrCount  = @($SysvolDcDetails | Where-Object { $_.DfsrStateNum -notin @(-1,4) -and -not $_.IsFrs }).Count
$_dcTotal       = @($SysvolDcDetails).Count

$Html += "<h3 id='sysvolAnchor' style='margin:28px 0 6px 0;font-size:15px;color:#0f2f4f;border-top:2px solid #e2e8f0;padding-top:18px;'><i class='fa-solid fa-folder-tree' style='margin-right:7px;color:#3b82f6;'></i>SYSVOL / NETLOGON Share Health</h3>"
$Html += "<p style='font-size:12px;color:#526980;margin:0 0 12px 0;'>Per-DC share accessibility, DFSR replication state, GPO folder count and script inventory. FRS (File Replication Service) is end-of-life — all DCs must use DFSR.</p>"
$Html += "<div class='section-stat-grid'>"
$_svCard  = if ($_svUnreach  -gt 0){'card--critical'}elseif($_dcTotal -gt 0){'card--green'}else{'card--gray'}
$_nlCard  = if ($_nlUnreach  -gt 0){'card--critical'}elseif($_dcTotal -gt 0){'card--green'}else{'card--gray'}
$_frsCard = if ($frsRiskCount -gt 0){'card--critical'}else{'card--green'}
$_dfsCard = if ($_dfsrErrCount -gt 0){'card--warn'}else{'card--green'}
$Html += "<div class='section-stat-card $_svCard'><div class='section-stat-icon'><i class='fa-solid fa-folder-open'></i></div><div class='section-stat-label'>SYSVOL Accessible</div><div class='section-stat-value'>$_svReachCount / $_dcTotal</div><div class='section-stat-note'>$(if($_svUnreach -gt 0){"$_svUnreach DC(s) unreachable!"}else{"All DCs reachable"})</div></div>"
$Html += "<div class='section-stat-card $_nlCard'><div class='section-stat-icon'><i class='fa-solid fa-network-wired'></i></div><div class='section-stat-label'>NETLOGON Accessible</div><div class='section-stat-value'>$_nlReachCount / $_dcTotal</div><div class='section-stat-note'>$(if($_nlUnreach -gt 0){"$_nlUnreach DC(s) unreachable!"}else{"All DCs reachable"})</div></div>"
$Html += "<div class='section-stat-card $_frsCard'><div class='section-stat-icon'><i class='fa-solid fa-rotate'></i></div><div class='section-stat-label'>FRS (EOL) DCs</div><div class='section-stat-value'>$frsRiskCount</div><div class='section-stat-note'>$(if($frsRiskCount -gt 0){"Must migrate to DFSR"}else{"All DCs use DFSR"})</div></div>"
$Html += "<div class='section-stat-card $_dfsCard'><div class='section-stat-icon'><i class='fa-solid fa-check-double'></i></div><div class='section-stat-label'>DFSR Errors</div><div class='section-stat-value'>$_dfsrErrCount</div><div class='section-stat-note'>$(if($_dfsrErrCount -gt 0){"Check DFSR state"}else{"DFSR running normally"})</div></div>"
$Html += "</div>"
$Html += "<div style='display:grid;grid-template-columns:repeat(auto-fill,minmax(295px,1fr));gap:10px;margin-top:12px;'>"
foreach ($svdc in $SysvolDcDetails) {
    $_cardBorder = if ($svdc.IsHealthy){'#86efac'}elseif($svdc.IsFrs -or -not $svdc.SysvolReach -or -not $svdc.NetlogonReach){'#fca5a5'}else{'#fde68a'}
    $_cardBg     = if ($svdc.IsHealthy){'#f0fdf4'}elseif($svdc.IsFrs -or -not $svdc.SysvolReach -or -not $svdc.NetlogonReach){'#fff1f2'}else{'#fffbeb'}
    $_statusDot  = if ($svdc.IsHealthy){'#16a34a'}elseif($svdc.IsFrs -or -not $svdc.SysvolReach -or -not $svdc.NetlogonReach){'#dc2626'}else{'#d97706'}
    $_svIcon     = if ($svdc.SysvolReach)   {"<i class='fa-solid fa-check' style='color:#16a34a;'></i>"}else{"<i class='fa-solid fa-xmark' style='color:#dc2626;'></i>"}
    $_nlIcon     = if ($svdc.NetlogonReach) {"<i class='fa-solid fa-check' style='color:#16a34a;'></i>"}else{"<i class='fa-solid fa-xmark' style='color:#dc2626;'></i>"}
    $_modeLabel  = if ($svdc.IsFrs){"<span style='color:#dc2626;font-weight:700;'>FRS (EOL)</span>"}else{"<span style='color:#16a34a;font-weight:600;'>DFSR</span>"}
    $_dfsrLabel  = if ($svdc.IsFrs){'N/A'}else{
        switch ($svdc.DfsrStateNum) {
            4       { "<span style='color:#16a34a;font-weight:600;'>Normal</span>" }
            -1      { "<span style='color:#6b7280;'>Unknown</span>" }
            default { "<span style='color:#d97706;font-weight:700;'>$($svdc.DfsrState)</span>" }
        }
    }
    $_sizeStr = if ($svdc.SysvolSizeMB -gt 0) { "$($svdc.SysvolSizeMB) MB" } else { "" }
    $Html += "<div style='border:1.5px solid $_cardBorder;border-radius:10px;padding:12px 14px;background:$_cardBg;'>"
    $Html += "<div style='display:flex;align-items:center;gap:8px;margin-bottom:8px;'>"
    $Html += "<span style='display:inline-block;width:9px;height:9px;border-radius:50%;background:$_statusDot;flex-shrink:0;'></span>"
    $Html += "<strong style='font-size:13px;' data-no-translate='true'>$([System.Net.WebUtility]::HtmlEncode($svdc.DCName))</strong>"
    $Html += "</div>"
    $Html += "<table style='width:100%;font-size:11.5px;border-collapse:collapse;'>"
    $Html += "<tr><td style='padding:2px 6px 2px 0;color:#526980;width:42%;'>SYSVOL Share</td><td>$_svIcon &nbsp;<code style='font-size:10px;'>\\$([System.Net.WebUtility]::HtmlEncode($svdc.DCName))\SYSVOL</code></td></tr>"
    $Html += "<tr><td style='padding:2px 6px 2px 0;color:#526980;'>NETLOGON Share</td><td>$_nlIcon &nbsp;<code style='font-size:10px;'>\\$([System.Net.WebUtility]::HtmlEncode($svdc.DCName))\NETLOGON</code></td></tr>"
    $Html += "<tr><td style='padding:2px 6px 2px 0;color:#526980;'>Replication Mode</td><td>$_modeLabel</td></tr>"
    $Html += "<tr><td style='padding:2px 6px 2px 0;color:#526980;'>DFSR State</td><td>$_dfsrLabel</td></tr>"
    $Html += "<tr><td style='padding:2px 6px 2px 0;color:#526980;'>GPO Folders</td><td><strong>$($svdc.GpoCount)</strong></td></tr>"
    $Html += "<tr><td style='padding:2px 6px 2px 0;color:#526980;'>Scripts in NETLOGON</td><td><strong>$($svdc.ScriptCount)</strong> (bat/ps1/cmd/vbs)</td></tr>"
    if ($_sizeStr) {
        $Html += "<tr><td style='padding:2px 6px 2px 0;color:#526980;'>SYSVOL Size</td><td>$_sizeStr</td></tr>"
    }
    $Html += "</table></div>"
}
$Html += "</div>"
if ($GppCount -gt 0) {
    $Html += "<div style='margin:12px 0 0 0;padding:10px 14px;border:1px solid #fca5a5;border-radius:8px;background:#fef2f2;color:#7f1d1d;'><strong><i class='fa-solid fa-key' style='margin-right:6px;'></i>GPP cpassword files found ($GppCount).</strong> AES key is publicly known (MS14-025) — treat as plaintext. Delete and rotate affected credentials.</div>"
    $Html += "<div class='table-wrapper'><table class='user-table' id='gppFilesTable2'><tr><th>File Path</th></tr>"
    foreach ($gf in $GppCpasswordFiles | Select-Object -First 50) {
        $Html += "<tr><td style='font-size:11px;font-family:monospace;' data-no-translate='true'>$([System.Net.WebUtility]::HtmlEncode([string]$gf))</td></tr>"
    }
    $Html += "</table></div>"
}
if ($netlogonSensitiveCount -gt 0) {
    $Html += "<div style='margin:10px 0 0 0;padding:10px 14px;border:1px solid #fde68a;border-radius:8px;background:#fffbeb;color:#78350f;'><strong><i class='fa-solid fa-file-code' style='margin-right:6px;'></i>Sensitive patterns in NETLOGON scripts ($netlogonSensitiveCount hits).</strong> Review scripts for hardcoded credential keywords and move secrets to a vault.</div>"
}
if ($frsRiskCount -gt 0) {
    $_frsStr = [System.Net.WebUtility]::HtmlEncode($frsRiskDcs -join ", ")
    $Html += "<div style='margin:10px 0 0 0;padding:10px 14px;border:1px solid #fca5a5;border-radius:8px;background:#fef2f2;color:#7f1d1d;'><strong><i class='fa-solid fa-triangle-exclamation' style='margin-right:6px;'></i>FRS Running On:</strong> <span data-no-translate='true'>$_frsStr</span> — Migrate to DFSR immediately.</div>"
}
if ($frsRiskCount -eq 0 -and $GppCount -eq 0 -and $netlogonSensitiveCount -eq 0 -and $_svUnreach -eq 0 -and $_nlUnreach -eq 0 -and $_dfsrErrCount -eq 0) {
    $Html += "<div style='margin:12px 0 0 0;padding:10px 14px;border:1px solid #86efac;border-radius:8px;background:#f0fdf4;color:#14532d;'><strong><i class='fa-solid fa-circle-check' style='margin-right:6px;'></i>SYSVOL / NETLOGON posture is clean.</strong> All shares reachable, DFSR running normally, no credential artifacts detected.</div>"
}

$Html += "</div></div>"

# ---------------------
# Exchange Users Container (Shortened)
# ---------------------
$ExchangeTotalCount = @($ExchangeUsers).Count
$ExchangeCloudCount = @($ExchangeUsers | Where-Object { $_.MailType -eq 'hybrid' }).Count
$ExchangeOnPremCount = @($ExchangeUsers | Where-Object { $_.MailType -eq 'onprem' }).Count
$ExchangeMissingMailCount = @($Users | Where-Object { -not $_.EmailAddress }).Count

$Html += "<div class='container' id='exchangeContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>Mail Users</h2>"
$Html += "<p class='section-intro'>Derived from on-prem AD email attributes. Pure cloud-only (Entra ID only) accounts are not visible here.</p>"
$Html += "<div class='section-stat-grid'>"
$Html += "<div class='section-stat-card card--blue' style='cursor:pointer;' onclick='invFilterExchange(""exchangeUserTable"",""all"",this)'><div class='section-stat-icon'><i class='fa-solid fa-envelope'></i></div><div class='section-stat-label'>Total Mail Users</div><div class='section-stat-value'>$ExchangeTotalCount</div><div class='section-stat-note'>EmailAddress attribute set</div></div>"
$Html += "<div class='section-stat-card card--blue' style='cursor:pointer;' onclick='invFilterExchange(""exchangeUserTable"",""hybrid"",this)'><div class='section-stat-icon'><i class='fa-solid fa-cloud'></i></div><div class='section-stat-label'>Hybrid (M365 Mailbox)</div><div class='section-stat-value'>$ExchangeCloudCount</div><div class='section-stat-note'>Mailbox in Exchange Online, AD object on-prem</div></div>"
$Html += "<div class='section-stat-card card--gray' style='cursor:pointer;' onclick='invFilterExchange(""exchangeUserTable"",""onprem"",this)'><div class='section-stat-icon'><i class='fa-solid fa-server'></i></div><div class='section-stat-label'>On-Prem Exchange</div><div class='section-stat-value'>$ExchangeOnPremCount</div><div class='section-stat-note'>Mailbox on local Exchange server</div></div>"
$Html += "</div>"
$Html += "<span class='section-note-pill'>Pure cloud (Entra ID only) users are not listed here — use Exchange Online Admin Center for those.</span>"
$Html += "<div class='table-wrapper'><table class='user-table' id='exchangeUserTable'><tr>"
$Html += "<th onclick='sortTable(""exchangeUserTable"",0)'>Name</th>"
$Html += "<th onclick='sortTable(""exchangeUserTable"",1)'>Email</th>"
$Html += "<th onclick='sortTable(""exchangeUserTable"",2)'>Mailbox Type</th>"
$Html += "</tr>"
foreach ($e in $ExchangeUsers | Sort Name) {
    $_typeLabel = if ($e.MailType -eq 'hybrid') { "<span style='display:inline-block;padding:2px 8px;border-radius:4px;background:#dbeafe;color:#1d4ed8;font-size:10px;font-weight:700;'>Hybrid (M365)</span>" } else { "<span style='display:inline-block;padding:2px 8px;border-radius:4px;background:#f1f5f9;color:#475569;font-size:10px;font-weight:700;'>On-Prem</span>" }
    $Html += "<tr data-mailtype='$($e.MailType)'><td>$($e.Name)</td><td>$($e.EmailAddress)</td><td>$_typeLabel</td></tr>"
}
$Html += "</table></div></div></div>"

# ---------------------
# PSO (Fine-Grained Password Policies) Container
# ---------------------
$Html += "<div class='container' id='psoContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>Password Policies</h2>"
$Html += "<p class='section-intro'>Default Domain Password Policy applies to all users unless overridden by a Fine-Grained Password Policy (PSO).</p>"

# --- Default Domain Password Policy ---
if ($PwdPolicy) {
    $pp_MaxAge    = if ($PwdPolicy.MaxPasswordAge.TotalDays -eq 0) { "Never expires" } else { "$([int]$PwdPolicy.MaxPasswordAge.TotalDays) days" }
    $pp_MinAge    = "$([int]$PwdPolicy.MinPasswordAge.TotalDays) days"
    $pp_History   = "$($PwdPolicy.PasswordHistoryCount) passwords remembered"
    $pp_MinLen    = "$($PwdPolicy.MinPasswordLength) characters"
    $pp_Complex   = if ($PwdPolicy.ComplexityEnabled) { "Enabled" } else { "Disabled" }
    $pp_RevEnc    = if ($PwdPolicy.ReversibleEncryptionEnabled) { "Enabled" } else { "Disabled" }
    $pp_LockThres = if ($PwdPolicy.LockoutThreshold -eq 0) { "0 — no lockout (risk!)" } else { "$($PwdPolicy.LockoutThreshold) invalid logon attempts" }
    $pp_LockDur   = if ($PwdPolicy.LockoutDuration.TotalMinutes -eq 0) { "Not Defined" } else { "$([int]$PwdPolicy.LockoutDuration.TotalMinutes) minutes" }
    $pp_LockObs   = if ($PwdPolicy.LockoutObservationWindow.TotalMinutes -eq 0) { "Not Defined" } else { "$([int]$PwdPolicy.LockoutObservationWindow.TotalMinutes) minutes" }

    $pp_LenColor    = if ($PwdPolicy.MinPasswordLength -lt 12) { "color:#b91c1c;font-weight:700;" } else { "color:#1a7f4b;font-weight:700;" }
    $pp_ComplexColor= if (-not $PwdPolicy.ComplexityEnabled) { "color:#b91c1c;font-weight:700;" } else { "color:#1a7f4b;font-weight:700;" }
    $pp_RevEncColor = if ($PwdPolicy.ReversibleEncryptionEnabled) { "color:#b91c1c;font-weight:700;" } else { "" }
    $pp_LockColor   = if ($PwdPolicy.LockoutThreshold -eq 0) { "color:#b91c1c;font-weight:700;" } else { "color:#1a7f4b;font-weight:700;" }
    $pp_MaxAgeColor = if ($PwdPolicy.MaxPasswordAge.TotalDays -eq 0) { "color:#b91c1c;font-weight:700;" } else { "" }

    $Html += "<h3 style='margin:16px 0 8px 0;font-size:15px;color:#0f2f4f;'>Password Policy <span style='font-size:11px;font-weight:400;color:#7a909f;margin-left:6px;'>Default Domain Policy</span></h3>"
    $Html += "<div class='table-wrapper'><table class='user-table' style='max-width:680px;'>"
    $Html += "<tr><th style='width:55%;'>Policy Setting</th><th>Value</th></tr>"
    $Html += "<tr><td>Enforce password history</td><td>$pp_History</td></tr>"
    $Html += "<tr><td>Maximum password age</td><td style='$pp_MaxAgeColor'>$pp_MaxAge</td></tr>"
    $Html += "<tr><td>Minimum password age</td><td>$pp_MinAge</td></tr>"
    $Html += "<tr><td>Minimum password length</td><td style='$pp_LenColor'>$pp_MinLen</td></tr>"
    $Html += "<tr><td>Password must meet complexity requirements</td><td style='$pp_ComplexColor'>$pp_Complex</td></tr>"
    $Html += "<tr><td>Store passwords using reversible encryption</td><td style='$pp_RevEncColor'>$pp_RevEnc</td></tr>"
    $Html += "</table></div>"

    $Html += "<h3 style='margin:16px 0 8px 0;font-size:15px;color:#0f2f4f;'>Account Lockout Policy <span style='font-size:11px;font-weight:400;color:#7a909f;margin-left:6px;'>Default Domain Policy</span></h3>"
    $Html += "<div class='table-wrapper'><table class='user-table' style='max-width:680px;'>"
    $Html += "<tr><th style='width:55%;'>Policy Setting</th><th>Value</th></tr>"
    $Html += "<tr><td>Account lockout threshold</td><td style='$pp_LockColor'>$pp_LockThres</td></tr>"
    $Html += "<tr><td>Account lockout duration</td><td>$pp_LockDur</td></tr>"
    $Html += "<tr><td>Reset account lockout counter after</td><td>$pp_LockObs</td></tr>"
    $Html += "</table></div>"
} else {
    $Html += "<div class='baseline-empty' style='margin-top:12px;'>Default Domain Password Policy could not be retrieved.</div>"
}

# --- Fine-Grained PSOs ---
$Html += "<h3 style='margin:20px 0 8px 0;font-size:15px;color:#0f2f4f;'>Fine-Grained Password Policies (PSO) <span style='font-size:11px;font-weight:400;color:#7a909f;margin-left:6px;'>$PsoCount configured</span></h3>"
if ($PsoCount -gt 0) {
    $Html += "<p class='section-intro'>PSOs override the Default Domain Policy for specific users or groups. Lower Precedence value = higher priority.</p>"
    $Html += "<div class='table-wrapper'><table class='user-table' id='psoTable'>"
    $Html += "<tr>
<th onclick='sortTable(""psoTable"",0)'>Policy Name</th>
<th onclick='sortTable(""psoTable"",1)'>Precedence</th>
<th onclick='sortTable(""psoTable"",2)'>Min Length</th>
<th onclick='sortTable(""psoTable"",3)'>Max Age</th>
<th onclick='sortTable(""psoTable"",4)'>Complexity</th>
<th onclick='sortTable(""psoTable"",5)'>Lockout Threshold</th>
<th onclick='sortTable(""psoTable"",6)'>Lockout Duration</th>
<th onclick='sortTable(""psoTable"",7)'>Rev. Encryption</th>
<th onclick='sortTable(""psoTable"",8)'>Targets</th>
</tr>"
    foreach ($pso in $AllFgppPolicies | Sort-Object Precedence) {
        $psoMaxAge  = try { if ($pso.MaxPasswordAge.TotalDays -eq 0) { "Never" } else { "$([int]$pso.MaxPasswordAge.TotalDays)d" } } catch { "N/A" }
        $psoLockDur = try { if ($pso.LockoutDuration.TotalMinutes -eq 0) { "Not Defined" } else { "$([int]$pso.LockoutDuration.TotalMinutes)m" } } catch { "N/A" }
        $psoTargets = @($pso.AppliesTo).Count
        $psoComplexClass = if ($pso.ComplexityEnabled) { "style='color:#1a7f4b;font-weight:600;'" } else { "style='color:#b91c1c;font-weight:600;'" }
        $psoRevEncClass  = if ($pso.ReversibleEncryptionEnabled) { "style='color:#b91c1c;font-weight:600;'" } else { "" }
        $psoLockClass    = if ($pso.LockoutThreshold -eq 0) { "style='color:#b91c1c;font-weight:600;'" } else { "" }
        $Html += "<tr>
<td><strong>$($pso.Name)</strong></td>
<td>$($pso.Precedence)</td>
<td>$($pso.MinPasswordLength)</td>
<td>$psoMaxAge</td>
<td $psoComplexClass>$(if($pso.ComplexityEnabled){'Yes'}else{'No'})</td>
<td $psoLockClass>$($pso.LockoutThreshold)</td>
<td>$psoLockDur</td>
<td $psoRevEncClass>$(if($pso.ReversibleEncryptionEnabled){'Yes (Risk!)'}else{'No'})</td>
<td>$psoTargets</td>
</tr>"
    }
    $Html += "</table></div>"
} else {
    $Html += "<p class='section-intro' style='color:#7a909f;'>No Fine-Grained Password Policies configured — Default Domain Policy applies to all users.</p>"
}
$Html += "</div></div>"

# ---------------------
# Hybrid / Entra Join Container
# ---------------------
$EntraStatusColor = if ($EntraContainerExists -and $EntraDeviceCount -gt 0) { "#1a7f4b" } elseif ($EntraContainerExists) { "#c0392b" } else { "#526980" }
$EntraStatusText = if ($EntraContainerExists -and $EntraDeviceCount -gt 0) { "Active" } elseif ($EntraContainerExists) { "Container exists, 0 devices" } else { "Not configured" }
$Html += "<div class='container' id='entraJoinContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>Hybrid / Entra Join Status</h2>"
$Html += "<p class='section-intro'>Hybrid Azure AD Join registers on-premises AD computer accounts into Entra ID. Devices appear under the RegisteredDevices container in AD when sync is healthy.</p>"
$Html += "<div class='section-stat-grid'>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Hybrid Join Status</div><div class='section-stat-value' style='font-size:16px;color:$EntraStatusColor;'>$EntraStatusText</div><div class='section-stat-note'>RegisteredDevices container</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Registered Devices</div><div class='section-stat-value'>$EntraDeviceCount</div><div class='section-stat-note'>Objects in AD container</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Total Computers</div><div class='section-stat-value'>$TotalComputerCount</div><div class='section-stat-note'>AD computer accounts</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>AD Connect Accounts</div><div class='section-stat-value'>$MsolCount</div><div class='section-stat-note'>MSOL_/Sync_ accounts found</div></div>"
$Html += "</div>"
if ($MsolCount -gt 0) {
    $Html += "<span class='section-note-pill'>Azure AD Connect sync account(s) detected. Verify permissions and restrict interactive logon.</span>"
    $Html += "<div class='table-wrapper'><table class='user-table' id='msolTable'>
<tr>
<th onclick='sortTable(""msolTable"",0)'>Account</th>
<th onclick='sortTable(""msolTable"",1)'>Enabled</th>
<th onclick='sortTable(""msolTable"",2)'>Password Never Expires</th>
<th onclick='sortTable(""msolTable"",3)'>Last Logon</th>
</tr>"
    foreach ($m in $MsolAccounts | Sort-Object SamAccountName) {
        $mLastLogon = if ($m.LastLogonTimestamp) { [datetime]::FromFileTime($m.LastLogonTimestamp).ToString("dd/MM/yyyy") } else { "Never" }
        $mPwdClass = if ($m.PasswordNeverExpires) { "style='color:#c0392b;font-weight:600;'" } else { "" }
        $Html += "<tr>
<td><strong>$($m.SamAccountName)</strong></td>
<td>$(if($m.Enabled){'Yes'}else{'No'})</td>
<td $mPwdClass>$(if($m.PasswordNeverExpires){'Yes (verify DCSync!)'}else{'No'})</td>
<td>$mLastLogon</td>
</tr>"
    }
    $Html += "</table></div>"
}
if (-not $EntraContainerExists) {
    $Html += "<div class='baseline-empty' style='margin-top:20px;'>RegisteredDevices container not found in this domain. Hybrid Entra join is not configured or no devices have registered yet.</div>"
}
$Html += "</div></div>"

# ---------------------
# AD Trusts Container
# ---------------------
$TrustTotalCount = @($Trusts).Count
$Html += "<div class='container' id='trustsContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>AD Trusts</h2>"
$Html += "<p class='section-intro'>Active Directory trust relationships between domains and forests. Misconfigured trusts (missing SID filtering, TGT delegation) are a primary lateral movement path.</p>"
$Html += "<div class='section-stat-grid'>"
$_trustSidOff = @($Trusts | Where-Object { $_.SIDFilteringQuarantined -eq $false -or $_.SIDFilteringForestAware -eq $false }).Count
$_trustTgtOn  = @($Trusts | Where-Object { $_.TGTDelegation -eq $true }).Count
$_trustNoSelAuth = @($Trusts | Where-Object { $_.SelectiveAuthentication -eq $false }).Count
$Html += "<div class='section-stat-card card--blue'><div class='section-stat-icon'><i class='fa-solid fa-handshake'></i></div><div class='section-stat-label'>Total Trusts</div><div class='section-stat-value'>$TrustTotalCount</div><div class='section-stat-note'>All configured trust relationships</div></div>"
$Html += "<div class='section-stat-card $(if($_trustSidOff -gt 0){"card--critical"}else{"card--blue"})'><div class='section-stat-icon'><i class='fa-solid fa-filter-circle-xmark'></i></div><div class='section-stat-label'>SID Filtering Off</div><div class='section-stat-value'>$_trustSidOff</div><div class='section-stat-note'>SID injection risk</div></div>"
$Html += "<div class='section-stat-card $(if($_trustTgtOn -gt 0){"card--critical"}else{"card--gray"})'><div class='section-stat-icon'><i class='fa-solid fa-ticket'></i></div><div class='section-stat-label'>TGT Delegation On</div><div class='section-stat-value'>$_trustTgtOn</div><div class='section-stat-note'>Cross-realm ticket abuse risk</div></div>"
$Html += "<div class='section-stat-card $(if($_trustNoSelAuth -gt 0){"card--warn"}else{"card--gray"})'><div class='section-stat-icon'><i class='fa-solid fa-user-check'></i></div><div class='section-stat-label'>No Selective Auth</div><div class='section-stat-value'>$_trustNoSelAuth</div><div class='section-stat-note'>All users can auth cross-trust</div></div>"
$Html += "</div>"
if ($TrustTotalCount -eq 0) {
    $Html += "<div class='baseline-empty' style='margin-top:16px;'>No trust relationships configured in this domain.</div>"
} else {
    $Html += "<div class='table-wrapper'><table class='user-table' id='trustsTable'>"
    $Html += "<tr><th onclick='sortTable(""trustsTable"",0)'>Trust Name</th><th onclick='sortTable(""trustsTable"",1)'>Direction</th><th onclick='sortTable(""trustsTable"",2)'>Type</th><th onclick='sortTable(""trustsTable"",3)'>SID Filtering</th><th onclick='sortTable(""trustsTable"",4)'>TGT Delegation</th><th onclick='sortTable(""trustsTable"",5)'>Selective Auth</th><th>Status</th></tr>"
    foreach ($t in $Trusts) {
        $sidFilter = if ($t.SIDFilteringQuarantined -eq $true -or $t.SIDFilteringForestAware -eq $true) { 'Enabled' } elseif ($null -ne $t.SIDFilteringQuarantined -or $null -ne $t.SIDFilteringForestAware) { 'Disabled' } else { 'N/A' }
        $tgtDeleg  = if ($t.TGTDelegation -eq $true) { 'Enabled' } else { 'Disabled' }
        $selAuth   = if ($t.SelectiveAuthentication -eq $true) { 'Enabled' } else { 'Disabled' }
        $issues = @()
        if ($sidFilter -eq 'Disabled') { $issues += 'SID Filtering Off' }
        if ($tgtDeleg -eq 'Enabled')   { $issues += 'TGT Delegation' }
        if ($selAuth -eq 'Disabled')   { $issues += 'No Selective Auth' }
        $statusLabel = if ($issues.Count -eq 0) { "<span style='color:#16a34a;font-weight:700;'>OK</span>" } else { "<span style='color:#b91c1c;font-weight:700;'>$($issues -join ', ')</span>" }
        $sidStyle  = if ($sidFilter -eq 'Disabled') { "style='color:#b91c1c;font-weight:600;'" } else { "" }
        $tgtStyle  = if ($tgtDeleg -eq 'Enabled') { "style='color:#b91c1c;font-weight:600;'" } else { "" }
        $selStyle  = if ($selAuth -eq 'Disabled') { "style='color:#d97706;font-weight:600;'" } else { "" }
        $Html += "<tr><td data-no-translate='true'>$($t.Name)</td><td>$($t.TrustDirection)</td><td>$($t.TrustType)</td><td $sidStyle>$sidFilter</td><td $tgtStyle>$tgtDeleg</td><td $selStyle>$selAuth</td><td>$statusLabel</td></tr>"
    }
    $Html += "</table></div>"
}
$Html += "</div></div>"

# ---------------------
# DNS Health Container — DNS Manager style
# ---------------------
$_dnsFwdZones  = @($DnsZoneData | Where-Object { -not $_.IsReverse })
$_dnsRevZones  = @($DnsZoneData | Where-Object { $_.IsReverse })
$_dnsDsInt     = @($DnsZoneData | Where-Object { $_.IsDsIntegrated }).Count
$_dnsScavOK    = $DnsScavenging -and $DnsScavenging.ScavengingState -eq $true
$_dnsFwdIPStr  = if ($DnsForwarderIPs.Count -gt 0) { [System.Net.WebUtility]::HtmlEncode($DnsForwarderIPs -join ', ') } else { 'Not configured' }

function Get-DnsRTypeBadge($t) {
    $cls = switch ($t) {
        'A'     { 'dns-rtype-A'    } 'AAAA'  { 'dns-rtype-AAAA'  }
        'CNAME' { 'dns-rtype-CNAME'} 'MX'    { 'dns-rtype-MX'    }
        'NS'    { 'dns-rtype-NS'   } 'PTR'   { 'dns-rtype-PTR'   }
        'SRV'   { 'dns-rtype-SRV'  } 'TXT'   { 'dns-rtype-TXT'   }
        'SOA'   { 'dns-rtype-SOA'  } default { 'dns-rtype-OTHER'  }
    }
    return "<span class='dns-rtype $cls'>$t</span>"
}

function Build-DnsZoneHtml($zone, $idx, $prefix) {
    $bodyId   = "dnsZB_${prefix}_$idx"
    $ztBadge  = if ($zone.ZoneTransferSafe) { "<span class='dns-zbadge dns-zbadge-green'>Transfer OK</span>" } else { "<span class='dns-zbadge dns-zbadge-red'>Transfer Risk</span>" }
    $dsBadge  = if ($zone.IsDsIntegrated)   { "<span class='dns-zbadge dns-zbadge-blue'>AD-Integrated</span>" } else { "<span class='dns-zbadge dns-zbadge-gray'>File-based</span>" }
    $typeBadge = "<span class='dns-zbadge dns-zbadge-gray'>$($zone.ZoneType)</span>"
    $replBadge = if ($zone.ReplicationScope) { "<span class='dns-zbadge dns-zbadge-gray'>$($zone.ReplicationScope)</span>" } else { '' }
    # Zone health badge
    $zhBadge = switch ($zone.ZoneHealth) {
        'Error' { "<span class='dns-zh dns-zh-error'><i class='fa-solid fa-circle-xmark'></i> Issues</span>" }
        'Warn'  { "<span class='dns-zh dns-zh-warn'><i class='fa-solid fa-triangle-exclamation'></i> Warning</span>" }
        default { "<span class='dns-zh dns-zh-ok'><i class='fa-solid fa-circle-check'></i> Healthy</span>" }
    }
    # Record type mini breakdown
    $rtCounts = @{}
    foreach ($r in $zone.Records) { if (-not $rtCounts.ContainsKey($r.RecordType)) { $rtCounts[$r.RecordType] = 0 }; $rtCounts[$r.RecordType]++ }
    $rtStr = ($rtCounts.GetEnumerator() | Sort-Object Name | ForEach-Object { "<span class='dns-rt-chip dns-rtype-$($_.Key)'>$($_.Key) <b>$($_.Value)</b></span>" }) -join ' '

    $h  = "<div class='dns-zone-item'>"
    $h += "<div class='dns-zone-hdr' onclick='dnsToggleZone(this,""$bodyId"")'>"
    $h += "<i class='fa-solid fa-chevron-right dns-chev'></i>"
    $h += "<i class='fa-solid fa-folder dns-folder'></i>"
    $h += "<span class='dns-zone-name' data-no-translate='true'>$([System.Net.WebUtility]::HtmlEncode($zone.ZoneName))</span>"
    $h += "<span class='dns-zone-badges'>$typeBadge $dsBadge $replBadge $ztBadge $zhBadge</span>"
    $h += "<span class='dns-zone-reccount'><i class='fa-solid fa-file-lines' style='margin-right:3px;'></i>$($zone.RecordCount) records</span>"
    $h += "</div>"
    $h += "<div class='dns-zone-body' id='$bodyId' style='display:none;'>"
    # Zone issues banner (if any)
    if ($zone.ZoneIssues -and $zone.ZoneIssues.Count -gt 0) {
        $issueColor = if ($zone.ZoneHealth -eq 'Error') { '#fee2e2' } else { '#fffbeb' }
        $issueBorder = if ($zone.ZoneHealth -eq 'Error') { '#fca5a5' } else { '#fde68a' }
        $issueText = if ($zone.ZoneHealth -eq 'Error') { '#991b1b' } else { '#92400e' }
        $issueIcon = if ($zone.ZoneHealth -eq 'Error') { 'fa-circle-xmark' } else { 'fa-triangle-exclamation' }
        $h += "<div style='margin:8px 14px 0 14px;padding:7px 12px;background:$issueColor;border:1px solid $issueBorder;border-radius:6px;display:flex;gap:8px;align-items:flex-start;'>"
        $h += "<i class='fa-solid $issueIcon' style='color:$issueText;margin-top:1px;flex-shrink:0;'></i>"
        $h += "<div style='font-size:11px;color:$issueText;'>" + ($zone.ZoneIssues -join ' &nbsp;·&nbsp; ') + "</div></div>"
    }
    # Record type breakdown chips
    if ($rtStr) { $h += "<div style='padding:6px 14px 0 14px;'>$rtStr</div>" }
    $h += "<div class='dns-rec-wrap'>"
    if ($zone.Records.Count -gt 0) {
        $h += "<table class='dns-rec-table'><thead><tr><th>Name</th><th>Type</th><th>TTL</th><th>Data</th></tr></thead><tbody>"
        foreach ($r in $zone.Records | Sort-Object HostName, RecordType) {
            $h += "<tr><td data-no-translate='true' style='font-family:monospace;font-size:11px;'>$([System.Net.WebUtility]::HtmlEncode($r.HostName))</td><td>$(Get-DnsRTypeBadge $r.RecordType)</td><td style='color:#64748b;white-space:nowrap;font-size:11px;'>$($r.TTL)</td><td data-no-translate='true' style='font-family:monospace;font-size:11px;word-break:break-all;'>$([System.Net.WebUtility]::HtmlEncode([string]$r.RecordData))</td></tr>"
        }
        if ($zone.RecordCount -ge 1000) {
            $h += "<tr><td colspan='4' style='color:#94a3b8;font-style:italic;padding:8px;text-align:center;background:#f8fafc;'>Showing first 1000 of $($zone.RecordCount)+ records.</td></tr>"
        }
        $h += "</tbody></table>"
    } else {
        $h += "<div class='dns-empty'>No records returned for this zone.</div>"
    }
    $h += "</div></div></div>"
    return $h
}

$Html += "<div class='container' id='dnsHealthContainer' style='display:none;'><div class='content-card'>"
$Html += "<style>
.dns-mgr{font-size:13px;}
/* Server bar */
.dns-server-bar{display:flex;flex-wrap:wrap;gap:16px;align-items:center;padding:10px 16px;background:linear-gradient(135deg,#f0f7ff 0%,#e8f0fb 100%);border:1px solid #c7d9f0;border-radius:10px;margin-bottom:14px;font-size:12px;color:#3d5a7a;}
.dns-server-bar strong{color:#0d2a4a;font-weight:700;}
/* Group wrapper */
.dns-group{border:1px solid #d1dce8;border-radius:10px;margin:12px 0;overflow:hidden;box-shadow:0 1px 4px rgba(0,40,80,.06);}
.dns-group-hdr{display:flex;align-items:center;gap:8px;padding:9px 14px;background:#eaf1fb;border-bottom:2px solid #b6d0f0;color:#0d2a4a;font-size:12px;font-weight:700;user-select:none;}
.dns-grp-actions{margin-left:auto;display:flex;gap:6px;}
.dns-grp-actions button{padding:3px 12px;border:1px solid #b6d0f0;border-radius:5px;background:#fff;color:#1d4ed8;font-size:11px;font-weight:600;cursor:pointer;transition:background .15s;}
.dns-grp-actions button:hover{background:#dbeafe;}
/* Zone rows */
.dns-zone-item{border-bottom:1px solid #e8eef5;}
.dns-zone-item:last-child{border-bottom:none;}
.dns-zone-hdr{display:flex;align-items:center;gap:8px;padding:9px 16px;cursor:pointer;background:#fff;border-left:3px solid transparent;transition:background .12s,border-color .12s;}
.dns-zone-hdr:hover{background:#f4f8fd;border-left-color:#3b82f6;}
.dns-zone-hdr.dns-zone-open{background:#edf4ff;border-left-color:#2563eb;}
.dns-chev{font-size:10px;color:#7fa3c4;width:12px;flex-shrink:0;transition:transform .15s;}
.dns-folder{color:#f59e0b;flex-shrink:0;font-size:14px;}
.dns-zone-name{font-weight:700;color:#0d2a4a;font-size:13px;min-width:160px;}
.dns-zone-badges{margin-left:6px;display:flex;gap:4px;flex-wrap:wrap;align-items:center;}
.dns-zbadge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:10px;font-weight:700;letter-spacing:.2px;}
.dns-zbadge-blue{background:#dbeafe;color:#1d4ed8;border:1px solid #bfdbfe;}
.dns-zbadge-green{background:#dcfce7;color:#15803d;border:1px solid #bbf7d0;}
.dns-zbadge-gray{background:#f1f5f9;color:#475569;border:1px solid #e2e8f0;}
.dns-zbadge-red{background:#fee2e2;color:#b91c1c;border:1px solid #fecaca;}
.dns-zone-reccount{margin-left:auto;font-size:11px;color:#7fa3c4;white-space:nowrap;flex-shrink:0;background:#f0f7ff;padding:2px 9px;border-radius:10px;border:1px solid #c7ddf5;}
/* Zone body / record table */
.dns-zone-body{padding:0 0 0 0;background:#f8fbff;border-top:1px solid #dce8f5;}
.dns-rec-wrap{padding:12px 20px 14px 40px;}
.dns-rec-table{width:100%;border-collapse:collapse;font-size:11.5px;border:1px solid #ccd9e8;border-radius:6px;overflow:hidden;}
.dns-rec-table thead tr{background:linear-gradient(135deg,#1e3a5f 0%,#2a4f7c 100%);}
.dns-rec-table th{padding:7px 10px;color:#e2ecf9;font-weight:700;text-align:left;white-space:nowrap;border-right:1px solid rgba(255,255,255,.15);}
.dns-rec-table th:last-child{border-right:none;}
.dns-rec-table td{padding:5px 10px;border-bottom:1px solid #dce8f5;border-right:1px solid #e8f0f9;color:#1e3a5f;vertical-align:top;}
.dns-rec-table td:last-child{border-right:none;}
.dns-rec-table tbody tr:nth-child(even) td{background:#f0f6ff;}
.dns-rec-table tbody tr:last-child td{border-bottom:none;}
.dns-rec-table tbody tr:hover td{background:#dbeafe;}
/* Record type badges */
.dns-rtype{display:inline-block;padding:2px 7px;border-radius:4px;font-size:10px;font-weight:800;min-width:40px;text-align:center;letter-spacing:.3px;}
.dns-rtype-A{background:#dbeafe;color:#1e40af;border:1px solid #bfdbfe;}
.dns-rtype-AAAA{background:#ede9fe;color:#5b21b6;border:1px solid #ddd6fe;}
.dns-rtype-CNAME{background:#d1fae5;color:#065f46;border:1px solid #a7f3d0;}
.dns-rtype-MX{background:#fae8ff;color:#7e22ce;border:1px solid #f0abfc;}
.dns-rtype-NS{background:#f1f5f9;color:#334155;border:1px solid #cbd5e1;}
.dns-rtype-PTR{background:#ccfbf1;color:#134e4a;border:1px solid #99f6e4;}
.dns-rtype-SRV{background:#ffedd5;color:#c2410c;border:1px solid #fed7aa;}
.dns-rtype-TXT{background:#fef9c3;color:#854d0e;border:1px solid #fde68a;}
.dns-rtype-SOA{background:#fee2e2;color:#991b1b;border:1px solid #fecaca;}
.dns-rtype-OTHER{background:#f1f5f9;color:#64748b;border:1px solid #e2e8f0;}
/* Alerts */
.dns-alert-warn{padding:10px 16px;background:#fffbeb;border:1px solid #fde68a;border-left:4px solid #f59e0b;border-radius:8px;color:#78350f;font-size:12px;margin:8px 0;display:flex;gap:10px;align-items:flex-start;}
.dns-alert-ok{padding:10px 16px;background:#f0fdf4;border:1px solid #86efac;border-left:4px solid #22c55e;border-radius:8px;color:#14532d;font-size:12px;margin:8px 0;display:flex;gap:10px;align-items:flex-start;}
.dns-empty{padding:16px;color:#94a3b8;font-style:italic;text-align:center;}
.dns-zh{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:4px;font-size:10px;font-weight:700;}
.dns-zh-ok{background:#dcfce7;color:#166534;border:1px solid #bbf7d0;}
.dns-zh-warn{background:#fef9c3;color:#854d0e;border:1px solid #fde68a;}
.dns-zh-error{background:#fee2e2;color:#991b1b;border:1px solid #fecaca;}
.dns-rt-chip{display:inline-block;padding:2px 7px;border-radius:4px;font-size:10px;margin:1px;}
</style>"

$Html += "<h2>DNS Health</h2>"

# Health Score Card
$_scorePct = $DnsHealthScore
$_scoreFactors = @()
if (-not $_dnsScavOK)                              { $_scoreFactors += "<span style='color:#b91c1c;'><i class='fa-solid fa-circle-xmark'></i> Scavenging disabled (-25)</span>" }
else                                               { $_scoreFactors += "<span style='color:#16a34a;'><i class='fa-solid fa-circle-check'></i> Scavenging enabled</span>" }
if ($DnsZoneTransferRisk -gt 0)                    { $_scoreFactors += "<span style='color:#b91c1c;'><i class='fa-solid fa-circle-xmark'></i> $DnsZoneTransferRisk risky zone transfer(s) (-$([math]::Min($DnsZoneTransferRisk*10,30)))</span>" }
else                                               { $_scoreFactors += "<span style='color:#16a34a;'><i class='fa-solid fa-circle-check'></i> Zone transfers secure</span>" }
if ($DnsAdminCount -gt 0)                          { $_scoreFactors += "<span style='color:#d97706;'><i class='fa-solid fa-triangle-exclamation'></i> DnsAdmins: $DnsAdminCount member(s)</span>" }
else                                               { $_scoreFactors += "<span style='color:#16a34a;'><i class='fa-solid fa-circle-check'></i> DnsAdmins empty</span>" }
$_unreachFwd = @($DnsForwarderStatus | Where-Object { -not $_.Reachable })
if ($_unreachFwd.Count -gt 0)                      { $_scoreFactors += "<span style='color:#b91c1c;'><i class='fa-solid fa-circle-xmark'></i> $($_unreachFwd.Count) forwarder(s) unreachable (-10)</span>" }
elseif ($DnsForwarderIPs.Count -gt 0)              { $_scoreFactors += "<span style='color:#16a34a;'><i class='fa-solid fa-circle-check'></i> Forwarders reachable</span>" }
else                                               { $_scoreFactors += "<span style='color:#64748b;'><i class='fa-solid fa-minus-circle'></i> No forwarders configured (-5)</span>" }
$_zoneWarn  = @($DnsZoneData | Where-Object { $_.ZoneHealth -eq 'Warn'  }).Count
$_zoneError = @($DnsZoneData | Where-Object { $_.ZoneHealth -eq 'Error' }).Count
if ($_zoneError -gt 0)                             { $_scoreFactors += "<span style='color:#b91c1c;'><i class='fa-solid fa-circle-xmark'></i> $_zoneError zone(s) with errors</span>" }
if ($_zoneWarn  -gt 0)                             { $_scoreFactors += "<span style='color:#d97706;'><i class='fa-solid fa-triangle-exclamation'></i> $_zoneWarn zone(s) with warnings</span>" }
if ($_zoneError -eq 0 -and $_zoneWarn -eq 0)       { $_scoreFactors += "<span style='color:#16a34a;'><i class='fa-solid fa-circle-check'></i> All zones healthy</span>" }

$Html += "<div style='background:$DnsHealthBg;border:1px solid $DnsHealthBorder;border-left:4px solid $DnsHealthColor;border-radius:10px;padding:16px 20px;margin:12px 0;display:flex;gap:24px;align-items:center;flex-wrap:wrap;'>"
# Grade circle
$Html += "<div style='width:72px;height:72px;border-radius:50%;background:$DnsHealthColor;display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 2px 8px rgba(0,0,0,.15);'>"
$Html += "<span style='font-size:28px;font-weight:900;color:#fff;line-height:1;'>$DnsHealthGrade</span>"
$Html += "<span style='font-size:11px;color:rgba(255,255,255,.85);font-weight:600;'>$DnsHealthScore/100</span>"
$Html += "</div>"
# Score bar + label
$Html += "<div style='flex:1;min-width:180px;'>"
$Html += "<div style='font-size:12px;font-weight:700;color:#0f2f4f;margin-bottom:6px;'>DNS Health Score</div>"
$Html += "<div style='background:#e2e8f0;border-radius:6px;height:10px;overflow:hidden;'><div style='width:$_scorePct%;height:100%;background:$DnsHealthColor;border-radius:6px;transition:width .6s;'></div></div>"
$Html += "<div style='font-size:11px;color:#64748b;margin-top:4px;'>$_scorePct / 100 — Grade: $DnsHealthGrade</div>"
$Html += "</div>"
# Factors list
$Html += "<div style='display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:4px 20px;font-size:12px;flex:2;min-width:260px;'>"
foreach ($f in $_scoreFactors) { $Html += "<div>$f</div>" }
$Html += "</div>"
$Html += "</div>"

# Server info bar (no scavenging here anymore)
$Html += "<div class='dns-server-bar dns-mgr'>"
$Html += "<span><i class='fa-solid fa-server' style='margin-right:5px;color:#526980;'></i>DNS Server: <strong data-no-translate='true'>$DnsServerName</strong></span>"
$Html += "<span style='color:#cbd5e1;'>|</span><span>Domain: <strong data-no-translate='true'>$Domain</strong></span>"
$Html += "<span style='color:#cbd5e1;'>|</span><span>Forwarders: <strong data-no-translate='true'>$_dnsFwdIPStr</strong></span>"
$Html += "</div>"

# Summary cards + Scavenging card side by side
$Html += "<div class='section-stat-grid'>"
$Html += "<div class='section-stat-card card--blue'><div class='section-stat-icon'><i class='fa-solid fa-globe'></i></div><div class='section-stat-label'>Total Zones</div><div class='section-stat-value'>$(@($DnsZoneData).Count)</div><div class='section-stat-note'>Primary + Secondary</div></div>"
$Html += "<div class='section-stat-card card--blue'><div class='section-stat-icon'><i class='fa-solid fa-arrow-right'></i></div><div class='section-stat-label'>Forward Zones</div><div class='section-stat-value'>$($_dnsFwdZones.Count)</div><div class='section-stat-note'>Name → IP lookup</div></div>"
$Html += "<div class='section-stat-card card--blue'><div class='section-stat-icon'><i class='fa-solid fa-arrow-left'></i></div><div class='section-stat-label'>Reverse Zones</div><div class='section-stat-value'>$($_dnsRevZones.Count)</div><div class='section-stat-note'>IP → Name lookup</div></div>"
$Html += "<div class='section-stat-card $(if($DnsZoneTransferRisk -gt 0){"card--critical"}elseif($DnsAdminCount -gt 0){"card--warn"}else{"card--gray"})'><div class='section-stat-icon'><i class='fa-solid fa-triangle-exclamation'></i></div><div class='section-stat-label'>Risk Items</div><div class='section-stat-value'>$($DnsZoneTransferRisk + $DnsAdminCount)</div><div class='section-stat-note'>Transfer risks + DnsAdmins</div></div>"
$Html += "</div>"

# Scavenging dedicated card
if ($DnsScavenging) {
    $_scavColor  = if ($_dnsScavOK) { '#16a34a' } else { '#b91c1c' }
    $_scavBg     = if ($_dnsScavOK) { '#f0fdf4' } else { '#fff1f2' }
    $_scavBorder = if ($_dnsScavOK) { '#86efac' } else { '#fecaca' }
    $_scavIcon   = if ($_dnsScavOK) { 'fa-circle-check' } else { 'fa-circle-xmark' }
    $_scavLabel  = if ($_dnsScavOK) { 'Enabled' } else { 'Disabled' }
    $_scavTip    = if ($_dnsScavOK) { "Stale records are cleaned automatically." } else { "Stale records accumulate. Enable scavenging in DNS Manager → Server Properties → Advanced." }

    $Html += "<div style='background:$_scavBg;border:1px solid $_scavBorder;border-left:4px solid $_scavColor;border-radius:10px;padding:14px 18px;margin:10px 0;display:flex;gap:18px;align-items:center;flex-wrap:wrap;'>"

    # Status badge
    $Html += "<div style='display:flex;align-items:center;gap:10px;min-width:160px;'>"
    $Html += "<i class='fa-solid $_scavIcon' style='font-size:28px;color:$_scavColor;flex-shrink:0;'></i>"
    $Html += "<div><div style='font-size:11px;font-weight:600;color:#64748b;letter-spacing:.5px;text-transform:uppercase;'>DNS Scavenging</div><div style='font-size:22px;font-weight:800;color:$_scavColor;line-height:1.1;'>$_scavLabel</div></div>"
    $Html += "</div>"

    # Interval details — only show when enabled
    if ($_dnsScavOK) {
        $_scavInt  = if ($DnsScavenging.ScavengingInterval  -and [int]$DnsScavenging.ScavengingInterval.TotalHours  -gt 0) { "$([int]$DnsScavenging.ScavengingInterval.TotalHours)h"  } else { 'Not set' }
        $_noRefInt = if ($DnsScavenging.NoRefreshInterval   -and [int]$DnsScavenging.NoRefreshInterval.TotalHours   -gt 0) { "$([int]$DnsScavenging.NoRefreshInterval.TotalHours)h"   } else { 'Not set' }
        $_refInt   = if ($DnsScavenging.RefreshInterval     -and [int]$DnsScavenging.RefreshInterval.TotalHours     -gt 0) { "$([int]$DnsScavenging.RefreshInterval.TotalHours)h"     } else { 'Not set' }

        # Last scavenge time
        $_lastScav = 'Never'
        try {
            if ($DnsScavenging.LastScavengeTime -and $DnsScavenging.LastScavengeTime -gt [datetime]'2000-01-01') {
                $_lastScav = $DnsScavenging.LastScavengeTime.ToString('yyyy-MM-dd HH:mm')
            }
        } catch {}

        $Html += "<div style='display:flex;gap:20px;flex-wrap:wrap;align-items:center;border-left:1px solid $_scavBorder;padding-left:18px;'>"
        $Html += "<div style='text-align:center;'><div style='font-size:18px;font-weight:800;color:#0f2f4f;'>$_noRefInt</div><div style='font-size:10px;color:#64748b;font-weight:600;'>No-Refresh Interval</div></div>"
        $Html += "<div style='text-align:center;'><div style='font-size:18px;font-weight:800;color:#0f2f4f;'>$_refInt</div><div style='font-size:10px;color:#64748b;font-weight:600;'>Refresh Interval</div></div>"
        $Html += "<div style='text-align:center;'><div style='font-size:18px;font-weight:800;color:#0f2f4f;'>$_scavInt</div><div style='font-size:10px;color:#64748b;font-weight:600;'>Scavenge Interval</div></div>"
        $Html += "<div style='text-align:center;border-left:1px solid $_scavBorder;padding-left:18px;'><div style='font-size:13px;font-weight:700;color:#0f2f4f;white-space:nowrap;' data-no-translate='true'>$_lastScav</div><div style='font-size:10px;color:#64748b;font-weight:600;'>Last Scavenge</div></div>"
        $Html += "</div>"
    }

    $Html += "<div style='flex:1;min-width:180px;font-size:12px;color:#374151;'>$_scavTip</div>"
    $Html += "</div>"
}

# DnsAdmins warning
if ($DnsAdminCount -gt 0) {
    $daNames = [System.Net.WebUtility]::HtmlEncode(($DnsAdmins | Select-Object -First 5 | ForEach-Object { [string]$_.SamAccountName }) -join ', ')
    $Html += "<div class='dns-alert-warn'><i class='fa-solid fa-user-tie' style='margin-top:1px;'></i><div><strong>DnsAdmins has $DnsAdminCount member(s): </strong><span data-no-translate='true'>$daNames</span>$(if($DnsAdminCount -gt 5){" and $($DnsAdminCount-5) more"}). Members can load a malicious DLL into dns.exe (runs as SYSTEM). Remove non-essential accounts.</div></div>"
}

$Html += "<div class='dns-mgr'>"

# Forward Lookup Zones
$Html += "<div class='dns-group'>"
$Html += "<div class='dns-group-hdr'><i class='fa-solid fa-folder-open'></i><span style='margin-left:4px;'>Forward Lookup Zones</span><span style='margin-left:8px;padding:1px 9px;border-radius:3px;background:rgba(255,255,255,0.18);font-size:11px;'>$($_dnsFwdZones.Count)</span><div class='dns-grp-actions'><button onclick='dnsGroupExpandAll(""dnsFwdGroup"")'>Expand All</button><button onclick='dnsGroupCollapseAll(""dnsFwdGroup"")'>Collapse All</button></div></div>"
$Html += "<div id='dnsFwdGroup'>"
if ($_dnsFwdZones.Count -eq 0) {
    $Html += "<div class='dns-empty'>No forward lookup zones found.</div>"
} else {
    $_fi = 0
    foreach ($z in $_dnsFwdZones | Sort-Object ZoneName) {
        $Html += Build-DnsZoneHtml $z $_fi 'fwd'
        $_fi++
    }
}
$Html += "</div></div>"

# Reverse Lookup Zones
$Html += "<div class='dns-group'>"
$Html += "<div class='dns-group-hdr'><i class='fa-solid fa-folder-open'></i><span style='margin-left:4px;'>Reverse Lookup Zones</span><span style='margin-left:8px;padding:1px 9px;border-radius:3px;background:rgba(255,255,255,0.18);font-size:11px;'>$($_dnsRevZones.Count)</span><div class='dns-grp-actions'><button onclick='dnsGroupExpandAll(""dnsRevGroup"")'>Expand All</button><button onclick='dnsGroupCollapseAll(""dnsRevGroup"")'>Collapse All</button></div></div>"
$Html += "<div id='dnsRevGroup'>"
if ($_dnsRevZones.Count -eq 0) {
    $Html += "<div class='dns-empty'>No reverse lookup zones found.</div>"
} else {
    $_ri = 0
    foreach ($z in $_dnsRevZones | Sort-Object ZoneName) {
        $Html += Build-DnsZoneHtml $z $_ri 'rev'
        $_ri++
    }
}
$Html += "</div></div>"

# Conditional Forwarders / Root Hints
$Html += "<div class='dns-group'>"
$Html += "<div class='dns-group-hdr'><i class='fa-solid fa-forward'></i><span style='margin-left:4px;'>Conditional Forwarders</span></div>"
if ($DnsForwarderStatus.Count -gt 0) {
    $Html += "<div style='padding:12px 16px;display:flex;flex-wrap:wrap;gap:10px;align-items:center;'>"
    foreach ($fs in $DnsForwarderStatus) {
        $fBg     = if ($fs.Reachable) { '#f0fdf4' } else { '#fff1f2' }
        $fBorder = if ($fs.Reachable) { '#86efac' } else { '#fca5a5' }
        $fColor  = if ($fs.Reachable) { '#15803d' } else { '#b91c1c' }
        $fIcon   = if ($fs.Reachable) { 'fa-circle-check' } else { 'fa-circle-xmark' }
        $fLabel  = if ($fs.Reachable) { 'Reachable' } else { 'Unreachable' }
        $Html += "<div style='display:flex;align-items:center;gap:8px;padding:8px 14px;background:$fBg;border:1px solid $fBorder;border-radius:8px;'>"
        $Html += "<i class='fa-solid $fIcon' style='color:$fColor;font-size:16px;'></i>"
        $Html += "<div><div style='font-size:13px;font-weight:700;font-family:monospace;color:#0f2f4f;' data-no-translate='true'>$($fs.IP)</div><div style='font-size:10px;font-weight:600;color:$fColor;'>$fLabel</div></div>"
        $Html += "</div>"
    }
    $Html += "</div>"
} elseif ($DnsForwarderIPs.Count -gt 0) {
    $Html += "<div style='padding:10px 14px;display:flex;flex-wrap:wrap;gap:8px;'>"
    foreach ($ip in $DnsForwarderIPs) {
        $Html += "<span style='padding:4px 14px;background:#dbeafe;color:#1d4ed8;border-radius:20px;font-size:12px;font-weight:700;font-family:monospace;' data-no-translate='true'>$ip</span>"
    }
    $Html += "</div>"
} else {
    $Html += "<div class='dns-empty'>No conditional forwarders configured. Using root hints for external resolution.</div>"
}
$Html += "</div>"

$Html += "</div>" # dns-mgr close

$Html += "<script>
function dnsToggleZone(hdr,bodyId){
  var b=document.getElementById(bodyId); if(!b)return;
  var isOpen=b.style.display!=='none';
  b.style.display=isOpen?'none':'';
  hdr.classList.toggle('dns-zone-open',!isOpen);
  var c=hdr.querySelector('.dns-chev'),f=hdr.querySelector('.dns-folder');
  if(c)c.className='fa-solid '+(isOpen?'fa-chevron-right':'fa-chevron-down')+' dns-chev';
  if(f)f.className='fa-solid '+(isOpen?'fa-folder':'fa-folder-open')+' dns-folder';
}
function dnsGroupExpandAll(gid){
  var g=document.getElementById(gid);if(!g)return;
  g.querySelectorAll('.dns-zone-body').forEach(function(b){b.style.display='';});
  g.querySelectorAll('.dns-zone-hdr').forEach(function(h){h.classList.add('dns-zone-open');});
  g.querySelectorAll('.dns-chev').forEach(function(i){i.className='fa-solid fa-chevron-down dns-chev';});
  g.querySelectorAll('.dns-folder').forEach(function(i){i.className='fa-solid fa-folder-open dns-folder';});
}
function dnsGroupCollapseAll(gid){
  var g=document.getElementById(gid);if(!g)return;
  g.querySelectorAll('.dns-zone-body').forEach(function(b){b.style.display='none';});
  g.querySelectorAll('.dns-zone-hdr').forEach(function(h){h.classList.remove('dns-zone-open');});
  g.querySelectorAll('.dns-chev').forEach(function(i){i.className='fa-solid fa-chevron-right dns-chev';});
  g.querySelectorAll('.dns-folder').forEach(function(i){i.className='fa-solid fa-folder dns-folder';});
}
</script>"

$Html += "</div></div>"

# ---------------------
# ADCS / PKI Health Container
# ---------------------
$_adcsScoreColor  = if ($AdcsHealthScore -ge 80){'#16a34a'}elseif($AdcsHealthScore -ge 60){'#d97706'}elseif($AdcsHealthScore -ge 40){'#ea580c'}else{'#dc2626'}
$_adcsScoreBg     = if ($AdcsHealthScore -ge 80){'#f0fdf4'}elseif($AdcsHealthScore -ge 60){'#fffbeb'}elseif($AdcsHealthScore -ge 40){'#fff7ed'}else{'#fff1f2'}
$_adcsScoreBorder = if ($AdcsHealthScore -ge 80){'#86efac'}elseif($AdcsHealthScore -ge 60){'#fde68a'}elseif($AdcsHealthScore -ge 40){'#fdba74'}else{'#fca5a5'}
$_adcsGrade = if($AdcsHealthScore -ge 90){'A'}elseif($AdcsHealthScore -ge 75){'B'}elseif($AdcsHealthScore -ge 60){'C'}elseif($AdcsHealthScore -ge 40){'D'}else{'F'}

$Html += "<div class='container' id='adcsContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>Certificate Security</h2>"
$Html += "<p class='section-intro'>Checks the domain's certificate infrastructure: whether certificate servers (CA) are healthy, and whether certificate templates are configured in a way that could allow a regular user to obtain admin-level access.</p>"

if (-not $AdcsInstalled) {
    $Html += "<div style='text-align:center;padding:40px 20px;'><i class='fa-solid fa-certificate' style='font-size:40px;color:#94a3b8;display:block;margin-bottom:12px;'></i><p style='color:#526980;'>No certificate server (CA) was found in this domain. If certificates are managed externally or on a standalone server not joined to AD, this section will not show data.</p></div>"
} else {
    # Health score + stat cards
    $Html += "<div style='display:flex;align-items:flex-start;gap:16px;flex-wrap:wrap;margin-bottom:16px;'>"
    $Html += "<div style='border:2px solid $_adcsScoreBorder;border-radius:12px;background:$_adcsScoreBg;padding:16px 22px;min-width:130px;text-align:center;flex-shrink:0;'>"
    $Html += "<div style='font-size:36px;font-weight:900;color:$_adcsScoreColor;line-height:1;'>$AdcsHealthScore</div>"
    $Html += "<div style='font-size:11px;color:#526980;margin-top:4px;'>Security Score</div>"
    $Html += "<div style='font-size:22px;font-weight:800;color:$_adcsScoreColor;margin-top:2px;'>$_adcsGrade</div>"
    $Html += "</div>"
    $Html += "<div class='section-stat-grid' style='flex:1;margin:0;'>"
    $_caOkCount  = @($AdcsCAs | Where-Object { $_.Reachable }).Count
    $_esc6Count  = @($AdcsCAs | Where-Object { $_.Esc6Risk  }).Count
    $_esc8Count  = @($AdcsCAs | Where-Object { $_.WebEnroll }).Count
    $_riskTmpl   = @($AdcsTemplates | Where-Object { $_.IsRisky }).Count
    $_caCard  = if ($_caOkCount -lt $AdcsCAs.Count){'card--critical'}elseif($AdcsCAs.Count -gt 0){'card--green'}else{'card--gray'}
    $_escCard = if ($AdcsEscCount -gt 0){'card--critical'}else{'card--green'}
    $_e6Card  = if ($_esc6Count -gt 0){'card--critical'}else{'card--green'}
    $Html += "<div class='section-stat-card $_caCard'><div class='section-stat-icon'><i class='fa-solid fa-building-columns'></i></div><div class='section-stat-label'>Certificate Servers</div><div class='section-stat-value'>$_caOkCount / $($AdcsCAs.Count)</div><div class='section-stat-note'>$(if($_caOkCount -lt $AdcsCAs.Count){"Server unreachable!"}else{"All servers online"})</div></div>"
    $Html += "<div class='section-stat-card $_escCard'><div class='section-stat-icon'><i class='fa-solid fa-triangle-exclamation'></i></div><div class='section-stat-label'>Security Vulnerabilities</div><div class='section-stat-value'>$AdcsEscCount</div><div class='section-stat-note'>$(if($AdcsEscCount -gt 0){"Critical — can lead to admin takeover"}else{"No vulnerabilities found"})</div></div>"
    $Html += "<div class='section-stat-card $_e6Card'><div class='section-stat-icon'><i class='fa-solid fa-sliders'></i></div><div class='section-stat-label'>Unsafe Server Config</div><div class='section-stat-value'>$_esc6Count</div><div class='section-stat-note'>$(if($_esc6Count -gt 0){"Server misconfiguration detected"}else{"Server config is safe"})</div></div>"
    $_tmplCard = if ($_riskTmpl -gt 0){'card--critical'}elseif($AdcsTemplates.Count -gt 0){'card--green'}else{'card--gray'}
    $Html += "<div class='section-stat-card $_tmplCard'><div class='section-stat-icon'><i class='fa-solid fa-file-certificate'></i></div><div class='section-stat-label'>Risky Certificate Types</div><div class='section-stat-value'>$_riskTmpl / $($AdcsTemplates.Count)</div><div class='section-stat-note'>$(if($_riskTmpl -gt 0){"Can be abused to gain admin access"}else{"All certificate types safe"})</div></div>"
    $Html += "</div></div>"

    # CA table
    if ($AdcsCAs.Count -gt 0) {
        $Html += "<h3 style='margin:16px 0 6px 0;font-size:14px;color:#0f2f4f;'>Certificate Servers</h3>"
        $Html += "<div class='table-wrapper'><table class='user-table' id='adcsCaTable'>"
        $Html += "<tr><th>Server Name</th><th>Host</th><th>Location</th><th>Service</th><th>Server Config Risk</th><th>Web Access Risk (ESC8)</th></tr>"
        foreach ($ca in $AdcsCAs) {
            $_locCell = if ($ca.IsLocal) {
                "<span style='background:#dbeafe;color:#1d4ed8;padding:2px 7px;border-radius:4px;font-size:11px;font-weight:600;'>This DC</span>"
            } else {
                "<span style='background:#f1f5f9;color:#475569;padding:2px 7px;border-radius:4px;font-size:11px;'>Remote</span>"
            }
            $_svcCell = switch ($ca.SvcStatus) {
                'Running'      { "<span style='color:#16a34a;font-weight:700;'>Running</span>" }
                'Stopped'      { "<span style='color:#dc2626;font-weight:700;'>Stopped</span>" }
                'Check failed' { "<span style='color:#d97706;'>Check failed</span>" }
                default        { "<span style='color:#94a3b8;'>$([System.Net.WebUtility]::HtmlEncode($ca.SvcStatus))</span>" }
            }
            $_esc6Cell = if (-not $ca.Esc6Checked) {
                "<span style='color:#94a3b8;font-size:11px;'>N/A</span>"
            } elseif ($ca.Esc6Risk) {
                "<span style='background:#fee2e2;color:#b91c1c;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:700;'>ESC6 Risk</span>"
            } else {
                "<span style='color:#16a34a;'>Clean</span>"
            }
            $_esc8Cell = if ($ca.WebEnroll) {
                "<span style='background:#fff3cd;color:#92400e;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:700;'>Port 80 Open</span>"
            } else {
                "<span style='color:#16a34a;'>Not detected</span>"
            }
            $_rowBg = if (-not $ca.IsHealthy) { " style='background:#fff1f2;'" } else { "" }
            $Html += "<tr$_rowBg><td data-no-translate='true'><strong>$([System.Net.WebUtility]::HtmlEncode($ca.Name))</strong></td>"
            $Html += "<td data-no-translate='true' style='font-family:monospace;font-size:11px;'>$([System.Net.WebUtility]::HtmlEncode($ca.DNSHost))</td>"
            $Html += "<td>$_locCell</td><td>$_svcCell</td><td>$_esc6Cell</td><td>$_esc8Cell</td></tr>"
        }
        $Html += "</table></div>"
        if ($_esc6Count -gt 0) {
            $Html += "<div style='margin:8px 0;padding:10px 14px;border:1px solid #fca5a5;border-radius:8px;background:#fef2f2;color:#7f1d1d;'><strong><i class='fa-solid fa-triangle-exclamation' style='margin-right:6px;'></i>Server misconfiguration detected on $($_esc6Count) certificate server(s).</strong> This setting allows any certificate type to be used to impersonate any user in the domain, including administrators. A technical engineer should disable this flag: <code style='font-size:11px;'>certutil -config &lt;CA&gt; -setreg policy\EditFlags -EDITF_ATTRIBUTESUBJECTALTNAME2</code></div>"
        }
        if ($_esc8Count -gt 0) {
            $Html += "<div style='margin:8px 0;padding:10px 14px;border:1px solid #fde68a;border-radius:8px;background:#fffbeb;color:#78350f;'><strong><i class='fa-solid fa-globe' style='margin-right:6px;'></i>Web access to certificate server detected ($($_esc8Count) server(s)).</strong> The certificate server is accessible over HTTP, which can be exploited to steal credentials. HTTPS should be enforced, or web access disabled if not in use.</div>"
        }
    }

    # Template table
    if ($AdcsTemplates.Count -gt 0) {
        $Html += "<h3 style='margin:18px 0 6px 0;font-size:14px;color:#0f2f4f;'>Certificate Types</h3>"
        $Html += "<p style='font-size:12px;color:#526980;margin:0 0 8px 0;'>Each row is a certificate type (template). A risky type is one where a regular domain user could request a certificate that grants them admin-level access.</p>"
        $Html += "<div class='table-wrapper'><table class='user-table' id='adcsTmplTable'>"
        $Html += "<tr><th onclick='sortTable(""adcsTmplTable"",0)'>Certificate Type</th><th>Risk Level</th><th>Can Log In As User</th><th>Anyone Can Request</th><th>Requires Approval</th></tr>"
        $sortedTmpls = $AdcsTemplates | Sort-Object { $_.EscFindings.Count } -Descending
        foreach ($t in $sortedTmpls) {
            $_escLabels = @{ 'ESC1'='Identity forgery risk'; 'ESC2'='Unrestricted use risk'; 'ESC3'='Delegation abuse risk' }
            $_escBadges = ($t.EscFindings | ForEach-Object { $lbl = if($_escLabels[$_]){$_escLabels[$_]}else{$_}; "<span style='display:inline-block;margin-right:3px;padding:2px 7px;border-radius:4px;font-size:11px;font-weight:700;background:#fee2e2;color:#b91c1c;' title='$_'>$lbl</span>" }) -join ''
            if (-not $_escBadges) { $_escBadges = "<span style='color:#16a34a;font-size:11px;'>Safe</span>" }
            $_caAuth  = if ($t.HasClientAuth) {"<i class='fa-solid fa-check' style='color:#d97706;'></i>"} else {"<i class='fa-solid fa-minus' style='color:#94a3b8;'></i>"}
            $_lpEnr   = if ($t.LowPrivCanEnroll)  {"<i class='fa-solid fa-check' style='color:$(if($t.IsRisky){"#dc2626"}else{"#d97706"});'></i>"} else {"<i class='fa-solid fa-minus' style='color:#94a3b8;'></i>"}
            $_approv  = if ($t.RequiresApproval)  {"<i class='fa-solid fa-check' style='color:#16a34a;'></i>"} else {"<i class='fa-solid fa-minus' style='color:#94a3b8;'></i>"}
            $_rowStyle = if ($t.IsRisky) { " style='background:#fff1f2;'" } else { "" }
            $Html += "<tr$_rowStyle><td data-no-translate='true'><strong>$([System.Net.WebUtility]::HtmlEncode($t.Name))</strong>"
            if ($t.DisplayName -and $t.DisplayName -ne $t.Name) { $Html += "<br><span style='font-size:10px;color:#526980;' data-no-translate='true'>$([System.Net.WebUtility]::HtmlEncode($t.DisplayName))</span>" }
            $Html += "</td><td>$_escBadges</td><td>$_caAuth</td><td>$_lpEnr</td><td>$_approv</td></tr>"
        }
        $Html += "</table></div>"
    }

    if ($AdcsEscCount -eq 0) {
        $Html += "<div style='margin:12px 0 0 0;padding:10px 14px;border:1px solid #86efac;border-radius:8px;background:#f0fdf4;color:#14532d;'><strong><i class='fa-solid fa-circle-check' style='margin-right:6px;'></i>No certificate security vulnerabilities found.</strong> All certificate types and server configurations appear safe. Review again after any new certificate type is added.</div>"
    }
}
$Html += "</div></div>"

# ---------------------
# ---------------------
# Password Expiry Container (Shortened)
# ---------------------
$PwdExpiredCount = @($PwdExpiry | Where-Object { $_.PasswordExpiryDate -like 'Expired*' }).Count
$PwdNoExpiryCount = @($Users | Where-Object { $_.PasswordNeverExpires -eq $true }).Count
$PwdDueSoonCount = @(
    $PwdExpiry | Where-Object {
        $dateRaw = [string]$_.PasswordExpiryDate
        if ([string]::IsNullOrWhiteSpace($dateRaw)) { return $false }
        if ($dateRaw -eq 'N/A' -or $dateRaw -like 'Expired*') { return $false }
        $parsed = [datetime]::MinValue
        if (-not [datetime]::TryParseExact($dateRaw, 'dd/MM/yyyy', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$parsed)) { return $false }
        return ($parsed -ge (Get-Date).Date -and $parsed -le (Get-Date).Date.AddDays(7))
    }
).Count

$Html += "<div class='container' id='pwdExpiryContainer' style='display:none;'><div class='content-card'>" 
$Html += "<h2>Password Expiry</h2>"
$Html += "<p class='section-intro'>Password lifecycle view for outage prevention and policy hygiene.</p>"
$Html += "<div class='section-stat-grid'>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Expired</div><div class='section-stat-value'>$PwdExpiredCount</div><div class='section-stat-note'>Action required</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Due in 7 Days</div><div class='section-stat-value'>$PwdDueSoonCount</div><div class='section-stat-note'>Notify before lockout</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Never Expires</div><div class='section-stat-value'>$PwdNoExpiryCount</div><div class='section-stat-note'>Policy exception count</div></div>"
$Html += "</div>"
$Html += "<span class='section-note-pill'>Focus first on expired users with business-critical roles.</span><div class='table-wrapper'>"
$Html += "<table class='user-table' id='pwdExpiryTable'><tr>
<th onclick='sortTable(""pwdExpiryTable"",0)'>User Name</th>
<th onclick='sortTable(""pwdExpiryTable"",1)'>Password Last Set</th>
<th onclick='sortTable(""pwdExpiryTable"",2)'>Password Expiry Date</th>
<th onclick='sortTable(""pwdExpiryTable"",3)'>Enabled</th>
<th onclick='sortTable(""pwdExpiryTable"",4)'>Privileged</th>
</tr>"
foreach ($p in $PwdExpiry | Sort Name) {
    $RowClass = if ($p.PasswordExpiryDate -like "Expired*") { "class='expired-row'" } else { "" }
    $AdminClass = if ($p.IsAdmin -eq 'Admin') { " style='color:#b91c1c;font-weight:600;'" } else { "" }
    $Html += "<tr $RowClass><td>$($p.Name)</td><td>$($p.PasswordLastSet)</td><td>$($p.PasswordExpiryDate)</td><td>$($p.Enabled)</td><td$AdminClass>$($p.IsAdmin)</td></tr>"
}
$Html += "</table></div></div></div>"

# ---------------------
# Skipped / Unreachable DC Summary
# ---------------------
$SkippedRows = @($SkippedDCs)
$Html += "<div class='container' id='skippedDcsContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>Skipped / Unreachable DCs</h2>"
if ($SkippedRows.Count -gt 0) {
    $Html += "<div style='margin:8px 0 12px 0;padding:10px 12px;border:1px solid #ffe082;border-radius:8px;background:#fff8e1;color:#7a5d00;font-weight:700;'>Warning: $($SkippedRows.Count) control(s) could not be fully evaluated due to unreachable/failed remote checks.</div>"
} else {
    $Html += "<p class='section-intro'>No skipped or unreachable DC/CA control execution detected.</p>"
}
$Html += "<div class='table-wrapper'><table class='user-table' id='skippedDcsTable'><tr><th onclick='sortTable(""skippedDcsTable"",0)'>Host</th><th onclick='sortTable(""skippedDcsTable"",1)'>Section</th><th onclick='sortTable(""skippedDcsTable"",2)'>Reason</th></tr>"
if ($SkippedRows.Count -eq 0) {
    $Html += "<tr><td colspan='3'>No skipped host record.</td></tr>"
} else {
    foreach ($s in $SkippedRows | Select-Object -First 500) {
        $reasonSafe = [System.Net.WebUtility]::HtmlEncode([string]$s.Reason)
        $Html += "<tr><td>$([string]$s.DC)</td><td>$([string]$s.Section)</td><td>$reasonSafe</td></tr>"
    }
}
$Html += "</table></div></div></div>"

# ---------------------
# Group Policy Check Container
# ---------------------
$Html += "<div class='container' id='gpoInventoryContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>Group Policy Check</h2>"
$Html += "<p class='section-intro'>GPO inventory, OU linkage map and hygiene analysis. Orphaned = not linked to any OU. Empty = no computer or user settings configured.</p>"

# Summary cards
$Html += "<div class='section-stat-grid'>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Total GPOs</div><div class='section-stat-value'>$GpoTotalCount</div><div class='section-stat-note'>All policies in domain</div></div>"
$GpoOrphanedColor = if ($GpoOrphanedCount -gt 0) { "color:#b91c1c;font-weight:700;" } else { "" }
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Orphaned (Not Linked)</div><div class='section-stat-value' style='$GpoOrphanedColor'>$GpoOrphanedCount</div><div class='section-stat-note'>Linked to no OU</div></div>"
$GpoEmptyColor = if ($GpoEmptyCount -gt 0) { "color:#d97706;font-weight:700;" } else { "" }
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Empty (No Settings)</div><div class='section-stat-value' style='$GpoEmptyColor'>$GpoEmptyCount</div><div class='section-stat-note'>No comp/user settings</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>All Settings Disabled</div><div class='section-stat-value'>$GpoDisabledCount</div><div class='section-stat-note'>AllSettingsDisabled status</div></div>"
$Html += "</div>"

if (-not $GPOModuleAvailable) {
    $ErrMsg = if ($GPOCollectError) { [System.Net.WebUtility]::HtmlEncode($GPOCollectError) } else { "GroupPolicy module not available on this system." }
    $Html += "<div style='margin:12px 0;padding:10px 14px;border:1px solid #ffe082;border-radius:8px;background:#fff8e1;color:#7a5d00;font-weight:600;'>Group Policy module unavailable: $ErrMsg</div>"
} else {

    # ---- OU Map & Effective GPO Calculator ----
    $_OuCalcHtml  = "<script>var OuTreeData=$OuTreeDataJson;var GpoSettingsIndex=$GpoSettingsIndexJson;</script>"
    $_OuCalcHtml += @'
<h3 style="margin:20px 0 4px 0;font-size:15px;color:#0f2f4f;">OU Hierarchy &amp; Effective GPO Calculator</h3>
<p class="section-intro">Click an OU to see its effective GPO stack — inheritance, Block Inheritance cutoffs, and Enforced links are all calculated automatically.</p>
<div style="display:flex;gap:10px;margin:10px 0 24px 0;min-height:360px;">

  <!-- LEFT: OU Tree -->
  <div style="flex:0 0 270px;border:1px solid #d0dce9;border-radius:8px;background:#fff;display:flex;flex-direction:column;">
    <div style="padding:7px 10px 5px 10px;border-bottom:1px solid #e9f0f7;font-size:11px;font-weight:700;color:#4b6880;letter-spacing:.04em;display:flex;align-items:center;gap:6px;">
      <i class="fa-solid fa-sitemap" style="color:#3b82f6;"></i>OU Structure
      <span id="ouMapSearchWrap" style="margin-left:auto;">
        <input id="ouMapSearch" type="text" placeholder="Filter..." style="font-size:11px;padding:2px 6px;border:1px solid #d0dce9;border-radius:4px;width:90px;outline:none;" oninput="ouMapFilter(this.value)">
      </span>
    </div>
    <div id="ouTreeInner" style="flex:1;overflow-y:auto;padding:4px 2px;"></div>
    <div style="padding:4px 8px;border-top:1px solid #e9f0f7;font-size:10px;color:#94a3b8;">
      <span style="margin-right:8px;"><span style="background:#dbeafe;color:#1d4ed8;border-radius:8px;padding:0 5px;font-weight:700;">3</span> = linked GPO count</span>
      <span style="background:#fef3c7;color:#b45309;border-radius:3px;padding:0 4px;border:1px solid #fde68a;font-size:9px;">BI</span> = Block Inherit
    </div>
  </div>

  <!-- RIGHT: Effective GPO Panel -->
  <div style="flex:1;border:1px solid #d0dce9;border-radius:8px;background:#fff;display:flex;flex-direction:column;min-width:0;">
    <div style="padding:7px 12px 5px 12px;border-bottom:1px solid #e9f0f7;font-size:11px;font-weight:700;color:#4b6880;letter-spacing:.04em;">
      <i class="fa-solid fa-layer-group" style="color:#3b82f6;margin-right:5px;"></i>Effective GPO Stack
    </div>
    <div id="ouPanelContent" style="flex:1;overflow-y:auto;padding:12px 14px;font-size:13px;color:#94a3b8;">
      <i class="fa-solid fa-arrow-left" style="margin-right:6px;"></i>Select an OU from the tree.
    </div>
  </div>

</div>

<script>
(function(){
  if(typeof OuTreeData==='undefined'||!OuTreeData.length)return;
  var _nd={},_ch={},_idxToId=[],_root=null;
  OuTreeData.forEach(function(n){_nd[n.Id]=n;});
  OuTreeData.forEach(function(n){
    if(!n.ParentId){_root=n;return;}
    if(!_ch[n.ParentId])_ch[n.ParentId]=[];
    _ch[n.ParentId].push(n);
  });
  Object.keys(_ch).forEach(function(k){_ch[k].sort(function(a,b){return a.Name.localeCompare(b.Name);});});

  function eh(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

  function gIdx(id){var i=_idxToId.indexOf(id);if(i<0){i=_idxToId.length;_idxToId.push(id);}return i;}

  function renderNode(node,depth){
    var idx=gIdx(node.Id);
    var kids=_ch[node.Id]||[];
    var hasK=kids.length>0;
    var lc=(node.GpoLinks||[]).filter(function(l){return l.Enabled;}).length;
    var bi=node.BlockInheritance;
    var isRoot=(node.Type==='domain');
    var pad=8+depth*16;
    var kidDisp=(depth===0)?'block':'none';
    var h='<div class="oum-item" data-idx="'+idx+'">';
    h+='<div class="oum-row" data-idx="'+idx+'" style="display:flex;align-items:center;gap:3px;padding:3px 6px 3px '+pad+'px;border-radius:4px;cursor:pointer;">';
    h+=hasK?'<span class="oum-tog" data-idx="'+idx+'" style="font-size:9px;color:#94a3b8;min-width:12px;text-align:center;">'+(depth===0?'&#9660;':'&#9654;')+'</span>':'<span style="min-width:12px;display:inline-block;"></span>';
    h+='<span style="font-size:12px;">'+(isRoot?'&#127760;':'&#128193;')+'</span>';
    h+='<span class="oum-name" style="flex:1;font-size:12px;color:#1e3a5f;font-weight:'+(isRoot?700:500)+';overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" data-no-translate>'+eh(node.Name)+'</span>';
    if(bi)h+='<span title="Block Inheritance" style="font-size:9px;padding:1px 4px;background:#fef3c7;color:#b45309;border-radius:3px;border:1px solid #fde68a;white-space:nowrap;">BI</span>';
    if(lc>0)h+='<span style="font-size:10px;font-weight:700;min-width:18px;text-align:center;padding:0 5px;background:#dbeafe;color:#1d4ed8;border-radius:10px;">'+lc+'</span>';
    h+='</div>';
    if(hasK){
      h+='<div class="oum-kids" data-idx="'+idx+'" style="display:'+kidDisp+';">';
      kids.forEach(function(kid){h+=renderNode(kid,depth+1);});
      h+='</div>';
    }
    h+='</div>';
    return h;
  }

  function ouMapInit(){
    var c=document.getElementById('ouTreeInner');
    if(!c||!_root)return;
    c.innerHTML=renderNode(_root,0);
    c.addEventListener('click',function(e){
      var togEl=e.target.closest('.oum-tog');
      var rowEl=e.target.closest('.oum-row');
      if(!rowEl)return;
      var idx=parseInt(rowEl.getAttribute('data-idx'),10);
      if(togEl){
        var kEl=c.querySelector('.oum-kids[data-idx="'+idx+'"]');
        if(kEl){var op=kEl.style.display!=='none';kEl.style.display=op?'none':'block';togEl.innerHTML=op?'&#9654;':'&#9660;';}
        e.stopPropagation();return;
      }
      c.querySelectorAll('.oum-row.oum-sel').forEach(function(r){r.classList.remove('oum-sel');r.style.background='';});
      rowEl.classList.add('oum-sel');rowEl.style.background='#e0f2fe';
      var id=_idxToId[idx];
      if(id)ouShowPanel(id);
    });
  }

  window.ouMapFilter=function(q){
    var c=document.getElementById('ouTreeInner');if(!c)return;
    var rows=c.querySelectorAll('.oum-row');
    rows.forEach(function(r){
      var nm=r.querySelector('.oum-name');
      if(!nm)return;
      var item=r.closest('.oum-item');
      if(!item)return;
      if(!q){item.style.display='';return;}
      item.style.display=nm.textContent.toLowerCase().indexOf(q.toLowerCase())>=0?'':'none';
    });
  };

  window.ouShowPanel=function(nodeId){
    var node=_nd[nodeId];if(!node)return;
    var panel=document.getElementById('ouPanelContent');if(!panel)return;
    // Build chain root → node
    var chain=[],cur=node,s=60;
    while(cur&&s-->0){chain.unshift(cur);if(!cur.ParentId)break;cur=_nd[cur.ParentId];}
    // Find BI cutoff index (first OU in chain that has BI, skip root)
    var biAt=-1;
    for(var i=1;i<chain.length;i++){if(chain[i].BlockInheritance){biAt=i;break;}}
    // Collect GPO rows
    var rows=[];
    for(var ci=0;ci<chain.length;ci++){
      var lvl=chain[ci];
      var links=(lvl.GpoLinks||[]).filter(function(l){return l.Enabled;});
      links.sort(function(a,b){return b.Order-a.Order;}); // descending Order → lower priority first within level
      links.forEach(function(lnk){
        var blocked=(biAt>0&&ci<biAt&&!lnk.Enforced);
        rows.push({id:lnk.GpoId,name:lnk.GpoName,enforced:lnk.Enforced,blocked:blocked,src:lvl.Name,lvl:ci});
      });
    }
    var h='';
    // Header
    h+='<div style="margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid #e9f0f7;">';
    h+='<div style="font-size:14px;font-weight:700;color:#0f2f4f;" data-no-translate>'+eh(node.Name)+'</div>';
    h+='<div style="font-size:10px;color:#94a3b8;word-break:break-all;margin-top:2px;" data-no-translate>'+eh(nodeId)+'</div>';
    if(node.BlockInheritance)h+='<div style="margin-top:5px;font-size:11px;color:#b45309;background:#fef3c7;padding:2px 8px;border-radius:4px;display:inline-block;border:1px solid #fde68a;">&#9888; Block Inheritance is enabled on this OU</div>';
    h+='</div>';
    // GPO stack
    if(!rows.length){
      h+='<div style="color:#94a3b8;padding:8px 0;">No enabled GPOs in the inheritance chain for this OU.</div>';
    } else {
      h+='<div style="font-size:12px;font-weight:600;color:#374151;margin-bottom:5px;">Effective GPO Stack <span style="font-weight:400;color:#94a3b8;font-size:11px;">lowest &#8594; highest priority</span></div>';
      var prevLvl=-1;
      rows.forEach(function(g,i){
        if(biAt>0&&g.lvl===biAt&&prevLvl<biAt){
          h+='<div style="margin:5px 0;padding:3px 8px;border-top:2px dashed #fbbf24;font-size:11px;color:#b45309;">&#9888; Block Inheritance at <b data-no-translate>'+eh(chain[biAt].Name)+'</b> &mdash; non-Enforced GPOs above are blocked</div>';
        }
        prevLvl=g.lvl;
        var bg=g.blocked?'#f3f4f6':(g.enforced?'#fffbeb':(i%2?'#f8fbff':'#fff'));
        var nst=g.blocked?'color:#9ca3af;text-decoration:line-through;':'color:#1e3a5f;font-weight:600;';
        h+='<div style="display:flex;align-items:center;gap:4px;padding:4px 6px;margin:2px 0;border-radius:5px;border:1px solid #e5e7eb;background:'+bg+';">';
        h+='<span style="min-width:22px;font-size:11px;color:#94a3b8;text-align:right;">'+(i+1)+'.</span>';
        h+='<span style="flex:1;font-size:12px;'+nst+'" data-no-translate>'+eh(g.name)+'</span>';
        h+='<span style="font-size:10px;color:#6b7280;white-space:nowrap;" data-no-translate>('+eh(g.src)+')</span>';
        if(g.enforced)h+='<span style="font-size:9px;padding:1px 5px;background:#fde68a;color:#92400e;border-radius:3px;font-weight:700;white-space:nowrap;">ENFORCED</span>';
        if(g.blocked)h+='<span style="font-size:9px;padding:1px 5px;background:#e5e7eb;color:#9ca3af;border-radius:3px;white-space:nowrap;">BLOCKED</span>';
        h+='</div>';
      });
    }
    // Conflict detection
    if(typeof GpoSettingsIndex!=='undefined'){
      var active=rows.filter(function(g){return !g.blocked;});
      var sm={};
      active.forEach(function(g){
        var gs=GpoSettingsIndex[g.id]||GpoSettingsIndex[g.id.toUpperCase()]||null;
        if(!gs)return;
        var secs=[];
        if(gs.c)secs=secs.concat(gs.c.split(',').map(function(x){return x.trim();}).filter(Boolean));
        if(gs.u)secs=secs.concat(gs.u.split(',').map(function(x){return x.trim();}).filter(Boolean));
        secs.forEach(function(sec){if(!sm[sec])sm[sec]=[];if(sm[sec].indexOf(g.name)<0)sm[sec].push(g.name);});
      });
      var conf=Object.keys(sm).filter(function(sec){return sm[sec].length>1;});
      if(conf.length){
        h+='<div style="margin-top:10px;padding-top:8px;border-top:1px solid #e9f0f7;">';
        h+='<div style="font-size:12px;font-weight:600;color:#b45309;margin-bottom:4px;">&#9888; Potential Setting Conflicts</div>';
        conf.forEach(function(sec){
          h+='<div style="font-size:11px;padding:3px 8px;margin:2px 0;background:#fef3c7;border:1px solid #fde68a;border-radius:4px;color:#92400e;">';
          h+='<b>'+eh(sec)+'</b> defined in: '+sm[sec].map(function(n){return'<span data-no-translate>'+eh(n)+'</span>';}).join(', ');
          h+='</div>';
        });
        h+='</div>';
      }
    }
    panel.innerHTML=h;
  };

  document.addEventListener('DOMContentLoaded',ouMapInit);
})();
</script>
