<script>
function filterGpoTable(type){
  document.querySelectorAll('.gpo-stat-card').forEach(function(c){c.classList.remove('gsc-active');});
  var activeCard=document.querySelector('.gpo-stat-card[data-filter="'+type+'"]');
  if(activeCard) activeCard.classList.add('gsc-active');
  document.querySelectorAll('#gpoInventoryTable tbody tr, #gpoInventoryTable tr:not(:first-child)').forEach(function(row){
    if(type==='all'){row.style.display='';return;}
    var st=(row.getAttribute('data-gpostatus')||'').split(',');
    row.style.display=st.indexOf(type)!==-1?'':'none';
  });
}
</script>
"@
    $Html += "<div class='table-wrapper'><table class='user-table' id='gpoInventoryTable'>"
