</tr>"

    foreach ($gpo in $AllGPOs) {
        $s = $GPOSettingsMap[$gpo.Id]
        $linkedOUs  = @($GPOLinkRows | Where-Object { $_.GpoId -eq $gpo.Id })
        $linkedCount = $linkedOUs.Count
        $isOrphaned  = $linkedCount -eq 0
        $isEmpty     = if ($s) { $s.IsEmpty } else { $false }
        $isDisabled  = $gpo.Status -eq "AllSettingsDisabled"
        $isUserDisabled = $gpo.Status -eq "UserSettingsDisabled"
        $isCompDisabled = $gpo.Status -eq "ComputerSettingsDisabled"

        $compCount   = if ($s) { $s.CompCount } else { "?" }
        $userCount   = if ($s) { $s.UserCount } else { "?" }
        $compSec     = if ($s -and $s.CompSections) { [System.Net.WebUtility]::HtmlEncode($s.CompSections) } else { "<span style='color:#aaa;'>—</span>" }
        $userSec     = if ($s -and $s.UserSections) { [System.Net.WebUtility]::HtmlEncode($s.UserSections) } else { "<span style='color:#aaa;'>—</span>" }

        $statusStyle = switch ($gpo.Status) {
            "AllSettingsDisabled"      { "color:#b91c1c;" }
            "UserSettingsDisabled"     { "color:#d97706;" }
            "ComputerSettingsDisabled" { "color:#d97706;" }
            default                    { "color:#1a7f4b;" }
        }

        $flags = ""
        $hasDisabledLink = @($linkedOUs | Where-Object { -not $_.Enabled }).Count -gt 0
        $hasEnforcedLink = @($linkedOUs | Where-Object { $_.Enforced }).Count -gt 0
        if ($isOrphaned)       { $flags += "<span style='background:#fee2e2;color:#b91c1c;border-radius:4px;padding:1px 5px;font-size:11px;font-weight:700;margin-right:3px;'>Orphaned</span>" }
        if ($isEmpty)          { $flags += "<span style='background:#fef3c7;color:#92400e;border-radius:4px;padding:1px 5px;font-size:11px;font-weight:700;margin-right:3px;'>Empty</span>" }
        if ($isDisabled)       { $flags += "<span style='background:#f1f5f9;color:#64748b;border-radius:4px;padding:1px 5px;font-size:11px;font-weight:700;margin-right:3px;'>Disabled</span>" }
        if ($hasDisabledLink)  { $flags += "<span style='background:#fff7ed;color:#c2410c;border-radius:4px;padding:1px 5px;font-size:11px;font-weight:700;margin-right:3px;'>Link Off</span>" }
        if ($hasEnforcedLink)  { $flags += "<span style='background:#ede9fe;color:#6d28d9;border-radius:4px;padding:1px 5px;font-size:11px;font-weight:700;margin-right:3px;'><i class='fa-solid fa-lock' style='font-size:9px;margin-right:2px;'></i>Enforced</span>" }
        if ($gpo.WmiFilter)    { $wmiSafe = [System.Net.WebUtility]::HtmlEncode($gpo.WmiFilter); $flags += "<span style='background:#f0fdf4;color:#166534;border-radius:4px;padding:1px 5px;font-size:11px;font-weight:700;' title='WMI Filter: $wmiSafe'><i class='fa-solid fa-filter' style='font-size:9px;margin-right:2px;'></i>WMI: $wmiSafe</span>" }
        # Feature 5: conflict badge
        if ($GpoConflictByGpo.ContainsKey($gpo.Id)) { $flags += "<span style='background:#fef3c7;color:#92400e;border-radius:4px;padding:1px 5px;font-size:11px;font-weight:700;margin-right:3px;' title='This GPO has overlapping policy sections with other GPOs at the same OU'>&#9888; Conflict</span>" }

        $rowStyle  = if ($isOrphaned -or $isDisabled) { " style='opacity:0.75;'" } else { "" }
        $nameSafe  = [System.Net.WebUtility]::HtmlEncode($gpo.Name)
        $idEsc     = $gpo.Id.Replace('{','').Replace('}','')

        # Clean status label
        $statusLabel = switch ($gpo.Status) {
            "AllSettingsEnabled"       { "<span style='color:#1a7f4b;font-weight:600;'>Enabled</span>" }
            "AllSettingsDisabled"      { "<span style='color:#b91c1c;font-weight:600;'>Disabled</span>" }
            "UserSettingsDisabled"     { "<span style='color:#d97706;font-weight:600;'>Computer Only</span>" }
            "ComputerSettingsDisabled" { "<span style='color:#d97706;font-weight:600;'>User Only</span>" }
            default                    { $gpo.Status }
        }

        # Feature 3: Linked OUs collapsible badge
        $ouNamesList = if ($linkedOUs.Count -eq 0) {
            "<span style='color:#aaa;font-style:italic;'>Not linked</span>"
        } else {
            $ouLinesHtml = @($linkedOUs | Sort-Object OUName | ForEach-Object {
                $ouHtml = [System.Net.WebUtility]::HtmlEncode($_.OUName)
                if ($_.Enabled) { $ouHtml } else { "<span style='color:#b91c1c;text-decoration:line-through;' title='Link disabled at this OU'>$ouHtml</span>" }
            }) -join '<br>'
            $ouBadgeCount = $linkedOUs.Count
            "<div class='ou-badge-wrap'><span class='ou-count-badge' onclick='this.nextElementSibling.style.display=this.nextElementSibling.style.display===""block""?""none"":""block""'>$ouBadgeCount OU(s)</span><div class='ou-list-expanded' style='display:none;'>$ouLinesHtml</div></div>"
        }

        # Settings cells
        $compCell = if ($compCount -gt 0) {
            "<a href='#' onclick='showGPODetail(""$idEsc"",""comp"");return false;' style='color:#1a5fa8;font-weight:600;text-decoration:none;'>$compCount section(s)</a> <span style='color:#7a909f;font-size:11px;'>— $compSec</span>"
        } else { "<span style='color:#aaa;'>—</span>" }

        $userCell = if ($userCount -gt 0) {
            "<a href='#' onclick='showGPODetail(""$idEsc"",""user"");return false;' style='color:#1a5fa8;font-weight:600;text-decoration:none;'>$userCount section(s)</a> <span style='color:#7a909f;font-size:11px;'>— $userSec</span>"
        } else { "<span style='color:#aaa;'>—</span>" }

        # Feature 1: data-gpostatus flags for filter
        $gpoStatusFlags = @()
        if ($isOrphaned)    { $gpoStatusFlags += 'orphaned' }
        if ($isEmpty)       { $gpoStatusFlags += 'empty' }
        if ($isDisabled)    { $gpoStatusFlags += 'disabled' }
        if ($hasEnforcedLink) { $gpoStatusFlags += 'enforced' }
        if ($isUserDisabled)  { $gpoStatusFlags += 'componly' }
        if ($isCompDisabled)  { $gpoStatusFlags += 'useronly' }
        $gpoStatusAttr = if ($gpoStatusFlags.Count -gt 0) { $gpoStatusFlags -join ',' } else { 'none' }

        $Html += "<tr$rowStyle data-gpostatus='$gpoStatusAttr'>"
        $Html += "<td data-no-translate><a href='#' onclick='showGPODetail(""$idEsc"");return false;' style='color:#0f4f9e;text-decoration:none;font-weight:600;'>$nameSafe</a></td>"
        $Html += "<td>$statusLabel</td>"
        $Html += "<td data-no-translate style='max-width:200px;'>$ouNamesList</td>"
        $Html += "<td>$compCell</td>"
        $Html += "<td>$userCell</td>"
        $Html += "<td>$($gpo.Modified)</td>"
        $Html += "<td>$flags</td>"
        $Html += "</tr>"
    }
    $Html += "</table></div>"
}
$Html += "</div></div>"

