.gpc-gponame{font-size:12px;color:#1a5fa8;font-weight:500;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.gpc-gponame:hover{text-decoration:underline;}
.gpc-pill{border-radius:4px;padding:1px 6px;font-size:10px;font-weight:700;flex-shrink:0;}
.pill-ord{background:#e0f2fe;color:#0369a1;}
.pill-off{background:#fee2e2;color:#b91c1c;}
.pill-enforced{background:#ede9fe;color:#6d28d9;}
.gpc-block-badge{background:#fff7ed;color:#c2410c;border:1px solid #fdba74;margin-left:5px;}
.gpc-enforce-badge{background:#ede9fe;color:#6d28d9;border:1px solid #ddd6fe;margin-left:5px;}
.pill-wmi{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;}
.pill-nolink{font-size:11px;color:#b0bec5;font-style:italic;padding:3px 0 5px 44px;display:block;}
.gpc-inh-section{margin:2px 0 6px 22px;}
.gpc-inh-hdr{display:flex;align-items:center;gap:5px;padding:3px 8px;font-size:11px;color:#7a909f;cursor:pointer;border-radius:5px;user-select:none;}
.gpc-inh-hdr:hover{background:#f1f5f9;color:#3a5570;}
.gpc-inh-body{padding-left:14px;border-left:2px dashed #d4e0ed;margin-left:6px;margin-top:3px;}
.gpc-inh-src{font-size:10px;color:#9ab0c5;padding:5px 4px 2px;font-weight:700;display:flex;align-items:center;gap:5px;text-transform:uppercase;letter-spacing:.04em;}
.gpc-inh-item{display:flex;align-items:center;gap:6px;padding:3px 7px;border-radius:5px;cursor:pointer;margin-bottom:1px;}
.gpc-inh-item:hover{background:#f0f7ff;}
.gpc-inh-name{font-size:11px;color:#5a789f;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.gpc-node.hidden{display:none;}
`;
document.head.appendChild(_s);

var ouTreeData=(typeof OuTreeData!=='undefined'?OuTreeData:[]).map(function(n){
  return {
    id:n.Id,
    parent:n.ParentId||'',
    name:n.Name,
    type:n.Type,
    blockInherit:!!n.BlockInheritance,
    links:(n.GpoLinks||[]).map(function(l){
      return {id:(l.GpoId||'').replace(/[{}]/g,''),name:l.GpoName,enabled:l.Enabled,enforced:l.Enforced,order:l.Order};
    })
  };
});
var _nameCnt={};
ouTreeData.forEach(function(n){_nameCnt[n.name]=(_nameCnt[n.name]||0)+1;});
var nodeMap={};
ouTreeData.forEach(function(n){nodeMap[n.id]=n;});

function countGPOs(nodeId){
    var n=nodeMap[nodeId]; if(!n) return 0;
    var cnt=(n.links||[]).length;
    ouTreeData.filter(function(c){return c.parent===nodeId;}).forEach(function(c){cnt+=countGPOs(c.id);});
    return cnt;
}

function getInheritedLinks(nodeId){
    var node=nodeMap[nodeId]; if(!node) return [];
    var inherited=[]; var parentId=node.parent;
    while(parentId){
        var par=nodeMap[parentId]; if(!par) break;
        var links=par.links||[];
        if(node.blockInherit) links=links.filter(function(l){return l.enforced;});
        inherited=inherited.concat(links);
        parentId=par.parent;
    }
    return inherited;
}

function getInheritedBySource(nodeId){
    var node=nodeMap[nodeId];if(!node)return[];
    var groups=[];var parentId=node.parent;
    while(parentId){
        var par=nodeMap[parentId];if(!par)break;
        var links=par.links||[];
        if(node.blockInherit)links=links.filter(function(l){return l.enforced;});
        if(links.length>0)groups.push({name:par.name,type:par.type,links:links.slice()});
        parentId=par.parent;
    }
    return groups;
}

function buildTree(parentId,container){
    var children=ouTreeData.filter(function(n){return n.parent===parentId;});
    children.forEach(function(node){
        var hasKids=ouTreeData.some(function(n){return n.parent===node.id;});
        var isDomain=node.type==='domain';
        var expanded=isDomain;
        var gpoCount=(node.links||[]).length;
        var inheritedLinks=getInheritedLinks(node.id);
        var inheritedCount=inheritedLinks.length;

        var wrap=document.createElement('div');
        wrap.className='gpc-node';
        wrap.dataset.id=node.id;
        wrap.dataset.name=(node.name||'').toLowerCase();

        var row=document.createElement('div');
        row.className='gpc-row'+(isDomain?' gpc-domain':'');
        row.title=node.id;

        var tog=document.createElement('i');
        tog.className='gpc-toggle fa-solid '+(hasKids?(expanded?'fa-chevron-down open':'fa-chevron-right'):'fa-minus');
        tog.style.fontSize='10px';

        var ico=document.createElement('i');
        if(isDomain){
            ico.className='gpc-icon fa-solid fa-building';
            ico.style.color='#2563eb';
        } else {
            ico.className='gpc-icon fa-solid fa-folder'+(hasKids?'':'-open');
            ico.style.color=hasKids?'#d97706':'#f59e0b';
        }

        var lbl=document.createElement('span');
        lbl.className='gpc-label'+(isDomain?' lbl-domain':'');
        var _displayName=node.name;
        if(!isDomain&&_nameCnt[node.name]>1&&node.parent&&nodeMap[node.parent]){_displayName=nodeMap[node.parent].name+' › '+node.name;}
        lbl.textContent=_displayName;
        lbl.dataset.noTranslate='true';

        var cnt=document.createElement('span');
        cnt.className='gpc-gpocnt'+(gpoCount===0?' cnt-0':'');
        cnt.textContent=gpoCount+' GPO';
        cnt.title=gpoCount+' linked policy object(s)';

        row.appendChild(tog); row.appendChild(ico); row.appendChild(lbl);
        if(node.blockInherit){var bi=document.createElement('span');bi.className='gpc-pill gpc-block-badge';bi.title='Block Inheritance active — policies from parent containers are ignored (unless Enforced)';bi.innerHTML='<i class="fa-solid fa-ban" style="font-size:8px;margin-right:3px;"></i>Block Inherit';row.appendChild(bi);}
        var hasEnforced=(node.links||[]).some(function(l){return l.enforced;});
        if(hasEnforced){var ef=document.createElement('span');ef.className='gpc-pill gpc-enforce-badge';ef.title='One or more GPOs at this OU are Enforced — Block Inheritance cannot block them';ef.innerHTML='<i class="fa-solid fa-lock" style="font-size:8px;margin-right:3px;"></i>Enforced';row.appendChild(ef);}
        row.appendChild(cnt);
        if(inheritedCount>0){var ihb=document.createElement('span');ihb.className='gpc-inh-cnt';ihb.textContent='↑'+inheritedCount;ihb.title=inheritedCount+' GPO(s) inherited from parent chain'+(node.blockInherit?' — Block Inheritance active, only Enforced GPOs pass through':'');row.appendChild(ihb);}
        if(typeof gpoConflictByOU!=='undefined'&&gpoConflictByOU[node.id]&&gpoConflictByOU[node.id].length>0){var cfb=document.createElement('span');cfb.style.cssText='background:#fef3c7;color:#92400e;border:1px solid #fcd34d;border-radius:4px;padding:1px 6px;font-size:10px;font-weight:700;margin-left:4px;cursor:default;';cfb.title='Policy conflict: multiple GPOs at this OU define the same setting categories';cfb.textContent='⚠ Conflict';row.appendChild(cfb);}
        wrap.appendChild(row);

        // GPO list
        var gpoList=document.createElement('div');
        gpoList.className='gpc-gpolist';
        cnt.style.cursor='pointer';
        cnt.title=(gpoCount===0?'No GPOs linked':gpoCount+' GPO(s) — click to show/hide');
        cnt.onclick=function(e){e.stopPropagation();gpoList.style.display=gpoList.style.display==='none'?'':'none';};
        if(node.links&&node.links.length>0){
            node.links.slice().sort(function(a,b){return a.order-b.order;}).forEach(function(lnk){
                var item=document.createElement('div');
                item.className='gpc-gpoitem'+(lnk.enabled?'':' gpo-disabled');
                item.onclick=function(e){e.stopPropagation();showGPODetail(lnk.id);};
                item.title='Click for details';

                var gi=document.createElement('i');
                gi.className='gpc-gpoicon fa-solid '+(lnk.enabled?'fa-file-shield':'fa-file-circle-xmark');
                gi.style.color=lnk.enabled?'#2563eb':'#dc2626';

                var gn=document.createElement('span');
                gn.className='gpc-gponame';
                gn.textContent=lnk.name;
                gn.dataset.noTranslate='true';

                var badges='<span class="gpc-pill pill-ord">#'+lnk.order+'</span>';
                if(!lnk.enabled) badges+='<span class="gpc-pill pill-off">Disabled</span>';
                if(lnk.enforced) badges+='<span class="gpc-pill pill-enforced"><i class="fa-solid fa-lock" style="font-size:8px;"></i> Enforced</span>';
                var wmiF=(typeof gpoWmiMap!=='undefined'&&gpoWmiMap[lnk.id])?gpoWmiMap[lnk.id]:null;
                if(wmiF) badges+='<span class="gpc-pill pill-wmi" title="WMI Filter: '+wmiF+'"><i class="fa-solid fa-filter" style="font-size:8px;margin-right:2px;"></i>WMI</span>';
                var bd=document.createElement('span');
                bd.innerHTML=badges;

                item.appendChild(gi); item.appendChild(gn); item.appendChild(bd);
                gpoList.appendChild(item);
            });
        } else {
            var np=document.createElement('span');
            np.className='pill-nolink';
            if(inheritedCount>0){np.textContent='No direct links';}
            else{np.textContent='No GPOs linked';}
            gpoList.appendChild(np);
        }
        wrap.appendChild(gpoList);

        // Inherited GPO section
        if(!isDomain){
            var inhGroups=getInheritedBySource(node.id);
            if(inhGroups.length>0){
                var inhSec=document.createElement('div');
                inhSec.className='gpc-inh-section';
                var inhHdr=document.createElement('div');
                inhHdr.className='gpc-inh-hdr';
                var inhTog=document.createElement('i');
                inhTog.className='fa-solid fa-chevron-right';
                inhTog.style.cssText='font-size:9px;width:14px;flex-shrink:0;';
                var inhTxt=document.createElement('span');
                inhTxt.innerHTML='<i class="fa-solid fa-arrow-turn-down" style="font-size:9px;margin-right:3px;color:#94a3b8;"></i>Inherited GPOs ('+inheritedCount+')';
                inhHdr.appendChild(inhTog);inhHdr.appendChild(inhTxt);
                var inhBody=document.createElement('div');
                inhBody.className='gpc-inh-body';
                inhBody.style.display='none';
                inhGroups.forEach(function(grp){
                    var srcDiv=document.createElement('div');
                    srcDiv.className='gpc-inh-src';
                    var srcIco=document.createElement('i');
                    srcIco.className='fa-solid '+(grp.type==='domain'?'fa-building':'fa-folder');
                    srcIco.style.cssText='font-size:10px;color:'+(grp.type==='domain'?'#2563eb':'#d97706')+';';
                    srcDiv.appendChild(srcIco);
                    srcDiv.dataset.noTranslate='true';
                    srcDiv.appendChild(document.createTextNode(' '+grp.name));
                    inhBody.appendChild(srcDiv);
                    grp.links.forEach(function(lnk){
                        var it=document.createElement('div');
                        it.className='gpc-inh-item';
                        it.onclick=function(e){e.stopPropagation();showGPODetail(lnk.id);};
                        it.title='Inherited from '+grp.name+' — click for details';
                        var ii=document.createElement('i');
                        ii.className='fa-solid fa-file-shield';
                        ii.style.cssText='font-size:11px;color:#a0b4c8;width:14px;text-align:center;flex-shrink:0;';
                        var nm=document.createElement('span');nm.className='gpc-inh-name';nm.textContent=lnk.name;nm.dataset.noTranslate='true';
                        var bd=document.createElement('span');
                        bd.style.cssText='font-size:9px;font-weight:700;color:#a0b4c8;flex-shrink:0;margin-right:2px;';
                        bd.textContent='#'+lnk.order;
                        it.appendChild(ii);it.appendChild(nm);it.appendChild(bd);
                        if(lnk.enforced){var ef=document.createElement('span');ef.className='gpc-pill pill-enforced';ef.style.cssText='font-size:9px;padding:0 4px;';ef.innerHTML='<i class="fa-solid fa-lock" style="font-size:7px;"></i>';it.appendChild(ef);}
                        inhBody.appendChild(it);
                    });
                });
                inhHdr.onclick=function(e){
                    e.stopPropagation();
                    var open=inhBody.style.display!=='none';
                    inhBody.style.display=open?'none':'';
                    inhTog.className='fa-solid '+(open?'fa-chevron-right':'fa-chevron-down');
                };
                inhSec.appendChild(inhHdr);inhSec.appendChild(inhBody);
                wrap.appendChild(inhSec);
            }
        }

        // Children
        var kids=document.createElement('div');
        kids.className='gpc-children';
        if(!expanded) kids.style.display='none';
        buildTree(node.id,kids);
        wrap.appendChild(kids);

        row.onclick=function(){
            if(!hasKids) return;
            var open=kids.style.display!=='none';
            kids.style.display=open?'none':'';
            tog.className='gpc-toggle fa-solid '+(open?'fa-chevron-right':'fa-chevron-down open');
            ico.className='gpc-icon fa-solid '+(isDomain?'fa-building':(open?'fa-folder':'fa-folder-open'));
        };

        container.appendChild(wrap);
    });
}

document.addEventListener('DOMContentLoaded',function(){
    var root=document.getElementById('gpoTreeRoot');
    if(root) buildTree('',root);
    var inp=document.getElementById('gpcSearchInput');
    if(inp) inp.addEventListener('input',function(){gpcSearch(this.value);});
});
})();

var _inhAllOpen=false;
function gpcToggleAllInherited(){
    _inhAllOpen=!_inhAllOpen;
    document.querySelectorAll('#gpoTreeRoot .gpc-inh-body').forEach(function(el){el.style.display=_inhAllOpen?'':'none';});
    document.querySelectorAll('#gpoTreeRoot .gpc-inh-hdr .fa-solid').forEach(function(el){
        if(el.classList.contains('fa-chevron-right')||el.classList.contains('fa-chevron-down')){
            el.className='fa-solid '+(_inhAllOpen?'fa-chevron-down':'fa-chevron-right');
        }
    });
    var btn=document.getElementById('gpcInhTogBtn');
    if(btn)btn.innerHTML='<i class="fa-solid '+(_inhAllOpen?'fa-eye-slash':'fa-eye')+'" style="font-size:10px;margin-right:4px;"></i>'+(_inhAllOpen?'Hide Inherited':'Show Inherited');
}
function gpcExpandAll(){
    document.querySelectorAll('#gpoTreeRoot .gpc-children').forEach(function(el){el.style.display='';});
    document.querySelectorAll('#gpoTreeRoot .gpc-toggle.fa-chevron-right').forEach(function(el){
        el.className=el.className.replace('fa-chevron-right','fa-chevron-down')+' open';
    });
}
function gpcCollapseAll(){
    document.querySelectorAll('#gpoTreeRoot .gpc-children').forEach(function(el){el.style.display='none';});
}
function gpcSearch(val){
    var q=(val||'').toLowerCase().trim();
    document.querySelectorAll('#gpoTreeRoot .gpc-node').forEach(function(n){
        if(!q){n.classList.remove('hidden');return;}
        var nm=n.dataset.name||'';
        var match=nm.indexOf(q)!==-1;
        var gpoMatch=false;
        n.querySelectorAll('.gpc-gponame').forEach(function(g){if(g.textContent.toLowerCase().indexOf(q)!==-1)gpoMatch=true;});
        n.classList.toggle('hidden',!match&&!gpoMatch);
        if(match||gpoMatch){
            var p=n.parentElement;
            while(p&&p.id!=='gpoTreeRoot'){
                if(p.classList.contains('gpc-children')){p.style.display='';}
                if(p.classList.contains('gpc-node')){p.classList.remove('hidden');}
                p=p.parentElement;
            }
        }
    });
}
</script>
<div class='gpc-wrap'>
  <div class='gpc-toolbar'>
    <input id='gpcSearchInput' class='gpc-search' type='text' placeholder='Search OUs or GPOs...' oninput='gpcSearch(this.value)'>
    <button class='gpc-tbtn' onclick='gpcExpandAll()'><i class='fa-solid fa-expand' style='font-size:10px;margin-right:4px;'></i>Expand All</button>
    <button class='gpc-tbtn' onclick='gpcCollapseAll()'><i class='fa-solid fa-compress' style='font-size:10px;margin-right:4px;'></i>Collapse All</button>
    <button id='gpcInhTogBtn' class='gpc-tbtn' onclick='gpcToggleAllInherited()' style='border-color:#94a3b8;'><i class='fa-solid fa-eye' style='font-size:10px;margin-right:4px;'></i>Show Inherited</button>
  </div>
  <div id='gpoTreeRoot' class='gpc-tree'></div>
</div>
'@

    # ---- Block Inheritance Summary ----
    $BlockInheritOUs = @($OUTreeNodes | Where-Object { $_.BlockInheritance })
    if ($BlockInheritOUs.Count -gt 0) {
        $Html += "<div style='margin-top:16px;padding:12px 16px;background:#fff7ed;border:1px solid #fdba74;border-radius:8px;'>"
        $Html += "<h4 style='margin:0 0 6px 0;color:#c2410c;font-size:13px;font-weight:700;'><i class='fa-solid fa-ban' style='margin-right:6px;'></i>Block Inheritance Detected ($($BlockInheritOUs.Count) OU(s))</h4>"
        $Html += "<p style='margin:0 0 8px 0;font-size:12px;color:#7c2d12;'>These OUs block GPO inheritance from parent containers. Policies linked above will NOT apply unless they are Enforced.</p>"
        $Html += "<ul style='margin:0;padding-left:18px;font-size:12px;color:#1a3550;line-height:1.8;'>"
        foreach ($biOU in $BlockInheritOUs) {
            $biName = [System.Net.WebUtility]::HtmlEncode($biOU.Name)
            $biDN   = [System.Net.WebUtility]::HtmlEncode($biOU.Id)
            $Html += "<li><strong>$biName</strong>&nbsp;<span style='color:#9ca3af;font-size:11px;'>$biDN</span></li>"
        }
        $Html += "</ul></div>"
    } else {
        $Html += "<p style='font-size:12px;color:#6b7280;margin-top:12px;'><i class='fa-solid fa-circle-check' style='color:#1a7f4b;margin-right:5px;'></i>No Block Inheritance configured in any OU.</p>"
    }

    # ---- GPO Detail Modal ----
    $Html += "<script>"
    $Html += "var gpoData = {};"
    foreach ($gpo in $AllGPOs) {
        $s          = $GPOSettingsMap[$gpo.Id]
        $idEsc      = $gpo.Id.Replace('{','').Replace('}','')
        $nameSafe   = ($gpo.Name -replace "'","\'") -replace '"','\"'
        $compCount  = if ($s) { $s.CompCount } else { 0 }
        $userCount  = if ($s) { $s.UserCount } else { 0 }
        $compB64    = if ($s -and $s.CompB64) { $s.CompB64 } else { "" }
        $userB64    = if ($s -and $s.UserB64) { $s.UserB64 } else { "" }

        $statusLabel = switch ($gpo.Status) {
            "AllSettingsEnabled"       { "Enabled" }
            "AllSettingsDisabled"      { "All Settings Disabled" }
            "UserSettingsDisabled"     { "Computer Only (User Disabled)" }
            "ComputerSettingsDisabled" { "User Only (Computer Disabled)" }
            default                    { $gpo.Status }
        }

        $linkedOUsJson = "["
        @($GPOLinkRows | Where-Object { $_.GpoId -eq $gpo.Id } | Sort-Object Depth, OUName) | ForEach-Object {
            $ouN  = ($_.OUName -replace "'","\'") -replace '"','\"'
            $ouDN = ($_.OUDN   -replace "'","\'") -replace '"','\"'
            $linkedOUsJson += "{ou:'$ouN',dn:'$ouDN',enabled:$(if($_.Enabled){'true'}else{'false'}),enforced:$(if($_.Enforced){'true'}else{'false'})},"
        }
        $linkedOUsJson += "]"

        $isOrphaned = if (@($GPOLinkRows | Where-Object { $_.GpoId -eq $gpo.Id }).Count -eq 0) { "true" } else { "false" }
        $Html += "gpoData['$idEsc']={name:'$nameSafe',status:'$statusLabel',created:'$($gpo.Created)',modified:'$($gpo.Modified)',compCount:$compCount,userCount:$userCount,compB64:'$compB64',userB64:'$userB64',links:$linkedOUsJson,orphaned:$isOrphaned};"
    }
    $Html += @"
function _b64dec(s){try{return s?new TextDecoder().decode(Uint8Array.from(atob(s),function(c){return c.charCodeAt(0);})):''}catch(e){return ''}}
function gpoTab(id){
    document.querySelectorAll('.gdm-tab').forEach(function(t){t.classList.remove('active');});
    document.querySelectorAll('.gdm-panel').forEach(function(p){p.style.display='none';});
    document.getElementById('gdmTab'+id).classList.add('active');
    document.getElementById('gdmPanel'+id).style.display='';
}
function showGPODetail(id, openTab) {
    var d = gpoData[id]; if(!d) return;

    var statusColor = d.status.indexOf('Disabled')!==-1 ? '#b91c1c' : (d.status.indexOf('Only')!==-1 ? '#d97706' : '#1a7f4b');

    var warns = '';
    if(d.orphaned) warns += '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:6px;padding:8px 12px;margin-bottom:8px;color:#991b1b;font-weight:600;font-size:12px;"><i class="fa-solid fa-triangle-exclamation" style="margin-right:6px;"></i>Orphaned — not linked to any OU. Has no effect.</div>';
    if(d.compCount===0&&d.userCount===0) warns += '<div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:6px;padding:8px 12px;margin-bottom:8px;color:#92400e;font-weight:600;font-size:12px;"><i class="fa-solid fa-circle-exclamation" style="margin-right:6px;"></i>No settings configured in this GPO.</div>';

    var ouRows = '';
    (d.links||[]).forEach(function(lnk){
        var enf = lnk.enforced ? '<span style="background:#ede9fe;color:#6d28d9;border-radius:3px;padding:1px 5px;font-size:10px;font-weight:700;margin-left:4px;">Enforced</span>' : '';
        var dis = !lnk.enabled ? '<span style="background:#fee2e2;color:#b91c1c;border-radius:3px;padding:1px 5px;font-size:10px;font-weight:700;margin-left:4px;">Link Off</span>' : '';
        ouRows += '<tr><td data-no-translate style="padding:5px 10px;border-bottom:1px solid #edf2f7;"><i class="fa-solid fa-folder" style="color:#d97706;margin-right:6px;font-size:11px;"></i>'+lnk.ou+'</td><td data-no-translate style="padding:5px 10px;border-bottom:1px solid #edf2f7;font-size:11px;color:#7a909f;">'+lnk.dn+'</td><td style="padding:5px 10px;border-bottom:1px solid #edf2f7;">'+enf+dis+'</td></tr>';
    });
    if(!ouRows) ouRows='<tr><td colspan="3" style="padding:8px 10px;color:#aaa;font-style:italic;">Not linked to any OU</td></tr>';

    var overviewHtml =
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;">' +
        '<div style="background:#f8fbff;border:1px solid #dce8f5;border-radius:8px;padding:10px 12px;"><div style="font-size:10px;text-transform:uppercase;color:#7a909f;font-weight:700;margin-bottom:4px;">Status</div><div style="font-weight:700;color:'+statusColor+';">'+d.status+'</div></div>' +
        '<div style="background:#f8fbff;border:1px solid #dce8f5;border-radius:8px;padding:10px 12px;"><div style="font-size:10px;text-transform:uppercase;color:#7a909f;font-weight:700;margin-bottom:4px;">Last Modified</div><div style="font-weight:600;color:#1a3550;">'+d.modified+'</div></div>' +
        '<div style="background:#f8fbff;border:1px solid #dce8f5;border-radius:8px;padding:10px 12px;"><div style="font-size:10px;text-transform:uppercase;color:#7a909f;font-weight:700;margin-bottom:4px;">Computer Config</div><div style="font-weight:600;color:#1a3550;">'+d.compCount+' section(s)</div></div>' +
        '<div style="background:#f8fbff;border:1px solid #dce8f5;border-radius:8px;padding:10px 12px;"><div style="font-size:10px;text-transform:uppercase;color:#7a909f;font-weight:700;margin-bottom:4px;">User Config</div><div style="font-weight:600;color:#1a3550;">'+d.userCount+' section(s)</div></div>' +
        '</div>' +
        '<div style="font-size:12px;font-weight:700;color:#0f2f4f;margin-bottom:6px;">Linked OUs / Containers</div>' +
        '<div style="border:1px solid #e2eaf4;border-radius:6px;overflow:hidden;"><table style="width:100%;border-collapse:collapse;font-size:12px;"><tr style="background:#eef3f9;"><th style="padding:6px 10px;text-align:left;font-weight:700;color:#1a3550;">OU Name</th><th style="padding:6px 10px;text-align:left;font-weight:700;color:#1a3550;">Distinguished Name</th><th style="padding:6px 10px;text-align:left;font-weight:700;color:#1a3550;">Flags</th></tr>'+ouRows+'</table></div>';

    var compHtml = _b64dec(d.compB64);
    var userHtml = _b64dec(d.userB64);

    // Feature 4: Link Chain tab
    var nodeByDN = {};
    if(typeof ouTreeData !== 'undefined'){ouTreeData.forEach(function(n){nodeByDN[n.id]=n;});}
    var chainHtml = '';
    if(!d.links || d.links.length === 0){
        chainHtml = '<p style="color:#aaa;font-style:italic;padding:10px;">This GPO is not linked to any OU.</p>';
    } else {
        chainHtml = '<div style="font-size:12px;color:#0f2f4f;font-weight:700;margin-bottom:10px;">This GPO is linked at ' + d.links.length + ' location(s). Each card shows sibling GPOs at the same OU.</div>';
        d.links.forEach(function(lnk){
            var node = nodeByDN[lnk.dn] || null;
            var siblings = '';
            if(node && node.links && node.links.length > 1){
                var others = node.links.filter(function(sl){return sl.id !== id;}).slice().sort(function(a,b){return a.order - b.order;});
                if(others.length > 0){
                    siblings = '<div style="margin-top:8px;font-size:11px;font-weight:700;color:#7a909f;text-transform:uppercase;letter-spacing:.04em;">Siblings at this OU</div><div style="margin-top:4px;">';
                    others.forEach(function(sl){
                        var sEnf = sl.enforced ? '<span style="background:#ede9fe;color:#6d28d9;border-radius:3px;padding:1px 4px;font-size:10px;font-weight:700;margin-left:4px;">Enforced</span>' : '';
                        var sOff = !sl.enabled ? '<span style="background:#fee2e2;color:#b91c1c;border-radius:3px;padding:1px 4px;font-size:10px;font-weight:700;margin-left:4px;">Disabled</span>' : '';
                        siblings += '<div style="display:flex;align-items:center;gap:6px;padding:4px 6px;border-radius:5px;cursor:pointer;margin-bottom:2px;background:#f8fbff;border:1px solid #e2eaf4;" onclick="closeGPODetail();showGPODetail(\''+sl.id+'\')"><i class="fa-solid fa-file-shield" style="color:#94a3b8;font-size:11px;"></i><span style="font-size:12px;color:#1a5fa8;flex:1;">' + sl.name + '</span><span style="font-size:10px;color:#94a3b8;">#' + sl.order + '</span>'+sEnf+sOff+'</div>';
                    });
                    siblings += '</div>';
                }
            } else if(!node){
                siblings = '<div style="font-size:11px;color:#aaa;margin-top:6px;font-style:italic;">OU node not found in tree data.</div>';
            } else {
                siblings = '<div style="font-size:11px;color:#aaa;margin-top:6px;font-style:italic;">No other GPOs linked at this OU.</div>';
            }
            var enfBadge = lnk.enforced ? '<span style="background:#ede9fe;color:#6d28d9;border-radius:4px;padding:2px 7px;font-size:11px;font-weight:700;margin-left:6px;">Enforced</span>' : '';
            var disBadge = !lnk.enabled ? '<span style="background:#fee2e2;color:#b91c1c;border-radius:4px;padding:2px 7px;font-size:11px;font-weight:700;margin-left:6px;">Link Off</span>' : '';
            var orderBadge = '<span style="background:#e0f2fe;color:#0369a1;border-radius:4px;padding:2px 7px;font-size:11px;font-weight:700;margin-left:6px;">Order #' + (node && node.links ? (node.links.find(function(l){return l.id===id;})||{order:'?'}).order : '?') + '</span>';
            chainHtml += '<div style="border:1px solid #d0dce9;border-radius:10px;padding:12px 14px;margin-bottom:10px;background:#fff;">'
                + '<div style="display:flex;align-items:center;flex-wrap:wrap;gap:4px;margin-bottom:4px;"><i class="fa-solid fa-folder" style="color:#d97706;font-size:13px;"></i><span style="font-weight:700;color:#1a3550;font-size:13px;" data-no-translate>' + lnk.ou + '</span>' + enfBadge + disBadge + orderBadge + '</div>'
                + '<div style="font-size:11px;color:#7a909f;margin-bottom:6px;" data-no-translate>' + lnk.dn + '</div>'
                + siblings
                + '</div>';
        });
    }

    document.getElementById('gdmModalName').textContent = d.name;
    document.getElementById('gdmPanelOverview').innerHTML = warns + overviewHtml;
    document.getElementById('gdmPanelComp').innerHTML = compHtml || '<p style="color:#aaa;font-style:italic;padding:10px;">No Computer Configuration settings.</p>';
    document.getElementById('gdmPanelUser').innerHTML = userHtml || '<p style="color:#aaa;font-style:italic;padding:10px;">No User Configuration settings.</p>';
    document.getElementById('gdmPanelChain').innerHTML = chainHtml;

    document.getElementById('gdmTabComp').textContent = 'Computer Config (' + d.compCount + ')';
    document.getElementById('gdmTabUser').textContent = 'User Config (' + d.userCount + ')';

    document.getElementById('gpoDetailModal').style.display = 'flex';
    gpoTab(openTab === 'comp' ? 'Comp' : openTab === 'user' ? 'User' : openTab === 'chain' ? 'Chain' : 'Overview');
}
function closeGPODetail(){document.getElementById('gpoDetailModal').style.display='none';}
</script>
