# ---------------------
# GPO Conflicts Container
# ---------------------
$Html += "<div class='container' id='gpoConflictsContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>GPO Conflicts</h2>"

    # ---- GPO Conflicts Table ----
    $Html += "<h3 style='margin:20px 0 6px 0;font-size:15px;color:#0f2f4f;'>GPO Conflicts <span style='font-size:11px;font-weight:400;color:#7a909f;'>($GpcConflictCount conflicts detected)</span></h3>"
    $Html += "<p class='section-intro'>Security-critical settings (password policy, lockout, audit, user rights, security options) set by 2+ GPOs in the same OU with different values. The <strong>effective winner</strong> column shows what actually applies — determined by link order and Enforced flag.</p>"
    if ($GpcConflictCount -eq 0) {
        $Html += "<p style='color:#22c55e;font-size:13px;margin:8px 0;'><i class='fa-solid fa-circle-check' style='margin-right:6px;'></i>No setting conflicts detected across linked GPOs.</p>"
    } else {
        $Html += "<div class='table-wrapper'><table class='user-table' id='gpcConflictTable'><tr>"
        $Html += "<th onclick='sortTable(""gpcConflictTable"",0)'>OU</th>"
        $Html += "<th onclick='sortTable(""gpcConflictTable"",1)'>Category</th>"
        $Html += "<th onclick='sortTable(""gpcConflictTable"",2)'>Setting</th>"
        $Html += "<th>GPO A — Effective</th>"
        $Html += "<th>GPO B — Overridden</th>"
        $Html += "<th>Effective Winner</th>"
        $Html += "</tr>"
        foreach ($row in $GpcConflictRows | Sort-Object OUName, Setting) {
            $catBadge = switch ($row.Category) {
                "PassLock" { "<span style='background:#dbeafe;color:#1e40af;padding:1px 7px;border-radius:4px;font-size:10px;font-weight:700;'>Password/Lockout</span>" }
                "Audit"    { "<span style='background:#fef3c7;color:#92400e;padding:1px 7px;border-radius:4px;font-size:10px;font-weight:700;'>Audit</span>" }
                "URA"      { "<span style='background:#ede9fe;color:#5b21b6;padding:1px 7px;border-radius:4px;font-size:10px;font-weight:700;'>User Rights</span>" }
                "SecOpt"   { "<span style='background:#dcfce7;color:#166534;padding:1px 7px;border-radius:4px;font-size:10px;font-weight:700;'>Security Options</span>" }
                default    { "<span style='background:#f1f5f9;color:#475569;padding:1px 7px;border-radius:4px;font-size:10px;font-weight:700;'>$($row.Category)</span>" }
            }
            $ouSafe      = [System.Net.WebUtility]::HtmlEncode($row.OUName)
            $ouDNSafe    = [System.Net.WebUtility]::HtmlEncode($row.OUDN)
            $settingSafe = [System.Net.WebUtility]::HtmlEncode($row.Setting)
            $gpoASafe    = [System.Net.WebUtility]::HtmlEncode($row.GpoAName)
            $gpoAValSafe = [System.Net.WebUtility]::HtmlEncode($row.GpoAVal)
            $gpoBSafe    = [System.Net.WebUtility]::HtmlEncode($row.GpoBName)
            $gpoBValSafe = [System.Net.WebUtility]::HtmlEncode($row.GpoBVal)
            $winnerSafe  = [System.Net.WebUtility]::HtmlEncode($row.Winner)
            $Html += "<tr>"
            $Html += "<td data-no-translate style='font-size:12px;'>$ouSafe<br><span style='font-size:10px;color:#94a3b8;'>$ouDNSafe</span></td>"
            $Html += "<td>$catBadge</td>"
            $Html += "<td style='font-weight:600;'>$settingSafe</td>"
            $Html += "<td data-no-translate><span style='font-size:11px;font-weight:700;color:#1a3550;'>$gpoASafe</span><br><span style='color:#1a7f4b;font-weight:800;font-size:12px;'>$gpoAValSafe</span> <span style='font-size:9px;background:#dcfce7;color:#166534;border-radius:3px;padding:1px 5px;'>Winner</span></td>"
            $Html += "<td data-no-translate><span style='font-size:11px;font-weight:700;color:#1a3550;'>$gpoBSafe</span><br><span style='color:#ef4444;font-weight:800;font-size:12px;'>$gpoBValSafe</span> <span style='font-size:9px;background:#fee2e2;color:#b91c1c;border-radius:3px;padding:1px 5px;'>Overridden</span></td>"
            $Html += "<td data-no-translate style='font-size:11px;font-weight:700;color:#0f2f4f;'>$winnerSafe</td>"
            $Html += "</tr>"
        }
        $Html += "</table></div>"
    }

$Html += "</div></div>"

# =====================================================
# ATTACK PATHS SECTION
# =====================================================
$Html += "<div class='container' id='attackPathsContainer' style='display:none;'><div class='content-card'>"
$Html += "<h2>Attack Path Analysis</h2>"
$Html += "<p class='section-intro'>Interactive privilege-escalation graph. Each node is a principal (user, group, computer); each arrow means <strong>can control or escalate into</strong> — nested group membership, dangerous ACLs (GenericAll / WriteDacl / WriteOwner) on Tier-0 objects, or group management rights. Red nodes are Tier-0 targets (Domain Admins, Enterprise Admins, AdminSDHolder, domain root). Click any node to trace its shortest path to a Tier-0 target.</p>"

# Stat cards
$_apReachColor = if ($AttackPathReachCount -gt 0) { "#b91c1c" } else { "#16a34a" }
$Html += "<div class='section-stat-grid'>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Principals Reaching Tier-0</div><div class='section-stat-value' style='color:$_apReachColor;font-weight:800;'>$AttackPathReachCount</div><div class='section-stat-note'>Non-privileged accounts with an escalation path</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Shortest Path</div><div class='section-stat-value'>$(if($AttackPathShortestHops -gt 0){"$AttackPathShortestHops hop(s)"}else{"—"})</div><div class='section-stat-note'>Fewest steps from an exposed account to Tier-0</div></div>"
$Html += "<div class='section-stat-card'><div class='section-stat-label'>Tier-0 Targets</div><div class='section-stat-value'>$AttackPathTargetCount</div><div class='section-stat-note'>Domain Admins, EA, SA, AdminSDHolder, root, dangerous-ACL objects</div></div>"
$Html += "</div>"

$Html += "<script>var apNodes=$AttackPathNodesJson;var apEdges=$AttackPathEdgesJson;var apSpotlight=$AttackPathSpotlightJson;var apExposed=$AttackPathExposedJson;</script>"
$Html += @'
<script>
