<style>
.ap-wrap{margin:14px 0 4px 0;}
.ap-table-wrap{border:1px solid #e2e8f0;border-radius:10px;background:#fff;margin-bottom:12px;overflow:hidden;}
.ap-table-head{display:flex;align-items:center;justify-content:space-between;padding:12px 15px;border-bottom:1px solid #eef2f7;}
.ap-table-title{font-size:14px;font-weight:800;color:#0f2f4f;}
.ap-table-sub{font-size:11px;color:#64748b;margin-top:2px;}
.ap-table-scroll{max-height:230px;overflow-y:auto;}
.ap-table{width:100%;border-collapse:collapse;font-size:12.5px;}
.ap-table thead th{position:sticky;top:0;background:#f8fafc;text-align:left;padding:8px 14px;font-size:11px;font-weight:700;color:#475569;border-bottom:1px solid #e2e8f0;white-space:nowrap;}
.ap-table tbody td{padding:8px 14px;border-bottom:1px solid #f1f5f9;color:#334155;}
.ap-table tbody tr{cursor:pointer;}
.ap-table tbody tr:hover{background:#f0f7ff;}
.ap-table tbody tr.ap-row-active{background:#fef2f2;box-shadow:inset 3px 0 0 #dc2626;}
.ap-tp{display:inline-block;padding:1px 7px;border-radius:4px;font-size:10px;font-weight:700;}
.ap-tp-user{background:#ccfbf1;color:#0f766e;}
.ap-tp-computer{background:#f1f5f9;color:#475569;}
.ap-tp-group{background:#dbeafe;color:#1d4ed8;}
.ap-hops{font-weight:800;color:#b91c1c;}
.ap-reach{font-weight:700;color:#991b1b;}
.ap-trace-btn{padding:3px 9px;border:1px solid #fca5a5;border-radius:5px;background:#fee2e2;color:#b91c1c;font-size:10px;font-weight:700;}
.ap-hint{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.92);border:1px solid #e2e8f0;border-radius:20px;padding:7px 15px;font-size:12px;color:#64748b;box-shadow:0 3px 12px rgba(15,47,79,.08);}
.ap-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:8px;}
.ap-input{padding:7px 11px;border:1px solid #cbd5e1;border-radius:7px;font-size:13px;min-width:190px;outline:none;}
.ap-input:focus{border-color:#2563eb;}
.ap-btn{padding:7px 12px;border:1px solid #cbd5e1;border-radius:7px;background:#fff;color:#334155;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px;}
.ap-btn:hover{background:#f1f5f9;}
.ap-btn-spot{background:#fee2e2;border-color:#fca5a5;color:#b91c1c;}
.ap-btn-spot:hover{background:#fecaca;}
.ap-legend{display:inline-flex;flex-wrap:wrap;gap:12px;margin-left:auto;font-size:11px;color:#475569;align-items:center;}
.ap-lg{display:inline-flex;align-items:center;gap:5px;}
.ap-dot{width:11px;height:11px;border-radius:50%;display:inline-block;}
.ap-edge-ace{width:16px;height:0;border-top:2px solid #dc2626;display:inline-block;}
.ap-stage{position:relative;border:1px solid #e2e8f0;border-radius:10px;background:linear-gradient(180deg,#fbfdff,#f4f8fc);height:560px;overflow:hidden;}
#apCanvas{width:100%;height:100%;display:block;cursor:grab;}
#apCanvas:active{cursor:grabbing;}
.ap-empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;text-align:center;color:#64748b;font-size:14px;padding:0 40px;}
.ap-empty i{font-size:40px;color:#22c55e;}
.ap-panel{position:absolute;top:10px;right:10px;width:300px;max-height:calc(100% - 20px);overflow-y:auto;background:#fff;border:1px solid #e2e8f0;border-radius:10px;box-shadow:0 8px 28px rgba(15,47,79,.14);font-size:12px;}
.ap-panel-head{display:flex;align-items:center;justify-content:space-between;padding:11px 14px;border-bottom:1px solid #eef2f7;font-weight:800;color:#0f2f4f;font-size:13px;}
.ap-panel-close{cursor:pointer;color:#94a3b8;}
.ap-panel-close:hover{color:#475569;}
#apPanelBody{padding:12px 14px;}
.ap-hop{display:flex;align-items:flex-start;gap:8px;padding:5px 0;}
.ap-hop-num{flex:0 0 auto;width:18px;height:18px;border-radius:50%;background:#0f2f4f;color:#fff;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;margin-top:1px;}
.ap-hop-body{flex:1;}
.ap-hop-name{font-weight:700;color:#0f2f4f;word-break:break-word;}
.ap-hop-via{font-size:10px;color:#64748b;}
.ap-badge-ace{background:#fee2e2;color:#b91c1c;border-radius:3px;padding:0 5px;font-size:9px;font-weight:700;}
.ap-badge-shadow{background:#ede9fe;color:#6d28d9;border-radius:3px;padding:0 5px;font-size:9px;font-weight:700;}
</style>
<script>
(function(){
  var canvas=document.getElementById('apCanvas');
  if(!canvas) return;
  var nodes=Array.isArray(apNodes)?apNodes:[];
  var edges=Array.isArray(apEdges)?apEdges:[];
  if(nodes.length===0){document.getElementById('apEmpty').style.display='flex';return;}

  var byId={}; nodes.forEach(function(n){ n.x=0;n.y=0;n.vx=0;n.vy=0; byId[n.id]=n; });
  // adjacency for path tracing (forward: source can reach dest)
  var adj={}; edges.forEach(function(e){ if(!adj[e.s])adj[e.s]=[]; adj[e.s].push(e); });
  // out-degree, to detect "leaf" members that can be collapsed under a hub group
  var outDeg={}; edges.forEach(function(e){ outDeg[e.s]=(outDeg[e.s]||0)+1; });

  // focus mode: only the currently traced path is drawn (readable at any domain size).
  // full mode: whole pruned graph, with leaf members collapsed under their group.
  var focusMode=true, visible={}, collapsed={};
  function computeCollapsed(){
    // in full mode, collapse leaf members (out-degree 1) hanging off a group that has many of them
    collapsed={};
    var childrenByGroup={};
    edges.forEach(function(e){
      if(e.k!=='mem') return;
      var src=byId[e.s];
      if(src && !src.tgt && (outDeg[e.s]||0)===1){ (childrenByGroup[e.d]=childrenByGroup[e.d]||[]).push(e.s); }
    });
    Object.keys(childrenByGroup).forEach(function(g){
      if(childrenByGroup[g].length>=6 && !expandedGroups[g]){ childrenByGroup[g].forEach(function(c){ collapsed[c]=g; }); }
    });
    return childrenByGroup;
  }
  var expandedGroups={}, groupChildCount={};
  function recomputeVisible(){
    visible={};
    if(focusMode){
      var keys=Object.keys(pathSet);
      if(keys.length===0){ nodes.forEach(function(n){ if(n.tgt) visible[n.id]=1; }); return; }
      keys.forEach(function(k){ visible[k]=1; }); return;
    }
    var cc=computeCollapsed();
    groupChildCount={};
    Object.keys(cc).forEach(function(g){ groupChildCount[g]=cc[g].length; });
    nodes.forEach(function(n){ if(!collapsed[n.id]) visible[n.id]=1; });
  }

  var ctx=canvas.getContext('2d'), DPR=window.devicePixelRatio||1;
  var W=0,H=0;
  function resize(){
    var r=canvas.getBoundingClientRect(); W=r.width; H=r.height;
    canvas.width=W*DPR; canvas.height=H*DPR; ctx.setTransform(DPR,0,0,DPR,0,0);
  }

  // initial layout: targets pulled toward center, others on a ring
  var cx=0,cy=0;
  function seed(){
    resize(); cx=W/2; cy=H/2;
    var i=0, tCount=nodes.filter(function(n){return n.tgt;}).length, ti=0;
    nodes.forEach(function(n){
      if(n.tgt){ var a=(ti/Math.max(1,tCount))*Math.PI*2; n.x=cx+Math.cos(a)*70; n.y=cy+Math.sin(a)*70; ti++; }
      else { var ang=(i*2.399963); var rad=90+((n.d||2)*46)+((i%7)*8); n.x=cx+Math.cos(ang)*rad; n.y=cy+Math.sin(ang)*rad; }
      i++;
    });
  }

  var alpha=1, view={x:0,y:0,k:1};
  function tick(){
    // repulsion
    for(var a=0;a<nodes.length;a++){
      var na=nodes[a];
      for(var b=a+1;b<nodes.length;b++){
        var nb=nodes[b], dx=na.x-nb.x, dy=na.y-nb.y, d2=dx*dx+dy*dy+0.01;
        if(d2<40000){ var f=1400/d2, d=Math.sqrt(d2); var fx=dx/d*f, fy=dy/d*f; na.vx+=fx;na.vy+=fy;nb.vx-=fx;nb.vy-=fy; }
      }
    }
    // springs
    edges.forEach(function(e){
      var s=byId[e.s], t=byId[e.d]; if(!s||!t) return;
      var dx=t.x-s.x, dy=t.y-s.y, d=Math.sqrt(dx*dx+dy*dy)+0.01, target=98;
      var f=(d-target)*0.015, fx=dx/d*f, fy=dy/d*f;
      s.vx+=fx;s.vy+=fy;t.vx-=fx;t.vy-=fy;
    });
    // gravity + integrate
    nodes.forEach(function(n){
      if(n.fixed) return;
      n.vx+=(cx-n.x)*0.004; n.vy+=(cy-n.y)*0.004;
      n.vx*=0.86; n.vy*=0.86;
      n.x+=n.vx*alpha*2; n.y+=n.vy*alpha*2;
    });
    alpha*=0.985;
  }

  var pathSet={}, pathEdgeSet={}, selected=null, hover=null;
  function colorFor(n){
    if(n.tgt) return '#dc2626';
    if(n.type==='group') return '#2563eb';
    if(n.type==='user') return '#0d9488';
    if(n.type==='computer') return '#94a3b8';
    return '#f59e0b';
  }
  function radFor(n){ return n.tgt?9:(n.type==='group'?6:5); }

  function vis(id){ return !!visible[id]; }
  function draw(){
    ctx.clearRect(0,0,W,H);
    ctx.save(); ctx.translate(view.x,view.y); ctx.scale(view.k,view.k);
    // edges (only between visible endpoints)
    edges.forEach(function(e){
      if(!vis(e.s)||!vis(e.d)) return;
      var s=byId[e.s], t=byId[e.d]; if(!s||!t) return;
      var onPath=pathEdgeSet[e.s+'>'+e.d];
      ctx.beginPath(); ctx.moveTo(s.x,s.y); ctx.lineTo(t.x,t.y);
      if(onPath){ ctx.strokeStyle='#dc2626'; ctx.lineWidth=2.6; ctx.setLineDash([]); }
      else if(e.k==='ace'){ ctx.strokeStyle='rgba(220,38,38,.55)'; ctx.lineWidth=1.6; ctx.setLineDash([]); }
      else if(e.k==='mgr'){ ctx.strokeStyle='rgba(234,88,12,.5)'; ctx.lineWidth=1.1; ctx.setLineDash([4,3]); }
      else { ctx.strokeStyle= (selected? 'rgba(148,163,184,.25)':'rgba(148,163,184,.5)'); ctx.lineWidth=1; ctx.setLineDash([]); }
      ctx.stroke(); ctx.setLineDash([]);
      var ang=Math.atan2(t.y-s.y,t.x-s.x), r=radFor(t)+2;
      var ax=t.x-Math.cos(ang)*r, ay=t.y-Math.sin(ang)*r;
      ctx.beginPath(); ctx.moveTo(ax,ay);
      ctx.lineTo(ax-Math.cos(ang-0.4)*6, ay-Math.sin(ang-0.4)*6);
      ctx.lineTo(ax-Math.cos(ang+0.4)*6, ay-Math.sin(ang+0.4)*6);
      ctx.closePath(); ctx.fillStyle=onPath?'#dc2626':(e.k==='ace'?'rgba(220,38,38,.55)':'rgba(148,163,184,.5)'); ctx.fill();
    });
    // nodes
    nodes.forEach(function(n){
      if(!vis(n.id)) return;
      var dim = selected && !pathSet[n.id] && n!==selected;
      ctx.globalAlpha = dim?0.28:1;
      ctx.beginPath(); ctx.arc(n.x,n.y,radFor(n),0,Math.PI*2);
      ctx.fillStyle=colorFor(n); ctx.fill();
      if((n.f||'').indexOf('shadow')>=0){ ctx.lineWidth=2; ctx.strokeStyle='#7c3aed'; ctx.stroke(); }
      if(n===selected||pathSet[n.id]){ ctx.lineWidth=2; ctx.strokeStyle='#0f2f4f'; ctx.stroke(); }
      // collapsed-member count badge on hub groups (full mode)
      var childN=groupChildCount[n.id];
      if(!focusMode && childN && !expandedGroups[n.id]){
        ctx.beginPath(); ctx.arc(n.x+radFor(n)+2, n.y-radFor(n)-2, 8,0,Math.PI*2);
        ctx.fillStyle='#334155'; ctx.fill();
        ctx.fillStyle='#fff'; ctx.font='700 9px Segoe UI, sans-serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
        ctx.fillText('+'+childN, n.x+radFor(n)+2, n.y-radFor(n)-2); ctx.textBaseline='alphabetic';
      }
      if(n.tgt||n===hover||n===selected||pathSet[n.id]){
        ctx.globalAlpha=dim?0.4:1;
        ctx.font=(n.tgt?'700 ':'')+'11px Segoe UI, sans-serif';
        ctx.fillStyle=n.tgt?'#991b1b':'#334155';
        ctx.textAlign='center';
        ctx.fillText(String(n.l||n.id).slice(0,26), n.x, n.y-radFor(n)-5);
      }
    });
    ctx.globalAlpha=1; ctx.restore();
  }

  var running=true;
  function loop(){ if(alpha>0.02){ tick(); } draw(); requestAnimationFrame(loop); }

  // ---- path tracing: forward BFS from node to nearest target ----
  function tracePath(startId){
    var q=[startId], prev={}, seen={}; seen[startId]=1; var found=null;
    while(q.length){
      var cur=q.shift();
      if(byId[cur] && byId[cur].tgt && cur!==startId){ found=cur; break; }
      (adj[cur]||[]).forEach(function(e){ if(!seen[e.d]){ seen[e.d]=1; prev[e.d]=e; q.push(e.d); } });
    }
    pathSet={}; pathEdgeSet={};
    if(!found){ return []; }
    var chain=[], c=found;
    while(c && c!==startId){ var e=prev[c]; chain.unshift(e); pathSet[c]=1; pathEdgeSet[e.s+'>'+e.d]=1; c=e.s; }
    pathSet[startId]=1;
    return chain;
  }

  function apTR(){ return (typeof currentLanguage!=='undefined' && currentLanguage==='tr'); }
  function edgeVerb(k){
    var tr=apTR();
    if(k==='mem') return tr?'şu grubun üyesi:':'is a member of';
    if(k==='ace') return tr?'şu nesne üzerinde tehlikeli ACL yetkisine sahip:':'has dangerous ACL over';
    if(k==='mgr') return tr?'şu grubu yönetiyor:':'manages';
    return k;
  }
  function showPanel(startId){
    var chain=tracePath(startId), start=byId[startId];
    selected=start;
    var tr=apTR();
    var panel=document.getElementById('apPanel'), body=document.getElementById('apPanelBody');
    document.getElementById('apPanelTitle').textContent = start.l||startId;
    if(chain.length===0){
      body.innerHTML='<div style="color:#16a34a;font-weight:600;">'+(tr?'Bu düğümden bir Tier-0 hedefe ulaşan yol yok.':'No path to a Tier-0 target from this node.')+'</div>';
    } else {
      var dest=escAp(byId[chain[chain.length-1].d].l);
      var head=tr?(chain.length+' adımda ulaşılan hedef: <b>'+dest+'</b>'):(chain.length+'-hop path to <b>'+dest+'</b>');
      var html='<div style="margin-bottom:8px;color:#b91c1c;font-weight:700;">'+head+'</div>';
      html+='<div class="ap-hop"><div class="ap-hop-num">0</div><div class="ap-hop-body"><div class="ap-hop-name">'+escAp(start.l)+ ((start.f||'').indexOf('shadow')>=0?' <span class="ap-badge-shadow">'+(tr?'gölge admin':'shadow')+'</span>':'') +'</div></div></div>';
      chain.forEach(function(e,i){
        var t=byId[e.d];
        html+='<div class="ap-hop"><div class="ap-hop-num">'+(i+1)+'</div><div class="ap-hop-body"><div class="ap-hop-name">'+escAp(t.l)+'</div><div class="ap-hop-via">'+edgeVerb(e.k)+(e.lbl?' <span class="ap-badge-ace">'+escAp(e.lbl)+'</span>':'')+'</div></div></div>';
      });
      body.innerHTML=html;
    }
    panel.style.display='block';
  }
  function escAp(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  // fit the view to a set of node ids (used when focusing a path)
  function fitTo(ids){
    var xs=[], ys=[];
    ids.forEach(function(id){ var n=byId[id]; if(n){ xs.push(n.x); ys.push(n.y); } });
    if(xs.length===0) return;
    var minX=Math.min.apply(null,xs), maxX=Math.max.apply(null,xs);
    var minY=Math.min.apply(null,ys), maxY=Math.max.apply(null,ys);
    var pad=70, bw=(maxX-minX)+pad*2, bh=(maxY-minY)+pad*2;
    var k=Math.min(2.4, Math.min(W/Math.max(bw,1), H/Math.max(bh,1)));
    view.k=Math.max(0.5,k);
    view.x=W/2 - ((minX+maxX)/2)*view.k;
    view.y=H/2 - ((minY+maxY)/2)*view.k;
  }
  function updateHint(){
    var hint=document.getElementById('apHint');
    if(hint) hint.style.display = (selected? 'none':'flex');
  }
  function markRow(id){
    var body=document.getElementById('apExposedBody'); if(!body) return;
    Array.prototype.forEach.call(body.querySelectorAll('tr'),function(tr){ tr.classList.toggle('ap-row-active', tr.getAttribute('data-id')===id); });
  }

  // central action: trace + focus + fit + panel + row highlight
  window.apFocus=function(id){
    if(!byId[id]) return;
    showPanel(id);
    recomputeVisible();
    alpha=Math.max(alpha,0.25);
    fitTo(Object.keys(pathSet));
    markRow(id); updateHint();
  };
  window.apToggleFocus=function(){
    focusMode=!focusMode;
    var btn=document.getElementById('apFocusToggle');
    var tr=apTR();
    if(btn) btn.innerHTML=focusMode?'<i class="fa-solid fa-expand"></i> '+(tr?'Tüm haritayı göster':'Show full map'):'<i class="fa-solid fa-compress"></i> '+(tr?'Yola odaklan':'Focus on path');
    recomputeVisible();
    alpha=Math.max(alpha,0.4);
    if(!focusMode){ view={x:0,y:0,k:1}; }
    else if(selected){ fitTo(Object.keys(pathSet)); }
  };

  window.apClosePanel=function(){ document.getElementById('apPanel').style.display='none'; selected=null; pathSet={}; pathEdgeSet={}; markRow(null); recomputeVisible(); updateHint(); };
  window.apResetView=function(){ view={x:0,y:0,k:1}; apClosePanel(); alpha=Math.max(alpha,0.4); };
  window.apShowSpotlight=function(){
    if(!Array.isArray(apSpotlight)||apSpotlight.length===0){ return; }
    if(byId[apSpotlight[0]]){ apFocus(apSpotlight[0]); }
  };
  window.apDoSearch=function(v){
    v=(v||'').toLowerCase().trim(); if(!v){ hover=null; return; }
    var hit=nodes.filter(function(n){ return String(n.l||'').toLowerCase().indexOf(v)>=0; })[0];
    if(hit){ hover=hit; centerOn(hit); }
  };
  function centerOn(n){ view.k=1.15; view.x=W/2 - n.x*view.k; view.y=H/2 - n.y*view.k; }

  // ---- exposed principals table ----
  function tpClass(t){ return t==='user'?'ap-tp-user':(t==='computer'?'ap-tp-computer':'ap-tp-group'); }
  function tpLabel(t){ var tr=apTR(); if(t==='user')return tr?'Kullanıcı':'User'; if(t==='computer')return tr?'Bilgisayar':'Computer'; return tr?'Grup':'Group'; }
  function renderExposedTable(){
    var body=document.getElementById('apExposedBody'); if(!body) return;
    var rows=Array.isArray(apExposed)?apExposed:[];
    if(rows.length===0){ body.innerHTML='<tr><td colspan="5" style="text-align:center;color:#16a34a;padding:16px;">'+(apTR()?'Tier-0’a ulaşan hesap yok.':'No account can reach Tier-0.')+'</td></tr>'; return; }
    var tr=apTR(), html='';
    rows.forEach(function(r){
      var shadow=(r.f||'').indexOf('shadow')>=0?' <span class="ap-badge-shadow">'+(tr?'gölge':'shadow')+'</span>':'';
      html+='<tr data-id="'+escAp(r.id)+'" onclick="apFocus(this.getAttribute(\'data-id\'))">'+
        '<td data-no-translate><b>'+escAp(r.l)+'</b>'+shadow+'</td>'+
        '<td><span class="ap-tp '+tpClass(r.t)+'">'+tpLabel(r.t)+'</span></td>'+
        '<td class="ap-hops">'+r.hops+'</td>'+
        '<td class="ap-reach" data-no-translate>'+escAp(r.tl)+'</td>'+
        '<td><span class="ap-trace-btn">'+(tr?'İzle':'Trace')+'</span></td></tr>';
    });
    body.innerHTML=html;
  }

  // ---- interaction ----
  function toWorld(px,py){ return {x:(px-view.x)/view.k, y:(py-view.y)/view.k}; }
  function pick(px,py){
    var w=toWorld(px,py), best=null, bd=999;
    nodes.forEach(function(n){ if(!visible[n.id]) return; var dx=n.x-w.x, dy=n.y-w.y, d=Math.sqrt(dx*dx+dy*dy); if(d<radFor(n)+6 && d<bd){ bd=d; best=n; } });
    return best;
  }
  var dragNode=null, panning=false, lastX=0, lastY=0, moved=false;
  canvas.addEventListener('mousedown',function(ev){
    var r=canvas.getBoundingClientRect(), px=ev.clientX-r.left, py=ev.clientY-r.top;
    var n=pick(px,py); moved=false; lastX=px; lastY=py;
    if(n){ dragNode=n; n.fixed=true; } else { panning=true; }
  });
  window.addEventListener('mousemove',function(ev){
    var r=canvas.getBoundingClientRect(), px=ev.clientX-r.left, py=ev.clientY-r.top;
    if(dragNode){ var w=toWorld(px,py); dragNode.x=w.x; dragNode.y=w.y; dragNode.vx=0; dragNode.vy=0; alpha=Math.max(alpha,0.3); moved=true; }
    else if(panning){ view.x+=px-lastX; view.y+=py-lastY; lastX=px; lastY=py; moved=true; }
    else { hover=pick(px,py); canvas.style.cursor=hover?'pointer':'grab'; }
  });
  window.addEventListener('mouseup',function(ev){
    if(dragNode){
      dragNode.fixed=false;
      if(!moved){
        // full mode: clicking a hub group with collapsed children expands them
        if(!focusMode && groupChildCount[dragNode.id] && !expandedGroups[dragNode.id]){
          expandedGroups[dragNode.id]=1; recomputeVisible(); alpha=Math.max(alpha,0.4);
        } else {
          apFocus(dragNode.id);
        }
      }
      dragNode=null;
    }
    else if(panning){ if(!moved){ apClosePanel(); } panning=false; }
  });
  canvas.addEventListener('wheel',function(ev){
    ev.preventDefault();
    var r=canvas.getBoundingClientRect(), px=ev.clientX-r.left, py=ev.clientY-r.top;
    var w=toWorld(px,py), factor=ev.deltaY<0?1.12:0.89;
    view.k=Math.max(0.3,Math.min(3.2,view.k*factor));
    view.x=px-w.x*view.k; view.y=py-w.y*view.k;
  },{passive:false});

  // (re)seed once the container becomes visible (canvas needs real size)
  var started=false;
  function startIfVisible(){
    if(started) return;
    var box=document.getElementById('attackPathsContainer');
    if(box && box.offsetParent!==null && canvas.getBoundingClientRect().width>0){
      started=true; seed(); loop();
      renderExposedTable();
      for(var i=0;i<180;i++){ tick(); }
      // open focused on the worst path (table-first, graph as drill-down)
      if(Array.isArray(apSpotlight)&&apSpotlight.length&&byId[apSpotlight[0]]){ apFocus(apSpotlight[0]); }
      else { recomputeVisible(); updateHint(); }
    }
  }
  var poll=setInterval(function(){ startIfVisible(); if(started) clearInterval(poll); },250);
  window.addEventListener('resize',function(){ if(started){ resize(); } });
})();
</script>
'@
$Html += "</div></div>"

# =====================================================
# AD TIER LIST SECTION
# =====================================================
$Html += "<div class='container' id='tierContainer'>"
$Html += "<div class='content-card'>"

# --- New Redesigned Header ---
$Html += @"
<div style='display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:4px;'>
  <div>
    <h2 style='margin:0 0 4px 0;font-size:20px;font-weight:800;color:#0f2f4f;display:flex;align-items:center;gap:10px;'>
      <i class='fa-solid fa-layer-group' style='color:#0ea5a2;'></i> Admin Privilege Tiers
    </h2>
    <p style='margin:0;font-size:13px;color:#5b7a99;'>Microsoft Tier Model — analyzes separation between identity infrastructure, servers, and end users.</p>
  </div>
  <div style='display:flex;align-items:center;gap:8px;'>
    <span style='font-size:11px;color:#7a909f;'>Score</span>
    <svg viewBox='0 0 100 100' width='72' height='72'>
      <circle cx='50' cy='50' r='40' fill='none' stroke='#e2e8f0' stroke-width='10'/>
      <circle cx='50' cy='50' r='40' fill='none' stroke='$TierScoreColor' stroke-width='10' stroke-dasharray='$_tierArc 251.2' stroke-linecap='round' transform='rotate(-90 50 50)'/>
      <text x='50' y='46' text-anchor='middle' dominant-baseline='central' font-size='17' font-weight='900' fill='$TierScoreColor'>$TierComplianceScore</text>
      <text x='50' y='62' text-anchor='middle' font-size='9' fill='#94a3b8'>/ 100</text>
    </svg>
  </div>
</div>
<div style='display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px;margin-top:8px;'>
  <span style='background:#fee2e2;color:#b91c1c;border-radius:6px;padding:4px 10px;font-size:12px;font-weight:700;'><i class='fa-solid fa-circle-exclamation' style='margin-right:4px;'></i>Critical: $TierCriticalCount</span>
  <span style='background:#fef3c7;color:#d97706;border-radius:6px;padding:4px 10px;font-size:12px;font-weight:700;'><i class='fa-solid fa-triangle-exclamation' style='margin-right:4px;'></i>Warning: $TierWarningCount</span>
  <span style='background:#dbeafe;color:#1d4ed8;border-radius:6px;padding:4px 10px;font-size:12px;font-weight:700;'><i class='fa-solid fa-circle-info' style='margin-right:4px;'></i>Info: $TierInfoCount</span>
  <span style='background:#dcfce7;color:#166534;border-radius:6px;padding:4px 10px;font-size:12px;font-weight:700;'><i class='fa-solid fa-circle-check' style='margin-right:4px;'></i>OK: $TierOKCount</span>
</div>
"@

# =====================================================================
# AD TIER MODEL — Tabbed Dashboard, English base, TR via domTextExactTr
# =====================================================================

# --- Gauge & score computation ---
$gaugeScore = $TierComplianceScore
$gaugeFill  = [Math]::Round($gaugeScore * 2.513, 1)
$gaugeColor = if ($gaugeScore -ge 80) { "#16a34a" } elseif ($gaugeScore -ge 60) { "#d97706" } else { "#b91c1c" }
$gaugeLabel = if ($gaugeScore -ge 80) { "Good"    } elseif ($gaugeScore -ge 60) { "Needs Work" } else { "At Risk" }
$gaugeBg    = if ($gaugeScore -ge 80) { "#f0fdf4" } elseif ($gaugeScore -ge 60) { "#fffbeb"   } else { "#fff5f5" }
$gaugeBorder= if ($gaugeScore -ge 80) { "#86efac" } elseif ($gaugeScore -ge 60) { "#fde68a"   } else { "#fca5a5" }

# --- Tier Status ---
$Tier0Status = if ($Tier0CritCount -gt 0) { "critical" } elseif ($Tier0WarnCount -gt 0) { "warning" } else { "ok" }
$Tier1Status = if ($Tier1CritCount -gt 0) { "critical" } elseif ($Tier1WarnCount -gt 0) { "warning" } else { "ok" }
$Tier2Status = if ($Tier2CritCount -gt 0) { "critical" } elseif ($Tier2WarnCount -gt 0) { "warning" } else { "ok" }

function Get-TierCardStyle([string]$s) {
    switch ($s) {
        "critical" { return @{ bg="#fff5f5"; border="#fca5a5"; accent="#b91c1c"; label="Critical"; icon="fa-circle-exclamation"; tabColor="#b91c1c" } }
        "warning"  { return @{ bg="#fffbeb"; border="#fde68a"; accent="#d97706"; label="Warning";  icon="fa-triangle-exclamation"; tabColor="#d97706" } }
        default    { return @{ bg="#f0fdf4"; border="#86efac"; accent="#166534"; label="OK";       icon="fa-circle-check"; tabColor="#166534" } }
    }
}
$s0 = Get-TierCardStyle $Tier0Status
$s1 = Get-TierCardStyle $Tier1Status
$s2 = Get-TierCardStyle $Tier2Status

$OUStatus = if ($OUWarnCount -gt 0) { "warning" } else { "ok" }
$sOU = Get-TierCardStyle $OUStatus

# --- Tab dot badges ---
function Get-TabDot([string]$status) {
    $c = switch ($status) { "critical" { "#b91c1c" } "warning" { "#d97706" } default { "#166534" } }
    return "<span style='display:inline-block;width:7px;height:7px;border-radius:50%;background:$c;margin-left:5px;vertical-align:middle;flex-shrink:0;'></span>"
}
$dot0  = Get-TabDot $Tier0Status
$dot1  = Get-TabDot $Tier1Status
$dot2  = Get-TabDot $Tier2Status
$dotOU = Get-TabDot $OUStatus

# --- Finding card helper ---
function Get-TierFindingHtml([PSCustomObject]$f) {
    switch ($f.Severity) {
        "Critical" { $sb="#fee2e2"; $sc="#b91c1c"; $sl="CRITICAL"; $si="fa-circle-exclamation"; $lb="border-left:4px solid #b91c1c;" }
        "Warning"  { $sb="#fef3c7"; $sc="#d97706"; $sl="WARNING";  $si="fa-triangle-exclamation"; $lb="border-left:4px solid #f59e0b;" }
        "Info"     { $sb="#dbeafe"; $sc="#1d4ed8"; $sl="INFO";     $si="fa-circle-info";           $lb="border-left:4px solid #3b82f6;" }
        default    { $sb="#dcfce7"; $sc="#166534"; $sl="OK";        $si="fa-circle-check";          $lb="border-left:4px solid #22c55e;" }
    }
    $enTitle = [System.Net.WebUtility]::HtmlEncode($f.Title)
    $enDesc  = [System.Net.WebUtility]::HtmlEncode($f.Description)
    $enRec   = [System.Net.WebUtility]::HtmlEncode($f.Recommendation)
    $trTitle = [System.Net.WebUtility]::HtmlEncode($f.TitleTR)
    $trDesc  = [System.Net.WebUtility]::HtmlEncode($f.DescTR)
    $trRec   = [System.Net.WebUtility]::HtmlEncode($f.RecTR)
    $h  = "<div class='tier-finding' style='background:#fff;border:1px solid #e8edf5;border-radius:10px;$lb padding:12px 15px;margin-bottom:10px;box-shadow:0 1px 3px rgba(0,0,0,.05);' data-en-title='$enTitle' data-tr-title='$trTitle' data-en-desc='$enDesc' data-tr-desc='$trDesc' data-en-rec='$enRec' data-tr-rec='$trRec'>"
    $h += "<div style='display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:6px;margin-bottom:7px;'>"
    $h += "<div style='display:flex;align-items:center;gap:7px;'>"
    $h += "<span style='background:$sb;color:$sc;border-radius:5px;padding:2px 7px;font-size:10px;font-weight:800;white-space:nowrap;'><i class='fa-solid $si' style='margin-right:3px;'></i>$sl</span>"
    $h += "<span class='fc-title' data-no-translate='true' style='font-size:12px;font-weight:700;color:#0f2f4f;'>$enTitle</span>"
    $h += "</div>"
    if ($f.AffectedCount -gt 0 -and $f.Severity -ne "OK") {
        $h += "<span style='background:#f1f5f9;color:#475569;border-radius:5px;padding:2px 7px;font-size:10px;font-weight:700;white-space:nowrap;'>$($f.AffectedCount) affected</span>"
    }
    $h += "</div>"
    $h += "<p class='fc-desc' data-no-translate='true' style='margin:0 0 7px 0;font-size:11px;color:#374151;line-height:1.55;'>$enDesc</p>"
    if ($f.AffectedObjects -and $f.AffectedObjects.Count -gt 0 -and $f.Severity -ne "OK") {
        $shown = ($f.AffectedObjects | Select-Object -First 5 | ForEach-Object { [System.Net.WebUtility]::HtmlEncode($_) }) -join "<br>"
        $more  = if ($f.AffectedObjects.Count -gt 5) { "<br><span style='color:#94a3b8;font-style:italic;'>... +$($f.AffectedObjects.Count-5) more objects</span>" } else { "" }
        $h += "<div style='margin:0 0 7px 0;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;padding:6px 10px;font-size:11px;color:#1a3550;font-family:Consolas,monospace;line-height:1.8;'>$shown$more</div>"
    }
    if ($f.Recommendation) {
        $h += "<div style='display:flex;align-items:flex-start;gap:6px;background:#fffbeb;border:1px solid #fde68a;border-radius:7px;padding:8px 10px;'>"
        $h += "<i class='fa-solid fa-screwdriver-wrench' style='color:#d97706;font-size:11px;margin-top:2px;flex-shrink:0;'></i>"
        $h += "<div><div style='font-size:10px;font-weight:700;color:#92400e;margin-bottom:2px;'>What To Do</div>"
        $h += "<div class='fc-rec-body' data-no-translate='true' style='font-size:11px;color:#78350f;line-height:1.5;'>$enRec</div></div>"
        $h += "</div>"
    }
    $h += "</div>"
    return $h
}

# =====================================================================
# BUILD OU TREES
# =====================================================================
function Render-TierCompactTree([string]$ParentId, [int]$Depth) {
    $children = @($OUTreeNodes | Where-Object { $_.ParentId -eq $ParentId } | Sort-Object Name)
    foreach ($node in $children) {
        $pad = if ($Depth -eq 0) { "" } else { ("&nbsp;" * (($Depth - 1)*3)) + "&#9492;&#9472;&nbsp;" }
        $ico = if ($node.Type -eq "domain") { "&#127760;" } else { "&#128193;" }
        $nm  = [System.Net.WebUtility]::HtmlEncode($node.Name)
        $lc  = $node.GpoLinks.Count
        $lb  = if ($lc -gt 0) { " <span style='background:#dbeafe;color:#1d4ed8;border-radius:3px;padding:0 4px;font-size:9px;font-weight:700;'>$lc GPO</span>" } else { "" }
        $script:TierTreeOut += "<div style='color:#1a3550;line-height:1.85;'>$pad$ico $nm$lb</div>"
        Render-TierCompactTree -ParentId $node.Id -Depth ($Depth + 1)
    }
}
$script:TierTreeOut = ""
Render-TierCompactTree -ParentId "" -Depth 0

$hasDisabledOU = @($OUTreeNodes | Where-Object { $_.Name -match '(?i)^(disabled|deactivated|inactive)' }).Count -gt 0

function Render-RecoTree([string]$ParentId, [int]$Depth) {
    $children = @($OUTreeNodes | Where-Object { $_.ParentId -eq $ParentId } | Sort-Object Name)
    foreach ($node in $children) {
        $pad = if ($Depth -eq 0) { "" } else { ("&nbsp;" * (($Depth - 1)*3)) + "&#9492;&#9472;&nbsp;" }
        $ico = if ($node.Type -eq "domain") { "&#127760;" } else { "&#128193;" }
        $nm  = [System.Net.WebUtility]::HtmlEncode($node.Name)
        $lc  = $node.GpoLinks.Count
        $lb  = if ($lc -gt 0) { " <span style='background:#dbeafe;color:#1d4ed8;border-radius:3px;padding:0 4px;font-size:9px;font-weight:700;'>$lc GPO</span>" } else { "" }
        $childNames = @($OUTreeNodes | Where-Object { $_.ParentId -eq $node.Id } | Select-Object -ExpandProperty Name)
        $isDept = ($childNames -icontains "USERS" -or $childNames -icontains "COMPUTER" -or $childNames -icontains "Computers")
        $tag = if ($isDept) { " <span style='background:#dcfce7;color:#166534;border-radius:3px;padding:0 4px;font-size:9px;font-weight:700;'>Tier 2</span>" } else { "" }
        $script:RecoTreeOut += "<div style='color:#374151;line-height:1.85;'>$pad$ico $nm$lb$tag</div>"
        Render-RecoTree -ParentId $node.Id -Depth ($Depth + 1)
    }
}
$script:RecoTreeOut = ""
Render-RecoTree -ParentId "" -Depth 0

$script:RecoTreeOut += "<div style='border-top:1px dashed #c4b5fd;margin-top:8px;padding-top:8px;'>"
$script:RecoTreeOut += "<div style='font-size:9px;font-weight:800;color:#7c3aed;margin-bottom:5px;letter-spacing:.04em;'>&#10133; RECOMMENDED ADDITIONS:</div>"
if (-not $HasAdminOU) {
    $p3 = "&nbsp;&nbsp;&nbsp;&#9492;&#9472;&nbsp;"
    $script:RecoTreeOut += "<div style='color:#059669;font-weight:700;line-height:1.9;'>&#128193; <strong>OU=Administration</strong> <span style='background:#dcfce7;color:#166534;border-radius:3px;padding:0 5px;font-size:9px;font-weight:800;'>NEW</span></div>"
    $script:RecoTreeOut += "<div style='color:#059669;line-height:1.8;'>$p3&#128193; OU=T0-Admins <span style='color:#94a3b8;font-size:9px;'>(DA / EA / SA)</span></div>"
    $script:RecoTreeOut += "<div style='color:#059669;line-height:1.8;'>$p3&#128193; OU=T1-Admins <span style='color:#94a3b8;font-size:9px;'>(Server admins)</span></div>"
    $script:RecoTreeOut += "<div style='color:#059669;line-height:1.8;'>$p3&#128193; OU=T2-Admins <span style='color:#94a3b8;font-size:9px;'>(Workstation admins)</span></div>"
    $script:RecoTreeOut += "<div style='color:#059669;line-height:1.8;'>$p3&#128193; OU=ServiceAccounts <span style='color:#94a3b8;font-size:9px;'>(gMSA / SPN)</span></div>"
}
if (-not $hasDisabledOU) {
    $script:RecoTreeOut += "<div style='color:#059669;font-weight:700;line-height:1.9;'>&#128193; <strong>OU=Disabled</strong> <span style='background:#dcfce7;color:#166534;border-radius:3px;padding:0 5px;font-size:9px;font-weight:800;'>NEW</span> <span style='color:#94a3b8;font-size:9px;'>(Disabled accounts)</span></div>"
}
if ($HasAdminOU -and $hasDisabledOU) {
    $script:RecoTreeOut += "<div style='color:#166534;font-size:11px;font-weight:700;'><i class='fa-solid fa-circle-check'></i> OU structure looks good!</div>"
}
$script:RecoTreeOut += "</div>"

# =====================================================================
# RENDER HTML
# =====================================================================
$activeUserCount   = @($AllUsers | Where-Object { $_.Enabled }).Count
$disabledUserCount = @($AllUsers | Where-Object { -not $_.Enabled }).Count
$Tier0Findings = @($TierFindings | Where-Object { $_.Tier -eq "Tier0" })
$Tier1Findings = @($TierFindings | Where-Object { $_.Tier -eq "Tier1" })
$Tier2Findings = @($TierFindings | Where-Object { $_.Tier -eq "Tier2" })
$OUFindings    = @($TierFindings | Where-Object { $_.Tier -eq "OU" })

$t0FindingsHtml = ($Tier0Findings | ForEach-Object { Get-TierFindingHtml -f $_ }) -join ""
$t1FindingsHtml = ($Tier1Findings | ForEach-Object { Get-TierFindingHtml -f $_ }) -join ""
$t2FindingsHtml = ($Tier2Findings | ForEach-Object { Get-TierFindingHtml -f $_ }) -join ""
$ouFindingsHtml = ($OUFindings    | ForEach-Object { Get-TierFindingHtml -f $_ }) -join ""

$t0HdrBg = if ($Tier0CritCount -gt 0) { "linear-gradient(135deg,#7f1d1d,#b91c1c)" } elseif ($Tier0WarnCount -gt 0) { "linear-gradient(135deg,#92400e,#d97706)" } else { "linear-gradient(135deg,#14532d,#16a34a)" }
$t1HdrBg = if ($Tier1CritCount -gt 0) { "linear-gradient(135deg,#1e3a8a,#b91c1c)" } elseif ($Tier1WarnCount -gt 0) { "linear-gradient(135deg,#1e3a8a,#1a5fa8)" } else { "linear-gradient(135deg,#1e3a8a,#0ea5e9)" }
$t2HdrBg = if ($Tier2CritCount -gt 0) { "linear-gradient(135deg,#14532d,#b91c1c)" } elseif ($Tier2WarnCount -gt 0) { "linear-gradient(135deg,#14532d,#d97706)" } else { "linear-gradient(135deg,#14532d,#059669)" }

$Html += @"
<style>
.tier-acc-wrap{margin-bottom:12px;border-radius:10px;box-shadow:0 1px 4px rgba(0,0,0,.06);}
.tier-acc-hdr{display:flex;align-items:center;gap:10px;padding:12px 18px;border-radius:10px;color:#fff;cursor:pointer;user-select:none;transition:opacity .15s;}
.tier-acc-hdr:hover{opacity:.92;}
.tier-acc-wrap.tier-acc-open .tier-acc-hdr{border-radius:10px 10px 0 0;}
.tier-acc-body{background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 10px 10px;padding:14px;display:none;}
.tier-acc-wrap.tier-acc-open .tier-acc-body{display:block;}
.tier-acc-chevron{margin-left:auto;font-size:12px;transition:transform .2s;flex-shrink:0;}
.tier-acc-wrap.tier-acc-open .tier-acc-chevron{transform:rotate(180deg);}
.tier-section-body{background:#fff;border:1px solid #e2e8f0;border-radius:0 0 10px 10px;padding:14px;}
</style>

<!-- What Is the AD Tier Model? -->
<div style='background:linear-gradient(135deg,#e0f2fe,#f0f9ff);border:1px solid #7dd3fc;border-radius:10px;padding:12px 16px;margin-bottom:20px;'>
  <div style='font-size:13px;font-weight:800;color:#0369a1;margin-bottom:4px;'>What Is the AD Tier Model?</div>
  <div style='font-size:11px;color:#0c4a6e;line-height:1.6;' data-no-translate='true'>
    Microsoft's <strong>Administrative Tier Model</strong> splits Active Directory into 3 isolated security layers.
    The goal: a compromised user workstation must <strong>never</strong> give an attacker a path to Domain Admin.
    Each tier requires dedicated accounts, separate GPOs, and logon restrictions.
  </div>
</div>

<!-- DOMAIN CORE -->
<div class='tier-acc-wrap tier-acc-open' id='tierAccT0'>
  <div class='tier-acc-hdr' style='background:$t0HdrBg;' onclick='toggleTierAcc("tierAccT0")'>
    <div style='width:34px;height:34px;background:rgba(255,255,255,.2);border-radius:7px;display:flex;align-items:center;justify-content:center;flex-shrink:0;'>
      <i class='fa-solid fa-crown' style='font-size:15px;'></i>
    </div>
    <div style='flex:1;min-width:0;'>
      <div style='font-size:9px;font-weight:700;opacity:.75;letter-spacing:.12em;'>DOMAIN CORE &mdash; MOST CRITICAL</div>
      <div style='font-size:14px;font-weight:800;'>AD, Domain Controllers &amp; Identity</div>
    </div>
    <div style='background:rgba(0,0,0,.18);border-radius:5px;padding:3px 9px;font-size:11px;font-weight:700;white-space:nowrap;'>$($s0.label) &bull; $Tier0CritCount critical &bull; $Tier0WarnCount warnings</div>
    <i class='fa-solid fa-chevron-down tier-acc-chevron'></i>
  </div>
  <div class='tier-acc-body'>
    $t0FindingsHtml
  </div>
</div>

<!-- SERVERS -->
<div class='tier-acc-wrap tier-acc-open' id='tierAccT1'>
  <div class='tier-acc-hdr' style='background:$t1HdrBg;' onclick='toggleTierAcc("tierAccT1")'>
    <div style='width:34px;height:34px;background:rgba(255,255,255,.2);border-radius:7px;display:flex;align-items:center;justify-content:center;flex-shrink:0;'>
      <i class='fa-solid fa-server' style='font-size:15px;'></i>
    </div>
    <div style='flex:1;min-width:0;'>
      <div style='font-size:9px;font-weight:700;opacity:.75;letter-spacing:.12em;'>SERVERS &mdash; SERVER LAYER</div>
      <div style='font-size:14px;font-weight:800;'>File, App &amp; Database Servers</div>
    </div>
    <div style='background:rgba(0,0,0,.18);border-radius:5px;padding:3px 9px;font-size:11px;font-weight:700;white-space:nowrap;'>$($s1.label) &bull; $Tier1CritCount critical &bull; $Tier1WarnCount warnings</div>
    <i class='fa-solid fa-chevron-down tier-acc-chevron'></i>
  </div>
  <div class='tier-acc-body'>
    $t1FindingsHtml
  </div>
</div>

<!-- USERS & DEVICES -->
<div class='tier-acc-wrap tier-acc-open' id='tierAccT2'>
  <div class='tier-acc-hdr' style='background:$t2HdrBg;' onclick='toggleTierAcc("tierAccT2")'>
    <div style='width:34px;height:34px;background:rgba(255,255,255,.2);border-radius:7px;display:flex;align-items:center;justify-content:center;flex-shrink:0;'>
      <i class='fa-solid fa-desktop' style='font-size:15px;'></i>
    </div>
    <div style='flex:1;min-width:0;'>
      <div style='font-size:9px;font-weight:700;opacity:.75;letter-spacing:.12em;'>USERS &amp; DEVICES &mdash; USER LAYER</div>
      <div style='font-size:14px;font-weight:800;'>Workstations &amp; End Users</div>
    </div>
    <div style='background:rgba(0,0,0,.18);border-radius:5px;padding:3px 9px;font-size:11px;font-weight:700;white-space:nowrap;'>$($s2.label) &bull; $Tier2CritCount critical &bull; $Tier2WarnCount warnings</div>
    <i class='fa-solid fa-chevron-down tier-acc-chevron'></i>
  </div>
  <div class='tier-acc-body'>
    $t2FindingsHtml
  </div>
</div>

<!-- OU STRUCTURE -->
<div class='tier-acc-wrap tier-acc-open' id='tierAccOU'>
  <div class='tier-acc-hdr' style='background:linear-gradient(135deg,#4c1d95,#7c3aed);' onclick='toggleTierAcc("tierAccOU")'>
    <div style='width:34px;height:34px;background:rgba(255,255,255,.2);border-radius:7px;display:flex;align-items:center;justify-content:center;flex-shrink:0;'>
      <i class='fa-solid fa-sitemap' style='font-size:15px;'></i>
    </div>
    <div style='flex:1;min-width:0;'>
      <div style='font-size:9px;font-weight:700;opacity:.75;letter-spacing:.12em;'>OU STRUCTURE</div>
      <div style='font-size:14px;font-weight:800;'>Hierarchy &amp; Organization Analysis</div>
    </div>
    <i class='fa-solid fa-chevron-down tier-acc-chevron'></i>
  </div>
  <div class='tier-acc-body'>
    $ouFindingsHtml
    <div style='margin-top:4px;'>
      <div style='font-size:12px;font-weight:800;color:#0f2f4f;margin-bottom:10px;display:flex;align-items:center;gap:6px;'>
        <i class='fa-solid fa-code-compare' style='color:#7c3aed;'></i>
        OU Structure Comparison &mdash; Current vs Recommended
      </div>
      <div style='display:grid;grid-template-columns:1fr 1fr;gap:12px;'>
        <div>
          <div style='font-size:10px;font-weight:800;color:#475569;margin-bottom:6px;text-transform:uppercase;letter-spacing:.06em;display:flex;align-items:center;gap:4px;'>
            <i class='fa-solid fa-folder-tree' style='color:#7c3aed;'></i> Your Current Structure
          </div>
          <div style='background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:10px 12px;font-family:Consolas,monospace;font-size:11px;max-height:320px;overflow-y:auto;'>
            $($script:TierTreeOut)
          </div>
        </div>
        <div>
          <div style='font-size:10px;font-weight:800;color:#475569;margin-bottom:6px;text-transform:uppercase;letter-spacing:.06em;display:flex;align-items:center;gap:4px;'>
            <i class='fa-solid fa-lightbulb' style='color:#f59e0b;'></i> Recommended (Tier Model)
          </div>
          <div style='background:#f8fff8;border:1px solid #bbf7d0;border-radius:8px;padding:10px 12px;font-family:Consolas,monospace;font-size:11px;max-height:320px;overflow-y:auto;'>
            $($script:RecoTreeOut)
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
"@

$Html += "</div></div>"  # close content-card + container

# Accordion JS + TR translations
$Html += @'
<script>
function toggleTierAcc(id) {
  var el = document.getElementById(id);
  if (el) el.classList.toggle('tier-acc-open');
}
(function(){
  function applyTierFindingLang(lang) {
    var isTR = (lang === 'tr');
    var cards = document.querySelectorAll('.tier-finding');
    for (var i = 0; i < cards.length; i++) {
      var el = cards[i]; var d = el.dataset;
      var te = el.querySelector('.fc-title');
      var de = el.querySelector('.fc-desc');
      var re = el.querySelector('.fc-rec-body');
      if (te) te.textContent = (isTR && d.trTitle) ? d.trTitle : d.enTitle;
      if (de) de.textContent = (isTR && d.trDesc)  ? d.trDesc  : d.enDesc;
      if (re) re.textContent = (isTR && d.trRec)   ? d.trRec   : d.enRec;
    }
  }
  var _orig = window.applyLanguage;
  window.applyLanguage = function(lang) { if (_orig) _orig(lang); applyTierFindingLang(lang); };
  if (typeof currentLanguage !== 'undefined' && currentLanguage === 'tr') {
    setTimeout(function(){ applyTierFindingLang('tr'); }, 200);
  }
})();
